GO
SET QUOTED_IDENTIFIER ON
GO
CREATE FUNCTION [dbo].[ObtenerFechaUltimaVisitaConHora] 
(
@Cliente NVARCHAR(50)
)
RETURNS DATETIME
AS
BEGIN
    DECLARE @FechaUltimaVisita DATETIME
    
    SELECT @FechaUltimaVisita = MAX(CONVERT(VARCHAR, FIN, 20))
     FROM EXACTUSERP.ERPADMIN.VISITA WITH(NOLOCK)
    WHERE Cliente = @Cliente
    
    DECLARE @Visitas TABLE (
        Cliente VARCHAR(20),
        FechaVisita DATETIME
       
    )
    
    INSERT INTO @Visitas (Cliente, FechaVisita)
    SELECT CLIENTE, CONVERT(VARCHAR, FIN, 20)
    FROM EXACTUSERP.ERPADMIN.VISITA WITH(NOLOCK)
    WHERE Cliente = @Cliente AND CONVERT(VARCHAR, FIN, 20) = @FechaUltimaVisita
    
    DECLARE @FechaUltimaVisitaConHora DATETIME
    
    SELECT @FechaUltimaVisitaConHora = MAX(FechaVisita)
    FROM @Visitas
    
    RETURN @FechaUltimaVisitaConHora
END
GO
/****** Object:  UserDefinedFunction [dbo].[SplitString]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE FUNCTION [dbo].[SplitString]
(
    @string NVARCHAR(MAX),
    @delimiter CHAR(1)
)
RETURNS @output TABLE (Value NVARCHAR(MAX))
AS
BEGIN
    DECLARE @start INT, @end INT
    SET @start = 1

    WHILE CHARINDEX(@delimiter, @string, @start) > 0
    BEGIN
        SET @end = CHARINDEX(@delimiter, @string, @start)
        INSERT INTO @output (Value)
        VALUES (SUBSTRING(@string, @start, @end - @start))
        SET @start = @end + 1
    END

    INSERT INTO @output (Value)
    VALUES (SUBSTRING(@string, @start, LEN(@string) - @start + 1))

    RETURN
END
GO
