CREATE FUNCTION [DIS86].[FUN_OBT_CUENTA_BANCARIA]
(
@BANCO VARCHAR(50)
)
RETURNS VARCHAR(500)
AS
BEGIN
    DECLARE @CUENTABANCARIA VARCHAR(500)
    
	 SELECT 
	       @CUENTABANCARIA = CUENTA_BANCO  
	 FROM  
	       EXACTUSERP.DIS86.CUENTA_BANCARIA  
	 WHERE 
	       ACTIVA             = 'S' 
	 AND   MONEDA             = 'CRC'
     AND   ENTIDAD_FINANCIERA = @BANCO

    RETURN @CUENTABANCARIA
END
