CREATE FUNCTION [DIS86].[FUN_OBT_DESCUENTO_ART_CLIE]

(
    @CLIENTE NVARCHAR(50),
    @ARTICULO NVARCHAR(50),
    @CANTIDAD_MIN INT
    
)
RETURNS DECIMAL(5, 2)
AS
BEGIN
    DECLARE @PORC_DESCUENTO DECIMAL(5, 2);

    SELECT @PORC_DESCUENTO = PORC_DESCUENTO
    FROM 
	      EXACTUSERP.DIS86.DCTO_ART_X_CLI
    WHERE 
	      CLIENTE       =  @CLIENTE
      AND ARTICULO      =  @ARTICULO
      AND @CANTIDAD_MIN >=  CANTIDAD_INICIAL
	  AND FECHA_INICIAL <= GETDATE() 
      AND  FECHA_FINAL  >= GETDATE(); 

    RETURN @PORC_DESCUENTO
END

