(
    @CLIENTE NVARCHAR(50),
    @ARTICULO NVARCHAR(50)
    
)
RETURNS INT
AS
BEGIN
    DECLARE @EXISTE INT;

    SELECT @EXISTE = COUNT(ARTICULO)
    FROM 
	      EXACTUSERP.DIS86.DCTO_ART_X_CLI
    WHERE 
	      CLIENTE       =  @CLIENTE
      AND ARTICULO      =  @ARTICULO
      AND FECHA_INICIAL >= GETDATE() 
     AND  FECHA_FINAL   <= GETDATE(); 

    RETURN @EXISTE
END

