CREATE FUNCTION [DIS86].[FUN_OBT_ESTADO_POR_FECHA]
(
@CLIENTE NVARCHAR(50),
@FECHA_INI VARCHAR(30),
@FECHA_FIN VARCHAR(30)
)
RETURNS VARCHAR(20)
AS
BEGIN
    DECLARE @ESTADO VARCHAR(20)
    
    SELECT @ESTADO = (SELECT  ESTADO_VISITA 
								 FROM    [PS_TRACKING].[DIS86].[VISITAS]
								 WHERE   CLIENTE = @CLIENTE
								 AND     CONVERT(VARCHAR,FECHA_VISITA,105) >= @FECHA_INI
								 AND     CONVERT(VARCHAR,FECHA_VISITA,105) <= @FECHA_FIN)
    
    RETURN @ESTADO
END
GO
/****** Object:  UserDefinedFunction [DIS86].[FUN_OBT_SEMANA_ULTIMA_VISITA]    Script Date: 22/5/2026 17:05:06 ******/
