CREATE  FUNCTION [DIS86].[FUN_OBT_SEMANA_ULTIMA_VISITA]
(@CLIENTE NVARCHAR(50),
 @RUTA VARCHAR(10)
)
RETURNS INT
AS
BEGIN
    DECLARE @YEAR INT = YEAR(GETDATE())
	DECLARE @SEMANA INT
      
	SELECT @SEMANA = DATEPART(WEEK, VTA.FIN) 
      --MIN(FIN) AS inicio_semana, 
      --MAX(FIN) AS fin_semana
	FROM EXACTUSERP.ERPADMIN.VISITA   AS VTA (NOLOCK)
	 WHERE VTA.CLIENTE = @CLIENTE
	 AND YEAR(VTA.FIN) = @YEAR -- Toma el anio de la fecha actual
	--AND VTA.RUTA = @RUTA
	GROUP BY DATEPART(WEEK, VTA.FIN)
	ORDER BY DATEPART(WEEK, VTA.FIN)

    RETURN @SEMANA
END


