CREATE FUNCTION  [DIS86].[FUN_TRACKING_COD_PED_SEGUIMIENTO]()
returns VARCHAR(20)
AS 
BEGIN 
DECLARE @Pedido AS VARCHAR(max)

DECLARE PedInfo CURSOR FOR SELECT DISTINCT PEDIDO FROM DIS86.SEGUIMIENTO 
OPEN PedInfo
FETCH NEXT FROM PedInfo INTO @Pedido
WHILE @@fetch_status = 0
BEGIN
     --PRINT @Pedido
     FETCH NEXT FROM PedInfo INTO @Pedido

END
CLOSE PedInfo
DEALLOCATE PedInfo

RETURN @Pedido
END 
