/****** Object:  UserDefinedFunction [DIS86].[OBTIENE_PRECIO_EXACTUSERP_NIVEL_PRECIOS_CLIENTE]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE FUNCTION [DIS86].[OBTIENE_PRECIO_EXACTUSERP_NIVEL_PRECIOS_CLIENTE] (@ARTICULO VARCHAR(20), @PEDIDO VARCHAR(40))
RETURNS DECIMAL(28,8)
AS
BEGIN

	DECLARe @CLIENTE VARCHAR(40), @CANT INT, @PRECIO DECIMAL(28,8),@NP VARCHAR(25) SET @NP = '' 
	 
	SET @CLIENTE = (SELECT CLIENTE 
					FROM DIS86.PEDIDO P 
					WHERE P.PEDIDO = @PEDIDO)   
	if((select count(*) from DIS86.VIEW_NIVEL_PRECIOS_EXACTUSERP_POR_CLIENTE where cliente = @cliente AND ARTICULO = @ARTICULO) < 1)
	begin
		set @CLIENTE = 'CL99999'
	end
	
    SET @NP = (SELECT ISNULL(MAX(NIVEL_PRECIO),'') FROM DIS86.VIEW_NIVEL_PRECIOS_EXACTUSERP_POR_CLIENTE WHERE CLIENTE =@CLIENTE and ARTICULO = @ARTICULO  )--'0015-'
	IF(@NP <> '')
	BEGIN
		SET @PRECIO = (
		SELECT CASE WHEN (SELECT ISNULL(MAX(PRECIO),0)PRECIO   --
			FROM	DIS86.VIEW_NIVEL_PRECIOS_EXACTUSERP_POR_CLIENTE 
			WHERE	ARTICULO = @ARTICULO--'07624'--
					and CLIENTE =@CLIENTE-- '0015-' --
					AND NIVEL_PRECIO = @NP) = '0.00000000' 
					THEN 
							(SELECT	 ISNULL(MAX(PRECIO),0)PRECIO 
								FROM	DIS86.VIEW_NIVEL_PRECIOS_EXACTUSERP_POR_CLIENTE 
								WHERE	ARTICULO = @ARTICULO --AND -- '15285'--
										--CLIENTE =@CLIENTE-- '0378-' --
										-- AND NIVEL_PRECIO = 'MAYORISTA'
										)
					ELSE
					(SELECT	ISNULL(MAX(PRECIO),0)PRECIO 
							FROM	DIS86.VIEW_NIVEL_PRECIOS_EXACTUSERP_POR_CLIENTE 
							WHERE	ARTICULO =@ARTICULO --'50187'AND--  
									and CLIENTE =@CLIENTE--'0378-' -- 
									AND NIVEL_PRECIO = @NP) 
					END PRECIO) 
	END
	ELSE
	BEGIN
		SET @PRECIO = (
		SELECT CASE WHEN (SELECT	ISNULL(MAX(PRECIO),0)PRECIO 
			FROM	DIS86.VIEW_NIVEL_PRECIOS_EXACTUSERP_POR_CLIENTE 
			WHERE	ARTICULO = @ARTICULO AND 
					NIVEL_PRECIO = @NP ) = '0.00000000' 
					THEN 
							(SELECT	ISNULL(MAX(PRECIO),0)PRECIO 
								FROM	DIS86.VIEW_NIVEL_PRECIOS_EXACTUSERP_POR_CLIENTE 
								WHERE	ARTICULO =@ARTICULO AND  
										NIVEL_PRECIO = @NP)
					ELSE
					(SELECT	ISNULL(MAX(PRECIO),0)PRECIO 
							FROM	DIS86.VIEW_NIVEL_PRECIOS_EXACTUSERP_POR_CLIENTE 
							WHERE	ARTICULO =@ARTICULO AND  
									NIVEL_PRECIO = @NP) 
					END PRECIO) 
	END 
	
	RETURN @PRECIO;
 
END
GO
/****** Object:  UserDefinedFunction [DIS86].[OBTIENE_TOTAL_DESCUENTO_LINEAS_PEDIDO]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [DIS86].[OBTIENE_TOTAL_DESCUENTO_LINEAS_PEDIDO] (@PEDIDO INT,@CLIENTE VARCHAR(20) )
RETURNS DECIMAL(28,2)
AS
BEGIN

	if(select count(*) from DIS86.VIEW_NIVEL_PRECIOS_EXACTUSERP_POR_CLIENTE where cliente = @cliente) =0
	begin
		set @CLIENTE = 'CL99999'
	end
	
	RETURN (SELECT
		ISNULL(SUM(  
		 
		case when NP.PORC_DESCUENTO2 > 100 then 
		(CANTIDAD * (CASE WHEN NP.PRECIO IS NULL THEN PL.PRECIO_UNITARIO ELSE NP.PRECIO END)* NP.PORC_DESCUENTO/100 ) 
		-(( CANTIDAD * (CASE WHEN NP.PRECIO IS NULL THEN PL.PRECIO_UNITARIO ELSE NP.PRECIO END)* NP.PORC_DESCUENTO/100 )
		-  NP.PORC_DESCUENTO2 )
					else
						(CANTIDAD * (CASE WHEN NP.PRECIO IS NULL THEN PL.PRECIO_UNITARIO ELSE NP.PRECIO END)* NP.PORC_DESCUENTO/100 ) 
		-(( CANTIDAD * (CASE WHEN NP.PRECIO IS NULL THEN PL.PRECIO_UNITARIO ELSE NP.PRECIO END)* NP.PORC_DESCUENTO/100 )
		*  NP.PORC_DESCUENTO2/100 )
					end 
		 )  ,0) 
		 
		FROM	DIS86.PEDIDO_LINEA PL
		LEFT JOIN [DIS86].[VIEW_NIVEL_PRECIOS_EXACTUSERP_POR_CLIENTE] NP ON NP.ARTICULO = PL.ARTICULO_EXACTUSERP AND CLIENTE =@CLIENTE--'0062-'-- 
		WHERE	PEDIDO = ---34-
		
		@PEDIDO) 
		 
	
END
GO
/****** Object:  UserDefinedFunction [DIS86].[OBTIENE_TOTAL_IMPUESTO_LINEAS_PEDIDO]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE FUNCTION [DIS86].[OBTIENE_TOTAL_IMPUESTO_LINEAS_PEDIDO] (@PEDIDO INT)
RETURNS DECIMAL(28,2)
AS
BEGIN

	DECLARe @CLIENTE VARCHAR(40), @CANT INT, @PRECIO DECIMAL(28,8),@POR_IMP DECIMAL(28,8)-- ,@ARTICULO VARCHAR(25) SET @ARTICULO= '75090'
	 
	SET @CLIENTE = (SELECT CLIENTE 
					FROM DIS86.PEDIDO P 
					WHERE P.PEDIDO = @PEDIDO)  
					--ISNULL(MIN(),0.00000000)
    if(select count(*) from DIS86.VIEW_NIVEL_PRECIOS_EXACTUSERP_POR_CLIENTE where cliente = @cliente) =0
	begin
		set @CLIENTE = 'CL99999'
	end
	 
	 RETURN (
		--SELECT	ISNULL(SUM((CANTIDAD * PRECIO_UNITARIO)* (A.PORC_TARIFA/100)),0)
		select
		isnull(sum(
		((CANTIDAD * PRECIO_UNITARIO ) -
		 (	case when a.PORC_DESCUENTO2 > 100 then 
		(CANTIDAD * (CASE WHEN a.PRECIO IS NULL THEN PL.PRECIO_UNITARIO ELSE a.PRECIO END)* a.PORC_DESCUENTO/100 ) 
		-(( CANTIDAD * (CASE WHEN a.PRECIO IS NULL THEN PL.PRECIO_UNITARIO ELSE a.PRECIO END)* a.PORC_DESCUENTO/100 )
		-  a.PORC_DESCUENTO2 )
					else
						(CANTIDAD * (CASE WHEN a.PRECIO IS NULL THEN PL.PRECIO_UNITARIO ELSE a.PRECIO END)* a.PORC_DESCUENTO/100 ) 
		-(( CANTIDAD * (CASE WHEN a.PRECIO IS NULL THEN PL.PRECIO_UNITARIO ELSE a.PRECIO END)* a.PORC_DESCUENTO/100 )
		*  a.PORC_DESCUENTO2/100 )
					end ))
		* (A.PORC_TARIFA/100) 
		) 
		,0) 		FROM	DIS86.PEDIDO_LINEA PL
		JOIN [DIS86].[VIEW_NIVEL_PRECIOS_EXACTUSERP_POR_CLIENTE] A ON PL.ARTICULO_EXACTUSERP = A.ARTICULO AND A.CLIENTE = @CLIENTE--'0078-05'--
		WHERE	PEDIDO = @PEDIDO
		
		)
	
END



GO
