/****** Object:  UserDefinedFunction [DIS86].[TF_SPLIT]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE  FUNCTION [DIS86].[TF_SPLIT]
(
    @CADENA VARCHAR(MAX),
    @DELIMITER VARCHAR(1)
)
RETURNS @TABLE TABLE ( VAL VARCHAR(MAX) )
AS
BEGIN
    if @CADENA is null return
    declare @iStart int,
            @iPos int
    if substring( @CADENA, 1, 1 ) = @DELIMITER 
    begin
        set @iStart = 2
        insert into @TABLE
        values( null )
    end
    else 
        set @iStart = 1
    while 1=1
    begin
        set @iPos = charindex( @DELIMITER, @CADENA, @iStart )
        if @iPos = 0
            set @iPos = len( @CADENA )+1
        if @iPos - @iStart > 0          
            insert into @TABLE
            values  ( substring( @CADENA, @iStart, @iPos-@iStart ))
        else
            insert into @TABLE
            values( null )
        set @iStart = @iPos+1
        if @iStart > len( @CADENA ) 
            break
    end
    RETURN

END
GO
/****** Object:  UserDefinedFunction [ERPADMIN].[SF_GETDATE]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE  FUNCTION [ERPADMIN].[SF_GETDATE]
(
	-- Add the parameters for the function here
)
RETURNS DATETIME
AS
BEGIN
	DECLARE @start DATETIME
	DECLARE @diff INT
	DECLARE @end DATETIME
	SET @diff = 0
	DECLARE db_cursor CURSOR FOR  
	SELECT DIFFMINUTES 
	FROM ERPADMIN.TIMEZONE
	WHERE  ISDEFAULT = 'S'
	OPEN db_cursor   
	FETCH NEXT FROM db_cursor INTO @diff
	CLOSE db_cursor
	IF @diff != 0
	BEGIN
	SET @start = GETUTCDATE()
	SET @end = DATEADD(MINUTE,@diff, @start)
	RETURN @end
	END
	ELSE
	SET @end = GETDATE()
	RETURN @end
END;
GO
