/****** Object:  UserDefinedFunction [GLOBAL].[FUNC_WRAP_TEXT]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [GLOBAL].[FUNC_WRAP_TEXT](@texto VARCHAR(MAX), @longitud INT)
RETURNS VARCHAR(MAX)
AS
BEGIN
    DECLARE @resultado VARCHAR(MAX) = ''
    DECLARE @linea_actual VARCHAR(1000) = ''
    
    -- Usar STRING_SPLIT para dividir en palabras (SQL Server 2016+)
    SELECT @linea_actual = '',
           @resultado = ''
    
    DECLARE @palabra VARCHAR(1000)
    DECLARE palabras CURSOR FOR 
    SELECT value 
    FROM STRING_SPLIT(REPLACE(@texto, CHAR(13) + CHAR(10), ' '), ' ')
    WHERE value <> ''
    
    OPEN palabras
    FETCH NEXT FROM palabras INTO @palabra
    
    WHILE @@FETCH_STATUS = 0
    BEGIN
        IF LEN(@linea_actual) + LEN(@palabra) + 1 <= @longitud
        BEGIN
            IF @linea_actual = ''
                SET @linea_actual = @palabra
            ELSE
                SET @linea_actual = @linea_actual + ' ' + @palabra
        END
        ELSE
        BEGIN
            IF @linea_actual <> ''
            BEGIN
                SET @resultado = @resultado + @linea_actual + CHAR(13) + CHAR(10)
            END
            SET @linea_actual = @palabra
        END
        
        FETCH NEXT FROM palabras INTO @palabra
    END
    
    CLOSE palabras
    DEALLOCATE palabras
    
    -- Agregar la última línea
    IF @linea_actual <> ''
        SET @resultado = @resultado + @linea_actual
    
    RETURN @resultado
END
GO
/****** Object:  UserDefinedFunction [GLOBAL].[GETTIPOCAMBIOFECHA]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE FUNCTION [GLOBAL].[GETTIPOCAMBIOFECHA](@MONEDA VARCHAR(4), @FECHA DATETIME)
 RETURNS DECIMAL(28,8)
 AS
 BEGIN
   
   DECLARE @MONTO DECIMAL(28,8) 
   
   
   SELECT @MONTO = MONTO
   FROM EXACTUSERP.DIS86.MONEDA_HIST AS A
   WHERE MONEDA = @MONEDA
     AND FECHA = (SELECT MAX(FECHA)
                  FROM EXACTUSERP.DIS86.MONEDA_HIST AS B 
                  WHERE A.MONEDA = B.MONEDA
                    AND B.FECHA <= ISNULL(@FECHA, ERPADMIN.SF_GETDATE()))
 
   
   RETURN ISNULL(@MONTO,1)
 END
GO
/****** Object:  UserDefinedFunction [GLOBAL].[STRING_AGG]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE FUNCTION [GLOBAL].[STRING_AGG] (
    @Delimiter NVARCHAR(10),
    @Input NVARCHAR(MAX)
)
RETURNS NVARCHAR(MAX)
AS
BEGIN
    DECLARE @Result NVARCHAR(MAX) = '';
    DECLARE @Value NVARCHAR(255);
    DECLARE @Pos INT;

    -- Reemplazar el delimitador con un espacio temporal para evitar problemas
    SET @Input = @Input + @Delimiter;  -- Añadir un delimitador al final

    -- Loop para separar los valores
    WHILE LEN(@Input) > 0
    BEGIN
        SET @Pos = CHARINDEX(@Delimiter, @Input);

        IF @Pos = 0 
            BREAK;

        -- Extraer el valor
        SET @Value = LEFT(@Input, @Pos - 1);
        SET @Input = RIGHT(@Input, LEN(@Input) - @Pos);

        -- Concatenar al resultado
        IF @Result = '' 
            SET @Result = @Value;
        ELSE 
            SET @Result = @Result + @Delimiter + @Value;
    END

    RETURN @Result;
END;

GO
