CREATE view [DIS86].[ARTICULO_DESCUENTO_PRECIO_CLIENTE]
as 
/****** Script for SelectTopNRows command from SSMS  ******/
SELECT 1 [ROWNUMBER]
      ,ap.[ARTICULO] 
      ,ap.[NIVEL_PRECIO]
      ,IM.[IMPUESTO1] [PORC_TARIFA]
      ,LEFT(IM.IMPUESTO,2) TIPO_IMPUESTO
	   ,RIGHT(IM.IMPUESTO,2) TIPO_TARIFA
      ,'' [CLASIFICACION]
		, ISNULL(DE.PORC_DCTO,0) PORC_DESCUENTO
		,0 PORC_DESCUENTO2 
      ,[PRECIO]
      ,'519003' [ACTIVIDAD_ECONOMICA]
  FROM EXACTUSERP.[DIS86].articulo_precio ap
  join EXACTUSERP.DIS86.ARTICULO  a on ap.ARTICULO = a.ARTICULO
  join EXACTUSERP.DIS86.IMPUESTO im on a.IMPUESTO = im.IMPUESTO
  LEFT JOIN EXACTUSERP.DIS86.ESCALA_DCTO DE ON ap.ARTICULO = DE.ARTICULO --AND DE.NIVEL_PRECIO = 'DETALLE' -- falta version
  --where ap.NIVEL_PRECIO = 'DETALLE'


GO
/****** Object:  View [DIS86].[VIEW_VISTA_GLOBAL_ARTICULOS_PRECIOS_EXACTUSERP_CLIENTE]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO



CREATE VIEW [DIS86].[VIEW_VISTA_GLOBAL_ARTICULOS_PRECIOS_EXACTUSERP_CLIENTE]
	AS
	SELECT  A.ARTICULO
			,A.DESCRIPCION
			,BODEGA 
			,CASE WHEN A.TIPO='K' THEN 
				(select MIN(CANT_DISPONIBLE) from EXACTUSERP.DIS86.EXISTENCIA_BODEGA 
				where ARTICULO in (select ARTICULO_HIJO from EXACTUSERP.DIS86.ARTICULO_ENSAMBLE
				where ARTICULO_PADRE = A.ARTICULO) AND BODEGA IN ('01' ) AND CANT_DISPONIBLE >0)
				ELSE EB.CANT_DISPONIBLE END CANT_DISPONIBLE
			
			,A.DESCRIPCION ARTICULO_DESCRIPCION 
			
			,CL1.CLASIFICACION AS CLASIFICACION1  
			,CL1.DESCRIPCION   AS CLASIFICACION1_NOMBRE 
			,CL2.CLASIFICACION AS CLASIFICACION2  
			,CL2.DESCRIPCION   AS CLASIFICACION2_NOMBRE 
			,CL3.CLASIFICACION AS CLASIFICACION3  
			,CL3.DESCRIPCION   AS CLASIFICACION3_NOMBRE 
			,CL4.CLASIFICACION AS CLASIFICACION4  
			,CL4.DESCRIPCION   AS CLASIFICACION4_NOMBRE 
			,CL5.CLASIFICACION AS CLASIFICACION5  
			,CL5.DESCRIPCION   AS CLASIFICACION5_NOMBRE 
			,'CUIDADOYANOESTA'CLIENTE -- DE ESTA [DIS86].[ARTICULO_DESCUENTO_PRECIO_CLIENTE]
			,NIVEL_PRECIO
			,PRECIO PRECIO_BASE
			,PORC_DESCUENTO
			,PORC_DESCUENTO2
			,PORC_TARIFA
			,TIPO_IMPUESTO
			,TIPO_TARIFA
			,ACTIVIDAD_ECONOMICA
			,'¢ '+convert(varchar(50) , CAST(ISNULL(
					case when AD.PORC_DESCUENTO2 > 100 then 
						(AD.PRECIO -((AD.PRECIO*AD.PORC_DESCUENTO/100)+ (AD.PORC_DESCUENTO2)))
						+((AD.PRECIO -((AD.PRECIO*AD.PORC_DESCUENTO/100)+ ( AD.PORC_DESCUENTO2 ))) * (AD.PORC_TARIFA/100))
						else
						(AD.PRECIO -((AD.PRECIO*AD.PORC_DESCUENTO/100)+ (AD.PRECIO*AD.PORC_DESCUENTO2/100)))
						+((AD.PRECIO -((AD.PRECIO*AD.PORC_DESCUENTO/100)+ (AD.PRECIO*AD.PORC_DESCUENTO2/100))) * (AD.PORC_TARIFA/100))
					end
					,0) 
					as money), -1
				) PRECIO_MONEY  
				,CAST(ISNULL( 
					case when AD.PORC_DESCUENTO2 > 100 then 
						(AD.PRECIO -((AD.PRECIO*AD.PORC_DESCUENTO/100)+ (AD.PORC_DESCUENTO2)))
						+((AD.PRECIO -((AD.PRECIO*AD.PORC_DESCUENTO/100)+ ( AD.PORC_DESCUENTO2 ))) * (AD.PORC_TARIFA/100))
						else
						(AD.PRECIO -((AD.PRECIO*AD.PORC_DESCUENTO/100)+ (AD.PRECIO*AD.PORC_DESCUENTO2/100)))
						+((AD.PRECIO -((AD.PRECIO*AD.PORC_DESCUENTO/100)+ (AD.PRECIO*AD.PORC_DESCUENTO2/100))) * (AD.PORC_TARIFA/100))
						end
					,0) AS decimal(28,2)
				) PRECIO
				,PROVEEDOR AS CODIGO_PROVEEDOR 
				,ISNULL(A.PROVEEDOR,'SIN PROVEEDOR') NOMBRE_PROVEEDOR 
				,UNIDAD_VENTA UNIDAD 
				,A.ORDEN_MINIMA 
				,A.FACTOR_VENTA 
				--,CAST(A.NOTAS AS VARCHAR(1500))NOTAS 
				--,case when  AI.ARTICULO is not null then 'A' else NULL end  FOTO
				--,case when  AI.ARTICULO is not null then AI.[BASE64] else '' end FOTO_STRING	 
				,CASE WHEN AD.PORC_DESCUENTO >0 THEN '-'+ CAST(FORMAT((AD.PORC_DESCUENTO*10/1000),'P0')+ ' DESCUENTO'  AS VARCHAR(20))  ELSE A.U_ECOM_BANNER END  BANNER 
				--A.U_ECOM_BANNER  BANNER 
				,A.U_ECOM_COLOR_BANNER COLOR_BANNER 
				,A.U_ECOM_ART_PRINCIPAL
			--------------------------------------------------------------------------------
			--SOY JONA COMO CAMBIE LA CLAS1 POR LA 2 ADIVINE! TENGO QUE CAMBIARLO AQUI :)
			--------------------------------------------------------------------------------
				--,ECOM.CLASIFICACION1 ECOM1
				--,ECOM.CLASIFICACION2 ECOM2
				--,ECOM.CLASIFICACION3 ECOM3

				--,ECOM.CLASIFICACION1 ECOM1
				--,ECOM.CLASIFICACION2 ECOM2
				--,ECOM.CLASIFICACION3 ECOM3

				--SELECT * FROM EXACTUSERP.DIS86.ARTICULO
	FROM [DIS86].[ARTICULO_DESCUENTO_PRECIO_CLIENTE]  AD(nolock) 
	 JOIN  [EXACTUSERP].[DIS86].ARTICULO A  with(nolock) ON A.ARTICULO = AD.ARTICULO
	INNER join (SELECT ARTICULO,/*CASE WHEN (CANT_DISPONIBLE -PS_CANTIDAD_PEDIDO ) < 0 THEN 0 ELSE(CANT_DISPONIBLE - PS_CANTIDAD_PEDIDO )  END*/ CANT_DISPONIBLE, 
		BODEGA FROM [EXACTUSERP].[DIS86].EXISTENCIA_BODEGA with(nolock) WHERE BODEGA = '01' ) EB ON A.ARTICULO = EB.ARTICULO 
	--LEFT JOIN [DIS86].[ARTICULO_IMAGEN] AI with(nolock) ON AI.ARTICULO = A.ARTICULO AND AI.SECUENCIA = (SELECT MIN(SECUENCIA) AS SECUENCIA_MIN FROM [DIS86].[ARTICULO_IMAGEN] WHERE ARTICULO = A.ARTICULO)
	LEFT JOIN [EXACTUSERP].DIS86.CLASIFICACION CL1 with(nolock) ON A.CLASIFICACION_1 = CL1.CLASIFICACION
	LEFT JOIN [EXACTUSERP].DIS86.CLASIFICACION CL2 with(nolock) ON A.CLASIFICACION_2 = CL2.CLASIFICACION
	LEFT JOIN [EXACTUSERP].DIS86.CLASIFICACION CL3 with(nolock) ON A.CLASIFICACION_3 = CL3.CLASIFICACION
	LEFT JOIN [EXACTUSERP].DIS86.CLASIFICACION CL4 with(nolock) ON A.CLASIFICACION_4 = CL4.CLASIFICACION
	LEFT JOIN [EXACTUSERP].DIS86.CLASIFICACION CL5 with(nolock) ON A.CLASIFICACION_5 = CL5.CLASIFICACION
	--JOIN DIS86.VIEW_CLASIFICACION_ECOM ECOM ON A.ARTICULO = ECOM.ARTICULO 
	WHERE A.ACTIVO = 'S' and CLASIFICACION_1 is not null  
	 AND  (EB.CANT_DISPONIBLE > 0 )--( OR A.ARTICULO = 'ND')
	GROUP BY A.[ARTICULO],A.DESCRIPCION,A.TIPO
      ,[BODEGA]
      ,[CANT_DISPONIBLE]
      ,A.[DESCRIPCION]
