CREATE VIEW [DIS86].[CARGA_PEDIDO_LINEA_EXACTUSERP]
AS

SELECT DISTINCT
   I.CONSECUTIVO   PEDIDO, 
   L.PEDIDO_LINEA,
   L.BODEGA,   
  --'N' ESTADO,   
   L.ARTICULO_EXACTUSERP, 
   CASE WHEN L.ES_BONIFICADO ='S' THEN 0 
        ELSE CONVERT(DECIMAL(28,2), L.CANTIDAD) END AS CANTIDAD,
   PRECIO_UNITARIO,
   IMP.TIPO_IMPUESTO1 TIPO_IMPUESTO,
   IMP.TIPO_TARIFA1   TIPO_TARIFA,
   IMP.IMPUESTO1      PORC_TARIFA,
   isnull(convert (DECIMAL(28,2), (( L.CANTIDAD* L.PRECIO_UNITARIO) * L.PORC_DESCUENTO_POR_100)),0)MONTO_DESCUENTO,  --NOTA: SE DEBE TOMAR PRIMERO EL DESCUENTO DE LA PARTE WEB
   CASE WHEN L.PORC_DESCUENTO_POR_100 IS NULL THEN 0 ELSE L.PORC_DESCUENTO_POR_100 END PORC_DESCUENTO,
   CASE WHEN ES_BONIFICADO = 'S' THEN CANTIDAD ELSE 0 END CANTIDAD_BONIFICAD 

FROM      [DIS86].[PEDIDO_LINEA] L 
join      [DIS86].[PEDIDO] I          ON I.pedido   = l.pedido
JOIN      EXACTUSERP.DIS86.ARTICULO A   ON A.ARTICULO = L.ARTICULO_EXACTUSERP
JOIN      EXACTUSERP.DIS86.IMPUESTO IMP ON A.IMPUESTO = IMP.IMPUESTO 
LEFT join [DIS86].[VIEW_VISTA_GLOBAL_ARTICULOS_PRECIOS_EXACTUSERP_CLIENTE] C ON  C.CLIENTE =I.CLIENTE  AND C.ARTICULO = L.ARTICULO_EXACTUSERP

WHERE L.PEDIDO =  I.PEDIDO 
--AND L.PEDIDO ='181'



GO
