CREATE VIEW [DIS86].[CARGA_PEDIDO_EXACTUSERP]
AS 
 
		SELECT	I.CONSECUTIVO			PEDIDO, 
		'N' ESTADO,
		GETDATE()				FECHA_PEDIDO, 
		GETDATE() 				FECHA_PROMETIDA, 
		GETDATE()				FECHA_PROX_EMBARQU, 
		GETDATE()				FECHA_ULT_EMBARQUE,  
		GETDATE()				FECHA_ORDEN, 
		ISNULL(c.TARJETA_CREDITO, 'ND')	TARJETA_CREDITO, 
		c.NOMBRE  EMBARCAR_A, 
		CASE WHEN I.CLIENTE ='CL99999' THEN substring(I.CONSECUTIVO,6,12)  ELSE 'ND' END DIREC_EMBARQUE, 
		c.DIRECCION	DIRECCION_FACTURA, 
		ISNULL(I.RUBRO1,'ND') RUBRO1, -- se llena desde el web.
		ISNULL(I.RUBRO1,'') RUBRO2,  
		ISNULL(I.RUBRO1,'') RUBRO3, 
		ISNULL(I.RUBRO1,'') RUBRO4, 
		ISNULL(I.RUBRO1,'') RUBRO5, --
		--ISNULL(replace(I.OBSERVACIONES,'ref:en desarrollo','')+case when i.CODIGO_AUTORIZACION is null then  '' else 'ref:'+CONVERT(varchar(50), i.CODIGO_AUTORIZACION)end +', '+I.ENTREGA_EN+', '+ISNULL((I.COMENTARIO),' SIN COMENTARIOS'), 'Pedido Portal de Clientes')+' ,No. del pedido: '+I.CONSECUTIVO   OBSERVACIONES, 
		ISNULL(I.COMENTARIO, 'Sin comentarios') OBSERVACIONES,
		I.TOTAL TOTAL_MERCADERIA, -- va el total sin impuesto.
		0	MONTO_ANTICIPO, 
		0	MONTO_FLETE, 
        0	MONTO_SEGURO, 
		0	MONTO_DOCUMENTACIO, 
	    'P' TIPO_DESCUENTO1,-- 
		'P'	TIPO_DESCUENTO2, 
		I.DESCUENTO	MONTO_DESCUENTO1,--0 
		0	MONTO_DESCUENTO2, 
		c.descuento 	PORC_DESCUENTO1, 
		0	PORC_DESCUENTO2, 
		I.IMPUESTO	TOTAL_IMPUESTO1, 
		I.TOTAL	    BASE_IMPUESTO1, 
		0	TOTAL_IMPUESTO2, 
		((I.TOTAL+I.IMPUESTO)-I.DESCUENTO)	TOTAL_A_FACTURAR, 
		(SELECT  COMISION FROM EXACTUSERP.DIS86.VENDEDOR WHERE VENDEDOR = C.VENDEDOR)	PORC_COMI_VENDEDOR, 
		(SELECT  COMISION FROM EXACTUSERP.DIS86.VENDEDOR WHERE VENDEDOR = C.VENDEDOR)	PORC_COMI_COBRADOR, 
		0	TOTAL_CANCELADO, 
		I.TOTAL_CANTIDADES	TOTAL_UNIDADES, 
		'N'	IMPRESO, 
		I.FECHA FECHA_HORA, 
		0	DESCUENTO_VOLUMEN, 
		'N'	TIPO_PEDIDO, 
        'L'	MONEDA_PEDIDO, 
		(select Max(VERSION) from EXACTUSERP.DIS86.[VERSION_NIVEL] WHERE NIVEL_PRECIO = c.NIVEL_PRECIO)	VERSION_NP, 
		'N' AUTORIZADO, 
		'F'	DOC_A_GENERAR, 
		'N'	CLASE_PEDIDO, 
		'L' MONEDA, 
		c.NIVEL_PRECIO	NIVEL_PRECIO,-- 'ND-LOCAL'
		C.COBRADOR		COBRADOR, 
		c.RUTA		RUTA, --'ND'
		'SA'		USUARIO, 
		c.CONDICION_PAGO CONDICION_PAGO,-- '30''CR30'
		'01'		BODEGA, --'ND'
		c.ZONA		ZONA,-- 'ND'
		I.VENDEDOR	VENDEDOR, 
		I.CLIENTE  CLIENTE, 
        I.CLIENTE  CLIENTE_DIRECCION, 
		I.CLIENTE  CLIENTE_CORPORAC, 
		I.CLIENTE  CLIENTE_ORIGEN, 
		--'CRI' PAIS, 
		c.PAIS,
		'0'			SUBTIPO_DOC_CXC, 
		'FAC'		TIPO_DOC_CXC, 
		'S'			BACKORDER, 
		0			PORC_INTCTE, 
		'S'			DESCUENTO_CASCADA, 
		'N'			FIJAR_TIPO_CAMBIO, 
		'F'			ORIGEN_PEDIDO, 
		CASE WHEN I.CLIENTE ='CL99999' THEN SUBSTRING(ENTREGA_EN,22,500) ELSE c.DIR_EMB_DEFAULT END DESC_DIREC_EMBARQUE, 	
		c.NOMBRE   NOMBRE_CLIENTE, 
		I.FECHA		FECHA_PROYECTADA, 
		'P' TIPO_DOCUMENTO 
		,DIVISION_GEOGRAFICA1
		,DIVISION_GEOGRAFICA2,
		--,I.NUM_COTIZACION_TRABAJO
		 --ISNULL(I.ACTIVIDAD_ECONOMICA,'523906') ACTIVIDAD_COMERCIAL--
		 (SELECT TOP 1 ISNULL(ACTIVIDAD_ECONOMICA,'519003') FROM DIS86.PEDIDO_LINEA WHERE PEDIDO = I.PEDIDO)ACTIVIDAD_COMERCIAL
		,ISNULL(I.TIPO_FACTURACION,'POSTEMPORADA')TIPO_FACTURACION
FROM    
		  DIS86.PEDIDO(nolock) I, 
	     EXACTUSERP.DIS86.CLIENTE(nolock) c 
where  c.CLIENTE =  I.CLIENTE 

GO
