CREATE VIEW [DIS86].[INSERTAR_PEDIDO_LINEA_EXACTUSERP] 
AS 

WITH Bonificadas AS (
    SELECT 
        PL.PEDIDO,
        PL.ARTICULO_EXACTUSERP,
        ROW_NUMBER() OVER(PARTITION BY PL.PEDIDO ORDER BY PL.PEDIDO) AS LINEA_BONIFICADA
    FROM [DIS86].[CARGA_PEDIDO_LINEA_EXACTUSERP] PL
    WHERE PL.CANTIDAD_BONIFICAD <> 0  -- Solo seleccionamos las líneas bonificadas
)
SELECT 
    PL.PEDIDO,
    ROW_NUMBER() OVER(PARTITION BY PL.PEDIDO ORDER BY PL.PEDIDO)                            AS LINEA, -- Línea normal (0-indexed)
    PL.BODEGA, 
    PL.[ARTICULO_EXACTUSERP],
    'N' AS ESTADO,
    GETDATE() AS FECHA_ENTREGA,
    ROW_NUMBER() OVER(PARTITION BY PL.PEDIDO ORDER BY PL.PEDIDO) - 1                         AS LINEA_USUARIO,
    PL.PRECIO_UNITARIO, 
    PL.CANTIDAD,
    '0' AS CANTIDAD_FACTURADA,
    0 AS CANTIDAD_RESERVADA,
    ISNULL(PL.CANTIDAD_BONIFICAD, 0) AS CANTIDAD_BONIFICAD,
    '0' AS CANTIDAD_CANCELADA,
    'P' AS TIPO_DESCUENTO,
    PL.MONTO_DESCUENTO,
    PL.PORC_DESCUENTO, 
    PL.PORC_TARIFA,                                                                          -- PORC_IMPUESTO1
    PL.TIPO_IMPUESTO,
    PL.TIPO_TARIFA,
    a.DESCRIPCION,
    'SistemaTomaPedidos'                                                                     AS COMENTARIO,
    GETDATE()                                                                                AS FECHA_PROMETIDA,
    NULL                                                                                     AS LINEA_ORDEN_COMPRA,
    CASE WHEN SC.CATEGORIA_CLIENTE = 'EXT' THEN AC.CTR_VENTAS_EXP ELSE AC.CTR_VENTAS_LOC END AS CENTRO_COSTO,
    CASE WHEN SC.CATEGORIA_CLIENTE = 'EXT' THEN AC.CTA_VENTAS_EXP ELSE AC.CTA_VENTAS_LOC END AS CUENTA_CONTABLE,
    0                                                                                        AS [PORC_IMPUESTO2],
    0                                                                                        AS [PORC_IMP2_BASE],
    CASE WHEN PL.CANTIDAD_BONIFICAD <> 0 THEN B.LINEA_BONIFICADA ELSE NULL  END              AS PEDIDO_LINEA_BONIF,  -- Esta es la columna de numeración consecutiva de las líneas bonificadas.
	A.CANASTA_BASICA,
	A.ES_OTRO_CARGO
FROM      [DIS86].[CARGA_PEDIDO_LINEA_EXACTUSERP] PL
JOIN      DIS86.CARGA_PEDIDO_EXACTUSERP           CP (NOLOCK) ON CP.PEDIDO            = PL.PEDIDO
JOIN      EXACTUSERP.DIS86.ARTICULO               a  (NOLOCK) ON pl.ARTICULO_EXACTUSERP = a.articulo
JOIN      EXACTUSERP.DIS86.ARTICULO_CUENTA        AC (NOLOCK) ON AC.ARTICULO_CUENTA   = A.ARTICULO_CUENTA
JOIN      EXACTUSERP.DIS86.CLIENTE                SC (NOLOCK) ON SC.CLIENTE           = CP.CLIENTE
JOIN      [DIS86].[PEDIDO]                      I  (NOLOCK) ON I.CONSECUTIVO        = PL.PEDIDO
LEFT JOIN Bonificadas                           B           ON PL.PEDIDO            = B.PEDIDO AND 
                                                               PL.ARTICULO_EXACTUSERP = B.ARTICULO_EXACTUSERP
--WHERE I.CONSECUTIVO='PTLC-00000098'





GO
