CREATE  VIEW [DIS86].[VIEW_PEDIDO_TRACKING]
AS 

SELECT  TOP 1000

		PD.PEDIDO, 
		PD.OBSERVACIONES,
		PD.U_TLA_ESTADO					       TLA_ESTADO,
		PD.USUARIO,
		CONVERT(varchar,PD.U_TI_TLA_RECIBIDO,20) FECHA_HORA_RECIBIDO,
		CONVERT(VARCHAR,PD.FECHA_HORA,103)	      FECHA_PEDIDO,
		convert(varchar,PD.FECHA_PROMETIDA,103)	  DIA_RUTA,
		PD.U_PS_TRACKING_ESTADO_PEDIDO			  ESTADO_PEDIDO, 
		E.DESCRIPCION					          ESTADO_PEDIDO_DESCRIPCION,
		PD.RUTA+' - '+RT.DESCRIPCION	          RUTA,

		FAC.FACTURA, 
		RT.U_HORA_CORTE+':00' AS TIEMPO,
		PD.U_PS_TRACKING_ESTADO_FACTURA SEGUIR_FAC, 
		F.DESCRIPCION					SEGUIR_FAC_DESCRIPCION,
		'' SUCESOS, -- JHONNY LO ELIMINO DE INTERFAZ. 
		
		CL.CLIENTE + ' - ' + CL.ALIAS	AS CLIENTE,  
		VEN.VENDEDOR+' - '+VEN.NOMBRE	AS AGENTE, 
		
		RT.U_LUNES, 
		RT.U_MARTES, 
		RT.U_MIERCOLES, 
		RT.U_JUEVES, 
		RT.U_VIERNES, 
		RT.U_SABADO,
		
		RT.U_DIAS_RUTA AS DIAS

FROM 
		EXACTUSERP.DIS86.PEDIDO			PD  WITH(NOLOCK)
JOIN	EXACTUSERP.DIS86.RUTA				RT  WITH(NOLOCK) ON PD.RUTA				= RT.RUTA
JOIN	EXACTUSERP.DIS86.CLIENTE			CL	WITH(NOLOCK) ON PD.CLIENTE			= CL.CLIENTE
JOIN	EXACTUSERP.DIS86.FACTURA			FAC WITH(NOLOCK) ON PD.PEDIDO			= FAC.PEDIDO 
JOIN	EXACTUSERP.DIS86.VENDEDOR			VEN WITH(NOLOCK) ON CL.VENDEDOR			= VEN.VENDEDOR
JOIN	PS_TRACKING.DIS86.ESTADO_PEDIDO	E	WITH(NOLOCK) ON PD.U_PS_TRACKING_ESTADO_PEDIDO	= E.ESTADO_PEDIDO
JOIN	PS_TRACKING.DIS86.ESTADO_FACTURA_SEGUIMIENTO	F	WITH(NOLOCK) ON PD.U_PS_TRACKING_ESTADO_FACTURA	= F.ESTADO_FACTURA_SEGUIMIENTO	
WHERE PD.ESTADO IN('A','B','F') 
AND PD.AUTORIZADO IN('N','S')


GO
