/****** Object:  View [DIS86].[VIEW_OBT_ARTICULO_PRECIO_DCTO]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO



CREATE VIEW [DIS86].[VIEW_OBT_ARTICULO_PRECIO_DCTO]
AS 
SELECT  
	    AP.NIVEL_PRECIO                                           AS NIVEL_PRECIO
	   ,AP.ARTICULO                                               AS ARTICULO
	   ,CONCAT(ART.ARTICULO,' | ',ART.DESCRIPCION)                AS COD_NOMBRE_ARTICULO 
	  											                         
	   ,ART.CLASIFICACION_2                                       AS ID_CASA
	   ,CONCAT(ART.CLASIFICACION_2,' | ',CLAS2.DESCRIPCION)       AS CASA

	   ,ART.CLASIFICACION_1                                       AS ID_SUBCASA
	   ,CONCAT(ART.CLASIFICACION_1,' | ', CLAS1.DESCRIPCION)      AS SUBCASA

	   ,ART.CLASIFICACION_3                                       AS ID_CATEGORIA_ART
	   ,CONCAT(ART.CLASIFICACION_3,' | ',CLAS3.DESCRIPCION)       AS CATEGORIA_ART
	   
	   ,AP.PRECIO								                  AS PRECIO 
	   ,CONVERT(VARCHAR,AP.FECHA_INICIO,23)                       AS FECHA_INICIAL
	   ,CONVERT(VARCHAR,AP.FECHA_FIN,23)                          AS FECHA_FIN
FROM 
       EXACTUSERP.DIS86.ARTICULO        AS ART WITH(NOLOCK)
 JOIN  EXACTUSERP.DIS86.ARTICULO_PRECIO AS AP  WITH(NOLOCK) ON  AP.ARTICULO     = ART.ARTICULO    AND
                                                              ART.ACTIVO      = 'S'  
 JOIN  EXACTUSERP.DIS86.VERSION_NIVEL   AS VN  WITH(NOLOCK) ON  AP.NIVEL_PRECIO = VN.NIVEL_PRECIO AND 
                                                              AP.MONEDA       = VN.MONEDA       AND 
															  AP.VERSION      = VN.VERSION      AND 
															  VN.ESTADO       = 'A'
JOIN   EXACTUSERP.DIS86.NIVEL_PRECIO    AS NP  WITH(NOLOCK) ON  AP.MONEDA       = NP.MONEDA       AND 
                                                              AP.NIVEL_PRECIO = NP.NIVEL_PRECIO  
JOIN   EXACTUSERP.DIS86.CLASIFICACION  AS CLAS2 WITH(NOLOCK) ON CLAS2.CLASIFICACION = ART.CLASIFICACION_2
LEFT JOIN   EXACTUSERP.DIS86.CLASIFICACION  AS CLAS3 WITH(NOLOCK) ON CLAS3.CLASIFICACION = ART.CLASIFICACION_3
JOIN   EXACTUSERP.DIS86.CLASIFICACION  AS CLAS1 WITH(NOLOCK) ON CLAS1.CLASIFICACION = ART.CLASIFICACION_1
WHERE  ART.ACTIVO           =  'S'
AND    ART.ARTICULO       <> 'ND'
--AND    ART.CLASIFICACION_3  =  'MLP'
AND    VN.ESTADO            =  'A'






GO
