CREATE view [DIS86].[CREAR_CLIENTE_DESDE_CLIENTE_PLANTILLA]
as
SELECT 
	U.USUARIO_EXACTUSERP 	CLIENTE, 
	P.NOMBRE, 
	U.USUARIO ALIAS, 
	P.CONTACTO, CARGO,
	DIRECCION, 
	DIR_EMB_DEFAULT, 
	UA.TELEFONO 	TELEFONO1,
	P.TELEFONO2, 
	P.  FAX,
	UA.IDENTIFICACION  CONTRIBUYENTE,
	FECHA_INGRESO, MULTIMONEDA, MONEDA, SALDO, SALDO_LOCAL, SALDO_DOLAR, SALDO_CREDITO, SALDO_NOCARGOS, 
	EXCEDER_LIMITE, TASA_INTERES, TASA_INTERES_MORA, FECHA_ULT_MORA, FECHA_ULT_MOV, 
	P.CONDICION_PAGO, NIVEL_PRECIO, DESCUENTO, 
    MONEDA_NIVEL, ACEPTA_BACKORDER, 
	P.PAIS, 
	 ZONA, 
	ISNULL(UA.RUTA,'ND')RUTA, 
	'V001' VENDEDOR, P.COBRADOR, ACEPTA_FRACCIONES, U.ACTIVO, EXENTO_IMPUESTOS, 
	EXENCION_IMP1, EXENCION_IMP2, COBRO_JUDICIAL, CATEGORIA_CLIENTE, CLASE_ABC, DIAS_ABASTECIMIEN, USA_TARJETA, 
	P.  E_MAIL, 
	UA.CORREO, 
	CASE P.CONDICION_PAGO WHEN 0 THEN 'N' ELSE 'S' END REQUIERE_OC, 
	ES_CORPORACION, REGISTRARDOCSACORP, USAR_DIREMB_CORP, 
         APLICAC_ABIERTAS, VERIF_LIMCRED_CORP, USAR_DESC_CORP, DOC_A_GENERAR, 
		 TIENE_CONVENIO, NOTAS, DIAS_PROMED_ATRASO,  ASOCOBLIGCONTFACT,  USAR_PRECIOS_CORP, 
         USAR_EXENCIMP_CORP,  AJUSTE_FECHA_COBRO, CLASE_DOCUMENTO, LOCAL, 
		 TIPO_CONTRIBUYENTE,  
		 MODELO_RETENCION, ACEPTA_DOC_ELECTRONICO, CONFIRMA_DOC_ELECTRONICO, 
          ACEPTA_DOC_EDI, NOTIFICAR_ERROR_EDI,  CODIGO_IMPUESTO, 
		  P. DIVISION_GEOGRAFICA1, 
		  P. DIVISION_GEOGRAFICA2,  
		  P. DIVISION_GEOGRAFICA3, 
		  P. DIVISION_GEOGRAFICA4,
		  MOROSO, MODIF_NOMB_EN_FAC, 
		  SALDO_TRANS, SALDO_TRANS_LOCAL, 
		  SALDO_TRANS_DOLAR, 
		  PERMITE_DOC_GP, 
		  PARTICIPA_FLUJOCAJA,  
		  USUARIO_CREACION, 
		  FECHA_HORA_CREACION,
		  DETALLAR_KITS,
		  ISNULL(P.OTRAS_SENAS,'SIN OTRAS SEÑAS')OTRAS_SENAS, 
		  USA_API_RECEPCION,  
		  P.TIPO_IMPUESTO, --P.TIPO_IMPUESTO, 
		  P.TIPO_TARIFA,
		  PORC_TARIFA, TIPIFICACION_CLIENTE, AFECTACION_IVA, ES_EXTRANJERO,  
		  --TL.CLIENTE U_PRODUSOFT_CLIENTE_HUBSPOT,
		  '01' TIPO_IDENTIFICACION
FROM	EXACTUSERP.DIS86.CLIENTE							P   
		,[GLOBAL].USUARIO U
		LEFT JOIN [GLOBAL].USUARIO_ADICIONALES UA ON U.USUARIO = UA.USUARIO
where	
		P.cliente = 'CL09999'--CONTADO
GO
