/****** Object:  View [DIS86].[PS_EXACTUSERP_INS_AUXILIAR_CC]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO




create VIEW [DIS86].[PS_EXACTUSERP_INS_AUXILIAR_CC]
AS
SELECT 
	 
	   RD.[TIPO_CREDITO]			                          AS  [TIPO_CREDITO]
      ,RD.[TIPO_DEBITO]				                          AS [TIPO_DEBITO]
      ,GETDATE()		                                      AS [FECHA]
	  ,RD.[CREDITO]					                          AS [CREDITO] 
      ,RD.[DEBITO]					                          AS [DEBITO]
	  ,RD.MONTO_PAGO				                          AS [MONTO_DEBITO] 
      ,RD.MONTO_PAGO				                          AS [MONTO_CREDITO]
	  ,RD.MONTO_PAGO						                  AS [MONTO_LOCAL]
	  ,ROUND(RD.MONTO_PAGO / R.TIPO_CAMBIO,4)                 AS  MONTO_DOLAR
	  ,CASE 
	    WHEN R.MONEDA = 'USD' AND R.MONEDA_CLIENTE = 'USD' 
	       THEN ROUND(RD.MONTO_PAGO / R.TIPO_CAMBIO,4)
	    ELSE RD.MONTO_PAGO 
	       END											      AS [MONTO_CLI_CREDITO]
	  ,''													  AS [ASIENTO]
	  ,CASE 
	    WHEN R.MONEDA = 'USD' AND R.MONEDA_CLIENTE = 'USD' 
	       THEN ROUND(RD.MONTO_PAGO / R.TIPO_CAMBIO,4)
	    ELSE RD.MONTO_PAGO
	       END											      AS [MONTO_CLI_DEBITO]
	  ,R.[MONEDA]											  AS [MONEDA_CREDITO]
      ,DEB.MONEDA											  AS [MONEDA_DEBITO]		 
      ,C.[CLIENTE]                                            AS [CLI_REPORTE_CREDIT]
      ,C.[CLIENTE]                                            AS [CLI_REPORTE_DEBITO]
      ,C.[CLIENTE]                                            AS [CLI_DOC_CREDIT]
      ,C.[CLIENTE]                                            AS [CLI_DOC_DEBITO]
	  ,''[FOLIOSAT_DEBITO]
      ,''[FOLIOSAT_CREDITO]
	  ,1 [TIPO_CAMBIO_APLICA]
	  ,'N' [ES_INT_CORRIENTE]
	  ,RD.[ID_DOC_DETALLE]								      AS [ID_DOC_DETALLE]
	  ,RD.[COD_DOCUMENTO]									  AS [ID_DOCUMENTO]
	  
FROM [DIS86].[DOCUMENTOS_DET]           RD  (NOLOCK)
JOIN [DIS86].[DOCUMENTOS]               R   (NOLOCK) ON R.CODIGO      = RD.COD_DOCUMENTO
JOIN [EXACTUSERP].[DIS86].[MONEDA]        M   (NOLOCK) ON R.MONEDA      = M.MONEDA
JOIN [EXACTUSERP].[DIS86].[CLIENTE]       C   (NOLOCK) ON C.CLIENTE     = R.CLIENTE
JOIN [EXACTUSERP].[DIS86].[DOCUMENTOS_CC] DEB (NOLOCK) ON DEB.DOCUMENTO = RD.DEBITO



GO
/****** Object:  View [DIS86].[PS_EXACTUSERP_INS_DOCUMENTOS_CC]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [DIS86].[PS_EXACTUSERP_INS_DOCUMENTOS_CC]
AS 
SELECT 				 
		 R.DOCUMENTO					   AS DOCUMENTO
		,R.TIPO_DOC						   AS TIPO
		,R.CONCEPTO						   AS APLICACION
		,CONVERT(DATE, GETDATE())		   AS FECHA_DOCUMENTO
		,R.FECHA 
		,R.MONTO_PAGO					   AS MONTO
		,R.MONTO_PAGO					   AS SALDO
	    ,R.MONTO_PAGO					   AS MONTO_LOCAL
		,R.MONTO_PAGO					   AS SALDO_LOCAL
		,CASE
			WHEN R.MONEDA = 'USD' AND R.MONEDA_CLIENTE = 'USD'
				THEN ROUND(R.MONTO_PAGO / R.TIPO_CAMBIO,4)  
			ELSE ROUND(R.MONTO_PAGO / R.TIPO_CAMBIO,4) 
		 END							    AS MONTO_DOLAR
		,CASE
			WHEN R.MONEDA = 'USD' AND R.MONEDA_CLIENTE = 'USD'
				THEN ROUND(R.MONTO_PAGO / R.TIPO_CAMBIO,4) 
			ELSE ROUND(R.MONTO_PAGO / R.TIPO_CAMBIO,4) 
		 END							     AS SALDO_DOLAR
		,R.MONTO_PAGO					     AS MONTO_CLIENTE
		,R.MONTO_PAGO					     AS SALDO_CLIENTE
		,1 TIPO_CAMBIO_MONEDA
		,R.TIPO_CAMBIO					     AS TIPO_CAMBIO_DOLAR	   
		,1 TIPO_CAMBIO_CLIENT
		,1 TIPO_CAMB_ACT_LOC	   
		,R.TIPO_CAMBIO					     AS TIPO_CAMB_ACT_DOL
		,1 TIPO_CAMB_ACT_CLI
		,R.MONTO_PAGO					     AS SUBTOTAL
	    ,0 DESCUENTO
		,0 IMPUESTO1
		,0 IMPUESTO2
		,0 RUBRO1
		,0 RUBRO2
		,0 MONTO_RETENCION 
		,0 SALDO_RETENCION 
		,CASE 
			WHEN R.TIPO_DOC IN('FAC','N/C')  
				THEN 'S' 
			ELSE 'N' 
				END							 AS   DEPENDIENTE
		,CASE 
			WHEN R.TIPO_DOC IN('TEF','REC') 
				THEN R.FECHA 
			ELSE '1980-01-01 00:00:00.000' 
				END							 AS FECHA_ULT_CREDITO
		,'N' CARGADO_DE_FACT
		,'S' APROBADO
		,'S' ASIENTO_PENDIENTE
		,GETDATE() FECHA_ULT_MOD
		,R.NOTAS  NOTAS
		,'N' CLASE_DOCUMENTO
		,CONVERT(DATE, GETDATE())			 AS  FECHA_VENCE
	    ,0 NUM_PARCIALIDADES
		,R.COBRADOR							 AS COBRADOR
		,R.USUARIO_CREACION			         AS USUARIO_ULT_MOD
		,C.CONDICION_PAGO
		,R.MONEDA MONEDA 
		,CB.CUENTA_BANCO 
		,R.VENDEDOR    							 AS VENDEDOR
		,C.CLIENTE							 AS CLIENTE_REPORTE
		,C.CLIENTE							 AS CLIENTE_ORIGEN
		,C.CLIENTE							 AS CLIENTE
		,R.SUBTIPO
	    ,0 PORC_INTCTE	
		,NULL [AUD_USUARIO_ANUL]
		,R.NUM_DOC_CB
		,R.USUARIO_CREACION					 AS [USUARIO_APROBACION]
		,CONVERT(DATE, GETDATE())			 AS FECHA_APROBACION
		,'N' ANULADO
		,CODIGO_IMPUESTO 
		,C.PAIS								 AS PAIS
		, C.DIVISION_GEOGRAFICA1			 AS DIVISION_GEOGRAFICA1
		, C.DIVISION_GEOGRAFICA2			 AS DIVISION_GEOGRAFICA2
		, R.MONTO_PAGO						 AS BASE_IMPUESTO1
		, R.MONTO_PAGO						 AS BASE_IMPUESTO2
		,'N' DEPENDIENTE_GP
		,0 SALDO_TRANS
		,0 SALDO_TRANS_LOCAL 
		,0 SALDO_TRANS_DOLAR 
		,'CC' TIPO_ASIENTO
		,'CC' PAQUETE
		,0 SALDO_TRANS_CLI
		,'N' FACTURADO 
		,'S' GENERA_DOC_FE 
		,R.ENTIDAD_FINANCIERA				  AS ENTIDAD_FINANCIERA
		,'' CLAVE_DE
	    ,NULL TIPO_IMPUESTO1
		,NULL TIPO_IMPUESTO2
		,NULL TIPO_TARIFA1
		,NULL TIPO_TARIFA2
		,'519003' ACTIVIDAD_COMERCIAL
		,'N' ES_FACTURA_REEMPLAZO
		,'N' TIENE_RELACIONADOS
	    ,0 PORC_DETRAC
		,'N' TIENE_COMPLEMENTO
		, 0 IMPUESTO_BOLSA
		, R.CODIGO							   AS ID_DOCUMENTO
		
FROM 
          [DIS86].[DOCUMENTOS]                 R   (NOLOCK)
     JOIN [EXACTUSERP].[DIS86].[CLIENTE]         C   (NOLOCK) ON C.CLIENTE      = R.CLIENTE
     JOIN [EXACTUSERP].[DIS86].[MONEDA]          M   (NOLOCK) ON R.MONEDA       = M.MONEDA
     JOIN [EXACTUSERP].[DIS86].[COBRADOR]        CBR   (NOLOCK) ON CBR.COBRADOR = R.COBRADOR
LEFT JOIN [EXACTUSERP].[DIS86].[CUENTA_BANCARIA] CB  (NOLOCK) ON M.MONEDA       = CB.MONEDA   AND CB.CUENTA_BANCO = R.CUENTA_BANCO 
LEFT JOIN [EXACTUSERP].[DIS86].[SUBTIPO_DOC_CC]  DCC (NOLOCK) ON DCC.SUBTIPO    = R.SUBTIPO   AND DCC.TIPO        = R.TIPO_DOC 
--LEFT JOIN [EXACTUSERP].[DIS86].[SUBTIPO_DOC_CB]  DCB (NOLOCK) ON DCC.SUBTIPO_CB = DCB.SUBTIPO AND DCC.SUBTIPO     <> 0 
--WHERE R.DOCUMENTO = 'C001|00000136'

GO
/****** Object:  View [DIS86].[PS_VIEW_CALCULO_INTERES_DOCUMENTOS]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- Jala la fecha de última mora y la tasa de interés de la mora
CREATE VIEW [DIS86].[PS_VIEW_CALCULO_INTERES_DOCUMENTOS]
AS
SELECT 
    C.cliente,
    C.nombre,
    C.fecha_ult_mora,
    C.tasa_interes_mora,
    D.tipo,
    D.documento,
    D.fecha,
    D.fecha_vence,
    D.monto_cliente,
    D.saldo_cliente,
    D.monto,
    D.moneda,
    D.contrarecibo,
    D.asiento,
    C.alias,
    C.categoria_cliente,
    C.pais,
    C.contribuyente,
    C.dias_promed_atraso,
    SDC.descripcion,
    D.aplicacion,
    D.subtotal,
    D.descuento,
    D.impuesto1,
    D.impuesto2,
    D.rubro1,
    D.rubro2,
    D.monto_retencion,
    D.saldo_retencion,
    P.dias_neto,
    D.vendedor,
    D.cobrador,
	(D.SALDO * C.TASA_INTERES_MORA/100) / (30 * 1) CALCULO_INTERES -- Tomar el valor del excel
FROM 
    exactusERP.DIS86.cliente C (NOLOCK),
    exactusERP.DIS86.documentos_cc D (NOLOCK),
    exactusERP.DIS86.condicion_pago P (NOLOCK),
    exactusERP.DIS86.subtipo_doc_cc SDC (NOLOCK)
WHERE 
        D.cliente = C.cliente
    AND D.tipo = SDC.tipo
    AND D.subtipo = SDC.subtipo
    AND D.condicion_pago = P.condicion_pago
    --AND C.fecha_ult_mora < '2025-09-03 23:59:59.998' -- fECHA QUE SE VA SOLICITAR PARA INICIAR EL PROCESO, PONER LA HORA QUE SE ESTA CORRIENDO
    AND C.tasa_interes_mora <> 0
    AND D.tipo IN ('B/V', 'F/C', 'FAC', 'L/C', 'N/D', 'O/D', 'PER', 'RED', 'RHP')
    --AND (
    --        (D.saldo = 0 AND D.fecha_ult_credito > '2025-09-03 00:00:00.000')
    --     OR (D.saldo <> 0)
    --    )
    --AND D.fecha_vence < '2025-09-03 23:59:59.998'
    AND D.aplicacion <> 'Interés de Mora'
	AND C.SALDO > 0
	and D.MONEDA = 'CRC'
GO
/****** Object:  View [DIS86].[PS_VIEW_CALCULO_INTERES_DOCUMENTOS_TOTAL_CLIENTE]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [DIS86].[PS_VIEW_CALCULO_INTERES_DOCUMENTOS_TOTAL_CLIENTE]
AS
SELECT ACC.CLIENTE, 
	SUM(acc.CALCULO_INTERES) INTERES_TOTAL
FROM DIS86.PS_VIEW_CALCULO_INTERES_DOCUMENTOS acc
GROUP BY acc.CLIENTE
GO
