	[CARGADO_CB] [varchar](2) NULL,
	[SE_INSERTO_EN_MOV_REPORTADOS] [varchar](1) NULL,
	[NoteExistsFlag] [tinyint] NULL,
	[RecordDate] [datetime] NULL,
	[RowPointer] [uniqueidentifier] NULL,
	[CreatedBy] [varchar](30) NULL,
	[UpdatedBy] [varchar](30) NULL,
	[CreateDate] [datetime] NULL,
	[PS_20_REFERENCIA] [varchar](100) NULL,
	[PS_25_NUMERO_CUENTA] [varchar](100) NULL,
	[PS_28C_ESTADO_SECUENCIA] [varchar](50) NULL,
