  CREATE VIEW [DIS86].[VIEW_OBT_TOTAL_LINEA_PEDIDO] 
  AS 

  SELECT ROW_NUMBER() OVER (Order by PED.PEDIDO) AS ID,
         PEDIDO,
         PEDIDO_LINEA, 
         ARTICULO_EXACTUSERP, 
		 ART.DESCRIPCION, 
		 CANTIDAD, 
		 ISNULL(EXISTENCIA,0) EXISTENCIA, 
		 PRECIO_UNITARIO,
		 CASE WHEN ES_BONIFICADO = 'S' THEN 0  
		 ELSE ISNULL(PORC_DESCUENTO,0) END PORC_DESCUENTO, 
		 CASE WHEN ES_BONIFICADO ='S'  THEN 0  ELSE  ((CANTIDAD * PRECIO_UNITARIO) * ISNULL(PORC_DESCUENTO,0)) END MONTO_DCTO,
		 CASE WHEN ES_BONIFICADO ='S'  THEN '13'  ELSE '13' END IVA,
		 CASE WHEN ES_BONIFICADO ='S'  THEN ((CANTIDAD * PRECIO_UNITARIO)-((CANTIDAD * PRECIO_UNITARIO) * ISNULL(PORC_DESCUENTO,0))) * 0.13  ELSE  ((CANTIDAD * PRECIO_UNITARIO)-((CANTIDAD * PRECIO_UNITARIO) * ISNULL(PORC_DESCUENTO,0))) * 0.13 END MONTO_IVA,
		 CASE WHEN ES_BONIFICADO ='S'  THEN 0  ELSE ((CANTIDAD * PRECIO_UNITARIO)-((CANTIDAD * PRECIO_UNITARIO) * ISNULL(PORC_DESCUENTO,0))) END SUBTOTAL,
		 CASE WHEN ES_BONIFICADO ='S'  THEN 0  ELSE ((CANTIDAD * PRECIO_UNITARIO)-((CANTIDAD * PRECIO_UNITARIO) * ISNULL(PORC_DESCUENTO,0))) +(((CANTIDAD * PRECIO_UNITARIO)-((CANTIDAD * PRECIO_UNITARIO) * ISNULL(PORC_DESCUENTO,0))) * 0.13) END TOTAL
  FROM [PS_TRACKING].[DIS86].[PEDIDO_LINEA] AS PED 
  INNER JOIN EXACTUSERP.DIS86.ARTICULO AS ART ON PED.ARTICULO_EXACTUSERP = ART.ARTICULO
 -- WHERE PEDIDO ='245'





GO
