CREATE VIEW [DIS86].[VIEW_OBT_VISITAS]
AS 
SELECT 
      VTA.CLIENTE AS COD_CLIENTE
	  ,CLI.NOMBRE NOM_CLIENTE
	  ,CLI.ALIAS
	  ,VTA.VENDEDOR COD_VENDEDOR
	  ,VEN.NOMBRE NOM_VENDEDOR
	  --,CONVERT(VARCHAR,VTA.FECHA_VISITA,105) FECHA_VISITA
	  ,CONVERT(varchar,VTA.FECHA_VISITA,23) FECHA_VISITA
	  ,VTA.RUTA 
	  ,RTA.DESCRIPCION
	  ,PROV.NOMBRE PROVINCIA
	  ,VTA.ESTADO_VISITA
      ,VTA.DOCUMENTO
	  ,ISNULL(TOTAL_A_FACTURAR,0) TOTAL_A_FACTURAR
	  ,VTA.COMENTARIO
	  ,COLOR_HEXA
	  ,VTA.SEMANA
	  ,VTA.DIA
	  ,VTA.TIPO_VISITA
	  ,VTA.LATITUD
	  ,VTA.LONGITUD
	  ,SUBSTRING(CONVERT(varchar, VTA.FECHA_CREACION, 108), 1, 8) AS HORA
	  ,VTA.DIRECCION
	  ,VTA.ID_VISITA
   FROM [PS_TRACKING].[DIS86].[VISITAS]     AS VTA
  INNER JOIN EXACTUSERP.DIS86.CLIENTE              AS CLI  ON VTA.CLIENTE = CLI.CLIENTE 
  INNER JOIN EXACTUSERP.DIS86.VENDEDOR             AS VEN  ON VTA.VENDEDOR = VEN.VENDEDOR 
  INNER JOIN EXACTUSERP.DIS86.RUTA                 AS RTA  ON VTA.RUTA = RTA.RUTA
  INNER JOIN DIS86.COLOR_ESTADO_VISITA           AS COL  ON COL.ESTADO_VISITA = VTA.ESTADO_VISITA
  LEFT  JOIN EXACTUSERP.DIS86.PEDIDO               AS PED  ON VTA.DOCUMENTO = PED.PEDIDO
  LEFT  JOIN EXACTUSERP.DIS86.DIVISION_GEOGRAFICA1 AS PROV ON CLI.DIVISION_GEOGRAFICA1 = PROV.DIVISION_GEOGRAFICA1
GO
