SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO





CREATE VIEW [DIS86].[VIEW_TRACKING]
AS 
SELECT 
        ROW_NUMBER() OVER (Order by PD.PEDIDO)             AS ID,
		PD.PEDIDO, 
		CONVERT(VARCHAR(800),PD.OBSERVACIONES)             AS OBSERVACIONES ,
		ISNULL(PD.U_TLA_ESTADO,'N')					       AS TLA_ESTADO,
		PD.USUARIO,
		CONVERT(varchar,PD.U_TI_TLA_RECIBIDO,20)           AS FECHA_HORA_RECIBIDO,
	 	CONVERT(varchar,PD.FECHA_HORA,23)	               AS FECHA_PEDIDO,
		convert(varchar,PD.FECHA_PROYECTADA,23)	           AS DIA_RUTA,

		ISNULL(PD.U_PS_TRACKING_ESTADO_PEDIDO,1)		   AS ESTADO_PEDIDO, 
		ISNULL(E.DESCRIPCION,'Sin Asignar')				   AS ESTADO_PEDIDO_DESCRIPCION,
		PD.RUTA+' - '+RT.DESCRIPCION	                   AS RUTA,
		PD.RUTA                                            AS COD_RUTA,
		RT.DESCRIPCION	                                   AS RUTA_NOMBRE,
		FAC.FACTURA, 
		RT.U_HORA_CORTE+':00'                              AS TIEMPO,
		ISNULL(FAC.U_PS_TRACKING_ESTADO_FACTURA,1)         AS SEGUIR_FAC, 
		ISNULL(F.DESCRIPCION,'Sin Asignar')				   AS SEGUIR_FAC_DESCRIPCION,
		ISNULL(CANTIDAD_SEGUIMIENTO,0)                     AS SUCESOS, -- JHONNY LO ELIMINO DE INTERFAZ. 
		CL.CLIENTE + ' - ' + CL.ALIAS                      AS CLIENTE, 
		U_TIPO_ENTREGA                                     AS TIPO_CORTE,
		CL.CLIENTE                                         AS COD_CLIENTE,
		CL.ALIAS	                                       AS CLIENTE_NOMBRE, 
		VEN.VENDEDOR+' - '+VEN.NOMBRE	                   AS AGENTE, 
		VEN.VENDEDOR                                       AS COD_VENDEDOR,
		VEN.NOMBRE                                         AS AGENTE_NOMBRE,
		--RT.U_LUNES, 
		--RT.U_MARTES, 
		--RT.U_MIERCOLES, 
		--RT.U_JUEVES, 
		--RT.U_VIERNES, 
		--RT.U_SABADO,
		 
		 ISNULL(RT.U_DIAS_RUTA,'')									  AS DIAS
		,CASE WHEN CL.CONDICION_PAGO='1' THEN 'CONTADO' ELSE 'CRÉDITO'END CONDICION_PAGO
		,CASE WHEN DATEDIFF(DD,PD.U_TI_TLA_RECIBIDO,GETDATE())>0 THEN '1' ELSE
		 CASE WHEN (ISNULL(CONVERT(CHAR(5),PD.U_TI_TLA_RECIBIDO,108),'00:00') <= RT.U_HORA_CORTE+':00') 
		AND PD.U_TLA_ESTADO NOT IN('N') THEN '1' ELSE '2' END END  AS HORA_FUERA_ENCORTE
		,ISNULL(CONVERT(CHAR(5),PD.U_TI_TLA_RECIBIDO,108),'00:00') HORA_RECIBIDO_TLA
		,RT.U_HORA_CORTE+':00' HORA_CORTE
		,DATEDIFF(DD,PD.U_TI_TLA_RECIBIDO,GETDATE())  DIAS_DE_CREADO_PEDIDO
		,PD.CreateDate
		,ISNULL(E.COLOR_HEXA,'label-light-dark') COLOR_HEXA_PED
		,ISNULL(F.COLOR_HEXA,'label-light-dark') COLOR_HEXA_FAC
		,CB.COBRADOR
		,convert(varchar,FAC.U_TI_CXC_RECIBE,23)  U_TI_CXC_RECIBE
FROM 
			EXACTUSERP.DIS86.PEDIDO			PD  WITH(NOLOCK)
JOIN		EXACTUSERP.DIS86.RUTA				RT  WITH(NOLOCK) ON PD.RUTA				= RT.RUTA
JOIN		EXACTUSERP.DIS86.CLIENTE			CL	WITH(NOLOCK) ON PD.CLIENTE			= CL.CLIENTE
JOIN        EXACTUSERP.DIS86.COBRADOR         CB  WITH(NOLOCK) ON CL.COBRADOR         = CB.COBRADOR
LEFT JOIN	EXACTUSERP.DIS86.FACTURA			FAC WITH(NOLOCK) ON PD.PEDIDO			= FAC.PEDIDO AND FAC.TIPO_DOCUMENTO = 'F'
JOIN	    EXACTUSERP.DIS86.VENDEDOR			VEN WITH(NOLOCK) ON CL.VENDEDOR			= VEN.VENDEDOR
LEFT JOIN	PS_TRACKING.DIS86.ESTADO_PEDIDO	E	WITH(NOLOCK) ON PD.U_PS_TRACKING_ESTADO_PEDIDO	= E.ESTADO_PEDIDO
LEFT JOIN	PS_TRACKING.DIS86.ESTADO_FACTURA_SEGUIMIENTO F	WITH(NOLOCK) ON FAC.U_PS_TRACKING_ESTADO_FACTURA	= F.ESTADO_FACTURA_SEGUIMIENTO	
LEFT JOIN  (select CASE WHEN ISNULL(COUNT(ID_SEG.PEDIDO),'0') <> '0'  THEN '1' ELSE '0' END AS CANTIDAD_SEGUIMIENTO,ID_SEG.PEDIDO from PS_TRACKING.DIS86.SEGUIMIENTO ID_SEG GROUP BY ID_SEG.PEDIDO) AS SEG ON SEG.PEDIDO= PD.PEDIDO
WHERE PD.ESTADO IN('A','B','F') AND 
      PD.AUTORIZADO IN('N','S')
	  AND PD.CreateDate > '2025-01-01'



GO
/****** Object:  View [DIS86].[VIEW_OBTENER_COD_PEDIDO]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
