/****** Object:  View [DIS86].[VIEW_OBTENER_LISTA_USUARIO_MANTENIMIENTO]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE VIEW [DIS86].[VIEW_OBTENER_LISTA_USUARIO_MANTENIMIENTO] 
AS 
				SELECT TOP 10000
				       US.USUARIO,
				       USAD.IDENTIFICACION,
				       USAD.NOMBRE,
				       ''COD_JEFE,
				       ''NOM_JEFE,
				       RL.DESCRIPCION,
				       US.ROL,
				       US.ACTIVO
					   ,ISNULL(USAD.VENDEDOR,'V001')                AS VENDEDOR
				       ,ISNULL(VEN.NOMBRE,'Administrativo')         AS NOM_VENDEDOR 
					   ,ISNULL(USAD.COBRADOR,'C001')                AS COBRADOR
				       ,ISNULL(COB.NOMBRE,'Administrativo')         AS NOM_COBRADOR
					   ,ISNULL(USAD.BODEGA,'01')                    AS COD_BODEGA
					   ,ISNULL(BOD.NOMBRE,'Producto para la Venta') AS  NOM_BODEGA

				FROM 
				           [GLOBAL].USUARIO              AS US 
				INNER JOIN [GLOBAL].ROL                  AS RL   ON US.ROL        = RL.ROL
				INNER JOIN [GLOBAL].USUARIO_ADICIONALES  AS USAD ON US.USUARIO  = USAD.USUARIO
				LEFT  JOIN EXACTUSERP.DIS86.VENDEDOR       AS VEN  ON VEN.VENDEDOR = USAD.VENDEDOR
				LEFT  JOIN EXACTUSERP.DIS86.COBRADOR       AS COB  ON COB.COBRADOR = USAD.COBRADOR
				LEFT JOIN  EXACTUSERP.DIS86.BODEGA         AS BOD  ON BOD.BODEGA = USAD.BODEGA
				ORDER BY NOMBRE



GO
