/****** Object:  View [DIS86].[VIEW_OBTENER_SEGUIMIENTO]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE VIEW [DIS86].[VIEW_OBTENER_SEGUIMIENTO]
AS 
select  SEG.SEGUIMIENTO
       ,PED.PEDIDO
	   ,FAC.FACTURA
       ,ISNULL(ESTADO_PEDIDO,1) ESTADO_PEDIDO
	   --,CASE WHEN ESTADO_PEDIDO =  1 THEN 'Sin Asignar' 
	   --      WHEN ESTADO_PEDIDO =  2 THEN 'En Reparto' 
			 --WHEN ESTADO_PEDIDO =  3 THEN 'Entregado' 
			 --WHEN ESTADO_PEDIDO =  4 THEN 'Rechazado' 
			 --WHEN ESTADO_PEDIDO =  5 THEN 'Vuelve a Salir' 
			 --WHEN ESTADO_PEDIDO =  6 THEN 'Cancelado'
			 --WHEN ESTADO_PEDIDO =  7 THEN 'Envío sin Factura(Carta)'
			 --WHEN ESTADO_PEDIDO =  8 THEN 'Pedido para OVAS'
			 --WHEN ESTADO_PEDIDO IS NULL THEN 'Sin Asignar'
	   --      END ESTADO_PEDIDO_DESCRIPCION
	     ,ISNULL((SELECT DESCRIPCION FROM DIS86.ESTADO_PEDIDO WHERE ESTADO_PEDIDO = SEG.ESTADO_PEDIDO),'Sin Asignar') ESTADO_PEDIDO_DESCRIPCION
        ,[ESTADO_FACTURA_SEGUIMIENTO]
	  --  ,CASE WHEN ESTADO_FACTURA_SEGUIMIENTO =	1 THEN 'Sin Asignar' 
	  --        WHEN ESTADO_FACTURA_SEGUIMIENTO =	2 THEN 'DIS86 a TLA' 
			--  WHEN ESTADO_FACTURA_SEGUIMIENTO =	3 THEN 'TLA a DIS86' 
			--  WHEN ESTADO_FACTURA_SEGUIMIENTO =	4 THEN 'DIS86 a CxC' 
			--  WHEN ESTADO_FACTURA_SEGUIMIENTO =	5 THEN 'CxC Recibe' 
			--  WHEN ESTADO_FACTURA_SEGUIMIENTO =	6 THEN 'Cobrador Recibe' 
			--  WHEN ESTADO_FACTURA_SEGUIMIENTO = 7 THEN 'Refacturada' 
			--  WHEN ESTADO_FACTURA_SEGUIMIENTO = 8 THEN 'Trámite'
			--  WHEN ESTADO_FACTURA_SEGUIMIENTO = 9 THEN 'Factura Posterior'
			--  WHEN ESTADO_FACTURA_SEGUIMIENTO = 10 THEN 'Anulada con NC'
		 --END SEGUIR_FAC_DESCRIPCION 
		 ,ISNULL((SELECT DESCRIPCION FROM DIS86.ESTADO_FACTURA_SEGUIMIENTO WHERE ESTADO_FACTURA_SEGUIMIENTO = SEG.ESTADO_FACTURA_SEGUIMIENTO),'Sin Asignar') AS SEGUIR_FAC_DESCRIPCION
		,TLA AS TLA_ESTADO
		,SEG.[USUARIO]
		,CONVERT(VARCHAR,SEG.FECHA_CREACION,20) AS MODIFICA
		,[SUCESO]
		,SEG.[OBSERVACIONES]
		,SEG.FECHA_CREACION
		,CONVERT(varchar,PED.U_TI_TLA_RECIBIDO,20) AS FECHA_HORA_RECIBIDO
		,CONVERT(varchar,PED.FECHA_HORA,23)	     AS FECHA_PEDIDO
		,PED.RUTA +' - '+ RTA.DESCRIPCION AS  RUTA
		,PED.RUTA AS COD_RUTA
		,CLI.CLIENTE + ' - ' + CLI.ALIAS AS CLIENTE
		,CLI.CLIENTE AS COD_CLIENTE
		,VEN.VENDEDOR +' - '+ VEN.NOMBRE	AS AGENTE 
		,VEN.VENDEDOR AS COD_VENDEDOR
		,convert(varchar,PED.FECHA_PROYECTADA,23)	AS  DIA_RUTA
		,CASE WHEN CLI.CONDICION_PAGO='1' THEN 'CONTADO' ELSE 'CRÉDITO'END CONDICION_PAGO
		,CONVERT(VARCHAR,FAC.FECHA_HORA,20) AS FECHA_FACTURA
		,CASE WHEN SEGUIMIENTO IN(SELECT SEGUIMIENTO FROM DIS86.SEGUIMIENTO AS S (NOLOCK) WHERE CONVERT(VARCHAR,S.FECHA,20)=CONVERT(VARCHAR,S.FECHA_CREACION,20) and ESTADO_FACTURA_SEGUIMIENTO<>1) THEN NULL ELSE CONVERT(VARCHAR,SEG.FECHA,20) END FECHA_CAMBIA_ESTADO_PED
		--,CASE WHEN ESTADO_PEDIDO <>  1  THEN CONVERT(VARCHAR,SEG.FECHA,20) END FECHA_CAMBIA_ESTADO_PED 
		,CASE WHEN ESTADO_FACTURA_SEGUIMIENTO = 2  THEN CONVERT(VARCHAR,FECHA_CREACION,20) 
		      WHEN ESTADO_FACTURA_SEGUIMIENTO = 3  THEN CONVERT(VARCHAR,FECHA_CREACION,20)
			  WHEN ESTADO_FACTURA_SEGUIMIENTO = 4  THEN CONVERT(VARCHAR,FECHA_CREACION,20)
			  WHEN ESTADO_FACTURA_SEGUIMIENTO = 5  THEN CONVERT(VARCHAR,FECHA_CREACION,20)
			  WHEN ESTADO_FACTURA_SEGUIMIENTO IN (6,7,8,9,10)  THEN CONVERT(VARCHAR, FECHA_CREACION,20)
 	          ELSE NULL END FECHA_CAMBIA_ESTADO_FACTURA 
			  ,CBR.COBRADOR AS COD_COBRADOR
			  ,CBR.COBRADOR + ' - ' + CBR.NOMBRE AS COBRADOR
			  ,CONVERT(VARCHAR,CC.FECHA_VENCE,20) FECHA_VENCE
			  ,CONVERT(NUMERIC(28,2),TOTAL_FACTURA) TOTAL_FACTURA
			  ,CONVERT(NUMERIC(28,2),CC.SALDO) SALDO
			  ,ISNULL((SELECT COLOR_HEXA FROM DIS86.ESTADO_PEDIDO WHERE ESTADO_PEDIDO = SEG.ESTADO_PEDIDO),'label-light-dark') AS COLOR_HEXA_PED
	          ,ISNULL((SELECT COLOR_HEXA FROM DIS86.ESTADO_FACTURA_SEGUIMIENTO WHERE ESTADO_FACTURA_SEGUIMIENTO = SEG.ESTADO_FACTURA_SEGUIMIENTO),'label-light-dark') AS COLOR_HEXA_FAC
  FROM [PS_TRACKING].[DIS86].[SEGUIMIENTO] AS SEG WITH(NOLOCK)
   JOIN  EXACTUSERP.DIS86.PEDIDO        AS  PED WITH(NOLOCK) ON SEG.PEDIDO = PED.PEDIDO
   LEFT JOIN  EXACTUSERP.DIS86.FACTURA  AS  FAC WITH(NOLOCK) ON PED.PEDIDO = FAC.PEDIDO  AND FAC.TIPO_DOCUMENTO= 'F'
   JOIN  EXACTUSERP.DIS86.DOCUMENTOS_CC AS CC ON FAC.FACTURA = CC.DOCUMENTO AND CC.TIPO ='FAC' 
   JOIN  EXACTUSERP.DIS86.RUTA          AS  RTA WITH(NOLOCK) ON PED.RUTA = RTA.RUTA
   JOIN	 EXACTUSERP.DIS86.CLIENTE       AS  CLI WITH(NOLOCK) ON PED.CLIENTE	= CLI.CLIENTE
   JOIN	 EXACTUSERP.DIS86.VENDEDOR      AS  VEN WITH(NOLOCK) ON CLI.VENDEDOR= VEN.VENDEDOR
   JOIN EXACTUSERP.DIS86.COBRADOR       AS  CBR WITH(NOLOCK) ON CLI.COBRADOR = CBR.COBRADOR 
  -- where ped.PEDIDO ='REFAC0000749'
GO
