/****** Object:  View [DIS86].[VIEW_SEGUIMIENTO_TRACKING]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO





CREATE   VIEW [DIS86].[VIEW_SEGUIMIENTO_TRACKING]
AS 
SELECT  TOP 1000

		PD.PEDIDO, 
		PD.OBSERVACIONES,
		PD.U_TLA_ESTADO					TLA_ESTADO,
		PD.USUARIO,
		PD.U_TI_TLA_RECIBIDO  FECHA_HORA_RECIBIDO,
		convert(varchar,PD.FECHA_HORA,103)					FECHA_PEDIDO,
		convert(varchar,PD.FECHA_PROMETIDA,103)					DIA_RUTA,
		PD.U_PS_TRACKING_ESTADO_PEDIDO					ESTADO_PEDIDO, 
		E.DESCRIPCION					ESTADO_PEDIDO_DESCRIPCION,
		PD.RUTA+' - '+RT.DESCRIPCION	RUTA,

		FAC.FACTURA, 
		RT.U_HORA_CORTE+':00' AS TIEMPO,
		PD.U_PS_TRACKING_ESTADO_FACTURA SEGUIR_FAC, 
		F.DESCRIPCION					SEGUIR_FAC_DESCRIPCION,
		'' SUCESOS, -- JHONNY LO ELIMINO DE INTERFAZ. 
		
		CL.CLIENTE + ' - ' + CL.ALIAS	AS CLIENTE,  
		VEN.VENDEDOR+' - '+VEN.NOMBRE	AS AGENTE, 
		
		RT.U_LUNES, 
		RT.U_MARTES, 
		RT.U_MIERCOLES, 
		RT.U_JUEVES, 
		RT.U_VIERNES, 
		RT.U_SABADO,
		
		RT.U_DIAS_RUTA AS DIAS

FROM 
		EXACTUSERP.DIS86.PEDIDO			PD  WITH(NOLOCK)
JOIN	EXACTUSERP.DIS86.RUTA				RT  WITH(NOLOCK) ON PD.RUTA				= RT.RUTA
JOIN	EXACTUSERP.DIS86.CLIENTE			CL	WITH(NOLOCK) ON PD.CLIENTE			= CL.CLIENTE
LEFT JOIN	EXACTUSERP.DIS86.FACTURA			FAC WITH(NOLOCK) ON PD.PEDIDO			= FAC.PEDIDO 
JOIN	EXACTUSERP.DIS86.VENDEDOR			VEN WITH(NOLOCK) ON CL.VENDEDOR			= VEN.VENDEDOR
LEFT JOIN	PS_TRACKING.DIS86.ESTADO_PEDIDO	E	WITH(NOLOCK) ON PD.U_PS_TRACKING_ESTADO_PEDIDO	= E.ESTADO_PEDIDO
LEFT JOIN	PS_TRACKING.DIS86.ESTADO_FACTURA_SEGUIMIENTO	F	WITH(NOLOCK) ON PD.U_PS_TRACKING_ESTADO_FACTURA	= F.ESTADO_FACTURA_SEGUIMIENTO	
WHERE PD.ESTADO IN('A','B','F') 
AND PD.AUTORIZADO IN('N','S')

GO
/****** Object:  View [DIS86].[VIEW_SUBTABLA_SEGUIMIENTO_TRACKING]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO




CREATE VIEW  [DIS86].[VIEW_SUBTABLA_SEGUIMIENTO_TRACKING]
as 
select [SEGUIMIENTO]
      ,[ESTADO_PEDIDO]
	  ,CASE WHEN ESTADO_PEDIDO = 1 THEN 'Sin Asignar' 
	        WHEN ESTADO_PEDIDO = 2 THEN 'En Reparto' 
			WHEN ESTADO_PEDIDO = 3 THEN 'Entregado' 
			WHEN ESTADO_PEDIDO = 4 THEN 'Rechazado' 
			WHEN ESTADO_PEDIDO = 5 THEN 'Vuelve a Salir' 
	    END ESTADO_PEDIDO_DESCRIPCION
      ,[ESTADO_FACTURA_SEGUIMIENTO]
	   , CASE WHEN ESTADO_FACTURA_SEGUIMIENTO =	1 THEN 'Sin Asignar' 
	          WHEN ESTADO_FACTURA_SEGUIMIENTO =	2 THEN 'DIS86 a TLA' 
			  WHEN ESTADO_FACTURA_SEGUIMIENTO =	3 THEN 'TLA a DIS86' 
			  WHEN ESTADO_FACTURA_SEGUIMIENTO =	4 THEN 'DIS86 a CxC' 
			  WHEN ESTADO_FACTURA_SEGUIMIENTO =	5 THEN 'CxC Recibe' 
			  WHEN ESTADO_FACTURA_SEGUIMIENTO =	6 THEN 'Vendedor Recibe'  
		END SEGUIR_FAC_DESCRIPCION 
		,TLA TLAESTADO
      ,[USUARIO]
      ,[FECHA]
      ,[SUCESO]
      ,[OBSERVACIONES]
  FROM [PS_TRACKING].[DIS86].[SEGUIMIENTO]

GO
/****** Object:  View [DIS86].[VIEW_TRACKING_COBRADOR]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE VIEW [DIS86].[VIEW_TRACKING_COBRADOR]
AS 
SELECT 
		PD.PEDIDO, 
		CONVERT(VARCHAR(800),PD.OBSERVACIONES) AS OBSERVACIONES ,
	 	CONVERT(varchar,PD.FECHA_HORA,23)	      FECHA_PEDIDO,
		convert(varchar,PD.FECHA_PROYECTADA,23)	  DIA_RUTA,
		ISNULL(E.DESCRIPCION,'Sin Asignar')					 ESTADO_PEDIDO_DESCRIPCION,
		PD.RUTA+' - '+RT.DESCRIPCION	          RUTA,
		RT.DESCRIPCION	          RUTA_NOMBRE,
		FAC.FACTURA, 
		ISNULL(F.DESCRIPCION,'Sin Asignar')					SEGUIR_FAC_DESCRIPCION,
		convert(varchar, FAC.U_TI_CXC_RECIBE, 105) U_TI_CXC_RECIBE,
		CL.CLIENTE + ' - ' + CL.ALIAS AS CLIENTE, 
		CL.ALIAS	AS CLIENTE_NOMBRE, 
		VEN.VENDEDOR+' - '+VEN.NOMBRE	AS AGENTE, 
		CL.CONTRIBUYENTE,
		VEN.NOMBRE AS AGENTE_NOMBRE,
		--CASE WHEN CL.CONDICION_PAGO='1' THEN 'CONTADO' ELSE 'CRÉDITO'END CONDICION_PAGO,
		FAC.CONDICION_PAGO,
		CB.COBRADOR + ' - ' + CB.NOMBRE COBRADOR,
		FAC.TOTAL_FACTURA,
		--FAC.CONDICION_PAGO,
		FAC.FECHA_RIGE + CAST (FAC.CONDICION_PAGO AS INT) FECHA_VENCE
FROM 
			EXACTUSERP.DIS86.PEDIDO			PD  WITH(NOLOCK)
JOIN		EXACTUSERP.DIS86.RUTA				RT  WITH(NOLOCK) ON PD.RUTA				= RT.RUTA
JOIN		EXACTUSERP.DIS86.CLIENTE			CL	WITH(NOLOCK) ON PD.CLIENTE			= CL.CLIENTE
JOIN        EXACTUSERP.DIS86.COBRADOR         CB  WITH(NOLOCK) ON CL.COBRADOR         = CB.COBRADOR
LEFT JOIN	EXACTUSERP.DIS86.FACTURA			FAC WITH(NOLOCK) ON PD.PEDIDO			= FAC.PEDIDO AND FAC.TIPO_DOCUMENTO = 'F'
JOIN	    EXACTUSERP.DIS86.VENDEDOR			VEN WITH(NOLOCK) ON CL.VENDEDOR			= VEN.VENDEDOR
LEFT JOIN	PS_TRACKING.DIS86.ESTADO_PEDIDO	E	WITH(NOLOCK) ON PD.U_PS_TRACKING_ESTADO_PEDIDO	= E.ESTADO_PEDIDO
LEFT JOIN	PS_TRACKING.DIS86.ESTADO_FACTURA_SEGUIMIENTO F	WITH(NOLOCK) ON FAC.U_PS_TRACKING_ESTADO_FACTURA	= F.ESTADO_FACTURA_SEGUIMIENTO	
LEFT JOIN  (select CASE WHEN ISNULL(COUNT(ID_SEG.PEDIDO),'0')<> '0'  THEN '1' ELSE '0' END AS CANTIDAD_SEGUIMIENTO,ID_SEG.PEDIDO from PS_TRACKING.DIS86.SEGUIMIENTO ID_SEG GROUP BY ID_SEG.PEDIDO) AS SEG ON SEG.PEDIDO= PD.PEDIDO
WHERE PD.ESTADO IN('A','B','F') AND PD.AUTORIZADO IN('N','S') 
AND (ISNULL(FAC.U_PS_TRACKING_ESTADO_FACTURA,1) IN( 5, 8, 6))
-- AND PD.pedido = 'PEJA003702'
GO
/****** Object:  View [DIS86].[VIEW_TRACKING_EXCEL]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO



CREATE VIEW [DIS86].[VIEW_TRACKING_EXCEL]
AS 
SELECT * FROM (SELECT 
        ROW_NUMBER() OVER (Order by PD.PEDIDO) AS ID,
		PD.PEDIDO, 
		CONVERT(VARCHAR(800),PD.OBSERVACIONES) AS OBSERVACIONES ,
		ISNULL(PD.U_TLA_ESTADO,'N')					       TLA_ESTADO,
		PD.ESTADO ESTADO_PEDIDO_EXACTUSERP,
		PD.USUARIO,
		CONVERT(varchar,PD.U_TI_TLA_RECIBIDO,20) FECHA_HORA_RECIBIDO,
	 	CONVERT(varchar,PD.FECHA_HORA,23)	      FECHA_PEDIDO,
		convert(varchar,PD.FECHA_PROYECTADA,23)	  DIA_RUTA,

		ISNULL(PD.U_PS_TRACKING_ESTADO_PEDIDO,1)			  ESTADO_PEDIDO, 
		ISNULL(E.DESCRIPCION,'Sin Asignar')					 ESTADO_PEDIDO_DESCRIPCION,
		PD.RUTA+' - '+RT.DESCRIPCION	          RUTA,
		PD.RUTA AS COD_RUTA,
		RT.DESCRIPCION	          RUTA_NOMBRE,
		FAC.FACTURA, 
		RT.U_HORA_CORTE+':00' AS TIEMPO,
		ISNULL(FAC.U_PS_TRACKING_ESTADO_FACTURA,1) SEGUIR_FAC, 
		ISNULL(F.DESCRIPCION,'Sin Asignar')					SEGUIR_FAC_DESCRIPCION,
		ISNULL(CANTIDAD_SEGUIMIENTO,0) SUCESOS, -- JHONNY LO ELIMINO DE INTERFAZ. 
		CL.CLIENTE + ' - ' + CL.ALIAS AS CLIENTE, 
		U_TIPO_ENTREGA AS TIPO_CORTE,
		CL.CLIENTE AS COD_CLIENTE,
		CL.ALIAS	AS CLIENTE_NOMBRE, 
		VEN.VENDEDOR+' - '+VEN.NOMBRE	AS AGENTE, 
		VEN.VENDEDOR AS COD_VENDEDOR,
		VEN.NOMBRE AS AGENTE_NOMBRE,
		--RT.U_LUNES, 
		--RT.U_MARTES, 
		--RT.U_MIERCOLES, 
		--RT.U_JUEVES, 
		--RT.U_VIERNES, 
		--RT.U_SABADO,
		 
		 RT.U_DIAS_RUTA AS DIAS
		,CASE WHEN CL.CONDICION_PAGO='1' THEN 'CONTADO' ELSE 'CRÉDITO'END CONDICION_PAGO
		,CASE WHEN DATEDIFF(DD,PD.U_TI_TLA_RECIBIDO,GETDATE())>0 THEN '1' ELSE
		 CASE WHEN (ISNULL(CONVERT(CHAR(5),PD.U_TI_TLA_RECIBIDO,108),'00:00') <= RT.U_HORA_CORTE+':00') 
		AND PD.U_TLA_ESTADO NOT IN('N') THEN '1' ELSE '2' END END  AS HORA_FUERA_ENCORTE
		,ISNULL(CONVERT(CHAR(5),PD.U_TI_TLA_RECIBIDO,108),'00:00') HORA_RECIBIDO_TLA
		,RT.U_HORA_CORTE+':00' HORA_CORTE
		,DATEDIFF(DD,PD.U_TI_TLA_RECIBIDO,GETDATE())  DIAS_DE_CREADO_PEDIDO
		,PD.CreateDate
		--,ISNULL(E.COLOR_HEXA,'label-light-dark') COLOR_HEXA_PED
		--,ISNULL(F.COLOR_HEXA,'label-light-dark') COLOR_HEXA_FAC
		,CB.COBRADOR
		,convert(varchar,FAC.U_TI_CXC_RECIBE,23)  U_TI_CXC_RECIBE
FROM 
			EXACTUSERP.DIS86.PEDIDO			PD  WITH(NOLOCK)
JOIN		EXACTUSERP.DIS86.RUTA				RT  WITH(NOLOCK) ON PD.RUTA				= RT.RUTA
JOIN		EXACTUSERP.DIS86.CLIENTE			CL	WITH(NOLOCK) ON PD.CLIENTE			= CL.CLIENTE
JOIN        EXACTUSERP.DIS86.COBRADOR         CB  WITH(NOLOCK) ON CL.COBRADOR         = CB.COBRADOR
LEFT JOIN	EXACTUSERP.DIS86.FACTURA			FAC WITH(NOLOCK) ON PD.PEDIDO			= FAC.PEDIDO AND FAC.TIPO_DOCUMENTO = 'F'
JOIN	    EXACTUSERP.DIS86.VENDEDOR			VEN WITH(NOLOCK) ON CL.VENDEDOR			= VEN.VENDEDOR
LEFT JOIN	PS_TRACKING.DIS86.ESTADO_PEDIDO	E	WITH(NOLOCK) ON PD.U_PS_TRACKING_ESTADO_PEDIDO	= E.ESTADO_PEDIDO
LEFT JOIN	PS_TRACKING.DIS86.ESTADO_FACTURA_SEGUIMIENTO F	WITH(NOLOCK) ON FAC.U_PS_TRACKING_ESTADO_FACTURA	= F.ESTADO_FACTURA_SEGUIMIENTO	
LEFT JOIN  (select CASE WHEN ISNULL(COUNT(ID_SEG.PEDIDO),'0')<> '0'  THEN '1' ELSE '0' END AS CANTIDAD_SEGUIMIENTO,ID_SEG.PEDIDO from PS_TRACKING.DIS86.SEGUIMIENTO ID_SEG GROUP BY ID_SEG.PEDIDO) AS SEG ON SEG.PEDIDO= PD.PEDIDO
WHERE PD.ESTADO IN('A','B','F', 'C') AND PD.AUTORIZADO IN('N','S')) AS T

WHERE T.CreateDate >= '2023-01-01'



GO
