CREATE VIEW  [DIS86].[VIW_OBT_SEMANA_POR_FECHA_VISITA] 
AS 
SELECT 
    CAST(SEMANA AS VARCHAR) AS semana,
    'S' + CAST(SEMANA AS VARCHAR) AS Descripcion,
    CONVERT(VARCHAR(10), (INICIO_SEMANA), 105) AS inicio_semana,
