/****** Object:  View [GLOBAL].[VIEW_OBT_MENU_EFECTIVO]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE   VIEW [GLOBAL].[VIEW_OBT_MENU_EFECTIVO]
AS
WITH PERMISOS_ROL AS
(
    SELECT DISTINCT URC.USUARIO, URC.ID_COMPANIA, RP.PERMISO
    FROM GLOBAL.USUARIO_ROL_COMPANIA URC WITH (NOLOCK)
    INNER JOIN GLOBAL.ROL_PERMISO RP WITH (NOLOCK) ON RP.ROL = URC.ROL
    WHERE URC.ACTIVO = 'S'
),
PERMISOS_EFECTIVOS AS
(
    SELECT PR.USUARIO, PR.ID_COMPANIA, PR.PERMISO
    FROM PERMISOS_ROL PR
    WHERE NOT EXISTS
    (
        SELECT 1
        FROM GLOBAL.USUARIO_PERMISO_COMPANIA UPC WITH (NOLOCK)
        WHERE UPC.USUARIO = PR.USUARIO
          AND UPC.ID_COMPANIA = PR.ID_COMPANIA
          AND UPC.PERMISO = PR.PERMISO
          AND UPC.ACTIVO = 'S'
          AND UPC.ES_PERMITIDO = 'N'
    )
    UNION
    SELECT UPC.USUARIO, UPC.ID_COMPANIA, UPC.PERMISO
    FROM GLOBAL.USUARIO_PERMISO_COMPANIA UPC WITH (NOLOCK)
    WHERE UPC.ACTIVO = 'S'
      AND UPC.ES_PERMITIDO = 'S'
)
SELECT DISTINCT
       PE.USUARIO,
       PE.ID_COMPANIA,
       M.ID_MENU,
       M.ID_MENU_PADRE,
       M.NOMBRE_MENU,
       M.RUTA_MENU,
       M.ICONO_MENU,
       M.ORDEN_MENU
FROM PERMISOS_EFECTIVOS PE
INNER JOIN GLOBAL.MENU_PERMISO MP WITH (NOLOCK) ON MP.PERMISO = PE.PERMISO
INNER JOIN GLOBAL.MENU M WITH (NOLOCK) ON M.ID_MENU = MP.ID_MENU
WHERE M.ACTIVO = 'S';

GO
/****** Object:  View [DIS86].[Reporte_Cuadre_Auxiliar]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO



--Son los asientos de cuentas por cobrar QUE TIENEN UNA APLICACION
CREATE VIEW [DIS86].[Reporte_Cuadre_Auxiliar]
AS 
SELECT 																		    
	AUX.CLI_DOC_CREDIT														    AS cliente,
	CLI.NOMBRE																    AS cliente_nombre,
	CRE.documento															    AS documento_credito,	
	CRE.tipo																    AS tipo_credito,
	 SCRE.DESCRIPCION														    AS SUBTIPO_CREDITO,
	cre.MONTO																    AS monto_credito,
	cre.SALDO																    AS saldo_credito,
	cre.MONEDA,																    
	CONVERT(DATE,cre.FECHA_DOCUMENTO)										    AS fecha_documento_credito,
	DEB.documento															    AS documento_debito,	
	DEB.tipo																    AS tipo_debito,
	SDEB.DESCRIPCION														    AS SUBTIPO_debito,
	SDEB.SUBTIPO															    AS COD_SUBTIPO_DEBITO,
	deb.MONEDA																    AS MONEDA_debito,
	deb.MONTO																    AS monto_debito,
	deb.SALDO																    AS saldo_debito,
																			    
	CONVERT(DATE,aux.FECHA)													    AS fecha_aplicacion,
	aux.MONTO_LOCAL															    AS monto_aplicado
    ,CONVERT(DATE,deb.FECHA_DOCUMENTO)										    AS fecha_documento_debito
	,CONVERT(DATE,deb.FECHA_VENCE)											    AS fecha_vence_debito
	,CASE WHEN DATEDIFF(DAY,DEB.FECHA_VENCE,GETDATE())  < 0 				    
	 THEN 0 ELSE DATEDIFF(DAY,DEB.FECHA_VENCE,GETDATE()) END				    AS DIAS_NETO
	,VDEB.NOMBRE															    AS VENDEDOR_DEBITO 
	,VCLI.NOMBRE															    AS VENDEDOR_CLIENTE
	,VCLI.VENDEDOR															    AS COD_VENDEDOR_CLI
	,VCRE.NOMBRE															    AS VENDEDOR_CREDITO
	,VDEB.E_MAIL															    AS E_MAIL_VENDEDOR
	,CLI.E_MAIL																    AS EMAIL_CLIENTE
	,CAST(deb.MONTO AS decimal(28,4)) - CAST(DEB.SALDO AS decimal(28,4))        AS MONTO_PAGO
	--,AUX.CreatedBy															    AS usuario_creacion 

	 ,CASE 
        WHEN CHARINDEX('/', AUX.CreatedBy) > 0 
        THEN LTRIM(SUBSTRING(AUX.CreatedBy, CHARINDEX('/', AUX.CreatedBy) + 1, LEN(AUX.CreatedBy)))
        ELSE AUX.CreatedBy END                                                  AS usuario_creacion

	,CASE WHEN CRE.TIPO IN('REC','TEF','O/C','DEP') THEN CASE WHEN CHARINDEX('/', CRE.CreatedBy) > 0 
	      THEN SUBSTRING(CRE.CreatedBy, CHARINDEX('/', CRE.CreatedBy) + 1, LEN(CRE.CreatedBy) - CHARINDEX('/', CRE.CreatedBy)) 
          ELSE CRE.CreatedBy END  END                                                          AS USUARIO_CREACION_CREDITO
    
	,CASE WHEN DEB.TIPO NOT IN('REC','TEF','O/C','DEP') THEN CASE WHEN CHARINDEX('/', DEB.CreatedBy) > 0 
	      THEN SUBSTRING(DEB.CreatedBy, CHARINDEX('/', DEB.CreatedBy) + 1, LEN(DEB.CreatedBy) - CHARINDEX('/', CRE.CreatedBy)) 
          ELSE DEB.CreatedBy END END                                                          AS USUARIO_CREACION_DEBITO
	
	,ISNULL(CLI.LIMITE_CREDITO,0) LIMITE_CREDITO
	,CASE WHEN DATEDIFF(DAY,DEB.FECHA_VENCE,GETDATE())  > 0  AND deb.SALDO > 0 
	 THEN 1 ELSE 0 END															AS DOC_VENC
	,CASE WHEN DEB.TIPO NOT IN('REC','TEF','O/C','DEP') THEN DEB.APLICACION ELSE ISNULL(FACDEB.RUBRO5,'')  END AS REFERENCIA_DEBITO 
	,CASE WHEN CRE.tipo = 'O/C' THEN CRE.APLICACION ELSE ISNULL(FACCRED.RUBRO5,'') END AS REFERENCIA_CREDITO
	,CASE WHEN  DEB.TIPO NOT IN('REC','TEF','O/C','DEP') THEN CONVERT(DATE,DEB.CreateDate)  END                     AS FECHA_CREACION_DEBITO
    ,CASE WHEN  CRE.TIPO IN('REC','TEF','O/C','DEP')     THEN CONVERT(DATE,CRE.CreateDate)  END                     AS FECHA_CREACION_CREDITO
	

FROM	
			 EXACTUSERP.DIS86.auxiliar_cc 		AUX		 WITH(NOLOCK)
	 JOIN	 EXACTUSERP.DIS86.documentos_cc 	    DEB		 WITH(NOLOCK) ON AUX.DEBITO         = DEB.documento and AUX.TIPO_DEBITO  = DEB.tipo
	 JOIN	 EXACTUSERP.DIS86.documentos_cc 		CRE		 WITH(NOLOCK) ON AUX.CREDITO        = CRE.documento and AUX.TIPO_CREDITO = CRE.tipo
	 JOIN	 EXACTUSERP.DIS86.CLIENTE				CLI		 WITH(NOLOCK) ON AUX.CLI_DOC_CREDIT = CLI.CLIENTE
	 JOIN    EXACTUSERP.DIS86.VENDEDOR			VDEB	 WITH(NOLOCK) ON DEB.VENDEDOR       = VDEB.VENDEDOR  
LEFT JOIN    EXACTUSERP.DIS86.VENDEDOR			VCRE	 WITH(NOLOCK) ON VCRE.VENDEDOR      = CRE.VENDEDOR 
	 JOIN    EXACTUSERP.DIS86.VENDEDOR			VCLI	 WITH(NOLOCK) ON VCLI.VENDEDOR      = CLI.VENDEDOR 
	 JOIN    EXACTUSERP.DIS86.SUBTIPO_DOC_CC		SDEB	 WITH(NOLOCK) ON SDEB.TIPO          = DEB.TIPO AND SDEB.SUBTIPO = DEB.SUBTIPO 
	 JOIN    EXACTUSERP.DIS86.SUBTIPO_DOC_CC		SCRE     WITH(NOLOCK) ON SCRE.TIPO          = CRE.TIPO AND SCRE.SUBTIPO = CRE.SUBTIPO 
LEFT JOIN    EXACTUSERP.DIS86.FACTURA				FACDEB   WITH(NOLOCK) ON FACDEB.FACTURA     = DEB.DOCUMENTO	
LEFT JOIN    EXACTUSERP.DIS86.FACTURA				FACCRED  WITH(NOLOCK) ON FACCRED.FACTURA    = CRE.DOCUMENTO
--WHERE deb.SALDO > 0   -- SE COMENTA YA QUE HAY REPORTES DE APLICACIONES
--AND CLI.CLIENTE ='CL02037'
--AND  DEB.DOCUMENTO ='000000001'
--AND  CRE.DOCUMENTO='CND000000051'

UNION 

SELECT  
		CLI.CLIENTE	                                                                                              AS cliente,
		CLI.NOMBRE		                                                                                          AS cliente_nombre,

		CASE  WHEN  DOC.TIPO IN('REC','TEF','O/C','DEP') THEN DOC.documento ELSE NULL END						  AS documento_credito,	
		CASE  WHEN  DOC.TIPO IN('REC','TEF','O/C','DEP') THEN DOC.TIPO ELSE NULL END							  AS tipo_credito,
		CASE  WHEN  DOC.TIPO IN('REC','TEF','O/C','DEP') THEN SDOC.DESCRIPCION ELSE NULL END					  AS SUBTIPO_CREDITO,
		CASE  WHEN  DOC.TIPO IN('REC','TEF','O/C','DEP') THEN DOC.MONTO ELSE 0 END 								  AS monto_credito,
		CASE  WHEN  DOC.TIPO IN('REC','TEF','O/C','DEP') THEN DOC.SALDO ELSE 0 END 								  AS saldo_credito,
		CASE  WHEN  DOC.TIPO IN('REC','TEF','O/C','DEP') THEN DOC.MONEDA ELSE NULL END							  AS MONEDA_CREDITO,
		CASE  WHEN  DOC.TIPO IN('REC','TEF','O/C','DEP') THEN CONVERT(DATE,DOC.FECHA_DOCUMENTO)  ELSE NULL END    AS fecha_documento_credito,
		DOC.documento																							  AS documento_debito,	
		DOC.tipo																								  AS tipo_debito,
		SDOC.DESCRIPCION																					      AS SUBTIPO_debito,
		SDOC.SUBTIPO																							  AS COD_SUBTIPO_DEBITO,
		DOC.MONEDA                                                                                                AS MONEDA_debito,
		DOC.MONTO		                                                                                          AS monto_debito,
		DOC.SALDO		                                                                                          AS saldo_debito,
		NULL                                                                                                      AS fecha_aplicacion,
		0                                                                                                         as monto_aplicado
		,CONVERT(DATE,DOC.FECHA_DOCUMENTO)                                                                        AS fecha_documento_debito
		,CONVERT(DATE,DOC.FECHA_VENCE)                                                                            AS fecha_vence_debito
		,CASE WHEN DATEDIFF(DAY,DOC.FECHA_VENCE,GETDATE())  < 0 THEN 0 ELSE DATEDIFF(DAY,DOC.FECHA_VENCE,GETDATE()) END  AS  DIAS_NETO
		,VDOC.NOMBRE                                                                                              AS VENDEDOR_DEBITO 
		,VCLI.NOMBRE                                                                                              AS VENDEDOR_CLIENTE
		,VCLI.VENDEDOR                                                                                            AS COD_VENDEDOR_CLI
		,CASE  WHEN  DOC.TIPO IN('REC','TEF','O/C','DEP') THEN VDOC.NOMBRE ELSE NULL END                          AS VENDEDOR_CREDITO
		,VDOC.E_MAIL                                                                                              AS E_MAIL_VENDEDOR
		,CLI.E_MAIL                                                                                               AS EMAIL_CLIENTE
		,CAST( DOC.MONTO AS decimal(28,4)) - CAST(DOC.SALDO AS decimal(28,4))                                     AS MONTO_PAGO

		--,CASE  WHEN  DOC.TIPO IN('REC','TEF','O/C','DEP') THEN DOC.CreatedBy ELSE 'ND' END   usuario_creacion
	   ,CASE WHEN CHARINDEX('/', DOC.CreatedBy) > 0  
	         THEN LTRIM(SUBSTRING(DOC.CreatedBy, CHARINDEX('/', DOC.CreatedBy) + 1, LEN(DOC.CreatedBy))) 
	         ELSE DOC.CreatedBy  END                                                                              AS usuario_creacion

	     ,CASE WHEN DOC.TIPO IN('REC','TEF','O/C','DEP') THEN CASE WHEN CHARINDEX('/', DOC.CreatedBy) > 0 
		      THEN SUBSTRING(DOC.CreatedBy, CHARINDEX('/', DOC.CreatedBy) + 1, LEN(DOC.CreatedBy) - CHARINDEX('/', DOC.CreatedBy)) 
              ELSE DOC.CreatedBy END  END                                                                         AS USUARIO_CREACION_CREDITO
       
	   ,CASE WHEN DOC.TIPO NOT IN('REC','TEF','O/C','DEP') THEN CASE WHEN CHARINDEX('/', DOC.CreatedBy) > 0 
		      THEN SUBSTRING(DOC.CreatedBy, CHARINDEX('/', DOC.CreatedBy) + 1, LEN(DOC.CreatedBy) - CHARINDEX('/', DOC.CreatedBy)) 
              ELSE DOC.CreatedBy END  END                                                                         AS USUARIO_CREACION_DEBITO

		,ISNULL(CLI.LIMITE_CREDITO,0)                                                                             AS LIMITE_CREDITO
		,CASE WHEN DATEDIFF(DAY,DOC.FECHA_VENCE,GETDATE())  > 0  AND DOC.SALDO > 0 THEN 1 ELSE 0 END              AS DOC_VENC
		,CASE  WHEN  DOC.TIPO NOT IN('REC','TEF','O/C','DEP') THEN DOC.APLICACION ELSE ISNULL(FAC.RUBRO5,'') END  AS REFERENCIA_DEBITO
		,CASE  WHEN  DOC.TIPO IN('REC','TEF','O/C','DEP')     THEN ISNULL(FAC.RUBRO5,'') ELSE DOC.APLICACION END  AS REFERENCIA_CREDITO
		,CASE  WHEN  DOC.TIPO NOT IN('REC','TEF','O/C','DEP') THEN CONVERT(DATE,DOC.CreateDate)   END             AS FECHA_CREACION_DEBITO
		,CASE  WHEN  DOC.TIPO IN('REC','TEF','O/C','DEP')     THEN CONVERT(DATE,DOC.CreateDate)   END             AS FECHA_CREACION_CREDITO
from	
			
		     EXACTUSERP.DIS86.documentos_cc 	 DOC  WITH(NOLOCK) 
	 JOIN	 EXACTUSERP.DIS86.CLIENTE			 CLI  WITH(NOLOCK) ON DOC.CLIENTE = CLI.CLIENTE
	 JOIN    EXACTUSERP.DIS86.VENDEDOR         VDOC WITH(NOLOCK) ON DOC.VENDEDOR = VDOC.VENDEDOR  
	 JOIN    EXACTUSERP.DIS86.VENDEDOR         VCLI WITH(NOLOCK) ON VCLI.VENDEDOR = CLI.VENDEDOR 
	 JOIN    EXACTUSERP.DIS86.SUBTIPO_DOC_CC   SDOC WITH(NOLOCK) ON SDOC.TIPO = DOC.TIPO AND SDOC.SUBTIPO = DOC.SUBTIPO 
LEFT JOIN    EXACTUSERP.DIS86.FACTURA          FAC  WITH(NOLOCK) ON  FAC.FACTURA = DOC.DOCUMENTO

--WHERE (
--       (DOC.TIPO = 'N/C')                                           -- Muestra todos los documentos de tipo 'N/C'
--    OR (FLOOR(DOC.MONTO) = FLOOR(DOC.SALDO)  AND DOC.TIPO <> 'N/C') -- Aplica la validación solo para documentos que no son 'N/C'
--	  )
--    AND DOC.SALDO > 0  
--    AND CLI.CLIENTE = 'CL02037'
	



GO
/****** Object:  View [DIS86].[VIEW_OBT_SALDO_CLIENTE_DOC_CC]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO



CREATE VIEW [DIS86].[VIEW_OBT_SALDO_CLIENTE_DOC_CC] 
AS 
SELECT CLIENTE,
		
       (SELECT [DIS86].[OBTENER_SALDO_DEBITO_CLIENTE] (CLIENTE))  saldo_debito,
	   MAX(LIMITE_CREDITO) limite_credito,
       MAX(LIMITE_CREDITO) - (SELECT [DIS86].[OBTENER_SALDO_DEBITO_CLIENTE] (CLIENTE)) Disponible, 
	   SUM(DOC_VENC) Doc_Venc
FROM [DIS86].[Reporte_Cuadre_Auxiliar] DOC WITH(NOLOCK) 
--WHERE cliente='1001'
GROUP BY cliente

GO
