CREATE VIEW [DIS86].[VIEW_OBT_DATOS_CLIENTE_ESTADO_CUENTA] 
AS 
SELECT 
		   --ISNULL(VTA.ESTADO_VISITA,'PEN')          AS ESTADO 
		   (SELECT ISNULL(MAX(ESTADO_VISITA),'PEN') FROM [DIS86].[VISITAS] WHERE CLIENTE =CLI.CLIENTE) ESTADO
		  ,CLI.CLIENTE					          
		  ,CLI.CLIENTE +'-'+ CLI.NOMBRE             AS CLI_NOMBRE
		  ,ALIAS							          
		  ,VEN.VENDEDOR                             AS COD_VENDEDOR
		  ,VEN.NOMBRE                               AS NOMBRE_VENDEDOR
		  ,VEN.VENDEDOR + ' - ' +VEN.NOMBRE         AS VEN_NOMBRE
		  ,CASE WHEN CLI.E_MAIL= ' ' THEN '' 
		        WHEN CLI.E_MAIL = NULL THEN '' 
				ELSE CLI.E_MAIL END AS EMAIL
		  ,CLI.TELEFONO1                            AS TELEFONO
		  ,CP.CONDICION_PAGO
		  ,CONVERT(VARCHAR,CP.DIAS_NETO) +' Dias '  AS DIAS_NETO
		  --,ISNULL(TSL.saldo_debito,0)               AS SALDO
		  ,ISNULL([DIS86].[OBTENER_SALDO_DEBITO_CLIENTE] (CLI.CLIENTE),0)  AS SALDO
		  ,CLI.U_DIA_VISITA                         AS DIAS_RUTA
		  --,CONVERT(VARCHAR,VTA.FECHA_VISITA, 103)   AS FECHA_ULTIMA_VISITA
		  ,(SELECT MAX(CONVERT(VARCHAR,FECHA_VISITA,103)) FROM [DIS86].[VISITAS] WHERE CLIENTE =CLI.CLIENTE) FECHA_ULTIMA_VISITA
		  ,ISNULL(CLI.U_SEMANA_VISITA,'1')          AS SEMANA 
		  ,ISNULL(CLI.U_ORDEN_VISITA,0)             AS U_ORDEN_VISITA
		 -- ,ISNULL(TSL.limite_credito,0)             AS LIMITE_CREDITO
		  ,ISNULL(CLI.LIMITE_CREDITO,0)             AS LIMITE_CREDITO
		 -- ,ISNULL(TSL.Disponible,0)                 AS DISPONIBLE
		   ,ISNULL(CLI.LIMITE_CREDITO - [DIS86].[OBTENER_SALDO_DEBITO_CLIENTE] (CLI.CLIENTE),0) DISPONIBLE
		  --,ISNULL(TSL.Doc_Venc,0)                   AS DOC_VENC
		  ,(SELECT ISNULL(SUM(DOC_VENC),0) FROM [DIS86].[VIEW_OBT_SALDO_CLIENTE_DOC_CC] where CLIENTE= CLI.CLIENTE) AS DOC_VENC
		  --,VTA.ID_VISITA
		  ,(SELECT MAX(ID_VISITA) FROM [DIS86].[VISITAS] WHERE CLIENTE =CLI.CLIENTE) ID_VISITA
		  ,COB.COBRADOR 
          ,CONCAT(COB.COBRADOR,' | ',COB.NOMBRE) COD_NOMBRE_COBRADOR
FROM 
	      EXACTUSERP.DIS86.CLIENTE					AS CLI WITH(NOLOCK)
JOIN      EXACTUSERP.DIS86.CONDICION_PAGO				AS CP  WITH(NOLOCK) ON CLI.CONDICION_PAGO = CP.CONDICION_PAGO
JOIN      EXACTUSERP.DIS86.VENDEDOR                   AS VEN WITH(NOLOCK) ON CLI.VENDEDOR       = VEN.VENDEDOR
JOIN      EXACTUSERP.DIS86.COBRADOR					AS COB WITH(NOLOCK) ON COB.COBRADOR       = CLI.COBRADOR
--LEFT JOIN [DIS86].[VISITAS]                         AS VTA WITH(NOLOCK) ON CLI.CLIENTE        = VTA.CLIENTE
--LEFT JOIN [DIS86].[VIEW_OBT_SALDO_CLIENTE_DOC_CC]   AS TSL WITH(NOLOCK) ON TSL.CLIENTE        = CLI.CLIENTE

WHERE   CLI.ACTIVO ='S'
--AND CLI.CLIENTE='CL02037'
--ORDER BY U_ORDEN_VISITA



GO
