CREATE VIEW [DIS86].[VIEW_OBT_LISTA_BONIFICACION_ARTICULOS]
AS 
SELECT DISTINCT --CAMBIO SE AGREGO EL DISTINCT
     AP.NIVEL_PRECIO                                                              AS NIVEL_PRECIO
    ,ART.ARTICULO                                                                 AS COD_ARTICULO_NORMAL
    ,ART.DESCRIPCION															  AS ARTICULO_NORMAL
	
	,ART.CLASIFICACION_2                                                          AS ID_CASA
	,CONCAT(ART.CLASIFICACION_2,' | ',CLAS2.DESCRIPCION)                          AS CASA
	
	,ART.CLASIFICACION_1														  AS ID_SUBCASA
	,CONCAT(ART.CLASIFICACION_1,' | ',CLAS1.DESCRIPCION)                          AS SUBCASA
	
	,ART.CLASIFICACION_3                                                          AS ID_CATEGORIA_ART
	,CONCAT(ART.CLASIFICACION_3,' | ',CLAS3.DESCRIPCION)                          AS CATEGORIA_ART
	
	,CASE WHEN AB.ARTICULO IS NOT NULL THEN AB.ARTICULO_BONIF ELSE '' END         AS COD_ART_BONIFICADO
    ,CASE WHEN AB.ARTICULO IS NOT NULL THEN '*** ' + ART.DESCRIPCION ELSE '' END  AS ARTICULO_BONIFICADO
	,ISNULL(AB.ESCALA_BONIF,0)                                                    AS ESCALA_BONIF 
	,ISNULL(AB.MIN_ART_FACT,0)                                                    AS CANT_MINIMA 
	,ISNULL(AB.MAX_ART_FACT,0)   											      AS CANT_MAXIMA
	,CONVERT(VARCHAR,AB.FECHA_INICIO_ESC,23)                                      AS FECHA_INICIAL 
	,CONVERT(VARCHAR,AB.FECHA_FIN_ESC,23)										  AS FECHA_FINAL 
	,ISNULL(AB.FACTOR_BONIF,0)													  AS FACTOR_BONIF
	,ISNULL(AB.UNIDADES_BONIF,0)    											  AS UNIDADES_BONIF
	,AB.MONEDA																      AS MONEDA
	,AB.VERSION_BONIF															  AS VERSION_BONIF 
	                                                                         
FROM    
	  [EXACTUSERP].[DIS86].ARTICULO          AS  ART   WITH(NOLOCK) 
JOIN  [EXACTUSERP].[DIS86].ARTICULO_PRECIO   AS  AP    WITH(NOLOCK)  ON  AP.ARTICULO         = ART.ARTICULO 
JOIN  [EXACTUSERP].[DIS86].[ESCALA_BONIF]    AS  AB    WITH(NOLOCK)  ON  AB.NIVEL_PRECIO     = AP.NIVEL_PRECIO 
                                                                  AND  AB.ARTICULO         = AP.ARTICULO
JOIN EXACTUSERP.DIS86.CLASIFICACION          AS CLAS2 WITH(NOLOCK) ON  CLAS2.CLASIFICACION   = ART.CLASIFICACION_2
JOIN EXACTUSERP.DIS86.CLASIFICACION          AS CLAS1 WITH(NOLOCK) ON  CLAS1.CLASIFICACION   = ART.CLASIFICACION_1
JOIN EXACTUSERP.DIS86.CLASIFICACION          AS CLAS3 WITH(NOLOCK) ON  CLAS3.CLASIFICACION   = ART.CLASIFICACION_3

WHERE ART.ACTIVO ='S'
AND   ART.ARTICULO <>'ND'
AND   CAST(AB.FECHA_INICIO_ESC AS DATE) >= (SELECT MAX(CAST(ABT.FECHA_INICIO_ESC AS DATE)) FROM [EXACTUSERP].[DIS86].[ESCALA_BONIF] ABT WITH(NOLOCK))
--AND   ART.CLASIFICACION_3 = 'MLP'

GO
