CREATE VIEW [DIS86].[VIEW_OBT_LISTA_ESCALA_DESCUENTOS]
AS 
	SELECT  DISTINCT
		 AP.NIVEL_PRECIO                                                                        AS NIVEL_PRECIO
		,ART.ARTICULO                                                                           AS ARTICULO
		,CONCAT(ART.ARTICULO, ' | ' ,ART.DESCRIPCION)									        AS COD_NOMBRE_ARTICULO
	
		,ART.CLASIFICACION_2                                                                    AS ID_CASA
		,CONCAT(ART.CLASIFICACION_2,' | ', CLAS2.DESCRIPCION)									AS CASA
	
		,ART.CLASIFICACION_1														            AS ID_SUBCASA
		,CONCAT(ART.CLASIFICACION_1,' | ', CLAS1.DESCRIPCION)	    							AS SUBCASA
	
		,ART.CLASIFICACION_3                                                                    AS ID_CATEGORIA_ART
		,CONCAT(ART.CLASIFICACION_3,' | ', CLAS3.DESCRIPCION)									AS CATEGORIA_ART

		,ROUND(ISNULL(AP.PRECIO,0),2)															AS PRECIO
		,ISNULL(DCTO.PORC_DCTO,0)																AS PORC_DESCUENTO 
		,CONVERT(VARCHAR,DCTO.FECHA_INICIO_ESC,23)												AS FECHA_INICIAL
		,CONVERT(VARCHAR,DCTO.FECHA_FIN_ESC,23)													AS FECHA_FINAL 
		,ROUND((ISNULL(AP.PRECIO,0)) - (ISNULL(AP.PRECIO,0) * ISNULL(DCTO.PORC_DCTO/100,0)),2)  AS PRECIO_FINAL
		,DCTO.ESCALA_DCTO
		,DCTO.MONEDA
		,DCTO.MIN_UNID_FACT                                                                     AS CANTIDAD_MIN 
		,DCTO.MAX_UNID_FACT                                                                     AS CANTIDAD_MAX

	FROM      
		 [EXACTUSERP].[DIS86].ARTICULO			 AS ART  WITH(NOLOCK)
	JOIN [EXACTUSERP].[DIS86].ARTICULO_PRECIO      AS AP   WITH(NOLOCK)  ON AP.ARTICULO        = ART.ARTICULO
	JOIN [EXACTUSERP].[DIS86].[ESCALA_DCTO]        AS DCTO WITH(NOLOCK)  ON DCTO.NIVEL_PRECIO  = AP.NIVEL_PRECIO AND 
																			   DCTO.ARTICULO      = AP.ARTICULO 
																		   -- AND AP.MONEDA       = DCTO.MONEDA
																	   
			 																AND AP.VERSION	  = DCTO.VERSION --ARREGLAR CON SOFTLAND HABLAR CON EL CLIENTE PARA DEJAR UNA UNICA VERSION, CONVOCAR REUNION
	JOIN EXACTUSERP.DIS86.CLASIFICACION AS CLAS1 WITH(NOLOCK) ON CLAS1.CLASIFICACION = ART.CLASIFICACION_1
	JOIN EXACTUSERP.DIS86.CLASIFICACION AS CLAS2 WITH(NOLOCK) ON CLAS2.CLASIFICACION = ART.CLASIFICACION_2
	JOIN EXACTUSERP.DIS86.CLASIFICACION AS CLAS3 WITH(NOLOCK) ON CLAS3.CLASIFICACION = ART.CLASIFICACION_3

	WHERE ART.ACTIVO ='S'  and ART.ARTICULO <> 'ND' 
	--AND   ART.CLASIFICACION_3 ='MLP'
	--AND   CAST(DCTO.FECHA_INICIO_ESC AS DATE) >= (SELECT MAX(CAST(ABT.FECHA_INICIO_ESC AS DATE)) 
	--											  FROM [EXACTUSERP].[DIS86].[ESCALA_BONIF] ABT WITH(NOLOCK))
GO
