CREATE VIEW [DIS86].[PS_VIEW_OBT_LISTADO_MT940]
AS
SELECT DISTINCT
    [ID_H2H],
    L.ID_LINEA,
    L.CUENTA_BANCO,
    DOCUMENTO_BANCO AS REFERENCIA,

    --L.TIPO,
    --L.SUBTIPO,
	CASE WHEN MB.U_PS_H2H_NUM_BANCO IS NOT NULL THEN ISNULL(L.TIPO,MB.TIPO_DOCUMENTO) ELSE L.TIPO END TIPO,
	CASE WHEN MB.U_PS_H2H_NUM_BANCO IS NOT NULL THEN ISNULL(L.SUBTIPO,MB.SUBTIPO) ELSE L.SUBTIPO END SUBTIPO,

    MB.NUMERO DOCUMENTO,
    CARGADO_ERP,
    FECHA_BANCO AS FECHA_TEF,
    CONVERT(VARCHAR, FECHA_BANCO, 103) AS FECHA_TEF_STR,
    [PS_86_REFERENCIA],
    CASE WHEN CREDITO_DEBITO = 'C' THEN L.MONTO ELSE 0 END AS CREDITO,
    CASE WHEN CREDITO_DEBITO = 'D' THEN L.MONTO ELSE 0 END AS DEBITO,
    CONVERT(VARCHAR(50), CAST(CASE WHEN CREDITO_DEBITO = 'C' THEN L.MONTO ELSE 0 END AS MONEY), -1) AS CREDITO_STR,
    CONVERT(VARCHAR(50), CAST(CASE WHEN CREDITO_DEBITO = 'D' THEN L.MONTO ELSE 0 END AS MONEY), -1) AS DEBITO_STR,
    CREDITO_DEBITO,
    L.CARGADO_CB AS ESTADO_CB,
    FECHA_CARGA AS FECHA_MT,
    CONVERT(VARCHAR, FECHA_CARGA, 103) AS FECHA_MT_STR,

    --L.[PROVEEDOR],
    --[CLIENTE],
	CASE WHEN (U_PS_H2H_NUM_BANCO IS NOT NULL AND CC_CP = 'N/D') OR (CC_CP = 'CB') THEN 'NO APLICA' ELSE L.PROVEEDOR END PROVEEDOR,
	CASE WHEN (U_PS_H2H_NUM_BANCO IS NOT NULL AND CC_CP = 'N/D') OR (CC_CP = 'CB') THEN 'NO APLICA' ELSE L.CLIENTE END CLIENTE,

    --CC_CP,
	CASE WHEN U_PS_H2H_NUM_BANCO IS NOT NULL AND CC_CP = 'N/D' THEN 'CB' ELSE CC_CP END CC_CP,

    L.MONEDA,
    REPLACE(FORMAT(L.MONTO, 'N2', 'es-ES'),'.','') AS MONTO,
	L.MONTO AS MONTO_TRIGGER,
    CASE WHEN MB.U_PS_H2H_NUM_BANCO IS NOT NULL THEN 'S' ELSE 'N' END AS ASOCIADO_H2H,
	MB.ASIENTO,
	L.ESTADO,
	L.DOCUMENTO_FUSION,
	L.DOCUMENTO_BANCO_VIEJO,
	L.SE_INSERTO_EN_MOV_REPORTADOS,
    CASE WHEN (SELECT COUNT(*) FROM EXACTUSERP.DIS86.MOV_BANCOS MM WHERE ISNULL(MM.U_PS_H2H_NUM_BANCO,MM.NUMERO) = L.DOCUMENTO_BANCO AND MM.CUENTA_BANCO = CB.CUENTA_BANCO) > 0 AND CC_CP = 'N/D' AND MB.ASIENTO IS NULL THEN 'S' ELSE 'N' END DUPLICADO_EN_LIBROS 
FROM 
    [PS_TRACKING].[DIS86].[ESTADO_H2H_LINEAS] L
JOIN 
	EXACTUSERP.DIS86.CUENTA_BANCARIA CB ON CB.CUENTA_BANCO = L.CUENTA_BANCO
LEFT JOIN 
    EXACTUSERP.DIS86.MOV_BANCOS MB ON MB.U_PS_H2H_NUM_BANCO = L.DOCUMENTO_BANCO AND CONVERT(DATE,MB.FECHA) = CONVERT(DATE,L.FECHA_BANCO)
GO
/****** Object:  View [DIS86].[VIEW_PAGOS_X_TRANSFERENCIA_PARA_REPORTE]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE VIEW [DIS86].[VIEW_PAGOS_X_TRANSFERENCIA_PARA_REPORTE]
AS
SELECT
    CONVERT(DATE, AUX.FECHA) AS FECHA_APLICACION,
    FORMAT(AUX.FECHA, 'dd/MM/yyyy') AS FECHA_APLICACION_STR,
    --CASE 
    --    WHEN CP.U_OC IS NULL THEN 'SIN ORDEN DE COMPRA'
    --    WHEN CP.U_OC = '' THEN 'SIN ORDEN DE COMPRA'
    --    ELSE CP.U_OC 
    --END AS ORDEN_COMPRA,
	'' AS ORDEN_COMPRA,
    CASE 
        WHEN AUX.MONEDA_DEBITO = 'USD' THEN AUX.MONTO_DOLAR 
        ELSE AUX.MONTO_LOCAL 
    END AS MONTO_APLICADO,
    AUX.DEBITO,
    ISNULL(MT.REFERENCIA, '') AS NUM_BANCO,
    AUX.MONEDA_CREDITO, -- MONTO DE LA FACTURA
    'CR' + MB.CUENTA_BANCO AS CUENTA_ORIGEN,
    PRO.NOMBRE,
    ISNULL(PRO.CONDICION_PAGO, 'MP INDICADO') AS CONDICION,
    CASE 
        WHEN ISNULL(PRO.TELEFONO1, '') = '' THEN 'NO INDICADO' 
        ELSE PRO.TELEFONO1 
    END AS TELEFONO,
    PRO.CONTRIBUYENTE,
    PRO.PROVEEDOR,
    RIGHT(PRO.PROVEEDOR, LEN(PRO.PROVEEDOR) - 1) AS PROVEEDOR_CRYSTAL,
    AUX.TIPO_CREDITO,
    AUX.TIPO_DEBITO,
    AUX.MONTO_DEBITO, -- MONTO DE LA TEF
    AUX.CREDITO
FROM 
    [EXACTUSERP].[DIS86].[PROVEEDOR] PRO 
LEFT JOIN 
    [EXACTUSERP].[DIS86].[AUXILIAR_CP] AUX ON PRO.PROVEEDOR = AUX.PROVEEDOR
JOIN 
    EXACTUSERP.DIS86.DOCUMENTOS_CP CP ON CP.DOCUMENTO = AUX.CREDITO 
                                  AND CP.PROVEEDOR = AUX.PROVEEDOR 
                                  AND CP.TIPO = AUX.TIPO_CREDITO
LEFT JOIN 
    EXACTUSERP.DIS86.MOV_BANCOS MB ON CONVERT(VARCHAR, MB.NUMERO) = CONVERT(VARCHAR, AUX.DEBITO) 
                                AND MB.TIPO_DOCUMENTO = 'T/D'
LEFT JOIN 
    DIS86.[PS_VIEW_OBT_LISTADO_MT940] MT ON CONVERT(INT, MT.REFERENCIA) = MB.U_PS_H2H_NUM_BANCO
WHERE 
    DATEDIFF(YEAR, AUX.FECHA, GETDATE()) <= 5
    -- AND DEBITO = '707166670';
GO
