CREATE VIEW [DIS86].[VIEW_OBT_DATOS_VISITA]
AS 
SELECT DISTINCT
    CLIENTE,
    VTA.ESTADO_VISITA,
    CASE WHEN CONVERT(DATE, FECHA_VISITA, 105) < CONVERT(DATE,GETDATE()) THEN NULL ELSE CONVERT(DATE, FECHA_VISITA, 105) END AS FECHA_VISITA,
    CASE WHEN CONVERT(DATE, FECHA_VISITA, 105) < CONVERT(DATE,GETDATE()) THEN NULL ELSE ID_VISITA END AS ID_VISITA,
    COL.COLOR_HEXA
FROM [PS_TRACKING].[DIS86].[VISITAS] AS VTA
JOIN [PS_TRACKING].DIS86.COLOR_ESTADO_VISITA AS COL ON VTA.ESTADO_VISITA = COL.[ESTADO_VISITA]
WHERE FECHA_VISITA = (
    SELECT MAX(FECHA_VISITA)
    FROM [PS_TRACKING].[DIS86].[VISITAS] AS VTA2
    WHERE VTA2.CLIENTE = VTA.CLIENTE
)


GO
/****** Object:  UserDefinedFunction [DIS86].[FUN_OBT_ESTADO_POR FECHA_V2]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE FUNCTION [DIS86].[FUN_OBT_ESTADO_POR FECHA_V2]
(
    @ListaClientes VARCHAR(MAX),
	@FECHA_INI VARCHAR(30),
    @FECHA_FIN VARCHAR(30)
)
RETURNS TABLE
AS
RETURN
(
    SELECT CLIENTE, ESTADO_VISITA
    FROM [DIS86].[VIEW_OBT_DATOS_VISITA] 
    WHERE CLIENTE IN (SELECT VAL FROM [DIS86].[TF_SPLIT](@ListaClientes, ','))
	AND     CONVERT(VARCHAR,FECHA_VISITA,105) >= @FECHA_INI 
	AND     CONVERT(VARCHAR,FECHA_VISITA,105) <= @FECHA_FIN
	
);
GO
