CREATE VIEW [DIS86].[VIEW_OBT_DOCUMENTOS_FACTURA_CLIENTE_DEBITOS]
AS 
SELECT DISTINCT
       [cliente]
      ,[cliente_nombre]
      ,[documento_debito]
      ,[tipo_debito]
      ,[SUBTIPO_debito]
      ,[COD_SUBTIPO_DEBITO]
      ,[MONEDA_DEBITO]
      ,[monto_debito]
      ,[saldo_debito]
      ,[fecha_documento_debito]
      ,[fecha_vence_debito]
      ,[DIAS_NETO]
      ,[VENDEDOR_DEBITO]
      ,[VENDEDOR_CLIENTE]
      ,[COD_VENDEDOR_CLI]
      ,[E_MAIL_VENDEDOR]
      ,[EMAIL_CLIENTE]
      ,[MONTO_PAGO]
      ,[USUARIO_CREACION_DEBITO]
      ,[DOC_VENC]
      ,[REFERENCIA_DEBITO]
	  ,COBRADOR_DEBITO
	  ,NOMBRE_COBRADOR_DEBITO
	  ,COMENTARIO_DEBITO
      ,CONDICION_PAGO_DESC_DEB
	,CONDICION_PAGO_DEB
	,CONDICION_PAGO_DESC_CRE
	,CONDICION_PAGO_CRE
  FROM [DIS86].[VIEW_OBT_DOCUMENTOS_CC_AUXI]
  WHERE TIPO_DEBITO IN('FAC','N/D','O/D', 'INT')
  AND saldo_debito  > 0 
  --AND SALDO_CREDITO > 0
  --AND cliente='000054'



GO
