CREATE VIEW [DIS86].[VIEW_OBT_DOCUMENTOS_FACTURA_CLIENTE]
AS 
SELECT DISTINCT
       [cliente]
      ,[cliente_nombre]
      ,[documento_credito]
      ,[tipo_credito]
      ,[SUBTIPO_CREDITO]
      ,[monto_credito]
      ,[saldo_credito]
      ,[MONEDA]
      ,[fecha_documento_credito]
      ,[documento_debito]
      ,[tipo_debito]
      ,[SUBTIPO_debito]
      ,[COD_SUBTIPO_DEBITO]
      ,[MONEDA_DEBITO]
      ,[monto_debito]
      ,[saldo_debito]
      ,[fecha_aplicacion]
      ,[monto_aplicado]
      ,[fecha_documento_debito]
      ,[fecha_vence_debito]
      ,[DIAS_NETO]
      ,[VENDEDOR_DEBITO]
      ,[VENDEDOR_CLIENTE]
      ,[COD_VENDEDOR_CLI]
      ,[VENDEDOR_CREDITO]
      ,[E_MAIL_VENDEDOR]
      ,[EMAIL_CLIENTE]
      ,[MONTO_PAGO]
      ,[usuario_creacion]
      ,[LIMITE_CREDITO]
      ,[DOC_VENC]
      ,[REFERENCIA_DEBITO]
      ,[REFERENCIA_CREDITO]
	  ,COBRADOR_DEBITO
	  ,NOMBRE_COBRADOR_DEBITO
	  ,COBRADOR_CREDITO
	  ,NOMBRE_COBRADOR_CREDITO
	  ,COMENTARIO_DEBITO
	  ,COD_COBRADOR_CLI
  FROM [DIS86].[VIEW_OBT_DOCUMENTOS_CC_AUXI]
WHERE  (TIPO_DEBITO IN ('FAC','N/D','O/D','INT') AND SALDO_DEBITO  > 0)
   OR  (SALDO_CREDITO > 0); 


