/****** Object:  View [DIS86].[VIEW_OBT_SALDO_VENCIDO_CLIENTE]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [DIS86].[VIEW_OBT_SALDO_VENCIDO_CLIENTE]
AS 
SELECT 
    CC.CLIENTE AS CLIENTE,
	COUNT(CASE WHEN CC.TIPO = 'FAC' AND FECHA_VENCE < GETDATE() THEN 1 END) AS DOC_VENCIDOS,
    SUM(CASE WHEN CC.TIPO   = 'FAC' AND FECHA_VENCE < GETDATE() THEN CC.SALDO ELSE 0 END) AS SALDO_VENCIDO,
    CAST(COUNT(CASE WHEN CC.TIPO = 'FAC' AND FECHA_VENCE < GETDATE() THEN 1 END) AS VARCHAR) + 
	' Facturas Vencidas | Saldo Vencido: ¢' + FORMAT(SUM(CASE WHEN CC.TIPO = 'FAC' AND FECHA_VENCE < GETDATE() THEN CC.SALDO ELSE 0 END), 'N2')  AS TEXTO
	
	--+' | Saldo Actual: ¢'                    + FORMAT(MAX(CLI.SALDO), 'N2') +
	--'  | Monto a Favor: ¢'                    + FORMAT(SUM(CASE WHEN CC.TIPO IN ('REC', 'TEF', 'N/C') THEN CC.SALDO ELSE 0 END), 'N2') +
	--'  | Documentos a favor: '                + CAST(COUNT(CASE WHEN CC.TIPO IN ('REC', 'TEF', 'N/C') AND FECHA_VENCE <= GETDATE() THEN 1 END) AS VARCHAR) 
	--   COUNT(CASE WHEN CC.TIPO IN ('REC', 'TEF', 'N/C','O/C') AND FECHA_VENCE <= GETDATE() THEN 1 END) DOC_FAVOR,
    --   SUM(CASE WHEN CC.TIPO   IN ('REC', 'TEF', 'N/C','O/C') THEN CC.SALDO ELSE 0 END) AS MONTO_FAVOR,
	--   MAX(CLI.SALDO) AS SALDO_CLIENTE,
FROM 
    EXACTUSERP.DIS86.DOCUMENTOS_CC AS CC 
--LEFT JOIN 
-- EXACTUSERP.DIS86.SALDO_CLIENTE AS CLI ON CLI.CLIENTE = CC.CLIENTE
WHERE 
      CC.SALDO > 1
  AND CC.FECHA_VENCE < GETDATE()
 --AND CC.CLIENTE in( '1081') 
 AND CC.TIPO ='FAC'
   
GROUP BY 
    CC.CLIENTE
GO
/****** Object:  View [DIS86].[VIEW_OBT_DATOS_CLIENTE_ESTADO_CUENTA_DEBITOS_CLIENTE]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE VIEW [DIS86].[VIEW_OBT_DATOS_CLIENTE_ESTADO_CUENTA_DEBITOS_CLIENTE] 
AS 
SELECT DISTINCT 
       (SELECT ISNULL(MAX(ESTADO_VISITA),'PEN') FROM [DIS86].[VISITAS] WHERE CLIENTE =CLI.CLIENTE)                              AS ESTADO,
       CLI.CLIENTE,																						                        
	   CONCAT(CLI.CLIENTE,'-',CLI.NOMBRE)                                                                                       AS CLI_NOMBRE,
	   CLI.ALIAS,
	   CLI.VENDEDOR																		                                        AS COD_VENDEDOR,
       VEN.NOMBRE                       													                                    AS NOMBRE_VENDEDOR ,
	   CONCAT(CLI.VENDEDOR,' - ',VEN.NOMBRE)                                                                                    AS VEN_NOMBRE,
	   CLI.E_MAIL                                                                                                               AS EMAIL,
	   CLI.TELEFONO1																		                                    AS TELEFONO,
	   CLI.CONDICION_PAGO,
	   CONVERT(VARCHAR,CP.DIAS_NETO) +' Dias '                                                                                  AS DIAS_NETO,
	   ISNULL([DIS86].[OBTENER_SALDO_DEBITO_CLIENTE] (CLI.CLIENTE),0) 							                                        AS SALDO,  --- ISNULL(SC.SALDO,0) ANTES [DIS86].[OBTENER_SALDO_DEBITO_CLIENTE] (@CLIENTE VARCHAR(50)
	   (SELECT MAX(CONVERT(VARCHAR,FECHA_VISITA,103)) FROM [DIS86].[VISITAS] WHERE CLIENTE =CLI.CLIENTE)                        AS FECHA_ULTIMA_VISITA,
	   
	   CASE WHEN (CLI.U_SEMANA_VISITA = 'ND' OR 
	              CLI.U_SEMANA_VISITA IS NULL OR
				  CLI.U_SEMANA_VISITA ='') THEN (SELECT TOP 1 SEMANA 
				                              FROM [PS_TRACKING].[DIS86].[VISITAS] AS VTA 
                                              WHERE CLIENTE = CLI.CLIENTE ORDER BY FECHA_VISITA DESC )
	   ELSE   ISNULL(CLI.U_SEMANA_VISITA,'1')  END                                                                              AS SEMANA,
	   ISNULL(CLI.U_ORDEN_VISITA,0)                                                                                             AS U_ORDEN_VISITA,
	   (SELECT MAX(ID_VISITA) FROM [DIS86].[VISITAS] WHERE CLIENTE =CLI.CLIENTE)                                                AS ID_VISITA,
	   CLI.COBRADOR,
	   CONCAT(CLI.COBRADOR,' | ', COB.NOMBRE)                                                                                   AS  COD_NOMBRE_COBRADOR,
	   ISNULL((SELECT SUM(DOC_VENCIDOS) FROM [DIS86].[VIEW_OBT_SALDO_VENCIDO_CLIENTE] AS DV WHERE DV.CLIENTE = CLI.CLIENTE),0)  AS DOC_VENC,
		
		CASE WHEN (CLI.U_DIA_VISITA = 'ND' OR 
	              CLI.U_DIA_VISITA IS NULL OR
				  CLI.U_DIA_VISITA ='') THEN (SELECT TOP 1 DIA 
				                              FROM [PS_TRACKING].[DIS86].[VISITAS] AS VTA 
                                              WHERE CLIENTE = CLI.CLIENTE ORDER BY FECHA_VISITA DESC )  
			ELSE CLI.U_DIA_VISITA END                                                                                           AS DIAS_RUTA

FROM  EXACTUSERP.DIS86.CLIENTE              AS CLI WITH(NOLOCK)
JOIN  EXACTUSERP.DIS86.VENDEDOR             AS VEN WITH(NOLOCK)  ON VEN.VENDEDOR      = CLI.VENDEDOR 
JOIN  EXACTUSERP.DIS86.COBRADOR             AS COB WITH(NOLOCK)  ON COB.COBRADOR      = CLI.COBRADOR
JOIN  EXACTUSERP.DIS86.CONDICION_PAGO       AS CP  WITH(NOLOCK)  ON CP.CONDICION_PAGO = CLI.CONDICION_PAGO
--LEFT JOIN  EXACTUSERP.DIS86.SALDO_CLIENTE   AS SC  WITH(NOLOCK)  ON SC.CLIENTE        = CLI.CLIENTE AND SC.MONEDA = CLI.MONEDA
WHERE CLI.ACTIVO = 'S'
--AND   CLI.CLIENTE='2287'








GO
/****** Object:  View [DIS86].[Produsoft_View_EC_CxC]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE VIEW [DIS86].[Produsoft_View_EC_CxC]
AS

-- ========================
-- PRIMER SELECT (FAC, O/D)
-- ========================
SELECT 
    CC.CLIENTE,
    CC.DOCUMENTO,
    CC.TIPO,
    CC.MONEDA,
    CC.MONTO,
    CC.SALDO,
    CC.FECHA_DOCUMENTO AS FECHA_DOCUMENTO,
    CC.FECHA_VENCE     AS FECHA_VENCE,
    0 AS INTERES_MORA,
    CC.TIPO + ' - ' + CC.DOCUMENTO AS TIPO_DOCUMENTO,
    CLI.NOMBRE + ' *** ' + ISNULL(CLI.ALIAS, CLI.NOMBRE) AS NOMBRE,
    VEN.NOMBRE AS NOMBRE_VENDEDOR,
    ISNULL(CLI.E_MAIL, 'SIN DEFINIR')  AS EMAIL_VENDEDOR,
    ISNULL(COB.E_MAIL, 'SIN DEFINIR')  AS EMAIL_VENDEDOR2,
    FAC.RUBRO5 AS DIRECCION,
    VEN.VENDEDOR,
    VEN.NOMBRE AS NOMBRE_VENDEDOR_NI,
    CASE WHEN CC.TIPO IN ('O/D','FAC') THEN 'DEBITO' ELSE 'CREDITO' END AS TIPO_DOC,
    RAZON_SOCIAL,
    COB.NOMBRE AS NOMBRE_COBRADOR,
    CASE WHEN CC.FECHA_VENCE <= GETDATE() AND CC.TIPO <> 'O/D' THEN CC.SALDO ELSE 0 END AS SALDOVENCIDO,
    CASE WHEN (CC.FECHA_VENCE > GETDATE()) OR (CC.FECHA_VENCE <= GETDATE() AND CC.TIPO = 'O/D') THEN CC.SALDO ELSE 0 END AS SALDO_NO_VENCIDO,
    ISNULL(FAC.RUBRO5,'') AS REFERENCIA,
    ISNULL(COB.E_MAIL,'ND') AS EMAIL_COBRADOR,
    CASE      
        WHEN DATEDIFF(DAY, CC.FECHA_VENCE, GETDATE()) < 1  THEN 'a- Sin Vencer'
        WHEN DATEDIFF(DAY, CC.FECHA_VENCE, GETDATE()) BETWEEN 1  AND 7  THEN 'b- 1 a 7 dias Vencido'
        WHEN DATEDIFF(DAY, CC.FECHA_VENCE, GETDATE()) BETWEEN 8  AND 15 THEN 'c- 8 a 15 dias Vencido'
        WHEN DATEDIFF(DAY, CC.FECHA_VENCE, GETDATE()) BETWEEN 16 AND 30 THEN 'd- 16 a 30 dias Vencido'
        WHEN DATEDIFF(DAY, CC.FECHA_VENCE, GETDATE()) BETWEEN 31 AND 60 THEN 'e- 31 a 60 dias Vencido'
        WHEN DATEDIFF(DAY, CC.FECHA_VENCE, GETDATE()) BETWEEN 61 AND 90 THEN 'f- 61 a 90 dias Vencido'
        WHEN DATEDIFF(DAY, CC.FECHA_VENCE, GETDATE()) > 90        THEN 'f- Mayor a 90 dias'
    END AS VENCIMIENTO,
    DATEDIFF(DAY, CC.FECHA_DOCUMENTO, CC.FECHA_VENCE) AS CONDICION_PAGO_DIAS,
    DATEDIFF(DAY, CC.FECHA_VENCE, GETDATE())          AS DIAS_VENCE,
	CC.CONDICION_PAGO
FROM EXACTUSERP.DIS86.DOCUMENTOS_CC CC WITH (NOLOCK)
LEFT JOIN EXACTUSERP.DIS86.CLIENTE  CLI WITH (NOLOCK) ON CLI.CLIENTE   = CC.CLIENTE
LEFT JOIN EXACTUSERP.DIS86.VENDEDOR VEN WITH (NOLOCK) ON VEN.VENDEDOR  = CLI.VENDEDOR
LEFT JOIN EXACTUSERP.DIS86.NIT      NIT WITH (NOLOCK) ON NIT.NIT       = CLI.CONTRIBUYENTE
LEFT JOIN EXACTUSERP.DIS86.COBRADOR COB WITH (NOLOCK) ON COB.COBRADOR  = CLI.COBRADOR
LEFT JOIN EXACTUSERP.DIS86.FACTURA  FAC WITH (NOLOCK) ON FAC.FACTURA   = CC.DOCUMENTO

WHERE 
    CC.SALDO > (CASE WHEN CC.MONEDA = 'USD' THEN 1 ELSE 500 END)
    AND CC.TIPO IN ('O/D','FAC')

UNION ALL

-- ============================
-- SEGUNDO SELECT (N/C, O/C…)
-- ============================
SELECT 
    CC.CLIENTE,
    CC.DOCUMENTO,
    CC.TIPO,
    CC.MONEDA,
    CASE WHEN CC.TIPO IN ('O/C','N/C') THEN CC.MONTO  * -1 ELSE CC.MONTO  END AS MONTO,
    CASE WHEN CC.TIPO IN ('O/C','N/C') THEN CC.SALDO  * -1 ELSE CC.SALDO  END AS SALDO,
    CC.FECHA_DOCUMENTO AS FECHA_DOCUMENTO,
    CC.FECHA_VENCE     AS FECHA_VENCE,
    0 AS INTERES_MORA,
    CC.TIPO + ' - ' + CC.DOCUMENTO AS TIPO_DOCUMENTO,
    CLI.NOMBRE + ' *** ' + ISNULL(CLI.ALIAS, CLI.NOMBRE) AS NOMBRE,
    VEN.VENDEDOR + ' *** ' + VEN.NOMBRE AS NOMBRE_VENDEDOR,
    ISNULL(CLI.E_MAIL,'SIN DEFINIR') AS EMAIL_VENDEDOR,
    ISNULL(COB.E_MAIL,'SIN DEFINIR') AS EMAIL_VENDEDOR2,
    FAC.RUBRO5 AS DIRECCION,
    VEN.VENDEDOR,
    VEN.NOMBRE AS NOMBRE_VENDEDOR_NI,
    CASE WHEN CC.TIPO IN ('O/D','FAC') THEN 'DEBITO' ELSE 'CREDITO' END AS TIPO_DOC,
    RAZON_SOCIAL,
    COB.NOMBRE AS NOMBRE_COBRADOR,
    CASE 
        WHEN CC.FECHA_VENCE <= GETDATE() AND CC.TIPO IN('O/C','N/C') THEN 0
        WHEN CC.FECHA_VENCE <= GETDATE() AND CC.TIPO NOT IN('O/C','N/C') THEN CC.SALDO
        ELSE 0 
    END AS SALDOVENCIDO,
    CASE 
        WHEN (CC.FECHA_VENCE > GETDATE() AND CC.TIPO IN('O/C','N/C')) 
          OR (CC.FECHA_VENCE <= GETDATE() AND CC.TIPO IN('O/C','N/C')) THEN CC.SALDO * -1
        WHEN (CC.FECHA_VENCE > GETDATE() AND CC.TIPO NOT IN('O/C','N/C')) THEN CC.SALDO
        ELSE 0 
    END AS SALDO_NO_VENCIDO,
    ISNULL(FAC.RUBRO5,'') AS REFERENCIA,
    ISNULL(COB.E_MAIL,'ND') AS EMAIL_COBRADOR,
    CASE      
        WHEN DATEDIFF(DAY, CC.FECHA_VENCE, GETDATE()) < 1  THEN 'a- Sin Vencer'
        WHEN DATEDIFF(DAY, CC.FECHA_VENCE, GETDATE()) BETWEEN 1  AND 7  THEN 'b- 1 a 7 dias Vencido'
        WHEN DATEDIFF(DAY, CC.FECHA_VENCE, GETDATE()) BETWEEN 8  AND 15 THEN 'c- 8 a 15 dias Vencido'
        WHEN DATEDIFF(DAY, CC.FECHA_VENCE, GETDATE()) BETWEEN 16 AND 30 THEN 'd- 16 a 30 dias Vencido'
        WHEN DATEDIFF(DAY, CC.FECHA_VENCE, GETDATE()) BETWEEN 31 AND 60 THEN 'e- 31 a 60 dias Vencido'
        WHEN DATEDIFF(DAY, CC.FECHA_VENCE, GETDATE()) BETWEEN 61 AND 90 THEN 'f- 61 a 90 dias Vencido'
        WHEN DATEDIFF(DAY, CC.FECHA_VENCE, GETDATE()) > 90        THEN 'f- Mayor a 90 dias'
    END AS VENCIMIENTO,
    DATEDIFF(DAY, CC.FECHA_DOCUMENTO, CC.FECHA_VENCE) AS CONDICION_PAGO_DIAS,
    DATEDIFF(DAY, CC.FECHA_VENCE, GETDATE())          AS DIAS_VENCE,
	CC.CONDICION_PAGO
FROM EXACTUSERP.DIS86.DOCUMENTOS_CC CC WITH (NOLOCK)
LEFT JOIN EXACTUSERP.DIS86.CLIENTE  CLI WITH (NOLOCK) ON CLI.CLIENTE   = CC.CLIENTE
LEFT JOIN EXACTUSERP.DIS86.VENDEDOR VEN WITH (NOLOCK) ON VEN.VENDEDOR  = CLI.VENDEDOR
LEFT JOIN EXACTUSERP.DIS86.NIT      NIT WITH (NOLOCK) ON NIT.NIT       = CLI.CONTRIBUYENTE
LEFT JOIN EXACTUSERP.DIS86.COBRADOR COB WITH (NOLOCK) ON COB.COBRADOR  = CLI.COBRADOR
LEFT JOIN EXACTUSERP.DIS86.FACTURA  FAC WITH (NOLOCK) ON FAC.FACTURA   = CC.DOCUMENTO
WHERE 
    CC.SALDO > (CASE WHEN CC.MONEDA = 'USD' THEN 1 ELSE 500 END)
    AND CC.TIPO NOT IN ('O/D','FAC','REC','TEF')
GO
