CREATE VIEW [DIS86].[VIEW_ESTADO_CUENTA]
AS 
	select		
		C.CLIENTE, 
		C.CLIENTE +  ' - ' + C.NOMBRE NOMBRE_CLIENTE, 
		isnull(p.EMAIL_VENDEDOR2,'sin definir') EMAIL_VENDEDOR,
		max(p.moneda) MONEDA, 
		max(P.DIRECCION) DIRECCION,
		convert(varchar,cast( SUM(p.SALDO) as money),1)  SALDO, 
		convert(varchar(20),max(p.FECHA_DOCUMENTO)) aNOMesFechaDocumento, 
		ISNULL(C.e_mail,'SIN DEFINIR') EMAIL_CLIENTE,
		'N' AS MARCA 
		from		PS_TRACKING.DIS86.PRODUSOFT_VIEW_EC_CXC_BASE	 P,
					EXACTUSERP.DIS86.CLIENTE C
			WHERE		 c.CLIENTE = p.CLIENTE
						--and c.ES_CORPORACION = 'N'
						--and c.CLIENTE not in(select CLI_CORPORAC_ASOC from EXACTUSERP.DIS86.CLIENTE where CLI_CORPORAC_ASOC is not null) 
						
			GROUP BY	C.CLIENTE, C.NOMBRE,c.E_MAIL, p.email_vendedor2,p.moneda
			HAVING		SUM(p.SALDO) > 0 
GO
/****** Object:  View [DIS86].[VIEW_CUENTAS_COBRAR_CORPORATIVO]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [DIS86].[VIEW_CUENTAS_COBRAR_CORPORATIVO]
AS 
	select  
		DCC.cliente_reporte CLIENTE_ORIGEN, 
		C.CLIENTE, 
		C.NOMBRE, 
		DCC.DOCUMENTO, 
		DCC.TIPO, 
		DCC.SUBTIPO, 
		DCC.MONTO,
		CASE 
			WHEN DCC.TIPO = 'REC' THEN convert(decimal(28,2),DCC.SALDO*-1) 
			WHEN DCC.TIPO = 'N/C' THEN convert(decimal(28,2),DCC.SALDO*-1) 
			ELSE convert(decimal(28,2),DCC.SALDO)
		END SALDO,  
		DCC.FECHA, 
		DCC.MONTO_LOCAL, 
		DCC.SALDO_LOCAL,
		YEAR(DCC.fecha_documento) AS AnoFechaDocumento,
		DATEPART(QUARTER,DCC.fecha_documento) AS TrimestreFechaDocumento,
		MONTH(DCC.fecha_documento) AS MesFechaDocumento,
		CAST(YEAR(DCC.fecha_documento)AS VARCHAR) + '-'+ RIGHT('0' + CAST(MONTH(DCC.fecha_documento) AS VARCHAR), 2) AS aNOMesFechaDocumento,
		case DCC.SALDO  WHEN 0 THEN 'CANCELADO' ELSE 'PENDIENTE' END ESTADO,
		S.DESCRIPCION,
		datediff(dd, dcc.fecha_documento, getdate()) diasVencido,
		c.e_mail,
		dcc.MONEDA,
		C.CLI_CORPORAC_ASOC,
		C.ES_CORPORACION
		,VEN.E_MAIL AS E_MAIL_VENDEDOR
			from	 EXACTUSERP.DIS86.DOCUMENTOS_CC  DCC,
					 EXACTUSERP.DIS86.CLIENTE   C,
  					 EXACTUSERP.DIS86.SUBTIPO_DOC_CC S
					,EXACTUSERP.DIS86.CLIENTE_VENDEDOR CV
			        ,EXACTUSERP.DIS86.VENDEDOR VEN 
				where
					C.CLIENTE = DCC.CLIENTE_REPORTE 
					AND DCC.SUBTIPO = S.SUBTIPO
					AND DCC.TIPO = S.TIPO 
					AND DCC.SALDO > 0
					and dcc.TIPO in ('FAC','O/D','N/D','N/C','O/C','REC') 
					AND CV.CLIENTE = C.CLIENTE
			        AND VEN.VENDEDOR = CV.VENDEDOR
GO
