/****** Object:  View [DIS86].[OBT_DEBITOS_POR_CREDITO_DOCUMENTOS_CC]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
