CREATE VIEW [DIS86].[OBT_DEBITOS_POR_CREDITO_DOCUMENTOS_CC] 
AS 
SELECT 
      AUX.TIPO_DEBITO AS TIPO,
	  AUX.DEBITO AS DOCUMENTO,
	  CONVERT(VARCHAR,AUX.FECHA,105) FECHA,
	  CONVERT(VARCHAR,CC.FECHA_VENCE,105) FECHA_VENCE,
	  CASE WHEN SALDO <=0 THEN 0 ELSE DATEDIFF(day, CC.FECHA_VENCE, GETDATE()) END  AS  DIAS_VENC ,
	  AUX.MONEDA_DEBITO MONEDA,
	  AUX.MONTO_DEBITO  MONTO,
	  AUX.MONTO_CREDITO MONTO_APLICADO,
	  CC.SALDO,
	  AUX.CREDITO
FROM EXACTUSERP.DIS86.AUXILIAR_CC AS AUX
INNER JOIN EXACTUSERP.DIS86.DOCUMENTOS_CC AS CC ON AUX.CREDITO = CC.DOCUMENTO 
--WHERE CREDITO ='C001|00000140'
GO
/****** Object:  View [DIS86].[Produsoft_View_EC_AuxCxC]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE VIEW [DIS86].[Produsoft_View_EC_AuxCxC]
as
 
SELECT T.*
      ,T.TIPO + ' - ' + T.DOCUMENTO AS TIPO_DOCUMENTO
      ,CLI.NOMBRE
	  ,AUX.TIPO_CREDITO
	  ,AUX.CREDITO
	  ,CONVERT(DATE,AUX.FECHA) AS FECHA_APLICACION
	  ,0 AS MONTO_DEBITO
	  ,ISNULL(CASE WHEN T.MONEDA = 'USD' THEN  AUX.MONTO_DOLAR
	               ELSE AUX.MONTO_LOCAL
	           END , 0 ) AS MONTO_CREDITO
 FROM
   (
	SELECT CC.CLIENTE
		  ,CC.DOCUMENTO
		  ,CC.TIPO
		  ,CC.MONEDA
		  ,CC.MONTO
		  ,CC.SALDO	  
		  ,CONVERT(DATE,CC.FECHA_DOCUMENTO) AS FECHA_DOCUMENTO
		  ,CONVERT(DATE,CC.FECHA_VENCE) AS FECHA_VENCE
	  FROM EXACTUSERP.DIS86.DOCUMENTOS_CC CC
	 WHERE CC.SALDO > (CASE WHEN CC.MONEDA = 'USD' THEN 1 ELSE 1000 END )
   ) T
   JOIN EXACTUSERP.DIS86.CLIENTE CLI ON CLI.CLIENTE = T.CLIENTE
   LEFT JOIN EXACTUSERP.DIS86.AUXILIAR_CC AUX ON AUX.DEBITO = T.DOCUMENTO AND AUX.TIPO_DEBITO = T.TIPO
WHERE T.TIPO IN ('FAC','O/D')
	and t.TIPO not in ('INT') 
UNION 
SELECT T.*
      ,T.TIPO + ' - ' + T.DOCUMENTO AS TIPO_DOCUMENTO
      ,CLI.NOMBRE
	  ,AUX.TIPO_DEBITO
	  ,AUX.DEBITO
	  ,CONVERT(DATE,AUX.FECHA) AS FECHA_APLICACION
	  ,ISNULL(CASE WHEN T.MONEDA = 'USD' THEN  AUX.MONTO_DOLAR
	               ELSE AUX.MONTO_LOCAL
	          END , 0 )AS MONTO_DEBITO
	  , 0 AS MONTO_CREDITO
 FROM
   (
	SELECT CC.CLIENTE
		  ,CC.DOCUMENTO
		  ,CC.TIPO
		  ,CC.MONEDA
		  ,CC.MONTO
		  ,CC.SALDO	  
		  ,CONVERT(DATE,CC.FECHA_DOCUMENTO) AS FECHA_DOCUMENTO
		  ,CONVERT(DATE,CC.FECHA_VENCE) AS FECHA_VENCE
			  FROM EXACTUSERP.DIS86.DOCUMENTOS_CC CC
				 WHERE CC.SALDO > (CASE WHEN CC.MONEDA = 'USD' THEN 1 ELSE 1000 END )
			   ) T
		JOIN EXACTUSERP.DIS86.CLIENTE CLI ON CLI.CLIENTE = T.CLIENTE
		LEFT JOIN EXACTUSERP.DIS86.AUXILIAR_CC AUX ON AUX.CREDITO = T.DOCUMENTO AND AUX.TIPO_CREDITO = T.TIPO
			WHERE T.TIPO NOT IN ('FAC','O/D','REC','TEF') and t.TIPO not in ('INT') 

GO
/****** Object:  View [DIS86].[PS_H2H_TEF_VIEW_PARA_INSERTAR_TEF_EN_AUXILIAR_CP]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO





CREATE VIEW  [DIS86].[PS_H2H_TEF_VIEW_PARA_INSERTAR_TEF_EN_AUXILIAR_CP]
AS

SELECT  CP.PROVEEDOR											AS PROVEEDOR,
		'TEF'													AS TIPO_DEBITO,
		U_TRANSFERENCIA AS DEBITO,
		CAST(CAST(FECHA_PROYECTADA AS VARCHAR(12)) AS DATETIME)	AS FECHA,
		CP.TIPO													AS TIPO_CREDITO,
		DOCUMENTO												AS CREDITO,
		MONTO_PAGO												AS MONTO_DEBITO,
		CASE WHEN P.MONEDA = 'USD' AND CP.MONEDA = 'USD' 
				THEN MONTO_PAGO 
			 WHEN P.MONEDA = 'USD' AND CP.MONEDA = 'CRC' 
				THEN MONTO_PAGO / 1
			 WHEN P.MONEDA = 'CRC' AND CP.MONEDA = 'CRC' 
				THEN MONTO_PAGO
			 WHEN P.MONEDA = 'CRC' AND CP.MONEDA = 'USD' 
				THEN MONTO_PAGO * 1
		ELSE MONTO_PAGO
		END														AS MONTO_PROV,
		CASE WHEN CP.MONEDA = 'USD' 
			 THEN MONTO_PAGO * 1 
			 ELSE MONTO_PAGO
		END														AS MONTO_LOCAL,
		CASE WHEN CP.MONEDA = 'USD' 
			 THEN MONTO_PAGO
			 ELSE MONTO_PAGO / 1
		END														AS MONTO_DOLAR,
		CP.MONEDA												AS MONEDA_DEBITO,
		MONTO_PAGO												AS MONTO_CREDITO,
		CP.MONEDA												AS MONEDA_CREDITO,
		NULL													AS ASIENTO, --EL ASIENTO SE ENVIA NULL PORQUE DE LO CONTRARIO EXACTUSERP LO REVERSA
		NULL													AS TIPO_DOCPPAGO,
		NULL													AS DOCUMENTO_DOCPPAGO,
		NULL													AS TIPO_DOCINTCTE,
		NULL													AS DOC_DOCINTCTE,
		NULL													AS FOLIOSAT_DEBITO,
		NULL													AS FOLIOSAT_CREDITO,
		1.00000000												AS TIPO_CAMBIO_APLICA,
		NULL													AS ASIENTO_DIF_CAMB_MR,
		NULL													AS MONTO_TOTAL_RET_PAGO,
		NULL													AS CODIGO_RET_PAGO
		FROM EXACTUSERP.DIS86.DOCUMENTOS_CP CP
		--JOIN [DIS86].[PS_VIEW_PARA_TIPO_CAMBIO_DOCUMENTOS_CP] TC ON TC.FECHA_PARA_VIEW = FORMAT(GETDATE(),'yyy-MM-dd') AND TC.TIPO_CAMBIO = 'TVEN'
		JOIN EXACTUSERP.DIS86.PROVEEDOR P ON P.PROVEEDOR = CP.PROVEEDOR
		--WHERE U_TRANSFERENCIA = '1313'
		--OR U_TRANSFERENCIA = '1314'
GO
