CREATE VIEW  [DIS86].[PS_H2H_TEF_VIEW_PARA_INSERTAR_TEF_EN_DET_TRANS_CB]
AS

SELECT 
	CAST(ROW_NUMBER() OVER(PARTITION BY U_TRANSFERENCIA ORDER BY U_TRANSFERENCIA ASC) AS VARCHAR) + '.00000000'			AS CONSECUTIVO,
	CP.CUENTA_BANCO																							AS CUENTA_ORIGEN,
	'T/D'																									AS TIPO_ORIGEN,
	U_TRANSFERENCIA																							AS NUMERO_ORIGEN,
	PE.CUENTA_BANCO																							AS CUENTA_DESTINO,
	'T/D'																									AS TIPO_DESTINO,
	U_TRANSFERENCIA																							AS NUMERO_DESTINO,
	0.00000000																								AS MONTO_COMISION,
	1																								AS TIPO_CAMBIO,
	MONTO_PAGO																								AS MONTO_ORIGEN,
	MONTO_PAGO																								AS MONTO_DESTINO,
	'DIS86'																								AS COMPANIA_DESTINO,
	'T'																										AS TIPO_MOV,
	P.NOMBRE																								AS BENEFICIARIO,
	CP.PROVEEDOR																							AS CONTRIBUYENTE,
	CP.DOCUMENTO																							AS CONCEPTO,
	PE.ENTIDAD_FINANCIERA																					AS ENTIDAD_FINANCIERA,
	CP.MONEDA																								AS MONEDA,
	CP.PROVEEDOR																							AS RUBRO1_DETTRANS,
	'PS - Proyeccion de Pagos'																				AS RUBRO2_DETTRANS,
	NULL																									AS RUBRO3_DETTRANS,
	NULL																									AS RUBRO4_DETTRANS,
	NULL																									AS RUBRO5_DETTRANS,
	NULL																									AS RUBRO6_DETTRANS,
	NULL																									AS RUBRO7_DETTRANS,
	NULL																									AS RUBRO8_DETTRANS,
	NULL																									AS RUBRO9_DETTRANS,
	NULL																									AS RUBRO10_DETTRANS,
	NULL																									AS CTR_CIERRE_TERCEROS,
	NULL																									AS CTA_CIERRE_TERCEROS,
	NULL																									AS METODO_PAGO
	FROM EXACTUSERP.DIS86.DOCUMENTOS_CP CP
	JOIN EXACTUSERP.DIS86.PROVEEDOR_ENTIDAD PE ON PE.PROVEEDOR = CP.PROVEEDOR AND PE.CTA_DEFAULT = 'S' AND PE.MONEDA = CP.MONEDA
	JOIN EXACTUSERP.DIS86.PROVEEDOR P ON P.PROVEEDOR = CP.PROVEEDOR AND P.PROVEEDOR = PE.PROVEEDOR
	--JOIN [DIS86].[PS_VIEW_PARA_TIPO_CAMBIO_DOCUMENTOS_CP] TC ON TC.FECHA_PARA_VIEW = FORMAT(GETDATE(),'yyy-MM-dd') AND TC.TIPO_CAMBIO = 'TVEN'
GO
