CREATE VIEW  [DIS86].[PS_H2H_TEF_VIEW_PARA_INSERTAR_TEF_EN_DOCUMENTOS_CP]
AS

SELECT
	CP.PROVEEDOR											AS PROVEEDOR,
	U_TRANSFERENCIA											AS DOCUMENTO,
	'TEF'													AS TIPO,
	'N'														AS EMBARQUE_APROBADO,
	NULL													AS TIPO_CAMB_LIQ_LOC,
	NULL													AS TIPO_CAMB_LIQ_DOL,
	CAST(CAST(FECHA_PROYECTADA AS VARCHAR(12)) AS DATETIME)	AS FECHA_DOCUMENTO,
	CAST(CAST(FECHA_PROYECTADA AS VARCHAR(12)) AS DATETIME)	AS FECHA,
	NULL													AS TIPO_PRORRATEO,
	NULL													AS ETIQUETA,
	'N'														AS TIPO_EMBARQUE,
	--LEFT(LEFT(P.NOMBRE,35) 
	--+ ' | ' 
	--+ STRING_AGG(RIGHT(CP.DOCUMENTO,8), '_'),249)			AS APLICACION,
	'' AS APLICACION,
	SUM(MONTO_PAGO)											AS MONTO,
	0.00000000												AS SALDO,
	SUM(CASE WHEN CP.MONEDA = 'CRC'
		 THEN MONTO_PAGO
		 ELSE MONTO_PAGO * 1
	END)													AS MONTO_LOCAL,
	0.00000000												AS SALDO_LOCAL,
	SUM(CASE WHEN CP.MONEDA = 'USD'
		 THEN MONTO_PAGO
		 ELSE MONTO_PAGO / 1 	
	END)													AS MONTO_DOLAR,
	0.00000000												AS SALDO_DOLAR,
	CASE WHEN CP.MONEDA = 'USD' 
		THEN 1 
		ELSE 1.00000000
	END														AS TIPO_CAMBIO_MONEDA,
	1												AS TIPO_CAMBIO_DOLAR,
	CAST(CAST(FECHA_PROYECTADA AS VARCHAR(12)) AS DATETIME)	AS FECHA_ULT_CREDITO,
	'S'														AS CHEQUE_IMPRESO,
	'N'														AS APROBADO,
	'N'														AS SELECCIONADO,
	'N'														AS CONGELADO,
	SUM(CASE WHEN P.MONEDA = 'USD' AND CP.MONEDA = 'USD' 
				THEN MONTO_PAGO 
			 WHEN P.MONEDA = 'USD' AND CP.MONEDA = 'CRC' 
				THEN MONTO_PAGO / 1
			 WHEN P.MONEDA = 'CRC' AND CP.MONEDA = 'CRC' 
				THEN MONTO_PAGO
			 WHEN P.MONEDA = 'CRC' AND CP.MONEDA = 'USD' 
				THEN MONTO_PAGO * 1
		ELSE MONTO_PAGO
		END
	)														AS MONTO_PROV,
	0.00000000												AS SALDO_PROV,
	CASE WHEN P.MONEDA = 'USD' 
		THEN 1 
		ELSE 1.00000000
	END														AS TIPO_CAMBIO_PROV,
	SUM(MONTO_PAGO)											AS SUBTOTAL,
	0.00000000												AS DESCUENTO,
	0.00000000												AS IMPUESTO1,
	0.00000000												AS IMPUESTO2,
	0.00000000												AS RUBRO1,
	0.00000000												AS RUBRO2,
	GETDATE()												AS FECHA_ULT_MOD,
	0.00000000												AS MONTO_RETENCION,
	0.00000000												AS SALDO_RETENCION,
	'N'														AS DEPENDIENTE,
	NULL													AS ASIENTO,
	'S'														AS ASIENTO_PENDIENTE,
	''														AS NOTAS,
	CASE WHEN CP.MONEDA = 'USD' 
		THEN 1 
		ELSE 1.00000000
	END														AS TIPO_CAMB_ACT_LOC,
	1												AS TIPO_CAMB_ACT_DOL, 
	CASE WHEN P.MONEDA = 'USD'
		THEN 1
		ELSE 1.00000000	
	END														AS TIPO_CAMB_ACT_PROV,
	'N' DOCUMENTO_EMBARQUE,
	NULL													AS FECHA_REVISION,
	NULL													AS LIQUIDAC_COMPRA,
	--LEFT(STRING_AGG(CP.USUARIO_ULT_MOD, ' | '),50)			AS USUARIO_ULT_MOD,
	'' AS USUARIO_ULT_MOD,
	0														AS CONDICION_PAGO,
	CP.MONEDA,
	CP.CUENTA_BANCO											AS CHEQUE_CUENTA,
	NULL													AS CONTRARECIBO,
	0														AS SUBTIPO,
	CAST(CAST(FECHA_PROYECTADA AS VARCHAR(12)) AS DATETIME)	AS FECHA_VENCE,
	NULL													AS FECHA_ANUL,
	NULL													AS AUD_USUARIO_ANUL,
	NULL													AS AUD_FECHA_ANUL,
	NULL													AS USUARIO_APROBACION,
	NULL													AS FECHA_APROBACION,
	NULL													AS MONTO_PAGO,
	NULL													AS USUARIO,
	NULL													AS CUENTA_BANCO,
	NULL													AS TIPO_CAMBIO,
	'N'														AS ANULADO,
	NULL													AS CODIGO_IMPUESTO,
	NULL													AS PAIS,
	P.DIVISION_GEOGRAFICA1									AS DIVISION_GEOGRAFICA1,
	P.DIVISION_GEOGRAFICA2									AS DIVISION_GEOGRAFICA2,
	0.00000000												AS BASE_IMPUESTO1,
	0.00000000												AS BASE_IMPUESTO2,
	'N'														AS DEPENDIENTE_GP,
	0.00000000												AS SALDO_TRANS,
	0.00000000												AS SALDO_TRANS_LOCAL,
	0.00000000												AS SALDO_TRANS_DOLAR,
	NULL													AS FECHA_PROYECTADA,
	0.00000000												AS IMP1_ASUMIDO_DESC,
	0.00000000												AS IMP1_ASUMIDO_NODESC,
	0.00000000												AS IMP1_RETENIDO_DESC,
	0.00000000												AS IMP1_RETENIDO_NODESC,
	'CP'													AS TIPO_ASIENTO,
	'CP'													AS PAQUETE,
	NULL													AS DOCUMENTO_FISCAL,
	NULL													AS ESTADO_ENVIO,
	NULL													AS CONCEPTO_ME,
	'N'														AS PARTICIPA_IETU,
	'N'														AS CLASE_DOCUMENTO,
	0.00000000												AS PORC_INTCTE,
	NULL													AS CONTRATO,
	0														AS NUM_PARCIALIDADES,
	NULL													AS TASA_IMPOSITIVA,
	NULL													AS TASA_IMPOSITIVA_PORC, 
	NULL													AS TASA_CREE1,
	NULL													AS TASA_CREE1_PORC,
	NULL													AS TASA_CREE2,
	NULL													AS TASA_CREE2_PORC,
	NULL													AS TASA_GAN_OCASIONAL_PORC,
	'N'														AS GENERA_DOC_FE,
	NULL													AS DOCUMENTO_GLOBAL, 
	NULL													AS FECHA_CAI,
	NULL													AS CAI,
	NULL													AS TIPO_IMPUESTO1,
	NULL													AS TIPO_TARIFA1,
	NULL													AS TIPO_IMPUESTO2,
	NULL													AS TIPO_TARIFA2,
	NULL													AS TIPO_AFECTACION_IVA,
	NULL													AS TIPO_IMPUESTO_AFECTACION,
	NULL													AS TIPO_TARIFA_AFECTACION,
	NULL													AS PORC_AFECTACION_IVA,
	NULL													AS MontoTotalImpuestoAcreditar,
	NULL													AS MontoTotalDeGastoAplicable,
	NULL													AS MontoProporcionalidad,
	NULL													AS UR,
	NULL													AS CLAVE_DE,
	NULL													AS CONSECUTIVO_DOC,
	'701002'												AS ACTIVIDAD_COMERCIAL,
	NULL													AS ITEM_HACIENDA,
	NULL													AS TIPO_DOC_REFERENCIA,
	NULL													AS CLAVE_REFERENCIA,
	NULL													AS FECHA_EMISION_REFERENCIA,
	NULL													AS CODIGO_REFERENCIA,
	NULL													AS RAZON_REFERENCIA,
	0.00000000												AS SUBTOTAL_BIENES,
	0.00000000												AS SUBTOTAL_SERVICIOS,
	NULL													AS NCF_MODIFICADO,
	NULL													AS DESTINO_ITBIS,
	'ND'													AS TIPO_PAGO,
	NULL													AS METODO_PAGO,
	NULL													AS MONTO_REFERENCIA,
	'N'														AS GENE_DOC_DETRAC,
	NULL													AS TIPO_DETRAC,
	NULL													AS ACT_DETRAC,
	NULL													AS PORC_DETRAC,
	'N'														AS ESTADO,
	NULL													AS AD_VALOREM,
	NULL													AS VALOR_ADUANA,
	NULL													AS ADUANA,
	NULL													AS DEDUC_COSTO_ENAJENA,
	NULL													AS RENTA_NETA,
	NULL													AS TIPO_RENTA,
	NULL													AS MODALIDAD_SERVICIO,
	NULL													AS ANIO_DUA,
	NULL													AS CLASIFICACION,
	NULL													AS MONTO_NO_GRAVADO,
	NULL													AS CLASE_DOC_ES, 
	NULL													AS RESOLUCION,
	NULL													AS SERIE,
	NULL													AS CONTROL_INTERNO, 
	NULL													AS SERIE_NUMERO,
	0.00000000												AS IMPUESTO_BOLSA,
	'N'														AS PROCESO_SEMT,
	NULL													AS HISTORIAL_SEMT,
	NULL													AS COD_CONSECUTIVO,
	NULL													AS TIPO_OPERACION,
	NULL													AS FORMA_PAGO,
	NULL													AS INCOTERMS,
	NULL													AS CUFE,
	NULL													AS CODIGOQR,
	NULL													AS TIPO_MODIFICACION,
	NULL													AS RAZON_MODIFICACION,
	NULL													AS TIPO_PAGO_RD,
	NULL													AS INDICADOR_FACTURACION,
	NULL													AS PORCENTAJE_IMP1,
	NULL													AS U_APROBADOR_GERENCIAL,
	NULL													AS U_USUARIO_TEF,
	NULL													AS U_APROBADOR_FINANCIERO,
	NULL													AS U_TRANSFERENCIA,
	NULL													AS U_ENVIADO
	FROM EXACTUSERP.DIS86.DOCUMENTOS_CP CP
	JOIN EXACTUSERP.DIS86.PROVEEDOR P ON P.PROVEEDOR = CP.PROVEEDOR
	--JOIN [DIS86].[PS_VIEW_PARA_TIPO_CAMBIO_DOCUMENTOS_CP] TC ON TC.FECHA_PARA_VIEW = FORMAT(GETDATE(),'yyy-MM-dd') AND TC.TIPO_CAMBIO = 'TVEN'
	JOIN EXACTUSERP.DIS86.CUENTA_BANCARIA CB ON CB.CUENTA_BANCO = CP.CUENTA_BANCO 
	--WHERE U_TRANSFERENCIA = '12102321104701'

	GROUP BY CP.PROVEEDOR, CP.U_TRANSFERENCIA, CP.FECHA_PROYECTADA, P.NOMBRE, CP.MONEDA,
	CP.CUENTA_BANCO, P.DIVISION_GEOGRAFICA1, P.DIVISION_GEOGRAFICA2, P.PAIS, P.MONEDA, CB.MONEDA
	
	
GO
