CREATE VIEW  [DIS86].[PS_H2H_TEF_VIEW_PARA_INSERTAR_TEF_EN_MOV_BANCOS]
AS

SELECT 
	CP.CUENTA_BANCO														AS CUENTA_BANCO,
	'T/D'																AS TIPO_DOCUMENTO,
	U_TRANSFERENCIA														AS NUMERO,
	0																	AS SUBTIPO,
	CAST(CAST(FECHA_PROYECTADA AS VARCHAR(12)) AS DATETIME)				AS FECHA,
	--LEFT(STRING_AGG(P.NOMBRE, ', '),150)								AS PAGADERO_A,
	'' AS PAGADERO_A,
	'PS - Pago a Proveedores'											AS REFERENCIA,
	SUM(MONTO_PAGO)														AS MONTO,
	NULL																AS CONCIL_ACLARACION,
	NULL																AS PROVEEDOR,
	MAX(P.CONTRIBUYENTE)												AS CONTRIBUYENTE,
	'PS - Generación de Transferencia desde CP para Pago de Documentos'	AS DETALLE,
	'S'																	AS CONFIRMADO,
	'CP'																AS ORIGEN,
	NULL																AS ASIENTO,
	'N'																	AS ANULADO,
	GETDATE()															AS FCH_HORA_CREACION,
	CP.USUARIO															AS USUARIO_CREACION,
	0.00000000															AS MONTO_ANULADO,
	'N'																	AS ESTADO,
	NULL																AS CONCILIACION,
	'S'																	AS IMPRESO,
	NULL																AS DOC_REPORTADO,
	0.00000000															AS MONTO_REPORTADO,
	'X'																	AS CLASE_DIF,
	'X'																	AS ACLARADA_DIF,
	NULL																AS DOC_AJUSTE,
	NULL																AS TIPO_DOC_AJUSTE,
	NULL																AS NUMERO_DOC_AJUSTE,
	'N'																	AS CLASE_DOCUMENTO,
	'M'																	AS MODO_REGISTRO,
	'N'																	AS LIQUIDADO,
	GETDATE()															AS FCH_HORA_MODIFIC,
	CP.USUARIO															AS USUARIO_MODIFIC,
	MAX(CASE WHEN CP.MONEDA = 'USD'
		 THEN 1
		 ELSE 1.00000000
	END)																AS TIPO_CAMBIO_LOCAL,
	MAX(1)															AS TIPO_CAMBIO_DOLAR,
	NULL																AS FCH_HORA_ANULADO,
	NULL																AS USUARIO_ANULADO,
	NULL																AS REFERENCIA_ANULADO,
	'N'																	AS APROBADO,
	NULL																AS USUARIO_APROBACION,
	NULL																AS FECHA_APROBACION,
	NULL																AS TIPO_ASIENTO,
	NULL																AS PAQUETE,
	'N'																	AS DEPENDIENTE_GP,
	NULL																AS DOCUMENTO_FISCAL,
	NULL																AS FECHA_CONTABLE,
	NULL																AS COD_IMPUESTO1,
	0.00000000															AS IMPUESTO1,
	0.00000000															AS IMP1_NODES,
	NULL																AS DOCUMENTO_GLOBAL,
	NULL																AS TIPO_CF,
	NULL																AS METODO_PAGO,
	NULL																AS CONSEC_AJUSTE_NOM,
	NULL																AS VALE,
	NULL																AS COMPANIA_ORIGEN
FROM EXACTUSERP.DIS86.DOCUMENTOS_CP	CP
JOIN EXACTUSERP.DIS86.PROVEEDOR		P	ON P.PROVEEDOR = CP.PROVEEDOR
JOIN EXACTUSERP.DIS86.CUENTA_BANCARIA CB	ON CB.CUENTA_BANCO = CP.CUENTA_BANCO
--JOIN [DIS86].[PS_VIEW_PARA_TIPO_CAMBIO_DOCUMENTOS_CP] TC ON TC.FECHA_PARA_VIEW = FORMAT(GETDATE(),'yyy-MM-dd') AND TC.TIPO_CAMBIO = 'TVEN'
--WHERE U_TRANSFERENCIA = '1313'
GROUP BY CP.CUENTA_BANCO, U_TRANSFERENCIA, CP.USUARIO, FECHA_PROYECTADA
	
GO
