CREATE VIEW  [DIS86].[PS_H2H_TEF_VIEW_PARA_INSERTAR_TEF_EN_TRANSFERENCIA_CB]
AS

SELECT 
	CUENTA_BANCO														AS CUENTA_ORIGEN,
	'T/D'																AS TIPO_ORIGEN,
	U_TRANSFERENCIA														AS NUMERO_ORIGEN,
	'PS - Generación de Transferencia desde CP para Pago de Documentos'	AS DESCRIPCION,
	0.00000000															AS MONTO_COMISION,
	SUM(MONTO_PAGO)														AS MONTO_ORIGEN,
	NULL																AS ASIENTO,
	GETDATE()															AS FCH_HORA_CREACION,
	USUARIO																AS USUARIO_CREACION,
	GETDATE()															AS FCH_HORA_MODIFIC,
	USUARIO																AS USUARIO_MODIFIC,
	'G'																	AS ESTADO,
	CAST(CAST(FECHA_PROYECTADA AS VARCHAR(12)) AS DATETIME)				AS FECHA_APLICACION,
	NULL																AS RUBRO1_TRANS,
	NULL																AS RUBRO2_TRANS,
	NULL																AS RUBRO3_TRANS,
	NULL																AS RUBRO4_TRANS,
	NULL																AS RUBRO5_TRANS,
	NULL																AS RUBRO6_TRANS,
	NULL																AS RUBRO7_TRANS,
	NULL																AS RUBRO8_TRANS,
	NULL																AS RUBRO9_TRANS,
	NULL																AS RUBRO10_TRANS,
	NULL																AS DOCUMENTO_FISCAL,
	NULL																AS DOCUMENTO_GLOBAL,
	NULL																AS METODO_PAGO

	FROM EXACTUSERP.DIS86.DOCUMENTOS_CP
	GROUP BY CUENTA_BANCO, U_TRANSFERENCIA, USUARIO, FECHA_PROYECTADA
	
GO
