CREATE VIEW [DIS86].[PS_VIEW_SALDOS_DOCUMENTOS_CC]
AS 
SELECT   SUM(CASE WHEN TIPO IN('REC','O/C','DEP','TEF','N/C') THEN -1* SALDO ELSE SALDO END) AS SALDO  ,
		 SUM(CASE WHEN TIPO IN('REC','O/C','DEP','TEF','N/C') THEN -1* SALDO_LOCAL ELSE SALDO_LOCAL END) SALDO_LOCAL,
		 SUM(CASE WHEN TIPO IN('REC','O/C','DEP','TEF','N/C') THEN -1* SALDO_DOLAR ELSE SALDO_DOLAR END ) AS SALDO_DOLAR, 
		 CLIENTE,
		 TIPO
		 FROM EXACTUSERP.DIS86.DOCUMENTOS_CC
		-- WHERE CLIENTE ='CL00856'
GROUP BY CLIENTE,TIPO
--ORDER BY CLIENTE 
