CREATE VIEW [DIS86].[VIEW_OBT_DOCUMENTOS_CC_CREDITOS]
AS 
SELECT TIPO,
	DOCUMENTO,
	SALDO,MONTO,
	APLICACION, 
	ISNULL(FAC.FACTURA_ORIGINAL,'ND') AS FACTURA, 
	ISNULL(FAC.RUBRO5,'ND')			  AS BOLETA, 
	ISNULL(FAC.COMENTARIO_CXC,'ND')   AS COMENTARIO, 
	DOC_CC.CLIENTE,
	DOC_CC.VENDEDOR,
	CONVERT(VARCHAR,DOC_CC.FECHA_DOCUMENTO,23) FECHA_DOCUMENTO,
	DOC_CC.COBRADOR
FROM 
          EXACTUSERP.DIS86.DOCUMENTOS_CC AS DOC_CC
LEFT JOIN EXACTUSERP.DIS86.FACTURA AS FAC ON DOC_CC.DOCUMENTO = FAC.FACTURA

WHERE TIPO IN('N/C','TEF','O/C','REC','DEP') ----'REC' 
AND   SALDO > 0
AND   APROBADO ='S'
GO
