CREATE VIEW [DIS86].[VIEW_OBT_DOCUMENTOS_POR_CLIENTE]
AS 
SELECT T.*
      ,T.TIPO + ' - ' + T.DOCUMENTO AS TIPO_DOCUMENTO
      ,CLI.NOMBRE + ' *** ' + ISNULL(CLI.ALIAS,CLI.NOMBRE) AS NOMBRE
	  ,VEN.VENDEDOR + ' *** ' + VEN.NOMBRE AS NOMBRE_VENDEDOR
	  ,ISNULL(CLI.E_MAIL,'') AS EMAIL_VENDEDOR
	  ,ven.E_MAIL as EMAIL_VENDEDOR2
	  ,REPLACE(CONVERT(VARCHAR(5000),CLI.DIRECCION),'DETALLE: ','') DIRECCION
	  ,VEN.VENDEDOR
	  ,VEN.NOMBRE NOMBRE_VENDEDOR_NI
	  ,CPG.DIAS_NETO
	  ,0 MONTO_PAGO
 FROM
   (
	SELECT	CC.CLIENTE
			,CC.DOCUMENTO
			,CC.TIPO
			,SBT.DESCRIPCION SUBTIPO
			,CC.MONEDA
			,CC.MONTO
			,CC.SALDO	  
			,CONVERT(VARCHAR,CC.FECHA_DOCUMENTO,23) AS FECHA_DOCUMENTO
			,CONVERT(VARCHAR,CC.FECHA_VENCE,23) AS FECHA_VENCE
	  FROM 
			EXACTUSERP.DIS86.DOCUMENTOS_CC CC LEFT JOIN 
			EXACTUSERP.DIS86.SUBTIPO_DOC_CC AS SBT ON CC.TIPO= SBT.TIPO AND SBT.SUBTIPO = CC.SUBTIPO
	 WHERE 
			CC.SALDO > (CASE WHEN CC.MONEDA = 'USD' THEN 1 ELSE 500 END )
   ) T
   LEFT JOIN EXACTUSERP.DIS86.CLIENTE        AS  CLI ON CLI.CLIENTE = T.CLIENTE
   LEFT JOIN EXACTUSERP.DIS86.VENDEDOR       AS  VEN ON VEN.VENDEDOR = CLI.VENDEDOR
   LEFT JOIN EXACTUSERP.DIS86.CONDICION_PAGO AS  CPG ON CPG.CONDICION_PAGO = CLI.CONDICION_PAGO
WHERE T.TIPO IN ('FAC','O/D')
and t.TIPO not in ('INT')

UNION 
SELECT T.*
      ,T.TIPO + ' - ' + T.DOCUMENTO AS TIPO_DOCUMENTO
      ,CLI.NOMBRE + ' *** ' + ISNULL(CLI.ALIAS,CLI.NOMBRE) AS NOMBRE
	  ,VEN.VENDEDOR + ' *** ' + VEN.NOMBRE AS NOMBRE_VENDEDOR 
	  ,ISNULL(CLI.E_MAIL,'') AS EMAIL_VENDEDOR,ven.E_MAIL as EMAIL_VENDEDOR2
	  ,REPLACE(CONVERT(VARCHAR(5000),CLI.DIRECCION),'DETALLE: ','') DIRECCION
	  ,VEN.VENDEDOR
	  ,VEN.NOMBRE NOMBRE_VENDEDOR_NI
	  ,CPG.DIAS_NETO
	  ,0 MONTO_PAGO
 FROM
   (
	SELECT	CC.CLIENTE
			,CC.DOCUMENTO
			,CC.TIPO
			,SBT.DESCRIPCION SUBTIPO
			,CC.MONEDA
			,CC.MONTO
			,CC.SALDO	  
			,CONVERT(VARCHAR,CC.FECHA_DOCUMENTO,23) AS FECHA_DOCUMENTO
			,CONVERT(VARCHAR,CC.FECHA_VENCE,23) AS FECHA_VENCE
	  FROM 
			EXACTUSERP.DIS86.DOCUMENTOS_CC CC LEFT JOIN 
			EXACTUSERP.DIS86.SUBTIPO_DOC_CC AS SBT ON CC.TIPO= SBT.TIPO AND SBT.SUBTIPO = CC.SUBTIPO
	 WHERE 
			CC.SALDO > (CASE WHEN CC.MONEDA = 'USD' THEN 1 ELSE 1000 END )
   ) T
   LEFT JOIN EXACTUSERP.DIS86.CLIENTE CLI ON CLI.CLIENTE = T.CLIENTE
   LEFT JOIN EXACTUSERP.DIS86.VENDEDOR VEN ON VEN.VENDEDOR = CLI.VENDEDOR
   LEFT JOIN EXACTUSERP.DIS86.CONDICION_PAGO AS  CPG ON CPG.CONDICION_PAGO = CLI.CONDICION_PAGO
WHERE T.TIPO NOT IN ('FAC','O/D')
and t.TIPO not in ('INT') 
GO
