CREATE VIEW [DIS86].[VIEW_OBT_LINEA_PEDIDO_PTC] 
AS 
SELECT 
      PEDIDO,
      PEDIDO_LINEA,
      PL.ARTICULO,
	  ART.DESCRIPCION,
      CASE WHEN ESTADO =  'F' THEN CANTIDAD_FACTURADA 
							  ELSE CANTIDAD_A_FACTURA END CANTIDAD,
	  PRECIO_UNITARIO,
	  PORC_DESCUENTO,
	  CASE WHEN ESTADO =  'F' THEN (PRECIO_UNITARIO * CANTIDAD_FACTURADA)- MONTO_DESCUENTO 
							  ELSE (PRECIO_UNITARIO * CANTIDAD_A_FACTURA)- MONTO_DESCUENTO END SUBTOTAL,
	  PL.ESTADO
FROM  
	  EXACTUSERP.DIS86.PEDIDO_LINEA AS PL
INNER JOIN EXACTUSERP.DIS86.ARTICULO AS  ART ON PL.ARTICULO = ART.ARTICULO
--WHERE PEDIDO ='R06PED0000001379'
GO
