CREATE view [DIS86].[VIEW_OBT_LISTA_ARTICULOS] 
as

SELECT	  ART.ARTICULO,
          ART.DESCRIPCION,
		  ART.CODIGO_BARRAS_VENT, 
		  BOD.CANT_DISPONIBLE, 
		  AP.PRECIO,
		  VN.NIVEL_PRECIO, 
		  ISNULL(DCTO_ECA.PORC_DCTO,0)  PORC_DCTO
FROM 
	      EXACTUSERP.DIS86.ARTICULO          AS  ART
JOIN      EXACTUSERP.DIS86.ARTICULO_PRECIO   AS  AP        ON  ART.ARTICULO    =  AP.ARTICULO            AND NIVEL_PRECIO ='DETALLE'
LEFT JOIN EXACTUSERP.DIS86.ESCALA_DCTO       AS  DCTO_ECA  ON  AP.NIVEL_PRECIO =  DCTO_ECA.NIVEL_PRECIO  AND AP.MONEDA = DCTO_ECA.MONEDA  AND AP.VERSION = DCTO_ECA.VERSION  AND AP.ARTICULO = DCTO_ECA.ARTICULO
JOIN      EXACTUSERP.DIS86.VERSION_NIVEL     AS  VN        ON  AP.NIVEL_PRECIO =  VN.NIVEL_PRECIO        AND AP.MONEDA = VN.MONEDA        AND AP.VERSION = VN.VERSION        AND VN.ESTADO   ='A'
JOIN      EXACTUSERP.DIS86.EXISTENCIA_BODEGA AS  BOD       ON  ART.ARTICULO    =  BOD.ARTICULO		   AND BODEGA = '01'
WHERE ART.ACTIVO ='S'

GO
