CREATE VIEW [DIS86].[VIEW_OBT_LISTA_ARTICULOS_DESCUENTOS]
AS 
SELECT 
     AP.NIVEL_PRECIO                                                                        AS NIVEL_PRECIO
    ,ART.ARTICULO                                                                           AS ARTICULO
    ,CONCAT(ART.ARTICULO, ' | ' ,ART.DESCRIPCION)									        AS COD_NOMBRE_ARTICULO
	,ART.CLASIFICACION_1														            AS ID_MARCA
	,CONCAT(ART.CLASIFICACION_1, ' | ' , CLA_1.DESCRIPCION)                                 AS MARCA
	,ART.CLASIFICACION_2                                                                    AS ID_CASA
	,CONCAT(ART.CLASIFICACION_2, ' | ' , CLA_2.DESCRIPCION)                                 AS CASA
	,ART.CLASIFICACION_3                                                                    AS ID_SUBCASA
	,CONCAT(ART.CLASIFICACION_3, ' | ' , CLA_3.DESCRIPCION)                                 AS SUBCASA
	,ROUND(AP.PRECIO,2)																		AS PRECIO
	,ISNULL(PORC_DESCUENTO,0)																AS PORC_DESCUENTO 
	,CONVERT(VARCHAR,FECHA_INICIAL,23)														AS FECHA_INICIAL
	,CONVERT(VARCHAR,FECHA_FINAL,23)														AS FECHA_FINAL 
	,ROUND((ISNULL(AP.PRECIO,0)) - (ISNULL(AP.PRECIO,0) * ISNULL(PORC_DESCUENTO/100,0)),2)  AS PRECIO_FINAL
	,DCTO.CLIENTE                                                                           AS CLIENTE 
	,DCTO.ESCALA_DCTO
FROM 
          [EXACTUSERP].[DIS86].[DCTO_ART_X_CLI]  AS  DCTO  WITH(NOLOCK) 
	 JOIN [EXACTUSERP].[DIS86].ARTICULO          AS  ART   WITH(NOLOCK) ON DCTO.ARTICULO       = ART.ARTICULO
     JOIN [EXACTUSERP].[DIS86].ARTICULO_PRECIO   AS  AP    WITH(NOLOCK) ON AP.ARTICULO         = ART.ARTICULO
LEFT JOIN [EXACTUSERP].[DIS86].CLASIFICACION     AS  CLA_1 WITH(NOLOCK) ON CLA_1.CLASIFICACION = ART.CLASIFICACION_1
LEFT JOIN [EXACTUSERP].[DIS86].CLASIFICACION     AS  CLA_2 WITH(NOLOCK) ON CLA_2.CLASIFICACION = ART.CLASIFICACION_2
LEFT JOIN [EXACTUSERP].[DIS86].CLASIFICACION     AS  CLA_3 WITH(NOLOCK) ON CLA_3.CLASIFICACION = ART.CLASIFICACION_3
WHERE ART.ACTIVO ='S'
--AND   ART.CLASIFICACION_3 ='MLP'
AND   ART.ARTICULO <>'ND'
--AND   AP.ARTICULO = '14050'
group by  AP.NIVEL_PRECIO,ART.ARTICULO,ART.DESCRIPCION,ART.CLASIFICACION_1,CLA_1.DESCRIPCION,
          ART.CLASIFICACION_2,CLA_2.DESCRIPCION,ART.CLASIFICACION_3,CLA_3.DESCRIPCION,AP.PRECIO,PORC_DESCUENTO
		  ,CONVERT(VARCHAR,FECHA_INICIAL,23),CONVERT(VARCHAR,FECHA_FINAL,23),DCTO.CLIENTE,DCTO.ESCALA_DCTO


GO
