CREATE VIEW [DIS86].[VIEW_OBT_LISTA_BONIF_ART_CLIENTE_V2]
AS
SELECT DISTINCT
    ART.ARTICULO            AS COD_ARTICULO,
    ART.DESCRIPCION         AS ARTICULO_NOMBRE,
    ART.CLASIFICACION_2     AS ID_CASA,
    C2.DESCRIPCION          AS DESC_CASA,
    ART.CLASIFICACION_1     AS ID_SUBCASA,
    C1.DESCRIPCION          AS DESC_SUBCASA,
    ART.CLASIFICACION_3     AS ID_CATEGORIA_ART,
    C3.DESCRIPCION          AS DESC_CATEGORIA_ART
FROM ExactusERP.DIS86.ARTICULO ART
LEFT JOIN ExactusERP.DIS86.CLASIFICACION C1
  ON C1.CLASIFICACION = ART.CLASIFICACION_1
LEFT JOIN ExactusERP.DIS86.CLASIFICACION C2
  ON C2.CLASIFICACION = ART.CLASIFICACION_2
LEFT JOIN ExactusERP.DIS86.CLASIFICACION C3
  ON C3.CLASIFICACION = ART.CLASIFICACION_3
WHERE ART.ACTIVO = 'S';
GO
