SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [DIS86].[VIEW_OBT_LISTA_BONIFICACION_ARTICULOS_INDEX_V2]
AS
SELECT DISTINCT
       AP.NIVEL_PRECIO                                   AS NIVEL_PRECIO,
       ART.ARTICULO                                      AS COD_ARTICULO_NORMAL,
       ART.DESCRIPCION                                   AS ARTICULO_NORMAL,
       ART.CLASIFICACION_2                               AS ID_CASA,
       CONCAT(ART.CLASIFICACION_2,' | ',C2.DESCRIPCION)  AS CASA,
       ART.CLASIFICACION_1                               AS ID_SUBCASA,
       CONCAT(ART.CLASIFICACION_1,' | ',C1.DESCRIPCION)  AS SUBCASA,
       ART.CLASIFICACION_3                               AS ID_CATEGORIA_ART,
       CONCAT(ART.CLASIFICACION_3,' | ',C3.DESCRIPCION)  AS CATEGORIA_ART,
       ISNULL(AB.ARTICULO_BONIF,'')                      AS COD_ART_BONIFICADO,
       CASE WHEN AB.ARTICULO_BONIF IS NOT NULL
            THEN '*** ' + ARTB.DESCRIPCION
            ELSE '' END                                 AS ARTICULO_BONIFICADO,
       ISNULL(AB.ESCALA_BONIF,0)                         AS ESCALA_BONIF,
       ISNULL(AB.MIN_ART_FACT,0)                         AS CANT_MINIMA,
       ISNULL(AB.MAX_ART_FACT,0)                         AS CANT_MAXIMA,
       CONVERT(varchar(23),AB.FECHA_INICIO_ESC,23)       AS FECHA_INICIAL,
       CONVERT(varchar(23),AB.FECHA_FIN_ESC,23)          AS FECHA_FINAL,
       ISNULL(AB.FACTOR_BONIF,0)                         AS FACTOR_BONIF,
       ISNULL(AB.UNIDADES_BONIF,0)                       AS UNIDADES_BONIF,
       AB.MONEDA                                         AS MONEDA,
       AB.VERSION_BONIF                                  AS VERSION_BONIF
FROM   ExactusERP.DIS86.ARTICULO            ART WITH (NOLOCK)
JOIN   ExactusERP.DIS86.ARTICULO_PRECIO     AP  WITH (NOLOCK)
       ON AP.ARTICULO = ART.ARTICULO
OUTER APPLY (
        SELECT TOP (1) *
        FROM   ExactusERP.DIS86.ESCALA_BONIF EB WITH (NOLOCK)
        WHERE  EB.ARTICULO     = AP.ARTICULO
          AND  EB.NIVEL_PRECIO = AP.NIVEL_PRECIO
        ORDER BY EB.FECHA_INICIO_ESC DESC
) AB
LEFT JOIN ExactusERP.DIS86.ARTICULO ARTB WITH (NOLOCK)
       ON ARTB.ARTICULO = AB.ARTICULO_BONIF          
LEFT JOIN ExactusERP.DIS86.CLASIFICACION C1 WITH (NOLOCK)
       ON C1.CLASIFICACION = ART.CLASIFICACION_1
LEFT JOIN ExactusERP.DIS86.CLASIFICACION C2 WITH (NOLOCK)
       ON C2.CLASIFICACION = ART.CLASIFICACION_2
LEFT JOIN ExactusERP.DIS86.CLASIFICACION C3 WITH (NOLOCK)
       ON C3.CLASIFICACION = ART.CLASIFICACION_3
WHERE  ART.ACTIVO = 'S'
  AND  ART.ARTICULO <> 'ND';
GO
