CREATE VIEW [DIS86].[VIEW_OBT_LISTA_DCTO_ART_X_CLIENTE]
AS 
SELECT DISTINCT CLI.CLIENTE                                             AS CLIENTE
       ,CLI.NOMBRE                                              AS NOMBRE
	   ,CLI.CATEGORIA_CLIENTE                                   AS CATEGORIA
	   ,CBN.ARTICULO                                            AS COD_ARTICULO
	   ,ART.DESCRIPCION                                         AS ARTICULO_NOMBRE
												                
	   ,ART.CLASIFICACION_2                                     AS ID_CASA
	   ,CONCAT(ART.CLASIFICACION_2,' | ',CLAS2.DESCRIPCION)          AS CASA
												                
	   ,ART.CLASIFICACION_1		                                AS ID_SUBCASA
	   ,CONCAT(ART.CLASIFICACION_1,' | ',CLAS1.DESCRIPCION)     AS SUBCASA

	   ,ART.CLASIFICACION_3                                     AS ID_CATEGORIA_ART
	   ,CONCAT(ART.CLASIFICACION_3,' | ',CLAS3.DESCRIPCION)     AS CATEGORIA_ART
	   
	   ,ISNULL(CBN.ESCALA_DCTO,0)                               AS ESCALA_DCTO 
	   ,ISNULL(CBN.CANTIDAD_INICIAL,0)                          AS CANT_MINIMA 
	   ,ISNULL(CBN.CANTIDAD_FINAL,0)   			                AS CANT_MAXIMA
	   ,CONVERT(VARCHAR,CBN.FECHA_INICIAL,23)                   AS FECHA_INICIAL 
	   ,CONVERT(VARCHAR,CBN.FECHA_FINAL,23)		                AS FECHA_FINAL 
	   ,ISNULL(CBN.PORC_DESCUENTO,0)			                AS PORC_DESCUENTO
                   

	   
FROM  
      EXACTUSERP.DIS86.CLIENTE               AS CLI
JOIN  EXACTUSERP.DIS86.DCTO_ART_X_CLI        AS CBN   ON CLI.CLIENTE         = CBN.CLIENTE 
JOIN  EXACTUSERP.DIS86.ARTICULO              AS ART   ON ART.ARTICULO        = CBN.ARTICULO 
JOIN  EXACTUSERP.DIS86.ESCALA_DCTO  AS ESC
  ON ESC.ESCALA_DCTO = CBN.ESCALA_DCTO




JOIN  EXACTUSERP.DIS86.CLASIFICACION         AS CLAS1 ON CLAS1.CLASIFICACION = ART.CLASIFICACION_1
JOIN  EXACTUSERP.DIS86.CLASIFICACION         AS CLAS2 ON CLAS2.CLASIFICACION = ART.CLASIFICACION_2
JOIN  EXACTUSERP.DIS86.CLASIFICACION         AS CLAS3 ON CLAS3.CLASIFICACION = ART.CLASIFICACION_3

--WHERE CAST(CBN.FECHA_INICIAL AS DATE) >= (SELECT MAX(CAST(ABT.FECHA_INICIAL AS DATE)) FROM [EXACTUSERP].[DIS86].[BONIF_ART_X_CLI] ABT WITH(NOLOCK))
WHERE ART.ACTIVO ='S'
AND CLI.ACTIVO ='S'
--AND ART.CLASIFICACION_3 = 'MLP'

GO
