LEFT  JOIN ExactusERP.DIS86.CLASIFICACION C1 ON C1.CLASIFICACION = ART.CLASIFICACION_1
LEFT  JOIN ExactusERP.DIS86.CLASIFICACION C2 ON C2.CLASIFICACION = ART.CLASIFICACION_2
LEFT  JOIN ExactusERP.DIS86.CLASIFICACION C3 ON C3.CLASIFICACION = ART.CLASIFICACION_3
WHERE ART.ACTIVO = 'S';
