/****** Object:  View [DIS86].[VIEW_OBT_LISTA_DESCUENTO_ARTICULOS_INDEX]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE   VIEW [DIS86].[VIEW_OBT_LISTA_DESCUENTO_ARTICULOS_INDEX]
AS
SELECT DISTINCT
    AP.NIVEL_PRECIO                                     AS NIVEL_PRECIO,
    ART.ARTICULO                                        AS COD_ARTICULO,
    ART.DESCRIPCION                                     AS ARTICULO,
    ART.CLASIFICACION_2                                 AS ID_CASA,
    CONCAT(ART.CLASIFICACION_2, ' | ', C2.DESCRIPCION)   AS CASA,
    ART.CLASIFICACION_1                                 AS ID_SUBCASA,
    CONCAT(ART.CLASIFICACION_1, ' | ', C1.DESCRIPCION)   AS SUBCASA,
    ART.CLASIFICACION_3                                 AS ID_CATEGORIA_ART,
    CONCAT(ART.CLASIFICACION_3, ' | ', C3.DESCRIPCION)   AS CATEGORIA_ART,

    ISNULL(AP.PRECIO, 0.00)                             AS PRECIO,
    ISNULL(ED.PORC_DCTO, 0.00)                          AS PORC_DESCUENTO,
    (ISNULL(AP.PRECIO, 0.00) - (ISNULL(AP.PRECIO, 0.00) * (ISNULL(ED.PORC_DCTO, 0.00) / 100))) AS PRECIO_FINAL,

    ISNULL(ED.ESCALA_DCTO, 0)                           AS ESCALA_DCTO,
    ISNULL(ED.VERSION_DCTO, 0)                          AS VERSION_DCTO,
    ISNULL(ED.MIN_UNID_FACT, 0)                         AS CANT_MINIMA,
    ISNULL(ED.MAX_UNID_FACT, 0)                         AS CANT_MAXIMA,
    CONVERT(VARCHAR(23), ED.FECHA_INICIO_ESC, 23)       AS FECHA_INICIAL,
    CONVERT(VARCHAR(23), ED.FECHA_FIN_ESC, 23)          AS FECHA_FINAL,
    CONVERT(VARCHAR(23), ED.FECHA_ULT_MODIF, 23)        AS FECHA_ULT_MODIF,
    ISNULL(ED.USUARIO_ULT_MODIF, 'sa')                  AS USUARIO_ULT_MODIF,
    ISNULL(ED.MONEDA, 'L')                              AS MONEDA,
    ISNULL(ED.VERSION, 1)                               AS VERSION_PRECIO,
    0                                                   AS NoteExistsFlag,
    ISNULL(ED.RecordDate, GETDATE())                    AS RecordDate

FROM ExactusERP.DIS86.ARTICULO ART WITH (NOLOCK)
JOIN ExactusERP.DIS86.ARTICULO_PRECIO AP WITH (NOLOCK)
    ON AP.ARTICULO = ART.ARTICULO
OUTER APPLY (
    SELECT TOP (1) *
    FROM ExactusERP.DIS86.ESCALA_DCTO ED WITH (NOLOCK)
    WHERE ED.ARTICULO = AP.ARTICULO
      AND ED.NIVEL_PRECIO = AP.NIVEL_PRECIO
    ORDER BY FECHA_INICIO_ESC DESC
) ED
LEFT JOIN ExactusERP.DIS86.CLASIFICACION C1 WITH (NOLOCK)
    ON C1.CLASIFICACION = ART.CLASIFICACION_1
LEFT JOIN ExactusERP.DIS86.CLASIFICACION C2 WITH (NOLOCK)
    ON C2.CLASIFICACION = ART.CLASIFICACION_2
LEFT JOIN ExactusERP.DIS86.CLASIFICACION C3 WITH (NOLOCK)
    ON C3.CLASIFICACION = ART.CLASIFICACION_3
WHERE ART.ACTIVO = 'S'
  AND ART.ARTICULO <> 'ND';
GO
/****** Object:  View [DIS86].[VIEW_OBT_RECIBOS_TRANSFERENCIA_DOCUMENTOS_CC]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE VIEW [DIS86].[VIEW_OBT_RECIBOS_TRANSFERENCIA_DOCUMENTOS_CC]
AS 
SELECT  DOC_CC.CLIENTE
       ,CLI.NOMBRE  NOMBRE_CLIENTE
	   ,DOC_CC.TIPO
	   ,DOC_CC.SUBTIPO
	   ,SBTCC.DESCRIPCION  FORMA_PAGO
	   ,DOC_CC.DOCUMENTO
	   ,DOC_CC.MONEDA
	   ,DOC_CC.MONTO
	   ,DOC_CC.MONTO MONTO_DESPOSITAR
	   ,ISNULL(U_PS_ESTADO_LIQUIDACION,1) COD_ESTADO 
	   ,CASE 
	        WHEN ISNULL(U_PS_ESTADO_LIQUIDACION,1) = 1 THEN 'Sin aprobar' 
	        WHEN ISNULL(U_PS_ESTADO_LIQUIDACION,1) = 2 THEN 'Aprobar'
			WHEN ISNULL(U_PS_ESTADO_LIQUIDACION,1) = 3 THEN 'Rechazado'
			WHEN ISNULL(U_PS_ESTADO_LIQUIDACION,1) = 4 THEN 'No depositado'
		END ESTADO_DESCRIPCION
	  ,[DIS86].[PS_EXACTUSERP_OBT_ENTIDAD_FINANCIERA](DOC_CC.CTA_BANCARIA) AS BANCO
	  ,BAN.NUMERO REFERENCIA
	  ,DOC_CC.FECHA_DOCUMENTO
	  ,DOC_CC.APLICACION COMENTARIO
	  ,DOC_CC.COBRADOR
	  ,COB.NOMBRE NOMBRE_COBRADOR
	  ,DOC_CC.SALDO
FROM 
          EXACTUSERP.DIS86.DOCUMENTOS_CC  AS DOC_CC
     left JOIN EXACTUSERP.DIS86.CLIENTE        AS CLI   ON DOC_CC.CLIENTE   = CLI.CLIENTE
left	 JOIN EXACTUSERP.DIS86.SUBTIPO_DOC_CC AS SBTCC ON DOC_CC.TIPO      = SBTCC.TIPO AND DOC_CC.SUBTIPO = SBTCC.SUBTIPO
left     JOIN EXACTUSERP.DIS86.COBRADOR       AS COB   ON COB.COBRADOR     = DOC_CC.COBRADOR
LEFT JOIN EXACTUSERP.DIS86.MOV_BANCOS     AS BAN   ON DOC_CC.DOCUMENTO = BAN.REFERENCIA

WHERE DOC_CC.TIPO IN('REC')  --'O/C','N/C' 
AND  NOT (DOC_CC.TIPO = 'REC' AND DOC_CC.SUBTIPO = 0)
--AND DOC_CC.SALDO > 10
--AND DOC_CC.DOCUMENTO ='C001|00000135'
--ORDER BY DOC_CC.CreateDate DESC 
GO
/****** Object:  View [DIS86].[VIEW_OBT_RECIBOS_TRANSFERENCIAS_DOCUMENTOS_CC]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [DIS86].[VIEW_OBT_RECIBOS_TRANSFERENCIAS_DOCUMENTOS_CC] 
AS 
SELECT    DOC.CLIENTE, 
          CLI.NOMBRE, 
	      DOC.TIPO,  
	      CASE 
		  WHEN DOC.TIPO = 'REC' AND DOC.SUBTIPO = 0  THEN 'Recibo' 
	      WHEN DOC.TIPO = 'REC' AND DOC.SUBTIPO = 30 THEN 'Efectivo'
		  WHEN DOC.TIPO = 'REC' AND DOC.SUBTIPO = 32 THEN 'Cheque Posfechado'
		  WHEN DOC.TIPO = 'REC' AND DOC.SUBTIPO = 33 THEN 'Cheque'
		  WHEN DOC.TIPO = 'TEF' AND DOC.SUBTIPO = 0  THEN 'Transferencia'
		  WHEN DOC.TIPO = 'TEF' AND DOC.SUBTIPO = 33 THEN 'Sinpe movil'
		  END  FORMA_PAGO,
		  DOC.SUBTIPO,
		  DOC.DOCUMENTO,
		  DOC.MONEDA,
	      DOC.MONTO,
		  DOC.MONTO MONTO_PAGO,
		  '' ESTADO,
		  [DIS86].[PS_EXACTUSERP_OBT_ENTIDAD_FINANCIERA](DOC.CTA_BANCARIA) BANCO,
 		  MOV.REFERENCIA,
		  DOC.FECHA_DOCUMENTO,
		  DOC.NOTAS,
		  DOC.COBRADOR CODIGO_COBRADOR,
		  COBR.NOMBRE COBRADOR
FROM 
          EXACTUSERP.DIS86.DOCUMENTOS_CC AS DOC  
JOIN      EXACTUSERP.DIS86.CLIENTE AS CLI ON DOC.CLIENTE = CLI.CLIENTE 
JOIN      EXACTUSERP.DIS86.COBRADOR AS COBR ON COBR.COBRADOR = DOC.COBRADOR
LEFT JOIN EXACTUSERP.DIS86.MOV_BANCOS AS MOV ON DOC.DOCUMENTO = MOV.REFERENCIA

WHERE 
       TIPO = 'REC' AND DOC.SUBTIPO = 30 OR
	   TIPO = 'REC' AND DOC.SUBTIPO = 32 OR 
	   TIPO = 'REC' AND DOC.SUBTIPO = 33 OR 
	   TIPO = 'TEF' AND DOC.SUBTIPO = 0  OR 
	   TIPO = 'TEF' AND DOC.SUBTIPO = 33
GO
