/****** Object:  View [DIS86].[VIEW_OBT_SALDO_CLIENTE_DEBITOS_MENOS_CREDITOS]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [DIS86].[VIEW_OBT_SALDO_CLIENTE_DEBITOS_MENOS_CREDITOS]
AS 
SELECT 
    SUM(CASE 
            WHEN TIPO IN('FAC', 'N/D', 'O/D') THEN SALDO 
            ELSE 0 
        END) AS Debitos,
    SUM(CASE 
            WHEN TIPO IN('N/C', 'O/C', 'REC', 'TEF') THEN SALDO 
            ELSE 0 
        END) AS Creditos,
    SUM(CASE 
            WHEN TIPO IN('FAC', 'N/D', 'O/D') THEN SALDO 
            WHEN TIPO IN('N/C', 'O/C', 'REC', 'TEF') THEN -SALDO 
            ELSE 0 
        END) AS Saldo,

	CLIENTE 
FROM 
    EXACTUSERP.DIS86.documentos_cc 
--WHERE 
--    cliente = 'CL01100'
GROUP BY 
    cliente;
GO
