/****** Object:  View [DIS86].[VIEW_OBT_TEF_DEP_DOCUMENTOS_CC]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO




  CREATE VIEW [DIS86].[VIEW_OBT_TEF_DEP_DOCUMENTOS_CC] 
  AS 
  SELECT 
		  CB.[CUENTA_BANCO]                            AS CUENTA_BANCO
		 ,DCC.TIPO_CB			                       AS TIPO_DOCUMENTO
		 ,CC.NUM_DOC_CB                                AS NUMERO
	     ,DCC.SUBTIPO_CB                               AS SUBTIPO
		 ,CC.FECHA_DOCUMENTO                           AS FECHA
		 ,CLI.NOMBRE                                   AS PAGADERO_A
		 ,CC.DOCUMENTO                                 AS REFERENCIA
	     ,CC.MONTO                                     AS MONTO
		 ,NULL                                         AS PROVEEDOR
	     ,CLI.CONTRIBUYENTE                            AS CONTRIBUYENTE
		 ,CC.APLICACION                                AS DETALLE 
		 ,'S'                                          AS CONFIRMADO
		 ,'CB'				                           AS ORIGEN
         ,CC.ASIENTO                                   AS ASIENTO
         ,'N'                                          AS ANULADO
         ,GETDATE()                                    AS FCH_HORA_CREACION
         ,'sa'                                         AS  USUARIO_CREACION
         ,0					                           AS MONTO_ANULADO
         ,'N'                                          AS ESTADO
         ,NULL                                         AS CONCILIACION
         ,'N'                                          AS IMPRESO
         ,NULL                                         AS DOC_REPORTADO
         ,CC.MONTO                                     AS MONTO_REPORTADO
         ,'X'                                          AS CLASE_DIF
         ,'X'                                          AS ACLARADA_DIF
         ,'N'				                           AS CLASE_DOCUMENTO
         ,'M'                                          AS MODO_REGISTRO
         ,'N'				                           AS LIQUIDADO
         ,GETDATE()			                           AS FCH_HORA_MODIFIC
         ,'sa'				                           AS USUARIO_MODIFIC
         ,1               	                           AS  [TIPO_CAMBIO_LOCAL]
         ,[DIS86].[PS_EXACTUSERP_OBT_TIPO_CAMBIO_HIST]() AS TIPO_CAMBIO_DOLAR
         ,''                                           AS APROBADO
         ,NULL                                         AS USUARIO_APROBACION
         ,NULL                                         AS FECHA_APROBACION
         ,NULL                                         AS TIPO_ASIENTO
         ,'CB'										   AS  PAQUETE
         ,'N'                                          AS DEPENDIENTE_GP
         ,NULL										   AS DOCUMENTO_FISCAL
         ,GETDATE()						               AS FECHA_CONTABLE
         ,NULL                                         AS COD_IMPUESTO1
         ,0                                            AS IMPUESTO1
         ,0										       AS IMP1_NODES
		 ,CC.DOCUMENTO								   AS DOCUMENTO 
		 FROM EXACTUSERP.DIS86.DOCUMENTOS_CC    AS  CC  WITH(NOLOCK)
		 JOIN EXACTUSERP.DIS86.CUENTA_BANCARIA  AS  CB  WITH(NOLOCK) ON  CB.CUENTA_BANCO = CC.CTA_BANCARIA 
		 JOIN EXACTUSERP.DIS86.[CLIENTE]        AS  CLI WITH(NOLOCK) ON  CLI.CLIENTE     = CC.CLIENTE
	     JOIN EXACTUSERP.DIS86.[SUBTIPO_DOC_CC] AS  DCC WITH(NOLOCK) ON  DCC.TIPO = CC.TIPO AND DCC.SUBTIPO = CC.SUBTIPO
		 --JOIN EXACTUSERP.DIS86.[SUBTIPO_DOC_CB] AS  DCB WITH(NOLOCK) ON  DCB.SUBTIPO = CC.SUBTIPO 
		 WHERE	NOT EXISTS(SELECT CUENTA_BANCO 
		                   FROM [EXACTUSERP].DIS86.MOV_BANCOS 
		                   WHERE CUENTA_BANCO = CB.CUENTA_BANCO 
		                   AND TIPO_DOCUMENTO = DCC.TIPO_CB AND NUMERO = CC.NUM_DOC_CB) 
		  AND CC.TIPO IN ('TEF', 'DEP') 
		 -- AND CC.DOCUMENTO = 'V001|00000079' 


		



	
GO
