CREATE VIEW [DIS86].[VIEW_OBT_TIPO_DOC_DETALLE]
AS 
SELECT  TIPO
       ,CASE WHEN  DESCRIPCION = 'T.E.F.'             THEN 'Transferencia' 
	         WHEN  DESCRIPCION = 'EFECTIVO'           THEN 'Efectivo'
		     WHEN  DESCRIPCION = 'CHEQUE  POSFECHADO' THEN 'Cheque PostFechado'
		     WHEN  DESCRIPCION = 'CHEQUE'             THEN 'Cheque'
		     WHEN  DESCRIPCION = 'SINPE MOVIL'        THEN 'Sinpe Móvil'
		     ELSE  DESCRIPCION 
		     END   DESCRIPCION 
	   
	   
FROM 
      EXACTUSERP.DIS86.SUBTIPO_DOC_CC
WHERE TIPO IN('DEP','TEF','REC')
AND  SUBTIPO IN('0','30','32','33','31')
AND  DESCRIPCION NOT IN('Depósito','Recibo')
GO
