CREATE VIEW [DIS86].[VIEW_OBTENER_DIA_RUTA]
AS 
SELECT DISTINCT 
	  CASE WHEN U_LUNES	    = 'S' THEN 'L'
           WHEN U_MARTES	= 'S' THEN 'K'
		   WHEN U_MIERCOLES	= 'S' THEN 'M'
		   WHEN U_JUEVES	= 'S' THEN 'J'
		   WHEN U_VIERNES	= 'S' THEN 'V'
		   WHEN U_SABADO	= 'S' THEN 'S'
		   ELSE 'ND' END AS DIA

FROM EXACTUSERP.DIS86.RUTA
WHERE RUTA NOT IN('ND')

