/****** Object:  StoredProcedure [dbo].[PROC_RESPALDO_PS_TRACKING]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[PROC_RESPALDO_PS_TRACKING] 
AS BEGIN 

DECLARE @name VARCHAR(50) -- Nombre de la Base de Datos
DECLARE @path VARCHAR(256) -- Ruta para las copias de seguridad
DECLARE @fileName VARCHAR(256) -- Nombre del Fichero
DECLARE @fileDate VARCHAR(20) -- Usado para el nombre del fichero

-- Ruta para las copias de seguridad
SET @name ='PS_TRACKING' 
SET @path = 'C:\PRODUSOFT\RESPALDOSBD' -- Formato del nombre del fichero OCUPAMOS QUE LE CAIGA ENCIMA POR DIA SIEMPRE 
SELECT @fileDate = DATENAME(weekday, GETDATE()) -- excluir estas bases datos
DECLARE db_cursor CURSOR FOR SELECT name FROM master.dbo.sysdatabases WHERE name NOT IN ('master','model','msdb','tempdb') 
 
OPEN db_cursor FETCH NEXT FROM db_cursor INTO @name 
 
WHILE @@FETCH_STATUS = 0
BEGIN
    SET @fileName = @name + '_' + @fileDate + '.BAK'
    BACKUP DATABASE @name TO DISK = @fileName
    FETCH NEXT FROM db_cursor INTO @name
END

END 
GO
