/****** Object:  StoredProcedure [DIS86].[OBTENER_PDF_BASE64]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [DIS86].[OBTENER_PDF_BASE64](@FACTURA VARCHAR(50))
AS
BEGIN

	DECLARE @NOMBRE_DOCUMENTO VARCHAR(150)
	SET @NOMBRE_DOCUMENTO = (select top 1  NOMBRE_PDF from EXACTUSERP.[DIS86].[DOC_ELECTRONICO_PROC_DE] where NUMERO_DOC = @FACTURA)
	
	DECLARE @UBICACION_BASICA NVARCHAR(400),@SQL NVARCHAR(MAX); 
	SET @UBICACION_BASICA ='\\DIS86rdp\\data_de\\DIS86\\'+@NOMBRE_DOCUMENTO; 
	
 
	DECLARE @TABLE AS TABLE(nombre nvarchar(50), FileType nvarchar(4), Document varbinary(max));
	 
	SET @SQL = 'SELECT '''+@FACTURA+''' AS nombre, ''.pdf'' AS FileType,* FROM OPENROWSET(BULK '''+@UBICACION_BASICA+''', SINGLE_BLOB) AS Document';
	
	INSERT INTO @TABLE EXEC SP_EXECUTESQL @SQL     
	
 
	select replace(replace((select * from (select Document from @TABLE) tbl for xml path('')),'<Document>','data:application/pdf;base64,'),'</Document>','')as FACTURA 
END  


GO
/****** Object:  StoredProcedure [DIS86].[PROC_ACTUALIZA_ESCALA_DCTO_VENCIDA]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE   PROCEDURE [DIS86].[PROC_ACTUALIZA_ESCALA_DCTO_VENCIDA]
AS
BEGIN
    SET NOCOUNT ON;

    UPDATE ExactusERP.DIS86.ESCALA_DCTO
    SET PORC_DCTO = CAST(
                        REPLACE(NIVEL_PRECIO, 'TODO_', '') 
                        AS DECIMAL(10,2)
                     ),
		FECHA_FIN_ESC = '2050-01-01'
    WHERE NIVEL_PRECIO IN (
            'TODO_5','TODO_7','TODO_8',
            'TODO_10','TODO_12','TODO_13','TODO_15'
          )
      AND FECHA_FIN_ESC < CAST(GETDATE() AS DATE);
END;
GO
/****** Object:  StoredProcedure [DIS86].[PROC_ACTUALIZAR_NUMEROS_BANCO]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [DIS86].[PROC_ACTUALIZAR_NUMEROS_BANCO] 

AS
BEGIN

DECLARE @CUENTA_BANCO VARCHAR(22), @MONTO DECIMAL(28,8), @FECHA DATETIME, @REFERENCIA VARCHAR(30), @NUM_BANCO VARCHAR(50), @TIPO VARCHAR(4)

DECLARE USU_CURSOR7 CURSOR FOR SELECT 
                                    CUENTA_BANCO AS CUENTA_BANCO,
                                    MONTO_TRIGGER,
                                    CONVERT(DATE, FECHA_TEF) AS FECHA,
                                    PS_86_REFERENCIA AS REFERENCIA,
                                    REFERENCIA AS NUM_BANCO,
									TIPO
                                FROM [DIS86].[PS_VIEW_OBT_LISTADO_MT940]
                                WHERE 
                                    --CONVERT(DATE, FECHA_MT) BETWEEN CONVERT(DATE, GETDATE() - 2) AND CONVERT(DATE, GETDATE()) 
                                    --AND 
									ASOCIADO_H2H = 'N'
									--AND REFERENCIA = '406400019'

OPEN USU_CURSOR7 
FETCH NEXT FROM USU_CURSOR7 INTO @CUENTA_BANCO, @MONTO, @FECHA, @REFERENCIA, @NUM_BANCO, @TIPO
WHILE @@FETCH_STATUS = 0 
BEGIN 
    DECLARE @ROWCOUNT INT

	IF @TIPO = 'T/C'  
	BEGIN
		-- VERIFICAR CUÁNTOS REGISTROS SE VAN A AFECTAR CON EL UPDATE
		SELECT @ROWCOUNT = COUNT(*)
		FROM EXACTUSERP.[DIS86].MOV_BANCOS
		WHERE NUMERO = @NUM_BANCO
			  AND MONTO = @MONTO
			  AND U_PS_H2H_NUM_BANCO IS NULL

		-- SI HAY SOLO UN REGISTRO QUE SE VA A ACTUALIZAR, OMITIR LA CONDICIÓN DETALLE
		IF @ROWCOUNT = 1  
		BEGIN
			UPDATE EXACTUSERP.[DIS86].MOV_BANCOS
			SET U_PS_H2H_NUM_BANCO = @NUM_BANCO
			WHERE NUMERO = @NUM_BANCO
				  AND MONTO = @MONTO
				  AND U_PS_H2H_NUM_BANCO IS NULL
		END
		ELSE  -- SI HAY MÁS DE UN REGISTRO QUE SE VA A ACTUALIZAR, INCLUIR LA CONDICIÓN DETALLE
		BEGIN
			UPDATE EXACTUSERP.[DIS86].MOV_BANCOS
			SET U_PS_H2H_NUM_BANCO = @NUM_BANCO
			WHERE NUMERO = @NUM_BANCO
				AND MONTO = @MONTO
				AND DETALLE LIKE '%'+@REFERENCIA+'%'
				AND U_PS_H2H_NUM_BANCO IS NULL
		END
	END
	ELSE
	BEGIN
		-- VERIFICAR CUÁNTOS REGISTROS SE VAN A AFECTAR CON EL UPDATE
		SELECT @ROWCOUNT = COUNT(*)
		FROM EXACTUSERP.[DIS86].MOV_BANCOS
		WHERE MONTO = @MONTO
			AND FECHA = @FECHA
			AND (CUENTA_BANCO = @CUENTA_BANCO OR CUENTA_BANCO = (
						SELECT CUENTA_BANCO
						FROM EXACTUSERP.DIS86.CUENTA_BANCARIA 
						WHERE CTA_ELECTRONICA = @CUENTA_BANCO
						--AND U_PS_H2H_VISUALIZAR = 'SI'
					))
			AND U_PS_H2H_NUM_BANCO IS NULL

		-- SI HAY SOLO UN REGISTRO QUE SE VA A ACTUALIZAR, OMITIR LA CONDICIÓN DETALLE
		IF @ROWCOUNT = 1  
		BEGIN
			UPDATE EXACTUSERP.[DIS86].MOV_BANCOS
			SET U_PS_H2H_NUM_BANCO = @NUM_BANCO
			WHERE MONTO = @MONTO
			AND FECHA = @FECHA
			AND (CUENTA_BANCO = @CUENTA_BANCO OR CUENTA_BANCO = (
						SELECT CUENTA_BANCO
						FROM EXACTUSERP.DIS86.CUENTA_BANCARIA 
						WHERE CTA_ELECTRONICA = @CUENTA_BANCO
						--AND U_PS_H2H_VISUALIZAR = 'SI'
					))
			AND U_PS_H2H_NUM_BANCO IS NULL
		END
		ELSE  -- SI HAY MÁS DE UN REGISTRO QUE SE VA A ACTUALIZAR, INCLUIR LA CONDICIÓN DETALLE
		BEGIN
			UPDATE EXACTUSERP.[DIS86].MOV_BANCOS
			SET U_PS_H2H_NUM_BANCO = @NUM_BANCO
			WHERE MONTO = @MONTO
			AND FECHA = @FECHA
			AND (CUENTA_BANCO = @CUENTA_BANCO OR CUENTA_BANCO = (
						SELECT CUENTA_BANCO
						FROM EXACTUSERP.DIS86.CUENTA_BANCARIA 
						WHERE CTA_ELECTRONICA = @CUENTA_BANCO
						--AND U_PS_H2H_VISUALIZAR = 'SI'
					))
			AND DETALLE LIKE '%'+@REFERENCIA+'%'
			AND U_PS_H2H_NUM_BANCO IS NULL
		END
	END

    FETCH NEXT FROM USU_CURSOR7 INTO @CUENTA_BANCO, @MONTO, @FECHA, @REFERENCIA, @NUM_BANCO, @TIPO
END 
CLOSE USU_CURSOR7
DEALLOCATE USU_CURSOR7

-- Paso 1: Usa un CTE para calcular los valores máximos y transformaciones necesarias
;WITH MaxProveedores AS (
    SELECT
        MB.U_PS_H2H_NUM_BANCO,
        MAX(P.PROVEEDOR) AS MaxProveedor,
        CASE
            WHEN MB.TIPO_DOCUMENTO = 'T/D' THEN 'TEF'
            WHEN MB.TIPO_DOCUMENTO = 'T/C' THEN 'DEP'
            ELSE MB.TIPO_DOCUMENTO
        END AS TipoDocumento,
        MB.SUBTIPO,
        MB.NUMERO AS Documento
    FROM
        EXACTUSERP.DIS86.MOV_BANCOS MB
    JOIN
        EXACTUSERP.DIS86.PROVEEDOR P
    ON
        MB.CONTRIBUYENTE = P.CONTRIBUYENTE
    GROUP BY
        MB.U_PS_H2H_NUM_BANCO, MB.TIPO_DOCUMENTO, MB.SUBTIPO, MB.NUMERO
)

-- Paso 2: Actualiza la tabla principal usando los valores calculados en el CTE
UPDATE L
SET 
    L.PROVEEDOR = M.MaxProveedor,
    L.TIPO = M.TipoDocumento,
    L.SUBTIPO = M.SUBTIPO,
    L.DOCUMENTO = M.Documento
FROM 
    DIS86.ESTADO_H2H_LINEAS L
JOIN 
    MaxProveedores M
ON 
    M.U_PS_H2H_NUM_BANCO = L.DOCUMENTO_BANCO
WHERE 
    L.DOCUMENTO_BANCO IS NOT NULL
	AND L.DOCUMENTO IS NULL



RETURN 1

END


GO
