/****** Object:  StoredProcedure [DIS86].[PROC_EDI_ARTICULO_CLIENTE_BONIFICADO]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [DIS86].[PROC_EDI_ARTICULO_CLIENTE_BONIFICADO] ( 
	@NIVEL_PRECIO VARCHAR(12),
	@ARTICULO VARCHAR(50), 
	@ARTICULO_BONIF   VARCHAR(50), 
	@CANTIDAD_MIN INT,
	@CANTIDAD_MAX INT,
	@UND_BONIFICAR INT, 
	@FACTOR INT,
	@FECHA_INI VARCHAR(30),
	@FECHA_FIN VARCHAR(30),
	@ESCALA INT, 
	@MONEDA VARCHAR(1),
	@VERSION_BONIF INT,
	@CIA VARCHAR(20)
) 
AS
BEGIN
	DECLARE	@SQL NVARCHAR(MAX)
	SET	@SQL = 'UPDATE EXACTUSERP.['+ISNULL(@CIA , '')+'].[ESCALA_BONIF]
				SET     
				      [MIN_ART_FACT]      = @CANTIDAD_MIN,
				      [MAX_ART_FACT]      = @CANTIDAD_MAX,
				      [UNIDADES_BONIF]	  = @UND_BONIFICAR,
				      [FECHA_INICIO_ESC]  = @FECHA_INI,
				      [FECHA_FIN_ESC]	  = @FECHA_FIN,
				      [FACTOR_BONIF]	  = @FACTOR,
					  [ARTICULO_BONIF]    = @ARTICULO_BONIF 
						
				WHERE 
				      [NIVEL_PRECIO]      = @NIVEL_PRECIO
				AND   [MONEDA]            = @MONEDA
				AND   [VERSION]		      = 1
				AND   [ARTICULO]	      = @ARTICULO
				AND   [ESCALA_BONIF]      = @ESCALA
				AND   [VERSION_BONIF]     = @VERSION_BONIF
				'

	EXEC SP_EXECUTESQL	@SQL,
						N'@NIVEL_PRECIO VARCHAR(12),
	                      @ARTICULO VARCHAR(50), 
						  @ARTICULO_BONIF VARCHAR(50),
	                      @CANTIDAD_MIN INT,
	                      @CANTIDAD_MAX INT,
	                      @UND_BONIFICAR INT, 
	                      @FACTOR INT,
	                      @FECHA_INI VARCHAR(30),
	                      @FECHA_FIN VARCHAR(30),
	                      @ESCALA INT, 
	                      @MONEDA VARCHAR(1),
	                      @VERSION_BONIF INT',
						  @NIVEL_PRECIO,
	                      @ARTICULO, 
						  @ARTICULO_BONIF,
	                      @CANTIDAD_MIN,
	                      @CANTIDAD_MAX,
	                      @UND_BONIFICAR, 
	                      @FACTOR,
	                      @FECHA_INI,
	                      @FECHA_FIN,
	                      @ESCALA, 
	                      @MONEDA,
	                      @VERSION_BONIF
	
	IF @@ROWCOUNT = 0
	BEGIN
		RETURN 0
	END
	ELSE 
	BEGIN
		RETURN 1
	END
END

GO
/****** Object:  StoredProcedure [DIS86].[PROC_EDI_ARTICULO_CLIENTE_BONIFICADO_MASIVO]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [DIS86].[PROC_EDI_ARTICULO_CLIENTE_BONIFICADO_MASIVO]
(
      @NIVEL_PRECIO     VARCHAR(12)
    , @LISTA_ARTICULOS  VARCHAR(MAX)      
    , @ARTICULO_BONIF   VARCHAR(50)       
    , @CANTIDAD_MIN     INT
    , @CANTIDAD_MAX     INT
    , @UND_BONIFICAR    INT
    , @FACTOR           INT
    , @FECHA_INI        VARCHAR(30)
    , @FECHA_FIN        VARCHAR(30)
    , @ESCALA           INT           
    , @MONEDA           CHAR(1) = 'L'   
    , @VERSION_BONIF    INT    = 1    
    , @CIA              VARCHAR(20)      
)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @SQL NVARCHAR(MAX) = N'
;WITH A AS (
    SELECT RTRIM(LTRIM(VAL)) AS ARTICULO
    FROM   DIS86.TF_SPLIT(@LISTA, '','')
)
MERGE EXACTUSERP.'+QUOTENAME(@CIA)+N'.ESCALA_BONIF     AS T
USING (
    SELECT
           @NIVEL      AS NIVEL_PRECIO,
           @MONEDA     AS MONEDA,
           1           AS VERSION,         
           ARTICULO    AS ARTICULO,
           @ESCALA     AS ESCALA_BONIF,
           @VER_BONIF  AS VERSION_BONIF,
           @ART_BONIF  AS ARTICULO_BONIF,
           @MIN        AS MIN_ART_FACT,
           @MAX        AS MAX_ART_FACT,
           @UNDBONI    AS UNIDADES_BONIF,
           @FINI       AS FECHA_INICIO_ESC,
           @FFIN       AS FECHA_FIN_ESC,
           @FACTOR     AS FACTOR_BONIF
    FROM A                         
) S
ON  T.NIVEL_PRECIO   = S.NIVEL_PRECIO
AND T.MONEDA         = S.MONEDA
AND T.VERSION        = S.VERSION
AND T.ARTICULO       = S.ARTICULO
AND T.ESCALA_BONIF   = S.ESCALA_BONIF
AND T.VERSION_BONIF  = S.VERSION_BONIF
WHEN MATCHED THEN
    UPDATE SET
          T.MIN_ART_FACT     = S.MIN_ART_FACT,
          T.MAX_ART_FACT     = S.MAX_ART_FACT,
          T.UNIDADES_BONIF   = S.UNIDADES_BONIF,
          T.FECHA_INICIO_ESC = S.FECHA_INICIO_ESC,
          T.FECHA_FIN_ESC    = S.FECHA_FIN_ESC,
          T.FACTOR_BONIF     = S.FACTOR_BONIF,
          T.ARTICULO_BONIF   = S.ARTICULO_BONIF
WHEN NOT MATCHED THEN
    INSERT (NIVEL_PRECIO, MONEDA, VERSION, ARTICULO,
            ESCALA_BONIF, VERSION_BONIF, ARTICULO_BONIF,
            MIN_ART_FACT, MAX_ART_FACT, UNIDADES_BONIF,
            FECHA_INICIO_ESC, FECHA_FIN_ESC, FACTOR_BONIF)
    VALUES (S.NIVEL_PRECIO, S.MONEDA, S.VERSION, S.ARTICULO,
            S.ESCALA_BONIF, S.VERSION_BONIF, S.ARTICULO_BONIF,
            S.MIN_ART_FACT, S.MAX_ART_FACT, S.UNIDADES_BONIF,
            S.FECHA_INICIO_ESC, S.FECHA_FIN_ESC, S.FACTOR_BONIF);';

    EXEC sys.sp_executesql
         @SQL,
         N'@NIVEL      VARCHAR(12),
           @MONEDA     CHAR(1),
           @ESCALA     INT,
           @VER_BONIF  INT,
           @ART_BONIF  VARCHAR(50),
           @MIN        INT,
           @MAX        INT,
           @UNDBONI    INT,
           @FINI       VARCHAR(30),
           @FFIN       VARCHAR(30),
           @FACTOR     INT,
           @LISTA      VARCHAR(MAX)',
         @NIVEL        = @NIVEL_PRECIO,
         @MONEDA       = @MONEDA,
         @ESCALA       = @ESCALA,
         @VER_BONIF    = @VERSION_BONIF,
         @ART_BONIF    = @ARTICULO_BONIF,
         @MIN          = @CANTIDAD_MIN,
         @MAX          = @CANTIDAD_MAX,
         @UNDBONI      = @UND_BONIFICAR,
         @FINI         = @FECHA_INI,
         @FFIN         = @FECHA_FIN,
         @FACTOR       = @FACTOR,
         @LISTA        = @LISTA_ARTICULOS;

    DECLARE @rc INT = @@ROWCOUNT;
    RETURN CASE WHEN @rc > 0 THEN 1 ELSE 0 END;
END
GO
/****** Object:  StoredProcedure [DIS86].[PROC_EDI_ARTICULO_PRECIO]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
