CREATE PROCEDURE [DIS86].[PROC_EDI_ARTICULO_PRECIO] ( 
	@ARTICULO VARCHAR(50), 
	@PRECIO DECIMAL(28,8), 
	@NIVEL_PRECIO VARCHAR(100), 
	@CIA VARCHAR(20)
) 
AS
BEGIN
	DECLARE	@SQL NVARCHAR(MAX)
	SET	@SQL = 'UPDATE EXACTUSERP.['+ISNULL(@CIA , '')+'].[ARTICULO_PRECIO]
				SET   PRECIO         = @PRECIO
				WHERE ARTICULO       = @ARTICULO
				  AND NIVEL_PRECIO   = @NIVEL_PRECIO'

	EXEC SP_EXECUTESQL	@SQL,
						N'@ARTICULO VARCHAR(50), 
						  @PRECIO DECIMAL(28,8), 
	                      @NIVEL_PRECIO VARCHAR(100)',
						  @ARTICULO,
						  @PRECIO,
						  @NIVEL_PRECIO
	
	IF @@ROWCOUNT = 0
	BEGIN
		RETURN 0
	END
	ELSE 
	BEGIN
		RETURN 1
	END
END

