/****** Object:  StoredProcedure [DIS86].[PROC_EDI_ARTICULO_PRECIO_CLIENTE_ARTICULO]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [DIS86].[PROC_EDI_ARTICULO_PRECIO_CLIENTE_ARTICULO] ( 
	   @NIVEL_PRECIO      VARCHAR(12),
       @MONEDA            VARCHAR(1),
       @VERSION           INT,
       @ARTICULO          VARCHAR(20),
       @VERSION_ARTICULO  INT,
       @PRECIO            DECIMAL(28,8),
       @ESQUEMA_TRABAJO   VARCHAR(1),
       @MARGEN_UTILIDAD   DECIMAL(28,8),
       @FECHA_INICIO      DATETIME,
       @FECHA_FIN         DATETIME,
	   @CIA               VARCHAR(20)
) 
AS
BEGIN
	IF  LTRIM(RTRIM(ISNULL(@NIVEL_PRECIO,''))) = ''
	 OR LTRIM(RTRIM(ISNULL(@MONEDA,    '')))   = ''
	 OR LTRIM(RTRIM(ISNULL(@ARTICULO,  '')))   = ''
	BEGIN
		RETURN 0;
	END

	DECLARE @SQL               NVARCHAR(MAX);
	DECLARE @EXIS_NIVEL_PRECIO INT,
	        @EXIS_ARTICULO     INT;

	SET @EXIS_ARTICULO =
		(SELECT COUNT(ARTICULO)
		   FROM EXACTUSERP.DIS86.ARTICULO
		  WHERE ARTICULO = @ARTICULO);

	IF EXISTS ( SELECT 1
				  FROM EXACTUSERP.[DIS86].[ARTICULO_PRECIO]
				 WHERE NIVEL_PRECIO     = @NIVEL_PRECIO
				   AND MONEDA           = @MONEDA
				   AND VERSION          = @VERSION
				   AND ARTICULO         = @ARTICULO
				   AND VERSION_ARTICULO = @VERSION_ARTICULO )
	BEGIN
		SET @SQL = N'
		UPDATE  EXACTUSERP.[' + ISNULL(@CIA,'') + N'].[ARTICULO_PRECIO]
		   SET  PRECIO          = @PRECIO,
		        ESQUEMA_TRABAJO = ''N'',
		        MARGEN_UTILIDAD = @MARGEN_UTILIDAD
		 WHERE NIVEL_PRECIO     = @NIVEL_PRECIO
		   AND MONEDA           = @MONEDA
		   AND VERSION          = @VERSION
		   AND ARTICULO         = @ARTICULO
		   AND VERSION_ARTICULO = @VERSION_ARTICULO';

		EXEC sp_executesql @SQL,
			  N'@NIVEL_PRECIO VARCHAR(12), @MONEDA VARCHAR(1), @VERSION INT,
			    @ARTICULO VARCHAR(20),   @VERSION_ARTICULO INT,
			    @PRECIO DECIMAL(28,8),  @MARGEN_UTILIDAD DECIMAL(28,8)',
			  @NIVEL_PRECIO, @MONEDA, @VERSION,
			  @ARTICULO, @VERSION_ARTICULO,
			  @PRECIO, @MARGEN_UTILIDAD;
	END
	ELSE
	BEGIN
		SET @EXIS_NIVEL_PRECIO =
			(SELECT COUNT(NIVEL_PRECIO)
			   FROM EXACTUSERP.DIS86.NIVEL_PRECIO
			  WHERE NIVEL_PRECIO = @NIVEL_PRECIO
			    AND MONEDA       = @MONEDA);

		IF(@EXIS_ARTICULO = 1 AND @EXIS_NIVEL_PRECIO = 0)
		BEGIN
			SET @SQL = N'
			INSERT INTO EXACTUSERP.[' + ISNULL(@CIA,'') + N'].[NIVEL_PRECIO]
			( NIVEL_PRECIO, MONEDA,  ESQUEMA_TRABAJO, DESCUENTOS,
			  SUGERIR_DESCUENTO,      SINC_MOVIL )
			VALUES
			( @NIVEL_PRECIO, @MONEDA, ''N'', ''V'', ''S'', ''N'' )';

			EXEC sp_executesql @SQL,
				   N'@NIVEL_PRECIO VARCHAR(12), @MONEDA VARCHAR(1)',
				   @NIVEL_PRECIO, @MONEDA;
		END

		IF(@EXIS_NIVEL_PRECIO = 0)
			SET @EXIS_NIVEL_PRECIO =
				(SELECT COUNT(NIVEL_PRECIO)
				   FROM EXACTUSERP.DIS86.NIVEL_PRECIO
				  WHERE NIVEL_PRECIO = @NIVEL_PRECIO
				    AND MONEDA       = @MONEDA);

		IF(@EXIS_ARTICULO = 1 AND @EXIS_NIVEL_PRECIO = 1)
		BEGIN
			SET @SQL = N'
			INSERT INTO EXACTUSERP.[' + ISNULL(@CIA,'') + N'].[VERSION_NIVEL]
			( NIVEL_PRECIO, MONEDA, VERSION, FECHA_INICIO, FECHA_CORTE,
			  ESTADO, USUARIO_CREACION, FCH_HORA_CREACION,
			  IMPUESTO1_INCLUIDO, SINC_MOVIL )
			VALUES
			( @NIVEL_PRECIO, @MONEDA, @VERSION,
			  ''1980-01-01'', ''2050-12-31'', ''A'',
			  ''sa'', GETDATE(), ''N'', ''N'' )';

			EXEC sp_executesql @SQL,
				  N'@NIVEL_PRECIO VARCHAR(12), @MONEDA VARCHAR(1), @VERSION INT',
				  @NIVEL_PRECIO, @MONEDA, @VERSION;

			SET @SQL = N'
			INSERT INTO EXACTUSERP.[' + ISNULL(@CIA,'') + N'].[ARTICULO_PRECIO]
			( NIVEL_PRECIO, MONEDA, VERSION, ARTICULO, VERSION_ARTICULO,
			  PRECIO, ESQUEMA_TRABAJO, MARGEN_UTILIDAD,
			  FECHA_INICIO, FECHA_FIN )
			VALUES
			( @NIVEL_PRECIO, @MONEDA, @VERSION, @ARTICULO, @VERSION_ARTICULO,
			  @PRECIO, ''N'', @MARGEN_UTILIDAD,
			  ''1980-01-01'', ''2050-12-31'' )';

			EXEC sp_executesql @SQL,
				  N'@NIVEL_PRECIO VARCHAR(12), @MONEDA VARCHAR(1), @VERSION INT,
				    @ARTICULO VARCHAR(20), @VERSION_ARTICULO INT,
				    @PRECIO DECIMAL(28,8), @MARGEN_UTILIDAD DECIMAL(28,8)',
				  @NIVEL_PRECIO, @MONEDA, @VERSION,
				  @ARTICULO, @VERSION_ARTICULO,
				  @PRECIO, @MARGEN_UTILIDAD;
		END
	END

	IF @NIVEL_PRECIO IN ('TODO_5','TODO_7','TODO_8','TODO_10','TODO_15')
	BEGIN

	IF EXISTS ( SELECT 1
				  FROM EXACTUSERP.[DIS86].[ESCALA_DCTO]
				 WHERE NIVEL_PRECIO     = @NIVEL_PRECIO
				   AND MONEDA           = @MONEDA
				   AND VERSION          = @VERSION
				   AND ARTICULO         = @ARTICULO
				   )
				   BEGIN 
				   UPDATE ExactusERP.DIS86.ESCALA_DCTO 
				   SET PORC_DCTO =   CASE @NIVEL_PRECIO
			 WHEN 'TODO_5'  THEN 5
			 WHEN 'TODO_7'  THEN 7
			 WHEN 'TODO_8'  THEN 8
			 WHEN 'TODO_10' THEN 10
			 WHEN 'TODO_15' THEN 15
		  END,
		         FECHA_ULT_MODIF = GETDATE() , 
				 USUARIO_ULT_MODIF =  'sa',
				 FECHA_INICIO_ESC =   '1980-01-01',
				 FECHA_FIN_ESC = '2050-12-12'
				
				   WHERE NIVEL_PRECIO     = @NIVEL_PRECIO
				   AND MONEDA           = @MONEDA
				   AND VERSION          = @VERSION
				   AND ARTICULO         = @ARTICULO
                  


				   END
		ELSE
		BEGIN
		INSERT INTO EXACTUSERP.DIS86.ESCALA_DCTO
		( NIVEL_PRECIO, MONEDA, VERSION, ARTICULO, ESCALA_DCTO, VERSION_DCTO,
		  MIN_UNID_FACT, MAX_UNID_FACT, PORC_DCTO,
		  FECHA_INICIO_ESC, FECHA_FIN_ESC,
		  FECHA_ULT_MODIF, USUARIO_ULT_MODIF,
		  NoteExistsFlag, RecordDate )
		VALUES
		( @NIVEL_PRECIO, 'L', 1, @ARTICULO, 1, 1,
		  1, 9999,
		  CASE @NIVEL_PRECIO
			 WHEN 'TODO_5'  THEN 5
			 WHEN 'TODO_7'  THEN 7
			 WHEN 'TODO_8'  THEN 8
			 WHEN 'TODO_10' THEN 10
			 WHEN 'TODO_15' THEN 15
		  END,
		  '1980-01-01', '2050-12-12',
		  GETDATE(), 'sa', 0, GETDATE() );
		  END
	END

	IF @NIVEL_PRECIO IN ('POLITICA1','POLITICA2','POLITICA3','POLITICA4','POLITICA5','POLITICA6')
	BEGIN
		DECLARE @CLASIFICACION_1 VARCHAR(20),
				@PORC_DCTO       INT;

		SELECT @CLASIFICACION_1 = CLASIFICACION_1
		  FROM EXACTUSERP.DIS86.ARTICULO
		 WHERE ARTICULO = @ARTICULO;

	





		/* Reglas centralizadas de descuento */
		WITH PoliticaDescuentos AS (
			SELECT *
			  FROM (VALUES
				/* ——— POLITICA1 ——— */
				('POLITICA1','UEN21',5), ('POLITICA1','UEN20',5),
				('POLITICA1','UEN4',7),  ('POLITICA1','UEN8',7),
				('POLITICA1','UEN2',9),  ('POLITICA1','UEN3',7),
				('POLITICA1','UEN9',7),  ('POLITICA1','UEN16',7),
				('POLITICA1','UEN17',7),

				/* ——— POLITICA2 ——— */
				('POLITICA2','UEN17',5),

				/* ——— POLITICA3 ——— */
				('POLITICA3','UEN21',7), ('POLITICA3','UEN20',7),

				/* ——— POLITICA4 ——— */
				('POLITICA4','UEN4',10), ('POLITICA4','UEN8',10),
				('POLITICA4','UEN2',8),  ('POLITICA4','UEN3',10),
				('POLITICA4','UEN9',10), ('POLITICA4','UEN16',10),
				('POLITICA4','UEN17',10),

				/* ——— POLITICA5 ——— */
				('POLITICA5','UEN21',5), ('POLITICA5','UEN20',5),
				('POLITICA5','UEN4',7),  ('POLITICA5','UEN8',7),
				('POLITICA5','UEN2',5),  ('POLITICA5','UEN3',7),
				('POLITICA5','UEN9',7),  ('POLITICA5','UEN16',7),
				('POLITICA5','UEN17',7),
				/* ——— POLITICA6 ——— */
				('POLITICA6','UEN21',7), ('POLITICA6','UEN20',7),
				('POLITICA6','UEN4',10), ('POLITICA6','UEN8',10),
				('POLITICA6','UEN3',10), ('POLITICA6','UEN9',10),
				('POLITICA6','UEN16',10) , ('POLITICA6','UEN17',10)
			  ) AS D (NIVEL_PRECIO, CLASIFICACION_1, PORC_DCTO)
		)
		SELECT @PORC_DCTO = D.PORC_DCTO
		  FROM PoliticaDescuentos D
		 WHERE D.NIVEL_PRECIO     = @NIVEL_PRECIO
		   AND D.CLASIFICACION_1  = @CLASIFICACION_1;

		IF @PORC_DCTO IS NOT NULL
		BEGIN
		IF EXISTS ( SELECT 1
				  FROM EXACTUSERP.[DIS86].[ESCALA_DCTO]
				 WHERE NIVEL_PRECIO     = @NIVEL_PRECIO
				   AND MONEDA           = @MONEDA
				   AND VERSION          = @VERSION
				   AND ARTICULO         = @ARTICULO
				   )
				   BEGIN 
				   UPDATE ExactusERP.DIS86.ESCALA_DCTO 
				   SET PORC_DCTO =  @PORC_DCTO,
		         FECHA_ULT_MODIF = GETDATE() , 
				 USUARIO_ULT_MODIF =  'sa',
				 FECHA_INICIO_ESC =   '1980-01-01',
				 FECHA_FIN_ESC = '2050-12-12'
				
				   WHERE NIVEL_PRECIO     = @NIVEL_PRECIO
				   AND MONEDA           = @MONEDA
				   AND VERSION          = @VERSION
				   AND ARTICULO         = @ARTICULO
                  
				   END
		ELSE
		BEGIN
			INSERT INTO EXACTUSERP.DIS86.ESCALA_DCTO
			( NIVEL_PRECIO, MONEDA, VERSION, ARTICULO, ESCALA_DCTO, VERSION_DCTO,
			  MIN_UNID_FACT, MAX_UNID_FACT, PORC_DCTO,
			  FECHA_INICIO_ESC, FECHA_FIN_ESC,
			  FECHA_ULT_MODIF, USUARIO_ULT_MODIF,
			  NoteExistsFlag, RecordDate )
			VALUES
			( @NIVEL_PRECIO, 'L', 1, @ARTICULO, 1, 1,
			  1, 9999, @PORC_DCTO,
			  '1980-01-01', '2050-12-12',
			  GETDATE(), 'sa', 0, GETDATE() );
		END
	END
	END
	IF @@ROWCOUNT = 0
		RETURN 0;
	RETURN 1;
END
GO
/****** Object:  StoredProcedure [DIS86].[PROC_EDI_ARTICULO_PRECIO_MASIVO]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [DIS86].[PROC_EDI_ARTICULO_PRECIO_MASIVO]
(
      @ARTICULOS_CSV VARCHAR(MAX),
      @PRECIO        DECIMAL(28,8),
      @NIVEL_PRECIO  VARCHAR(100),
      @CIA           VARCHAR(20)
)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @SQL NVARCHAR(MAX) = N'
        UPDATE AP
           SET AP.PRECIO = @P
        FROM  EXACTUSERP.' + QUOTENAME(@CIA) + N'.ARTICULO_PRECIO  AP
        JOIN  (SELECT TRIM(value) AS ARTICULO
                 FROM STRING_SPLIT(@CSV,'','')) X
          ON  X.ARTICULO = AP.ARTICULO
        WHERE AP.NIVEL_PRECIO = @N;

        /* devuelve filas tocadas */
        SET @AFECTADAS = @@ROWCOUNT;';

    DECLARE @AFECTADAS INT = 0;

    EXEC sp_executesql
         @SQL,
         N'@P DECIMAL(28,8),
           @N VARCHAR(100),
           @CSV VARCHAR(MAX),
           @AFECTADAS INT OUTPUT',
         @P         = @PRECIO,
         @N         = @NIVEL_PRECIO,
         @CSV       = @ARTICULOS_CSV,
         @AFECTADAS = @AFECTADAS OUTPUT;

    RETURN CASE WHEN @AFECTADAS > 0 THEN 1 ELSE 0 END;
END
GO
/****** Object:  StoredProcedure [DIS86].[PROC_EDI_BONIFICACION]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [DIS86].[PROC_EDI_BONIFICACION] ( 
	@CLIENTE VARCHAR(20),
	@ARTICULO VARCHAR(20), 
	@ESCALA INT, 
	@VERSION INT,
	@CANTIDAD_MIN INT,
	@CANTIDAD_MAX INT,
	@UND_BONIFICAR INT, 
	@FACTOR INT,
	@FECHA_INI DATETIME,
	@FECHA_FIN DATETIME,
	@CIA VARCHAR(20)
) 
AS
BEGIN
	DECLARE	@SQL NVARCHAR(MAX)
	DECLARE @EXIS_CLIENTE INT, @EXIS_ARTICULO INT

	
	IF EXISTS ( SELECT ARTICULO 
	            FROM   EXACTUSERP.[DIS86].[BONIF_ART_X_CLI] 
	            WHERE  CLIENTE      = @CLIENTE 
				AND    ARTICULO     = @ARTICULO 
				AND    ESCALA_BONIF = @ESCALA)
	BEGIN 
	SET	@SQL = 'UPDATE EXACTUSERP.['+ISNULL(@CIA , '')+'].[BONIF_ART_X_CLI]
				SET    
				       CANTIDAD_INICIAL = @CANTIDAD_MIN,
				       CANTIDAD_FINAL   = @CANTIDAD_MAX,
					   UNIDADES_BONIF   = @UND_BONIFICAR,
					   FACTOR_BONIF     = @FACTOR,
					   FECHA_INICIAL    = @FECHA_INI,
					   FECHA_FINAL      = @FECHA_FIN,
				
				WHERE  
				       CLIENTE          = @CLIENTE
				  AND  ARTICULO         = @ARTICULO
				  AND  ESCALA_BONIF     = @ESCALA'

	EXEC SP_EXECUTESQL	@SQL,
						N'@CLIENTE VARCHAR(20),
	                      @ARTICULO VARCHAR(20), 
	                      @ESCALA INT, 
	                      @VERSION INT,
	                      @CANTIDAD_MIN INT,
	                      @CANTIDAD_MAX INT,
	                      @UND_BONIFICAR INT, 
	                      @FACTOR INT,
	                      @FECHA_INI DATETIME,
	                      @FECHA_FIN DATETIME',
						  @CLIENTE,
	                      @ARTICULO, 
	                      @ESCALA, 
	                      @VERSION,
	                      @CANTIDAD_MIN,
	                      @CANTIDAD_MAX,
	                      @UND_BONIFICAR, 
	                      @FACTOR,
	                      @FECHA_INI,
	                      @FECHA_FIN
						  						  
	END 
	
	IF @@ROWCOUNT = 0
	BEGIN
		RETURN 0
	END
	ELSE 
	BEGIN
		RETURN 1
	END
END




GO
/****** Object:  StoredProcedure [DIS86].[PROC_EDI_BONIFICACION_CLIENTE_ARTICULO]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [DIS86].[PROC_EDI_BONIFICACION_CLIENTE_ARTICULO] ( 
	@CLIENTE VARCHAR(20),
	@ARTICULO VARCHAR(20), 
	@ESCALA INT, 
	@CANTIDAD_MIN INT,
	@CANTIDAD_MAX INT,
	@FECHA_INI DATETIME,
	@FECHA_FIN DATETIME,
	@FACTOR INT,
	@ARTICULO_BONI VARCHAR(20),
	@UND_BONIFICAR INT, 
	@CIA VARCHAR(20)
) 
AS

BEGIN
	DECLARE	@SQL NVARCHAR(MAX)
	DECLARE @EXIS_CLIENTE INT, @EXIS_ARTICULO INT

	SET @EXIS_CLIENTE  = (SELECT COUNT(CLIENTE) FROM EXACTUSERP.DIS86.CLIENTE WHERE CLIENTE = @CLIENTE)
	SET @EXIS_ARTICULO = (SELECT COUNT(ARTICULO) FROM EXACTUSERP.DIS86.ARTICULO WHERE ARTICULO = @ARTICULO)
	  IF EXISTS (
        SELECT 1
          FROM EXACTUSERP.DIS86.BONIF_ART_X_CLI
         WHERE CLIENTE      = @CLIENTE
           AND ARTICULO     = @ARTICULO
           AND ESCALA_BONIF = 0
    )
	   BEGIN
        SET @SQL = N'
        UPDATE EXACTUSERP.[' + ISNULL(@CIA,'') + '].[BONIF_ART_X_CLI]
           SET ESCALA_BONIF     = @ESCALA,
               CANTIDAD_INICIAL = @CANTIDAD_MIN,
               CANTIDAD_FINAL   = @CANTIDAD_MAX,
               FECHA_INICIAL    = @FECHA_INI,
               FECHA_FINAL      = @FECHA_FIN,
               FACTOR_BONIF     = @FACTOR,
               ARTICULO_BONIF   = @ARTICULO_BONI,
               UNIDADES_BONIF   = @UND_BONIFICAR
         WHERE CLIENTE      = @CLIENTE
           AND ARTICULO     = @ARTICULO
           AND ESCALA_BONIF = 0;';

        EXEC sp_executesql
            @SQL,
            N'@CLIENTE VARCHAR(20), @ARTICULO VARCHAR(20), @ESCALA INT,
              @CANTIDAD_MIN INT, @CANTIDAD_MAX INT,
              @FECHA_INI DATETIME, @FECHA_FIN DATETIME,
              @FACTOR INT, @ARTICULO_BONI VARCHAR(20), @UND_BONIFICAR INT',
            @CLIENTE, @ARTICULO, @ESCALA,
            @CANTIDAD_MIN, @CANTIDAD_MAX,
            @FECHA_INI, @FECHA_FIN,
            @FACTOR, @ARTICULO_BONI, @UND_BONIFICAR;

        RETURN CASE WHEN @@ROWCOUNT > 0 THEN 1 ELSE 0 END;
    END

	IF EXISTS ( SELECT ARTICULO 
	            FROM   EXACTUSERP.[DIS86].[BONIF_ART_X_CLI] 
	            WHERE  CLIENTE      = @CLIENTE 
				AND    ARTICULO     = @ARTICULO 
				AND    ESCALA_BONIF = @ESCALA)
	BEGIN 
	SET	@SQL = 'UPDATE EXACTUSERP.['+ISNULL(@CIA , '')+'].[BONIF_ART_X_CLI]
				SET    
				       CANTIDAD_INICIAL = @CANTIDAD_MIN,
				       CANTIDAD_FINAL   = @CANTIDAD_MAX,
					   FECHA_INICIAL    = @FECHA_INI,
					   FECHA_FINAL      = @FECHA_FIN,
					   FACTOR_BONIF     = @FACTOR,
					   ARTICULO_BONIF   = @ARTICULO_BONI,
					   UNIDADES_BONIF   = @UND_BONIFICAR
				      
				WHERE  CLIENTE          = @CLIENTE
				  AND  ARTICULO         = @ARTICULO
				  AND  ESCALA_BONIF     = @ESCALA'

	EXEC SP_EXECUTESQL	@SQL,
						N'@CLIENTE VARCHAR(20),
	                      @ARTICULO VARCHAR(20), 
	                      @ESCALA INT, 
	                      @CANTIDAD_MIN INT,
	                      @CANTIDAD_MAX INT,
	                      @FECHA_INI DATETIME,
	                      @FECHA_FIN DATETIME,
	                      @FACTOR INT,
	                      @ARTICULO_BONI VARCHAR(20),
	                      @UND_BONIFICAR INT',
						  @CLIENTE,
	                      @ARTICULO, 
	                      @ESCALA, 
	                      @CANTIDAD_MIN,
	                      @CANTIDAD_MAX,
	                      @FECHA_INI,
	                      @FECHA_FIN,
	                      @FACTOR,
	                      @ARTICULO_BONI,
	                      @UND_BONIFICAR 
						  
	END 
	ELSE 
	BEGIN 

	  IF(@EXIS_CLIENTE = 1 AND @EXIS_ARTICULO = 1 )
		BEGIN
		 SET @SQL = 'INSERT INTO  EXACTUSERP.['+ISNULL(@CIA , '')+'].[BONIF_ART_X_CLI]
					 (
					 [CLIENTE]
					,[ARTICULO]
					,[ESCALA_BONIF]
					,[VERSION_BONIF]
					,[CANTIDAD_INICIAL]
					,[CANTIDAD_FINAL]
					,[FECHA_INICIAL]
					,[FECHA_FINAL]
					,[FACTOR_BONIF]
					,[ARTICULO_BONIF]
					,[UNIDADES_BONIF]
					)
					VALUES
					(
					 @CLIENTE,
					 @ARTICULO, 
					 @ESCALA, 
					 1,
					 @CANTIDAD_MIN,
					 @CANTIDAD_MAX,
					 @FECHA_INI,
					 @FECHA_FIN,
					 @FACTOR,
					 @ARTICULO_BONI,
					 @UND_BONIFICAR
					)
					'
		EXECUTE SP_EXECUTESQL	@SQL,
								N'@CLIENTE VARCHAR(20),
								@ARTICULO VARCHAR(20), 
								@ESCALA INT, 
								@CANTIDAD_MIN INT,
								@CANTIDAD_MAX INT,
								@FECHA_INI DATETIME,
								@FECHA_FIN DATETIME,
								@FACTOR INT,
								@ARTICULO_BONI VARCHAR(20),
								@UND_BONIFICAR INT',
								@CLIENTE,
								@ARTICULO, 
								@ESCALA, 
								@CANTIDAD_MIN,
								@CANTIDAD_MAX,
								@FECHA_INI,
								@FECHA_FIN,
								@FACTOR,
								@ARTICULO_BONI,
								@UND_BONIFICAR
		END
	END 

	IF @@ROWCOUNT = 0
	BEGIN
		RETURN 0
	END
	ELSE 
	BEGIN
		RETURN 1
	END
END




GO
/****** Object:  StoredProcedure [DIS86].[PROC_EDI_BONIFICACION_CLIENTE_ARTICULO_MASIVO]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [DIS86].[PROC_EDI_BONIFICACION_CLIENTE_ARTICULO_MASIVO]
(
    @CLIENTE           VARCHAR(20),
    @ARTICULOS_CSV     VARCHAR(MAX),
    @ESCALA            INT,
    @CANTIDAD_MIN      INT,
    @CANTIDAD_MAX      INT,
    @FECHA_INI         DATETIME,
    @FECHA_FIN         DATETIME,
    @FACTOR            INT,
    @ARTICULO_BONI     VARCHAR(20),
    @UND_BONIFICAR     INT,
    @CIA               VARCHAR(20)
)
AS
BEGIN
    SET NOCOUNT   ON;
    SET XACT_ABORT ON;

    -- ? Declaración de variables
    DECLARE 
      @Schema NVARCHAR(128),
      @Tabla  NVARCHAR(256),
      @sql    NVARCHAR(MAX),
	  @EscUso   INT = CASE WHEN @ESCALA = 0 THEN 1 ELSE @ESCALA END; 
    -- ? Construcción del nombre del esquema/tabla
    SET @Schema = QUOTENAME(ISNULL(@CIA, ''));
    SET @Tabla  = N'EXACTUSERP.' + @Schema + N'.[BONIF_ART_X_CLI]';

    BEGIN TRAN;
    BEGIN TRY
        -- 1) Validar cliente
        IF NOT EXISTS (
            SELECT 1 FROM EXACTUSERP.DIS86.CLIENTE WHERE CLIENTE = @CLIENTE
        )
            THROW 51000, 'Cliente no existe', 1;

        -- 2) Poblar tabla temporal
        IF OBJECT_ID('tempdb..#Articulos') IS NOT NULL
            DROP TABLE #Articulos;
        CREATE TABLE #Articulos(ARTICULO VARCHAR(20) PRIMARY KEY);
        INSERT INTO #Articulos(ARTICULO)
        SELECT LTRIM(RTRIM(value))
        FROM STRING_SPLIT(@ARTICULOS_CSV, ',')
        WHERE value <> '';
        DELETE A
        FROM #Articulos A
        WHERE NOT EXISTS (
            SELECT 1 FROM EXACTUSERP.DIS86.ARTICULO art
            WHERE art.ARTICULO = A.ARTICULO
        );
        IF NOT EXISTS (SELECT 1 FROM #Articulos)
            THROW 51001, 'Ningún artículo válido en la lista', 1;

        -- 3) Forzar actualización de todos los registros seleccionados
        SET @sql = N'
        UPDATE T
        SET
          ESCALA_BONIF      = @ES,
          CANTIDAD_INICIAL  = @CANT_MIN,
          CANTIDAD_FINAL    = @CANT_MAX,
          FECHA_INICIAL     = @FI,
          FECHA_FINAL       = @FF,
          FACTOR_BONIF      = @FA,
          ARTICULO_BONIF    = @ABI,
          UNIDADES_BONIF    = @UNI
        FROM ' + @Tabla + N' AS T
        INNER JOIN #Articulos AS A
          ON T.CLIENTE = @CL
         AND T.ARTICULO = A.ARTICULO
         AND T.VERSION_BONIF = 1;';

        EXEC sp_executesql
          @sql,
          N'@CL VARCHAR(20), @ES INT, @CANT_MIN INT, @CANT_MAX INT,
            @FI DATETIME, @FF DATETIME, @FA INT, @ABI VARCHAR(20), @UNI INT',
          @CL        = @CLIENTE,
          @ES        = @EscUso,
          @CANT_MIN  = @CANTIDAD_MIN,
          @CANT_MAX  = @CANTIDAD_MAX,
          @FI        = @FECHA_INI,
          @FF        = @FECHA_FIN,
          @FA        = @FACTOR,
          @ABI       = @ARTICULO_BONI,
          @UNI       = @UND_BONIFICAR;

        -- 4) Insertar los faltantes
        SET @sql = N'
        INSERT INTO ' + @Tabla + N' (
          CLIENTE, ARTICULO, ESCALA_BONIF, VERSION_BONIF,
          CANTIDAD_INICIAL, CANTIDAD_FINAL,
          FECHA_INICIAL, FECHA_FINAL,
          FACTOR_BONIF, ARTICULO_BONIF, UNIDADES_BONIF
        )
        SELECT
          @CL, A.ARTICULO, @ES, 1,
          @CANT_MIN, @CANT_MAX,
          @FI, @FF,
          @FA, @ABI, @UNI
        FROM #Articulos A
        LEFT JOIN ' + @Tabla + N' T
          ON T.CLIENTE = @CL
         AND T.ARTICULO = A.ARTICULO
         AND T.VERSION_BONIF = 1
         AND T.ESCALA_BONIF = @ES
        WHERE T.ARTICULO IS NULL;';

        EXEC sp_executesql
          @sql,
          N'@CL VARCHAR(20), @ES INT, @CANT_MIN INT, @CANT_MAX INT,
            @FI DATETIME, @FF DATETIME, @FA INT, @ABI VARCHAR(20), @UNI INT',
          @CL        = @CLIENTE,
          @ES        = @EscUso,
          @CANT_MIN  = @CANTIDAD_MIN,
          @CANT_MAX  = @CANTIDAD_MAX,
          @FI        = @FECHA_INI,
          @FF        = @FECHA_FIN,
          @FA        = @FACTOR,
          @ABI       = @ARTICULO_BONI,
          @UNI       = @UND_BONIFICAR;

        COMMIT;
        RETURN 1;
    END TRY
    BEGIN CATCH
        ROLLBACK;
        RETURN 0;
    END CATCH
END
GO
