CREATE PROCEDURE [DIS86].[PROC_EDI_DESCUENTO_ARTICULO_PRECIO] ( 
	@NIVEL_PRECIO VARCHAR(12),
	@MONEDA VARCHAR(1),
	@VERSION INT,
	@ARTICULO VARCHAR(20), 
	@ESCALA INT, 
	@VERSION_DCTO INT,
	@CANTIDAD_MIN INT,
	@CANTIDAD_MAX INT,
	@PORC_DESCUENTO INT,
	@FECHA_INI DATETIME,
	@FECHA_FIN DATETIME,
	@CIA VARCHAR(20)
) 
AS
BEGIN

   IF  @NIVEL_PRECIO   IS NULL OR LTRIM(RTRIM(@NIVEL_PRECIO))   = '' OR
        @MONEDA         IS NULL OR LTRIM(RTRIM(@MONEDA))         = '' OR
        @VERSION        IS NULL OR
        @ARTICULO       IS NULL OR LTRIM(RTRIM(@ARTICULO))       = '' OR
        @ESCALA         IS NULL OR
        @VERSION_DCTO   IS NULL OR
        @CANTIDAD_MIN   IS NULL OR
        @CANTIDAD_MAX   IS NULL OR
        @PORC_DESCUENTO IS NULL OR
        @FECHA_INI      IS NULL OR
        @FECHA_FIN      IS NULL OR
        @CIA            IS NULL OR LTRIM(RTRIM(@CIA))            = ''
    BEGIN
        RAISERROR('Todos los parámetros son obligatorios y deben venir llenos.', 16, 1);
        RETURN -1; 
    END;

	DECLARE	@SQL NVARCHAR(MAX)
	DECLARE @EXIS_CLIENTE INT, @EXIS_ARTICULO INT

	
	SET @EXIS_ARTICULO = (SELECT COUNT(ARTICULO) FROM EXACTUSERP.DIS86.ARTICULO WHERE ARTICULO = @ARTICULO)

	IF EXISTS ( SELECT ARTICULO 
	            FROM   EXACTUSERP.[DIS86].[ESCALA_DCTO] 
	            WHERE  NIVEL_PRECIO  = @NIVEL_PRECIO 
				AND    ARTICULO      = @ARTICULO 
				AND    ESCALA_DCTO   = @ESCALA
				AND    VERSION_DCTO  = @VERSION
				AND    MONEDA        = @MONEDA
				)
	BEGIN 
	SET	@SQL = 'UPDATE EXACTUSERP.['+ISNULL(@CIA , '')+'].[ESCALA_DCTO]
				SET    
                        [MIN_UNID_FACT]    = @CANTIDAD_MIN
                       ,[MAX_UNID_FACT]    = @CANTIDAD_MAX
                       ,[PORC_DCTO]        = @PORC_DESCUENTO
                       ,[FECHA_INICIO_ESC] = @FECHA_INI
                       ,[FECHA_FIN_ESC]    = @FECHA_FIN
				      
				WHERE   NIVEL_PRECIO       = @NIVEL_PRECIO 
				AND     ARTICULO           = @ARTICULO 
				AND     ESCALA_DCTO        = @ESCALA
				AND     VERSION_DCTO       = @VERSION
				AND     MONEDA             = @MONEDA'

	EXEC SP_EXECUTESQL	@SQL,
						N'@NIVEL_PRECIO VARCHAR(12),
	                      @MONEDA VARCHAR(1),
	                      @VERSION INT,
	                      @ARTICULO VARCHAR(20), 
	                      @ESCALA INT, 
	                      @VERSION_DCTO INT,
	                      @CANTIDAD_MIN INT,
	                      @CANTIDAD_MAX INT,
	                      @PORC_DESCUENTO INT,
	                      @FECHA_INI DATETIME,
	                      @FECHA_FIN DATETIME',
						  @NIVEL_PRECIO,
	                      @MONEDA,
	                      @VERSION,
	                      @ARTICULO, 
	                      @ESCALA, 
	                      @VERSION_DCTO,
	                      @CANTIDAD_MIN,
	                      @CANTIDAD_MAX,
	                      @PORC_DESCUENTO,
	                      @FECHA_INI,
	                      @FECHA_FIN
	END 
	ELSE 
	BEGIN 

	  IF(@EXIS_ARTICULO = 1)
		BEGIN
		 SET @SQL = 'INSERT INTO  EXACTUSERP.['+ISNULL(@CIA , '')+'].[ESCALA_DCTO]
					 (
					   [NIVEL_PRECIO]
                      ,[MONEDA]
                      ,[VERSION]
                      ,[ARTICULO]
                      ,[ESCALA_DCTO]
                      ,[VERSION_DCTO]
                      ,[MIN_UNID_FACT]
                      ,[MAX_UNID_FACT]
                      ,[PORC_DCTO]
                      ,[FECHA_INICIO_ESC]
                      ,[FECHA_FIN_ESC]
					)
					VALUES
					(
					  @NIVEL_PRECIO,
					  @MONEDA,
					  @VERSION,
					  @ARTICULO, 
					  @ESCALA, 
					  @VERSION_DCTO,
					  @CANTIDAD_MIN,
					  @CANTIDAD_MAX,
					  @PORC_DESCUENTO,
					  @FECHA_INI,
					  @FECHA_FIN
					)'
		EXECUTE SP_EXECUTESQL	@SQL,
								N'@NIVEL_PRECIO VARCHAR(12),
									@MONEDA VARCHAR(1),
									@VERSION INT,
									@ARTICULO VARCHAR(20), 
									@ESCALA INT, 
									@VERSION_DCTO INT,
									@CANTIDAD_MIN INT,
									@CANTIDAD_MAX INT,
									@PORC_DESCUENTO INT,
									@FECHA_INI DATETIME,
									@FECHA_FIN DATETIME',
									@NIVEL_PRECIO,
									@MONEDA,
									@VERSION,
									@ARTICULO, 
									@ESCALA, 
									@VERSION_DCTO,
									@CANTIDAD_MIN,
									@CANTIDAD_MAX,
									@PORC_DESCUENTO,
									@FECHA_INI,
									@FECHA_FIN
						          
		END
	END 

	IF @@ROWCOUNT = 0
	BEGIN
		RETURN 0
	END
	ELSE 
	BEGIN
		RETURN 1
	END
END




