/****** Object:  StoredProcedure [DIS86].[PROC_EDI_DESCUENTO_CLIENTE_ARTICULO]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [DIS86].[PROC_EDI_DESCUENTO_CLIENTE_ARTICULO] ( 
	
	@CLIENTE VARCHAR(20),
	@ARTICULO VARCHAR(20), 
	@ESCALA INT, 
	@CANTIDAD_MIN INT,
	@CANTIDAD_MAX INT,
	@FECHA_INI DATETIME,
	@FECHA_FIN DATETIME,
	@PORC_DESCUENTO INT,
	@CIA VARCHAR(20)
) 
AS
BEGIN
	DECLARE	@SQL NVARCHAR(MAX)
	DECLARE @EXIS_CLIENTE INT, @EXIS_ARTICULO INT

	SET @EXIS_CLIENTE  = (SELECT COUNT(CLIENTE) FROM EXACTUSERP.DIS86.CLIENTE WHERE CLIENTE = @CLIENTE)
	SET @EXIS_ARTICULO = (SELECT COUNT(ARTICULO) FROM EXACTUSERP.DIS86.ARTICULO WHERE ARTICULO = @ARTICULO)
	IF @CLIENTE = 'TODOS'
BEGIN
			SET @SQL = N'
			MERGE INTO EXACTUSERP.[' + ISNULL(@CIA,'') + '].[DCTO_ART_X_CLI] AS dst
			USING (
				SELECT CLIENTE
				FROM   EXACTUSERP.DIS86.CLIENTE
			) AS src
			  ON dst.CLIENTE      = src.CLIENTE
			 AND dst.ARTICULO     = @ARTICULO
			 AND dst.ESCALA_DCTO  = 2
			 AND dst.VERSION_DCTO = 1

			WHEN MATCHED THEN
				UPDATE SET
					dst.CANTIDAD_INICIAL = @CANTIDAD_MIN,
					dst.CANTIDAD_FINAL   = @CANTIDAD_MAX,
					dst.FECHA_INICIAL    = @FECHA_INI,
					dst.FECHA_FINAL      = @FECHA_FIN,
					dst.PORC_DESCUENTO   = @PORC_DESCUENTO

			WHEN NOT MATCHED THEN
				INSERT (
					CLIENTE,
					ARTICULO,
					ESCALA_DCTO,
					VERSION_DCTO,
					CANTIDAD_INICIAL,
					CANTIDAD_FINAL,
					FECHA_INICIAL,
					FECHA_FINAL,
					PORC_DESCUENTO,
					TIPO_DESCUENTO
				)
				VALUES (
					src.CLIENTE,
					@ARTICULO,
					2,
					1,
					@CANTIDAD_MIN,
					@CANTIDAD_MAX,
					@FECHA_INI,
					@FECHA_FIN,
					@PORC_DESCUENTO,
					''P''
				);

			UPDATE EXACTUSERP.[' + ISNULL(@CIA,'') + '].[DCTO_ART_X_CLI]
			SET
				FECHA_INICIAL = DATEADD(DAY,  1, @FECHA_FIN)
			WHERE
				ARTICULO     = @ARTICULO
				AND ESCALA_DCTO  = 1
				AND VERSION_DCTO = 1;
			';

			EXEC sp_executesql
				@SQL,
				N'@ARTICULO       VARCHAR(20),
				  @CANTIDAD_MIN   INT,
				  @CANTIDAD_MAX   INT,
				  @FECHA_INI      DATETIME,
				  @FECHA_FIN      DATETIME,
				  @PORC_DESCUENTO INT',
				@ARTICULO,
				@CANTIDAD_MIN,
				@CANTIDAD_MAX,
				@FECHA_INI,
				@FECHA_FIN,
				@PORC_DESCUENTO;
		END

	IF EXISTS ( SELECT ARTICULO 
	            FROM   EXACTUSERP.[DIS86].[DCTO_ART_X_CLI] 
	            WHERE  CLIENTE      = @CLIENTE 
				AND    ARTICULO     = @ARTICULO 
				AND    ESCALA_DCTO  = @ESCALA
                AND    VERSION_DCTO = 1   
				)
	BEGIN 
	SET	@SQL = 'UPDATE EXACTUSERP.['+ISNULL(@CIA , '')+'].[DCTO_ART_X_CLI]
				SET    
				       CANTIDAD_INICIAL = @CANTIDAD_MIN,
				       CANTIDAD_FINAL   = @CANTIDAD_MAX,
					   FECHA_INICIAL    = @FECHA_INI,
					   FECHA_FINAL      = @FECHA_FIN,
					   PORC_DESCUENTO   = @PORC_DESCUENTO
				      
				WHERE  CLIENTE          = @CLIENTE
				  AND  ARTICULO         = @ARTICULO
				  AND  ESCALA_DCTO      = @ESCALA
				  AND  VERSION_DCTO     = 1'

	EXEC SP_EXECUTESQL	@SQL,
						N'@CLIENTE VARCHAR(20),
	                      @ARTICULO VARCHAR(20), 
	                      @ESCALA INT, 
	                      @CANTIDAD_MIN INT,
	                      @CANTIDAD_MAX INT,
	                      @FECHA_INI DATETIME,
	                      @FECHA_FIN DATETIME,
	                      @PORC_DESCUENTO INT',
						  @CLIENTE,
	                      @ARTICULO, 
	                      @ESCALA, 
	                      @CANTIDAD_MIN,
	                      @CANTIDAD_MAX,
	                      @FECHA_INI,
	                      @FECHA_FIN,
	                      @PORC_DESCUENTO
	                      
	END 
	ELSE 
	BEGIN 

	  IF(@EXIS_CLIENTE = 1 AND @EXIS_ARTICULO = 1 )
		BEGIN
		 SET @SQL = 'INSERT INTO  EXACTUSERP.['+ISNULL(@CIA , '')+'].[DCTO_ART_X_CLI]
					 (
					  [CLIENTE]
                     ,[ARTICULO]
                     ,[ESCALA_DCTO]
                     ,[VERSION_DCTO]
                     ,[CANTIDAD_INICIAL]
                     ,[CANTIDAD_FINAL]
                     ,[FECHA_INICIAL]
                     ,[FECHA_FINAL]
                     ,[PORC_DESCUENTO]
                     ,[TIPO_DESCUENTO]
					)
					VALUES
					(
					  @CLIENTE,
	                  @ARTICULO, 
	                  @ESCALA, 
	                  1,
	                  @CANTIDAD_MIN,
	                  @CANTIDAD_MAX,
	                  @FECHA_INI,
	                  @FECHA_FIN,
	                  @PORC_DESCUENTO,
	                  ''P''
					)'
		EXECUTE SP_EXECUTESQL	@SQL,
								N'@CLIENTE VARCHAR(20),
	                              @ARTICULO VARCHAR(20), 
	                              @ESCALA INT, 
	                              @CANTIDAD_MIN INT,
	                              @CANTIDAD_MAX INT,
	                              @FECHA_INI DATETIME,
	                              @FECHA_FIN DATETIME,
	                              @PORC_DESCUENTO INT',
						          @CLIENTE,
	                              @ARTICULO, 
	                              @ESCALA,
	                              @CANTIDAD_MIN,
	                              @CANTIDAD_MAX,
	                              @FECHA_INI,
	                              @FECHA_FIN,
	                              @PORC_DESCUENTO
	                              
		END
	END 

	IF @@ROWCOUNT = 0
	BEGIN
		RETURN 0
	END
	ELSE 
	BEGIN
		RETURN 1
	END
END




GO
/****** Object:  StoredProcedure [DIS86].[PROC_EDI_DESCUENTO_CLIENTE_ARTICULO_MASIVO]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE   PROCEDURE [DIS86].[PROC_EDI_DESCUENTO_CLIENTE_ARTICULO_MASIVO]
(
    @CLIENTE           VARCHAR(20),
    @ARTICULOS_CSV     VARCHAR(MAX),
    @ESCALA            INT,
    @CANTIDAD_MIN      INT,
    @CANTIDAD_MAX      INT,
    @FECHA_INI         DATETIME,
    @FECHA_FIN         DATETIME,
    @PORC_DESCUENTO    INT,
    @CIA               VARCHAR(20)
)
AS
BEGIN
    SET NOCOUNT, XACT_ABORT ON;
    BEGIN TRAN;

    BEGIN TRY
        -- 1) Validar cliente
        IF NOT EXISTS (
            SELECT 1 
            FROM EXACTUSERP.DIS86.CLIENTE 
            WHERE CLIENTE = @CLIENTE
        )
            THROW 51000, 'Cliente no existe', 1;

        -- 2) Poblar tabla temporal con los artículos recibidos
        IF OBJECT_ID('tempdb..#Articulos') IS NOT NULL
            DROP TABLE #Articulos;

        CREATE TABLE #Articulos (
            ARTICULO VARCHAR(20) PRIMARY KEY
        );

        INSERT INTO #Articulos(ARTICULO)
        SELECT LTRIM(RTRIM(value))
        FROM STRING_SPLIT(@ARTICULOS_CSV, ',')
        WHERE value <> '';

        -- 3) Eliminar de #Articulos los que no existen en maestro
        DELETE A
        FROM #Articulos AS A
        WHERE NOT EXISTS (
            SELECT 1
            FROM EXACTUSERP.DIS86.ARTICULO art
            WHERE art.ARTICULO = A.ARTICULO
        );

        -- 4) Si quedó vacío, abortar
        IF NOT EXISTS (SELECT 1 FROM #Articulos)
            THROW 51001, 'Ningún artículo válido en la lista', 1;

        -- 5) Construir nombre de la tabla destino
        DECLARE @Schema NVARCHAR(128) = QUOTENAME(ISNULL(@CIA, ''));
        DECLARE @Tabla  NVARCHAR(256) = N'EXACTUSERP.' + @Schema + N'.[DCTO_ART_X_CLI]';

        -- 6) Actualizar filas existentes
        DECLARE @sql NVARCHAR(MAX) = N'
        UPDATE T
        SET
            CANTIDAD_INICIAL = @CANT_MIN,
            CANTIDAD_FINAL   = @CANT_MAX,
            FECHA_INICIAL    = @FI,
            FECHA_FINAL      = @FF,
            PORC_DESCUENTO   = @PD
        FROM ' + @Tabla + ' AS T
        INNER JOIN #Articulos AS A
            ON T.CLIENTE      = @CL
           AND T.ARTICULO     = A.ARTICULO
           AND T.VERSION_DCTO = 1
           AND T.ESCALA_DCTO  = @ES;';

        EXEC sp_executesql
            @sql,
            N'@CL VARCHAR(20),
              @ES INT,
              @CANT_MIN INT,
              @CANT_MAX INT,
              @FI DATETIME,
              @FF DATETIME,
              @PD INT',
            @CL        = @CLIENTE,
            @ES        = @ESCALA,
            @CANT_MIN  = @CANTIDAD_MIN,
            @CANT_MAX  = @CANTIDAD_MAX,
            @FI        = @FECHA_INI,
            @FF        = @FECHA_FIN,
            @PD        = @PORC_DESCUENTO;

        -- 7) Insertar los que no estaban
        SET @sql = N'
        INSERT INTO ' + @Tabla + ' (
            CLIENTE, ARTICULO, ESCALA_DCTO, VERSION_DCTO,
            CANTIDAD_INICIAL, CANTIDAD_FINAL,
            FECHA_INICIAL, FECHA_FINAL,
            PORC_DESCUENTO, TIPO_DESCUENTO
        )
        SELECT
            @CL, A.ARTICULO, @ES, 1,
            @CANT_MIN, @CANT_MAX,
            @FI, @FF,
            @PD, ''P''
        FROM #Articulos AS A
        LEFT JOIN ' + @Tabla + ' AS T
            ON T.CLIENTE      = @CL
           AND T.ARTICULO     = A.ARTICULO
           AND T.VERSION_DCTO = 1
           AND T.ESCALA_DCTO  = @ES
        WHERE T.ARTICULO IS NULL;';

        EXEC sp_executesql
            @sql,
            N'@CL VARCHAR(20),
              @ES INT,
              @CANT_MIN INT,
              @CANT_MAX INT,
              @FI DATETIME,
              @FF DATETIME,
              @PD INT',
            @CL        = @CLIENTE,
            @ES        = @ESCALA,
            @CANT_MIN  = @CANTIDAD_MIN,
            @CANT_MAX  = @CANTIDAD_MAX,
            @FI        = @FECHA_INI,
            @FF        = @FECHA_FIN,
            @PD        = @PORC_DESCUENTO;

        COMMIT;
        RETURN 1;
    END TRY
    BEGIN CATCH
        ROLLBACK;
        RETURN 0;
    END CATCH
END
GO
/****** Object:  StoredProcedure [DIS86].[PROC_EDI_ESCALA_BONIFICACION]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
