CREATE PROCEDURE [DIS86].[PROC_EDI_ESCALA_BONIFICACION] ( 
	@NIVEL_PRECIO VARCHAR(12),
	@MONEDA VARCHAR(1),
	@VERSION INT,
	@ARTICULO VARCHAR(20),
	@ESCALA INT,
	@VERSION_BONIF INT,
	@ARTICULO_BONI VARCHAR(20),
	@CANTIDAD_MIN INT,
	@CANTIDAD_MAX INT,
	@UND_BONIFICAR INT, 
	@FECHA_INI DATETIME,
	@FECHA_FIN DATETIME,
	@FACTOR INT,
	@CIA VARCHAR(20)
) 
AS
BEGIN

 IF  @NIVEL_PRECIO  IS NULL OR LTRIM(RTRIM(@NIVEL_PRECIO))   = '' OR
        @MONEDA        IS NULL OR LTRIM(RTRIM(@MONEDA))         = '' OR
        @VERSION       IS NULL OR
        @ARTICULO      IS NULL OR LTRIM(RTRIM(@ARTICULO))       = '' OR
        @ESCALA        IS NULL OR
        @VERSION_BONIF IS NULL OR
        @ARTICULO_BONI IS NULL OR LTRIM(RTRIM(@ARTICULO_BONI))  = '' OR
        @CANTIDAD_MIN  IS NULL OR
        @CANTIDAD_MAX  IS NULL OR
        @UND_BONIFICAR IS NULL OR
        @FECHA_INI     IS NULL OR
        @FECHA_FIN     IS NULL OR
        @FACTOR        IS NULL OR
        @CIA           IS NULL OR LTRIM(RTRIM(@CIA))            = ''
    BEGIN
        RAISERROR (N'Todos los parámetros son obligatorios y deben venir llenos.', 16, 1);
        RETURN -1; 
    END;

	DECLARE	@SQL NVARCHAR(MAX)
	DECLARE @EXIS_CLIENTE INT = 1, @EXIS_ARTICULO INT
	
	SET @EXIS_ARTICULO = (SELECT COUNT(ARTICULO) FROM EXACTUSERP.DIS86.ARTICULO WHERE ARTICULO = @ARTICULO)

	IF EXISTS ( SELECT ARTICULO 
	            FROM   EXACTUSERP.[DIS86].[ESCALA_BONIF] 
	            WHERE 
				       [NIVEL_PRECIO]   = @NIVEL_PRECIO 
				AND    [MONEDA]         = @MONEDA
				AND    [VERSION]        = @VERSION
				AND    [ARTICULO]       = @ARTICULO
				AND    [ESCALA_BONIF]   = @ESCALA
				AND    [VERSION_BONIF]  = @VERSION_BONIF
			
				)
	BEGIN 
	SET	@SQL = 'UPDATE EXACTUSERP.['+ISNULL(@CIA , '')+'].[ESCALA_BONIF]
				SET    
				       [MIN_ART_FACT]     = @CANTIDAD_MIN,
				       [MAX_ART_FACT]     = @CANTIDAD_MAX,
					   [UNIDADES_BONIF]   = @UND_BONIFICAR,
					   [FECHA_INICIO_ESC] = @FECHA_INI,
					   [FECHA_FIN_ESC]    = @FECHA_FIN,
					   FACTOR_BONIF       = @FACTOR,
					   [ARTICULO_BONIF]   =  @ARTICULO_BONI
				WHERE 
				       [NIVEL_PRECIO]     =  @NIVEL_PRECIO 
				AND    [MONEDA]		      =  @MONEDA
				AND    [VERSION]	      =  @VERSION
				AND    [ARTICULO]	      =  @ARTICULO
				AND    [ESCALA_BONIF]     =  @ESCALA
				AND    [VERSION_BONIF]    =  @VERSION_BONIF'

	EXEC SP_EXECUTESQL	@SQL,
						N'@NIVEL_PRECIO VARCHAR(12),
	                      @MONEDA VARCHAR(1),
	                      @VERSION INT,
	                      @ARTICULO VARCHAR(20),
	                      @ESCALA INT,
	                      @VERSION_BONIF INT,
	                      @ARTICULO_BONI VARCHAR(20),
	                      @CANTIDAD_MIN INT,
	                      @CANTIDAD_MAX INT,
	                      @UND_BONIFICAR INT, 
	                      @FECHA_INI DATETIME,
	                      @FECHA_FIN DATETIME,
	                      @FACTOR INT',
						  @NIVEL_PRECIO,
	                      @MONEDA,
	                      @VERSION,
	                      @ARTICULO,
	                      @ESCALA,
	                      @VERSION_BONIF,
	                      @ARTICULO_BONI,
	                      @CANTIDAD_MIN,
	                      @CANTIDAD_MAX,
	                      @UND_BONIFICAR, 
	                      @FECHA_INI,
	                      @FECHA_FIN,
	                      @FACTOR
						  
	END 
	ELSE 
	BEGIN 

	  IF(@EXIS_CLIENTE = 1 AND @EXIS_ARTICULO = 1 )
		BEGIN
		 SET @SQL = 'INSERT INTO  EXACTUSERP.['+ISNULL(@CIA , '')+'].[ESCALA_BONIF]
					 (
					 [NIVEL_PRECIO]
                    ,[MONEDA]
                    ,[VERSION]
                    ,[ARTICULO]
                    ,[ESCALA_BONIF]
                    ,[VERSION_BONIF]
                    ,[ARTICULO_BONIF]
                    ,[MIN_ART_FACT]
                    ,[MAX_ART_FACT]
                    ,[UNIDADES_BONIF]
                    ,[FECHA_INICIO_ESC]
                    ,[FECHA_FIN_ESC]
                    ,[FACTOR_BONIF]
					)
					VALUES
					(
					 @NIVEL_PRECIO,
	                 @MONEDA,
	                 @VERSION,
	                 @ARTICULO,
	                 @ESCALA,
	                 @VERSION_BONIF,
	                 @ARTICULO_BONI,
	                 @CANTIDAD_MIN,
	                 @CANTIDAD_MAX,
	                 @UND_BONIFICAR, 
	                 @FECHA_INI,
	                 @FECHA_FIN,
	                 @FACTOR
					)'

		EXECUTE SP_EXECUTESQL	@SQL,
								N'@NIVEL_PRECIO VARCHAR(12),
	                              @MONEDA VARCHAR(1),
	                              @VERSION INT,
	                              @ARTICULO VARCHAR(20),
	                              @ESCALA INT,
	                              @VERSION_BONIF INT,
	                              @ARTICULO_BONI VARCHAR(20),
	                              @CANTIDAD_MIN INT,
	                              @CANTIDAD_MAX INT,
	                              @UND_BONIFICAR INT, 
	                              @FECHA_INI DATETIME,
	                              @FECHA_FIN DATETIME,
	                              @FACTOR INT',
						          @NIVEL_PRECIO,
	                              @MONEDA,
	                              @VERSION,
	                              @ARTICULO,
	                              @ESCALA,
	                              @VERSION_BONIF,
	                              @ARTICULO_BONI,
	                              @CANTIDAD_MIN,
	                              @CANTIDAD_MAX,
	                              @UND_BONIFICAR, 
	                              @FECHA_INI,
	                              @FECHA_FIN,
	                              @FACTOR
								
		END
	END 

	IF @@ROWCOUNT = 0
	BEGIN
		RETURN 0
	END
	ELSE 
	BEGIN
		RETURN 1
	END
END




