/****** Object:  StoredProcedure [DIS86].[PROC_EDI_PORCENTAJE_DESCUENTO]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [DIS86].[PROC_EDI_PORCENTAJE_DESCUENTO] ( 
	@NIVEL_PRECIO VARCHAR(12),
	@ARTICULO VARCHAR(20), 
	@ESCALA INT, 
	@CANTIDAD_MIN INT,
	@CANTIDAD_MAX INT,
	@PORC_DESCUENTO INT,
	@FECHA_INI DATETIME,
	@FECHA_FIN DATETIME,
	@CIA VARCHAR(20)
) 
AS
BEGIN
	DECLARE	@SQL NVARCHAR(MAX)
	DECLARE @ESCALA_FINAL INT

	SET @ESCALA_FINAL = CASE WHEN @ESCALA = 0 THEN 1 ELSE @ESCALA END

	IF EXISTS (
		SELECT ARTICULO 
		FROM EXACTUSERP.[DIS86].[ESCALA_DCTO]
		WHERE  NIVEL_PRECIO  = @NIVEL_PRECIO 
		AND    ARTICULO      = @ARTICULO 
		AND    ESCALA_DCTO   = @ESCALA
		AND    VERSION_DCTO  = 1
		AND    MONEDA        = 'L'
	)
	BEGIN 

		SET	@SQL = '
			UPDATE EXACTUSERP.[' + ISNULL(@CIA , '') + '].[ESCALA_DCTO]
			SET    [MIN_UNID_FACT]    = @CANTIDAD_MIN,
				   [MAX_UNID_FACT]    = @CANTIDAD_MAX,
                   [PORC_DCTO]        = @PORC_DESCUENTO,
                   [FECHA_INICIO_ESC] = @FECHA_INI,
                   [FECHA_FIN_ESC]    = @FECHA_FIN,
                   [FECHA_ULT_MODIF]  = GETDATE()
			WHERE 
				   [NIVEL_PRECIO]     = @NIVEL_PRECIO
			AND    [ARTICULO]         = @ARTICULO
			AND    [MONEDA]           = ''L''
			AND    [VERSION]          = 1 
			AND    [ESCALA_DCTO]      = @ESCALA
			AND    [VERSION_DCTO]     = 1'
	END 
	ELSE
	BEGIN

		SET @SQL = '
			INSERT INTO EXACTUSERP.[' + ISNULL(@CIA , '') + '].[ESCALA_DCTO]
			(
				NIVEL_PRECIO,
				ARTICULO,
				ESCALA_DCTO,
				MIN_UNID_FACT,
				MAX_UNID_FACT,
				PORC_DCTO,
				MONEDA,
				VERSION,
				VERSION_DCTO,
				FECHA_INICIO_ESC,
				FECHA_FIN_ESC,
				FECHA_ULT_MODIF,
				USUARIO_ULT_MODIF,
				RecordDate
			)
			VALUES
			(
				@NIVEL_PRECIO,
				@ARTICULO,
				@ESCALA_FINAL,
				@CANTIDAD_MIN,
				@CANTIDAD_MAX,
				@PORC_DESCUENTO,
				''L'',
				1,
				1,
				@FECHA_INI,
				@FECHA_FIN,
				GETDATE(),
				''sa'',
				GETDATE()
			)'
	END

	EXEC SP_EXECUTESQL 
		@SQL,
		N'@NIVEL_PRECIO VARCHAR(12),
		  @ARTICULO VARCHAR(20), 
		  @ESCALA INT,
		  @ESCALA_FINAL INT,
		  @CANTIDAD_MIN INT,
		  @CANTIDAD_MAX INT,
		  @PORC_DESCUENTO INT,
		  @FECHA_INI DATETIME,
		  @FECHA_FIN DATETIME',
		@NIVEL_PRECIO,
		@ARTICULO,
		@ESCALA,
		@ESCALA_FINAL,
		@CANTIDAD_MIN,
		@CANTIDAD_MAX,
		@PORC_DESCUENTO,
		@FECHA_INI,
		@FECHA_FIN

	IF @@ROWCOUNT = 0
	BEGIN
		RETURN 0
	END
	ELSE 
	BEGIN
		RETURN 1
	END
END

GO
/****** Object:  StoredProcedure [DIS86].[PROC_EDI_PORCENTAJE_DESCUENTO_MASIVO]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [DIS86].[PROC_EDI_PORCENTAJE_DESCUENTO_MASIVO]
(
      @NIVEL_PRECIO     VARCHAR(12),
      @LISTA_ARTICULOS  VARCHAR(MAX),
      @CANTIDAD_MIN     INT,
      @CANTIDAD_MAX     INT,
      @PORC_DESCUENTO   INT,
      @FECHA_INI        VARCHAR(30),
      @FECHA_FIN        VARCHAR(30),
      @ESCALA           INT,
      @CIA              VARCHAR(20)
)
AS
BEGIN
    SET NOCOUNT ON;
    BEGIN TRY
        BEGIN TRANSACTION;

        DECLARE @SQL NVARCHAR(MAX);
        DECLARE @ESCALA_FINAL INT = CASE WHEN @ESCALA = 0 THEN 1 ELSE @ESCALA END;

        SET @SQL = N'
        ;WITH A AS (
            SELECT RTRIM(LTRIM(VAL)) AS ARTICULO
            FROM DIS86.TF_SPLIT(@LISTA, '','')
        )
        MERGE EXACTUSERP.' + QUOTENAME(@CIA) + N'.ESCALA_DCTO AS T
        USING (
            SELECT
                @NIVEL       AS NIVEL_PRECIO,
                ''L''        AS MONEDA,
                1            AS VERSION,
                ARTICULO     AS ARTICULO,
                @ESCALA      AS ESCALA_DCTO,
                1            AS VERSION_DCTO,
                @MIN         AS MIN_UNID_FACT,
                @MAX         AS MAX_UNID_FACT,
                @DESC        AS PORC_DCTO,
                @FINI        AS FECHA_INICIO_ESC,
                @FFIN        AS FECHA_FIN_ESC,
                GETDATE()    AS FECHA_ULT_MODIF,
                ''sa''       AS USUARIO_ULT_MODIF,
                GETDATE()    AS RecordDate
            FROM A
        ) S
        ON  T.NIVEL_PRECIO   = S.NIVEL_PRECIO
        AND T.MONEDA         = S.MONEDA
        AND T.VERSION        = S.VERSION
        AND T.ARTICULO       = S.ARTICULO
        AND T.ESCALA_DCTO    = S.ESCALA_DCTO
        AND T.VERSION_DCTO   = S.VERSION_DCTO
        WHEN MATCHED THEN
            UPDATE SET
                T.MIN_UNID_FACT     = S.MIN_UNID_FACT,
                T.MAX_UNID_FACT     = S.MAX_UNID_FACT,
                T.PORC_DCTO         = S.PORC_DCTO,
                T.FECHA_INICIO_ESC  = S.FECHA_INICIO_ESC,
                T.FECHA_FIN_ESC     = S.FECHA_FIN_ESC,
                T.FECHA_ULT_MODIF   = S.FECHA_ULT_MODIF,
                T.USUARIO_ULT_MODIF = S.USUARIO_ULT_MODIF
        WHEN NOT MATCHED THEN
            INSERT (NIVEL_PRECIO, MONEDA, VERSION, ARTICULO,
                    ESCALA_DCTO, VERSION_DCTO,
                    MIN_UNID_FACT, MAX_UNID_FACT, PORC_DCTO,
                    FECHA_INICIO_ESC, FECHA_FIN_ESC,
                    FECHA_ULT_MODIF, USUARIO_ULT_MODIF, RecordDate)
            VALUES (S.NIVEL_PRECIO, S.MONEDA, S.VERSION, S.ARTICULO,
                    S.ESCALA_DCTO, S.VERSION_DCTO,
                    S.MIN_UNID_FACT, S.MAX_UNID_FACT, S.PORC_DCTO,
                    S.FECHA_INICIO_ESC, S.FECHA_FIN_ESC,
                    S.FECHA_ULT_MODIF, S.USUARIO_ULT_MODIF, S.RecordDate);';

        EXEC sys.sp_executesql
             @SQL,
             N'@NIVEL VARCHAR(12),
               @ESCALA INT,
               @MIN INT,
               @MAX INT,
               @DESC INT,
               @FINI VARCHAR(30),
               @FFIN VARCHAR(30),
               @LISTA VARCHAR(MAX)',
             @NIVEL  = @NIVEL_PRECIO,
             @ESCALA = @ESCALA_FINAL,
             @MIN    = @CANTIDAD_MIN,
             @MAX    = @CANTIDAD_MAX,
             @DESC   = @PORC_DESCUENTO,
             @FINI   = @FECHA_INI,
             @FFIN   = @FECHA_FIN,
             @LISTA  = @LISTA_ARTICULOS;

        COMMIT;
        RETURN 1;
    END TRY
    BEGIN CATCH
        ROLLBACK;
        RETURN 0;
    END CATCH
END
GO
