CREATE PROC [DIS86].[PROC_ENVIAR_REPORTE_RUTA_CXC]
(
@PEDIDO VARCHAR(MAX),
@ESTADO_FAC INT
)
AS
BEGIN
SELECT 
FACTURA,
PEDIDO,
CLIENTE_NOMBRE CLIENTE,
RUTA_NOMBRE RUTA, 
CONDICION_PAGO,
SEGUIR_FAC,
CASE WHEN OBSERVACIONES LIKE 'Cargado de FR%' THEN SUBSTRING(OBSERVACIONES,15,800) ELSE OBSERVACIONES END OBSERVACIONES
FROM DIS86.VIEW_TRACKING
WHERE SEGUIR_FAC = @ESTADO_FAC
