AND (PEDIDO IN(SELECT VAL FROM [DIS86].[TF_SPLIT](@PEDIDO,',')) OR '0' IN(SELECT VAL FROM [DIS86].[TF_SPLIT](@PEDIDO,',')))
ORDER BY FACTURA ASC
END
