CREATE PROC [DIS86].[PROC_FACTURA_CXC_RECIBE_DIARIO]

AS 
BEGIN 

DECLARE @FECHA date = GETDATE()


SELECT COUNT(PD.PEDIDO)  CANT_FACTURA

FROM DIS86.VIEW_TRACKING PD 
 
WHERE  PD.SEGUIR_FAC = 5 --CxC Recibe
AND    PD.FACTURA IS NOT NULL
AND CAST(FECHA_HORA_RECIBIDO AS DATE) = @FECHA

END 



GO
/****** Object:  StoredProcedure [DIS86].[PROC_FACTURA_CXC_RECIBE_SEMANAL]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROC [DIS86].[PROC_FACTURA_CXC_RECIBE_SEMANAL]

AS 
BEGIN 
DECLARE @FECHA date = GETDATE()
DECLARE 
	        @INICIOMES    DATE, 
			@FINMES       DATE, 
			@NUM_SEMANA    INT, 
			@UNASOLAFECHA  INT

	SET 	@INICIOMES   = DATEADD(DAY, 1, EOMONTH(@FECHA, -1))
	SET 	@FINMES      = EOMONTH(@FECHA)
	SET 	@NUM_SEMANA  =(select datepart(week,getdate())- datepart(week, dateadd(dd,-day(getdate())+1,getdate()))+1) ---(SELECT ((DATEPART(ISO_WEEK, @INICIOMES) - DATEPART(ISO_WEEK, @FINMES)) + 1)* -1)
	                         
 SELECT 	COUNT(PD.PEDIDO)  CANT_FACTURA
   FROM 
			DIS86.VIEW_TRACKING PD 
  WHERE  
			PD.SEGUIR_FAC = 5 --CxC Recibe
	AND     PD.FACTURA IS NOT NULL
    AND		DATEDIFF(DD,PD.FECHA_HORA_RECIBIDO,@FINMES)>=0 AND DATEDIFF(DD,PD.FECHA_HORA_RECIBIDO,@INICIOMES)<=0
    AND	    (DATEPART(WEEK, PD.FECHA_HORA_RECIBIDO)-DATEPART(WEEK, DATEADD(MM, DATEDIFF(MM,0,PD.FECHA_HORA_RECIBIDO), 0))+ 1) = @NUM_SEMANA
	--AND PD.PEDIDO = 'GESSA00000435'
END 



GO
