CREATE  PROCEDURE [DIS86].[PROC_INS_SEGUI_FACTURA]
(
	@DESCRIPCION VARCHAR(200),
	@DET_DESCRIPCION VARCHAR(800),
	@COLOR_HEXA VARCHAR(100),
	@CIA VARCHAR(30)
	
)
AS 
BEGIN
DECLARE @SQL NVARCHAR(MAX)

SET @SQL = 'INSERT INTO '+ISNULL(@CIA , '')+'.[ESTADO_FACTURA_SEGUIMIENTO]
           (
		    DESCRIPCION
           ,DET_DESCRIPCION
           ,COLOR_HEXA
		   )
           VALUES
           (
		   @DESCRIPCION,
		   @DET_DESCRIPCION,
		   @COLOR_HEXA
		   )'
			
		 
	
	EXECUTE SP_EXECUTESQL	@SQL,
							N'@DESCRIPCION VARCHAR(50),
							@DET_DESCRIPCION VARCHAR(800),
							@COLOR_HEXA VARCHAR(100)',
							@DESCRIPCION,
							@DET_DESCRIPCION,
							@COLOR_HEXA
	IF @@ROWCOUNT = 0
	BEGIN
		RETURN 0
	END
	ELSE
	BEGIN
		RETURN 1
	END
	
END


GO
