CREATE PROCEDURE [DIS86].[PROC_INSERTAR_LINEA_BONIFICADA_PEDIDO]
    @pedido INT,
	@cliente_id VARCHAR(20),
    @articulo_id VARCHAR(20),
    @unidades_pedidas INT,
	@existencia INT
AS
BEGIN
    SET NOCOUNT ON;

    -- Variables para almacenar los valores
    DECLARE @unidades_min INT;
    DECLARE @unidades_max INT;
	DECLARE @factor_bonif INT;    
    DECLARE @unidades_bonif INT 
	DECLARE @nivel_precio varchar(12)
	DECLARE @cant_max INT
	DECLARE @bonif_art_x_cli_existe int
	DECLARE @unidades_a_bonificar INT
	DECLARE @sumarunidades_a_bonificar INT
	DECLARE @existeNivelBoni int

	-- obtenemos el nivel de precio del cliente 

	SELECT 
	       @nivel_precio =  NIVEL_PRECIO
	FROM   [EXACTUSERP].[DIS86].[CLIENTE]
    WHERE  CLIENTE = @cliente_id

	--- SELECT * FROM [EXACTUSERP].[DIS86].[BONIF_ART_X_CLI]

	set @bonif_art_x_cli_existe =(SELECT COUNT(CLIENTE) 
	                              FROM   [EXACTUSERP].[DIS86].[BONIF_ART_X_CLI]
								  WHERE  CLIENTE       = @cliente_id
		                          AND    ARTICULO      = @articulo_id
		                          AND    VERSION_BONIF = 1
								  AND FECHA_INICIAL <= GETDATE() 
								  AND  FECHA_FINAL  >= GETDATE())
		  

   IF(@bonif_art_x_cli_existe = 1)
   BEGIN 

     SELECT 
           @unidades_min   = CANTIDAD_INICIAL,
		   @unidades_max   = CANTIDAD_FINAL,
		   @factor_bonif   = FACTOR_BONIF,
		   @unidades_bonif = UNIDADES_BONIF
     FROM 
           [EXACTUSERP].[DIS86].[BONIF_ART_X_CLI]
	 WHERE CLIENTE       = @cliente_id
	 AND   ARTICULO      = @articulo_id 
	 AND   VERSION_BONIF = 1
   
 

        -- Verificar si las unidades pedidas están dentro del rango permitido
    IF @unidades_pedidas >= @unidades_min AND @unidades_pedidas <= @unidades_max
    BEGIN
	  
	   --- consultamos si ya existe el articulo bonificado
	              SELECT 
	                     @cant_max= COUNT(ARTICULO_EXACTUSERP) 
	              FROM   
				         DIS86.PEDIDO_LINEA 
				  WHERE 
				         PEDIDO            = @pedido 
				  AND    ARTICULO_EXACTUSERP = @articulo_id
				  AND    ES_BONIFICADO     = 'S' 
	
	-- sumamos la cantidad de la linea bonificada. 

	IF(@cant_max >= 1) 
     BEGIN 

	 -- Calcular las unidades a bonificar
        SET @sumarunidades_a_bonificar = (CAST(@unidades_pedidas AS DECIMAL(10, 2)) / @factor_bonif) * @unidades_bonif;

		 UPDATE [DIS86].PEDIDO_LINEA  
		 SET    CANTIDAD   = @sumarunidades_a_bonificar, 
			    EXISTENCIA = EXISTENCIA - @sumarunidades_a_bonificar
		 WHERE  PEDIDO             = @PEDIDO 
		 AND    ARTICULO_EXACTUSERP  = @articulo_id
		 AND    ES_BONIFICADO      = 'S' 
	
	 END
	  ELSE 
		BEGIN
        -- Calcular las unidades a bonificar
        SET @unidades_a_bonificar = (CAST(@unidades_pedidas AS DECIMAL(10, 2)) / @factor_bonif) * @unidades_bonif;
        
		-- Insertar la línea de bonificación si aplica
        IF @unidades_a_bonificar > 0
        BEGIN
           
			INSERT INTO [DIS86].[PEDIDO_LINEA]
						   ([PEDIDO]
						   ,[ARTICULO_EXACTUSERP]
						   ,[CANTIDAD]
						   ,[ACTIVIDAD_ECONOMICA]
						   ,[EXISTENCIA]
						   ,[PORC_DESCUENTO]
						   ,[BODEGA]
						   ,[ES_BONIFICADO]
						    )
					 VALUES
						   (@Pedido
						   ,@articulo_id
						   ,@unidades_a_bonificar 
						   ,'519003'
						   ,@EXISTENCIA
						   ,0
						   ,'01'
						   ,'S')

          END
        
      END
    
  END

   END 
   ELSE 
   BEGIN 
    -- Obtener los valores mínimos y máximos de la tabla ESCALA_BONIF

	set @existeNivelBoni =(SELECT COUNT(ARTICULO) 
	                              FROM 
								  [EXACTUSERP].[DIS86].[ESCALA_BONIF]
							       WHERE ARTICULO     = @articulo_id
							       AND   NIVEL_PRECIO = @nivel_precio
								  AND    FECHA_INICIO_ESC <= GETDATE() 
								  AND    FECHA_FIN_ESC  >= GETDATE())


	if(@existeNivelBoni = 1)
	BEGIN 

    SELECT 
          @unidades_min   = [MIN_ART_FACT],
          @unidades_max   = [MAX_ART_FACT],
		  @factor_bonif   = [FACTOR_BONIF],
		  @unidades_bonif = [UNIDADES_BONIF]

    FROM 
          [EXACTUSERP].[DIS86].[ESCALA_BONIF]
    WHERE ARTICULO     = @articulo_id
    AND   NIVEL_PRECIO = @nivel_precio

	
	        -- Verificar si las unidades pedidas están dentro del rango permitido
    IF @unidades_pedidas >= @unidades_min AND @unidades_pedidas <= @unidades_max
    BEGIN
	  
	   --- consultamos si ya existe el articulo bonificado
	              SELECT 
	                     @cant_max= COUNT(ARTICULO_EXACTUSERP) 
	              FROM   
				         DIS86.PEDIDO_LINEA 
				  WHERE 
				         PEDIDO            = @pedido 
				  AND    ARTICULO_EXACTUSERP = @articulo_id
				  AND    ES_BONIFICADO     = 'S' 
	
	-- sumamos la cantidad de la linea bonificada. 

	END

	IF(@cant_max >= 1) 
     BEGIN 

	 -- Calcular las unidades a bonificar
        --DECLARE @sumarunidades_a_bonificar INT;
        SET @sumarunidades_a_bonificar = (CAST(@unidades_pedidas AS DECIMAL(10, 2)) / @factor_bonif) * @unidades_bonif;

		 UPDATE [DIS86].PEDIDO_LINEA  
		 SET    CANTIDAD   = @sumarunidades_a_bonificar, 
			    EXISTENCIA = EXISTENCIA - @sumarunidades_a_bonificar
		 WHERE  PEDIDO             = @PEDIDO 
		 AND    ARTICULO_EXACTUSERP  = @articulo_id
		 AND    ES_BONIFICADO      = 'S' 
	
	 END
	   ELSE 
		BEGIN
        -- Calcular las unidades a bonificar
        
        SET @unidades_a_bonificar = (CAST(@unidades_pedidas AS DECIMAL(10, 2)) / @factor_bonif) * @unidades_bonif;

        -- Insertar la línea de bonificación si aplica
        IF @unidades_a_bonificar > 0
        BEGIN
           
			INSERT INTO [DIS86].[PEDIDO_LINEA]
						   ([PEDIDO]
						   ,[ARTICULO_EXACTUSERP]
						   ,[CANTIDAD]
						   ,[ACTIVIDAD_ECONOMICA]
						   ,[EXISTENCIA]
						   ,[PORC_DESCUENTO]
						   ,[BODEGA]
						   ,[ES_BONIFICADO]
						    )
					 VALUES
						   (@Pedido
						   ,@articulo_id
						   ,@unidades_a_bonificar 
						   ,'519003'
						   ,@EXISTENCIA
						   ,0
						   ,'01'
						   ,'S')

          END
        
      END
    
  END

  END 
END 






GO
/****** Object:  StoredProcedure [DIS86].[PROC_LLENAR_TABLA_SEMANA_VISITA]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROC [DIS86].[PROC_LLENAR_TABLA_SEMANA_VISITA]
AS 
BEGIN 

DECLARE @current_date DATE = GETDATE()
DECLARE @year INT = YEAR(@current_date)
DECLARE @start_date DATE = DATEFROMPARTS(@year, 1, 1)
DECLARE @end_date DATE = DATEFROMPARTS(@year, 12, 31)

;WITH numbers AS (
    SELECT ROW_NUMBER() OVER (ORDER BY (SELECT NULL)) AS num
    FROM master..spt_values
)

INSERT INTO DIS86.U_PS_SEMANA_VISITA ( U_CODIGO, U_DESCRIP, U_SEMANA, U_FECHA_INICIO, U_FECHA_FIN, U_SEMANA_MES, U_ANIO)

SELECT 

        +'S'+RIGHT('0' + CONVERT(VARCHAR, n.num), 2) +'|'+CONVERT(VARCHAR,@year) , 
      
		 +'S'+ RIGHT('0' + CONVERT(VARCHAR, n.num), 2)+ ' | ' + CONVERT(VARCHAR(10), DATEADD(WEEK, n.num - 1, DATEADD(DAY, 1 - DATEPART(WEEKDAY, @start_date), @start_date)), 105) + ' | ' + CONVERT(VARCHAR(10), DATEADD(DAY, 6, DATEADD(WEEK, n.num - 1, DATEADD(DAY, 1 - DATEPART(WEEKDAY, @start_date), @start_date))), 105) AS Descripcion,
         n.num AS semana, 
      
        DATEADD(WEEK, n.num - 1, DATEADD(DAY, 1 - DATEPART(WEEKDAY, @start_date), @start_date)) AS inicio_semana, 
        DATEADD(DAY, 6, DATEADD(WEEK, n.num - 1, DATEADD(DAY, 1 - DATEPART(WEEKDAY, @start_date), @start_date))) AS fin_semana,
	    n.num%4 U_SEMANA_MES, 
	   @year ANIO
FROM numbers n
WHERE DATEADD(WEEK, n.num - 1, DATEADD(DAY, 1 - DATEPART(WEEKDAY, @start_date), @start_date)) <= @end_date
ORDER BY n.num


END
GO
