/****** Object:  StoredProcedure [DIS86].[PROC_OBT_BONIF_ART_CLIENTE_INDEX]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [DIS86].[PROC_OBT_BONIF_ART_CLIENTE_INDEX]
(
@CLIENTE VARCHAR(20),
@CATEGORIA_CLIENTE VARCHAR(10),
@ARTICULO VARCHAR(20),
@CASA VARCHAR(MAX),
@SUBCASA VARCHAR(MAX),
@CIA VARCHAR(20)
)
AS 
BEGIN
DECLARE @SQL NVARCHAR(MAX),@PARAM NVARCHAR(MAX)

DECLARE @TABLE AS TABLE( [CLIENTE] VARCHAR(20)
                        ,[NOMBRE] VARCHAR(4000)
			            ,[CATEGORIA] VARCHAR(10)
			            ,[COD_ARTICULO] VARCHAR(20)
			            ,[ARTICULO_NOMBRE] VARCHAR(8000)
			            ,[ID_CASA] VARCHAR(12)
			            ,[CASA] VARCHAR(4000)
			            ,[ID_SUBCASA] VARCHAR(12)
			            ,[SUBCASA] VARCHAR(4000)
						,[ID_CATEGORIA_ART] VARCHAR(12)
			            ,[CATEGORIA_ART] VARCHAR(4000)
						,[COD_ART_BONIFICADO] VARCHAR(20)
						,[ARTICULO_BONIFICADO] VARCHAR(8000)
			            ,[ESCALA_BONIF] INT 
		                ,[CANT_MINIMA] INT
		                ,[CANT_MAXIMA] INT
		                ,[FECHA_INICIAL] VARCHAR(20) 
		                ,[FECHA_FINAL] VARCHAR(20) 
		                ,[FACTOR_BONIF] INT
		                ,[UNIDADES_BONIF] INT
						,[VERSION_BONIF] INT
				        )

SET @SQL ='SELECT 
				 [CLIENTE] 
                ,[NOMBRE] 
			    ,[CATEGORIA] 
				,[COD_ARTICULO]
				,[ARTICULO_NOMBRE]
				,[ID_CASA]
				,[CASA]
				,[ID_SUBCASA]
				,[SUBCASA]
				,[ID_CATEGORIA_ART]
				,[CATEGORIA_ART]
				,[COD_ART_BONIFICADO]
				,[ARTICULO_BONIFICADO]
				,[ESCALA_BONIF]
				,[CANT_MINIMA]
				,[CANT_MAXIMA]
				,[FECHA_INICIAL]
				,[FECHA_FINAL]
				,[FACTOR_BONIF]
				,[UNIDADES_BONIF]
				,[VERSION_BONIF]
	   FROM     
	            [PS_TRACKING].[DIS86].[VIEW_OBT_LISTA_BONIF_ART_X_CLIENTE]
	   WHERE   	(CLIENTE      = @CLIENTE           OR @CLIENTE           =''0'')
	    AND     (CATEGORIA    = @CATEGORIA_CLIENTE OR @CATEGORIA_CLIENTE = ''0'' )
	    AND     (COD_ARTICULO = @ARTICULO          OR @ARTICULO = ''0'')
		AND     (ID_CASA IN(SELECT VAL FROM [DIS86].[TF_SPLIT](@CASA,'',''))       OR ''0'' IN(SELECT VAL FROM [DIS86].[TF_SPLIT](@CASA,'','')))
		AND     (ID_SUBCASA IN(SELECT VAL FROM [DIS86].[TF_SPLIT](@SUBCASA,'','')) OR ''0'' IN(SELECT VAL FROM [DIS86].[TF_SPLIT](@SUBCASA,'','')))
		'

SET @PARAM = '@CLIENTE VARCHAR(20),
              @CATEGORIA_CLIENTE VARCHAR(10),
			  @ARTICULO VARCHAR(20),
              @CASA VARCHAR(MAX),
              @SUBCASA VARCHAR(MAX)'


INSERT INTO @TABLE EXEC SP_EXECUTESQL @SQL,@PARAM,
										   @CLIENTE,
										   @CATEGORIA_CLIENTE,
										   @ARTICULO,
										   @CASA,
										   @SUBCASA 
	 
SELECT * FROM @TABLE NOLOCK

END 
GO
/****** Object:  StoredProcedure [DIS86].[PROC_OBT_BONIF_ART_CLIENTE_INDEX_V2]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROC [DIS86].[PROC_OBT_BONIF_ART_CLIENTE_INDEX_V2]
(
  @CLIENTE            VARCHAR(20),
  @CATEGORIA_CLIENTE  VARCHAR(10),
  @ARTICULO           VARCHAR(20),
  @CASA               VARCHAR(MAX),
  @SUBCASA            VARCHAR(MAX),
  @CIA                VARCHAR(20)
)
AS
BEGIN
  SET NOCOUNT ON;

  DECLARE @SQL   NVARCHAR(MAX),
          @PARAM NVARCHAR(MAX);

  -- tabla temporal
  DECLARE @TABLE TABLE(
     CLIENTE            VARCHAR(20),
     NOMBRE             VARCHAR(4000),
     CATEGORIA          VARCHAR(10),
     COD_ARTICULO       VARCHAR(20),
     ARTICULO_NOMBRE    VARCHAR(8000),
     ID_CASA            VARCHAR(12),
     CASA               VARCHAR(4000),
     ID_SUBCASA         VARCHAR(12),
     SUBCASA            VARCHAR(4000),
     ID_CATEGORIA_ART   VARCHAR(12),
     CATEGORIA_ART      VARCHAR(4000),
     COD_ART_BONIFICADO VARCHAR(20),
     ARTICULO_BONIFICADO VARCHAR(8000),
     ESCALA_BONIF       INT,
     CANT_MINIMA        INT,
     CANT_MAXIMA        INT,
     FECHA_INICIAL      VARCHAR(20),
     FECHA_FINAL        VARCHAR(20),
     FACTOR_BONIF       INT,
     UNIDADES_BONIF     INT,
     VERSION_BONIF      INT
  );

  SET @SQL = N'
    SELECT
      @CLIENTE                           AS CLIENTE,
      CLI.NOMBRE                         AS NOMBRE,
      CLI.CATEGORIA_CLIENTE              AS CATEGORIA,
      V.COD_ARTICULO                     AS COD_ARTICULO,
      V.ARTICULO_NOMBRE                  AS ARTICULO_NOMBRE,
      V.ID_CASA                          AS ID_CASA,
      V.DESC_CASA                        AS CASA,
      V.ID_SUBCASA                       AS ID_SUBCASA,
      V.DESC_SUBCASA                     AS SUBCASA,
      V.ID_CATEGORIA_ART                 AS ID_CATEGORIA_ART,
      V.DESC_CATEGORIA_ART               AS CATEGORIA_ART,
      ISNULL(B.ARTICULO_BONIF,'''')      AS COD_ART_BONIFICADO,
      ISNULL(B.ARTICULO_BONIF + '' | '' + ARTB.DESCRIPCION,'''')
                                         AS ARTICULO_BONIFICADO,
      ISNULL(B.ESCALA_BONIF,0)           AS ESCALA_BONIF,
      ISNULL(B.CANTIDAD_INICIAL,0)       AS CANT_MINIMA,
      ISNULL(B.CANTIDAD_FINAL,0)         AS CANT_MAXIMA,
      ISNULL(CONVERT(varchar(23),B.FECHA_INICIAL,23),'''')
                                         AS FECHA_INICIAL,
      ISNULL(CONVERT(varchar(23),B.FECHA_FINAL,23),'''')
                                         AS FECHA_FINAL,
      ISNULL(B.FACTOR_BONIF,0)           AS FACTOR_BONIF,
      ISNULL(B.UNIDADES_BONIF,0)         AS UNIDADES_BONIF,
      ISNULL(B.VERSION_BONIF,0)          AS VERSION_BONIF
    FROM ['+@CIA+'].VIEW_OBT_LISTA_BONIF_ART_CLIENTE_V2 AS V
    JOIN ExactusERP.['+@CIA+'].CLIENTE AS CLI
      ON CLI.CLIENTE = @CLIENTE
     AND CLI.ACTIVO  = ''S''
    LEFT JOIN ExactusERP.['+@CIA+'].BONIF_ART_X_CLI AS B
      ON B.CLIENTE  = @CLIENTE
     AND B.ARTICULO = V.COD_ARTICULO
    LEFT JOIN ExactusERP.['+@CIA+'].ARTICULO AS ARTB
      ON ARTB.ARTICULO = B.ARTICULO_BONIF
    WHERE (@ARTICULO          = ''0'' OR V.COD_ARTICULO  = @ARTICULO)
      AND (@CATEGORIA_CLIENTE = ''0'' OR CLI.CATEGORIA_CLIENTE = @CATEGORIA_CLIENTE)
      AND (@CASA               = ''0'' OR V.ID_CASA    IN (
           SELECT VAL FROM ['+@CIA+'].TF_SPLIT(@CASA,'','')))
      AND (@SUBCASA            = ''0'' OR V.ID_SUBCASA IN (
           SELECT VAL FROM ['+@CIA+'].TF_SPLIT(@SUBCASA,'','')))
		     ORDER BY
    CASE WHEN B.FECHA_INICIAL IS NOT NULL THEN 0 ELSE 1 END,
    V.COD_ARTICULO
  ';

  SET @PARAM = N'
    @CLIENTE            VARCHAR(20),
    @CATEGORIA_CLIENTE  VARCHAR(10),
    @ARTICULO           VARCHAR(20),
    @CASA               VARCHAR(MAX),
    @SUBCASA            VARCHAR(MAX)
  ';

  INSERT INTO @TABLE
  EXEC sp_executesql
       @SQL, @PARAM,
       @CLIENTE           = @CLIENTE,
       @CATEGORIA_CLIENTE = @CATEGORIA_CLIENTE,
       @ARTICULO          = @ARTICULO,
       @CASA              = @CASA,
       @SUBCASA           = @SUBCASA;

  SELECT * FROM @TABLE;
END;
GO
