)
AS 
BEGIN
DECLARE @SQL NVARCHAR(MAX),@PARAM NVARCHAR(MAX), @CONTADOR VARCHAR(100) 

DECLARE @TABLE AS TABLE(CLASIFICACION VARCHAR(10),DESCRIPCION VARCHAR(800))


SET @SQL ='SELECT MAR.CLASIFICACION, 
                  MAR.DESCRIPCION 
           FROM 
                 EXACTUSERP.['+ISNULL(@CIA,'')+'].CLASIFICACION AS MAR
	      WHERE MAR.AGRUPACION = 2'

SET @PARAM = '@FECHAINI varchar(15)'


INSERT INTO @TABLE EXEC SP_EXECUTESQL @SQL
	 
SELECT * FROM @TABLE NOLOCK

END 
