-- exec [DIS86].[PROC_OBT_CATEGORIA_CLIENTE_NIVEL_PRECIO]'DIS86'

CREATE PROC [DIS86].[PROC_OBT_CATEGORIA_CLIENTE_NIVEL_PRECIO]
(
--@CLIENTE VARCHAR(100),
@CIA VARCHAR(20)
)
AS 
BEGIN
DECLARE @SQL NVARCHAR(MAX),@PARAM NVARCHAR(MAX), @CATEGORIA_CLIENTE VARCHAR(100) ='0' 

--IF @CLIENTE <> '0'
--BEGIN 
--SET @CATEGORIA_CLIENTE = ( SELECT TOP 1 CATEGORIA_CLIENTE 
