/****** Object:  StoredProcedure [DIS86].[PROC_OBT_CLIENTE_ARTICULO_BONIFICADO_INDEX_V2]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROC [DIS86].[PROC_OBT_CLIENTE_ARTICULO_BONIFICADO_INDEX_V2]
(
     @ARTICULO      VARCHAR(20), 
     @NIVEL_PRECIO  VARCHAR(12),   
     @CASA          VARCHAR(MAX),  
     @SUBCASA       VARCHAR(MAX),  
     @CIA           VARCHAR(20)   
)
AS
BEGIN
    SET NOCOUNT ON;

   
    DECLARE @TABLE TABLE
    (
          NIVEL_PRECIO        VARCHAR(12)
        , COD_ARTICULO_NORMAL VARCHAR(20)
        , ARTICULO_NORMAL     VARCHAR(8000)
        , ID_CASA             VARCHAR(12)
        , CASA                VARCHAR(4000)
        , ID_SUBCASA          VARCHAR(12)
        , SUBCASA             VARCHAR(4000)
        , ID_CATEGORIA_ART    VARCHAR(12)
        , CATEGORIA_ART       VARCHAR(4000)
        , COD_ART_BONIFICADO  VARCHAR(12)
        , ARTICULO_BONIFICADO VARCHAR(8000)
        , ESCALA_BONIF        INT
        , CANT_MINIMA         INT
        , CANT_MAXIMA         INT
        , FECHA_INICIAL       VARCHAR(20)
        , FECHA_FINAL         VARCHAR(20)
        , FACTOR_BONIF        INT
        , UNIDADES_BONIF      INT
        , MONEDA              VARCHAR(1)
        , VERSION_BONIF       INT
    );

 
   DECLARE @SQL   NVARCHAR(MAX) = N'
    SELECT DISTINCT
          NIVEL_PRECIO
        , COD_ARTICULO_NORMAL
        , ARTICULO_NORMAL
        , ID_CASA
        , CASA
        , ID_SUBCASA
        , SUBCASA
        , ID_CATEGORIA_ART
        , CATEGORIA_ART
        , COD_ART_BONIFICADO
        , ARTICULO_BONIFICADO
        , ESCALA_BONIF
        , CANT_MINIMA
        , CANT_MAXIMA
        , FECHA_INICIAL
        , FECHA_FINAL
        , FACTOR_BONIF
        , UNIDADES_BONIF
        , MONEDA
        , VERSION_BONIF
    FROM  [PS_TRACKING].' + QUOTENAME(@CIA) + N'.[VIEW_OBT_LISTA_BONIFICACION_ARTICULOS_INDEX_V2]  V
    WHERE (@ARTICULO = ''0'' OR V.COD_ARTICULO_NORMAL = @ARTICULO)
      AND  V.NIVEL_PRECIO = @NIVEL_PRECIO
      AND ( V.ID_CASA IN (SELECT VAL FROM ' + QUOTENAME(@CIA) + N'.TF_SPLIT(@CASA,'',''))
             OR ''0'' IN (SELECT VAL FROM ' + QUOTENAME(@CIA) + N'.TF_SPLIT(@CASA,'','')) )
			 AND  V.ID_CATEGORIA_ART IS NOT NULL
      AND ( V.ID_SUBCASA IN (SELECT VAL FROM ' + QUOTENAME(@CIA) + N'.TF_SPLIT(@SUBCASA,'',''))
             OR ''0'' IN (SELECT VAL FROM ' + QUOTENAME(@CIA) + N'.TF_SPLIT(@SUBCASA,'','')) );';

    ------------------------------------------------------------------
    DECLARE @PARAM NVARCHAR(MAX) = N'
        @ARTICULO     VARCHAR(20),
        @NIVEL_PRECIO VARCHAR(12),
        @CASA         VARCHAR(MAX),
        @SUBCASA      VARCHAR(MAX)';

    INSERT INTO @TABLE
    EXEC sp_executesql
         @SQL,
         @PARAM,
         @ARTICULO     = @ARTICULO,
         @NIVEL_PRECIO = @NIVEL_PRECIO,
         @CASA         = @CASA,
         @SUBCASA      = @SUBCASA;


  	 
SELECT * FROM @TABLE NOLOCK
 ORDER  BY
           CASE
                WHEN (ISNULL(FECHA_INICIAL,'') = '' OR ISNULL(FECHA_FINAL,'') = '')
                     THEN 1 ELSE 0
           END,
           COD_ARTICULO_NORMAL; 

END 
GO
