CREATE PROC [DIS86].[PROC_OBT_CLIENTE_ARTICULO_PRECIO_INDEX_V2]
(
    @ARTICULO VARCHAR(20),
    @CASA      VARCHAR(MAX),
    @SUBCASA   VARCHAR(MAX),
    @CIA       VARCHAR(20)
)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @SQL   NVARCHAR(MAX),
            @PARAM NVARCHAR(MAX);

    DECLARE @TABLE TABLE(
        ARTICULO            VARCHAR(20),
        COD_NOMBRE_ARTICULO VARCHAR(8000),
        ID_CASA             VARCHAR(12),
        CASA                VARCHAR(4000),
        ID_SUBCASA          VARCHAR(12),
        SUBCASA             VARCHAR(4000),
        ID_CATEGORIA_ART    VARCHAR(12),
        CATEGORIA_ART       VARCHAR(4000)
    );

    SET @SQL = N'
    SELECT
        COD_ARTICULO            AS ARTICULO,
        ARTICULO_NOMBRE         AS COD_NOMBRE_ARTICULO,
        ID_CASA,
        DESC_CASA               AS CASA,
        ID_SUBCASA,
        DESC_SUBCASA            AS SUBCASA,
        ID_CATEGORIA_ART,
        DESC_CATEGORIA_ART      AS CATEGORIA_ART
    FROM [' + @CIA + '].VIEW_OBT_LISTA_BONIF_ART_CLIENTE_V2
    WHERE (@ARTICULO = ''0'' OR COD_ARTICULO = @ARTICULO)
      AND (@CASA      = ''0'' OR ID_CASA    IN (SELECT VAL FROM [' + @CIA + '].TF_SPLIT(@CASA,    '','')))
      AND (@SUBCASA   = ''0'' OR ID_SUBCASA IN (SELECT VAL FROM [' + @CIA + '].TF_SPLIT(@SUBCASA, '','')))
    ';

    SET @PARAM = N'
        @ARTICULO VARCHAR(20),
        @CASA      VARCHAR(MAX),
        @SUBCASA   VARCHAR(MAX)
    ';

    INSERT INTO @TABLE
    EXEC sp_executesql
         @SQL,
         @PARAM,
         @ARTICULO = @ARTICULO,
         @CASA      = @CASA,
         @SUBCASA   = @SUBCASA;
	 
SELECT * FROM @TABLE NOLOCK
END;
GO
