/****** Object:  StoredProcedure [DIS86].[PROC_OBT_CONDICION_PAGO_POR_CLIENTE]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [DIS86].[PROC_OBT_CONDICION_PAGO_POR_CLIENTE]
AS 
BEGIN 

SELECT DISTINCT  
       CNP.CONDICION_PAGO, 
	   RIGHT('0' + CONVERT(VARCHAR,CNP.DIAS_NETO), 2)  + ' - '+ CNP.DESCRIPCION AS DIAS_NETO
FROM EXACTUSERP.DIS86.CONDICION_PAGO AS CNP 
JOIN EXACTUSERP.DIS86.CLIENTE AS CLI ON CNP.CONDICION_PAGO = CLI.CONDICION_PAGO
ORDER BY CNP.CONDICION_PAGO ASC
END 

GO
