/****** Object:  StoredProcedure [DIS86].[PROC_OBT_DATOS_CLIENTE_ESTADO_CUENTA]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO




 -- EXEC [DIS86].[PROC_OBT_DATOS_CLIENTE_ESTADO_CUENTA] '0','0','0','0','0','0','0','1|01-10-2023|07-10-2023'

CREATE  PROC [DIS86].[PROC_OBT_DATOS_CLIENTE_ESTADO_CUENTA]
(
@SEMANA VARCHAR(100),
--@RUTA VARCHAR(4),
@DIA_SEMANA VARCHAR(8),
@SALDO VARCHAR(100),
@CONDICION_PAGO VARCHAR(4),
@ESTADO_VISTA VARCHAR(10),
@VENDEDOR VARCHAR(4),
@CLIENTE VARCHAR(20)

)
AS 
BEGIN 

DECLARE @SQL NVARCHAR(MAX),@PARAM NVARCHAR(MAX)

DECLARE @TABLE AS TABLE(ESTADO VARCHAR(10),CLIENTE VARCHAR(21),CLI_NOMBRE VARCHAR(171),ALIAS VARCHAR(150),COD_VENDEDOR VARCHAR(4),NOMBRE_VENDEDOR VARCHAR(40),
						VEN_NOMBRE VARCHAR(47),EMAIL VARCHAR(249),TELEFONO VARCHAR(50),CONDICION_PAGO VARCHAR(4),DIAS_NETO VARCHAR(36),SALDO DECIMAL(28,8),
						FECHA_ULTIMA_VISITA VARCHAR(100),SEMANA VARCHAR(100), COLOR_HEXA VARCHAR(50), U_ORDEN_VISITA VARCHAR(2))

DECLARE @FSEMANA AS VARCHAR(2), @FFECHAINICIO AS VARCHAR(100), @FFECHAFIN AS VARCHAR(100), @FECHAVISTIAFILTROSEMANA1 VARCHAR(MAX)


-- Crear la tabla temporal ##FECHAS_SEMANAS
CREATE TABLE #FECHAS_SEMANAS (
    SEMANA NVARCHAR(MAX),
    FECHAINICIO NVARCHAR(MAX),
    FECHAFIN NVARCHAR(MAX)
)

-- Dividir las cadenas utilizando la función TF_SPLIT


SET @SALDO		= CASE  WHEN @SALDO = '1' THEN	'AND (EC.SALDO <=0)' -- SIN SALDO O EN NEGATIVO
                        WHEN @SALDO = '2' THEN  'AND (EC.SALDO >=1)' -- SALDO MAYOR A CERO 
  						WHEN @SALDO = '0' THEN	' '		             -- MUESTRA TODOS			                         
						END 


-- Eliminar la tabla temporal #ProveedoresAdicionales
DROP TABLE #FECHAS_SEMANAS

SET @SQL = 'SELECT  
			 ESTADO
			,CLIENTE
			,CLI_NOMBRE
			,ALIAS
			,COD_VENDEDOR
			,NOMBRE_VENDEDOR
			,VEN_NOMBRE
			,EMAIL
			,TELEFONO
			,CONDICION_PAGO
			,DIAS_NETO
			,SALDO
			,FECHA_ULTIMA_VISITA
			,SEMANA
			,COLOR_HEXA
			,EC.U_ORDEN_VISITA
		FROM [DIS86].[VIEW_OBT_DATOS_CLIENTE_ESTADO_CUENTA] AS EC 
		WHERE (EC.CONDICION_PAGO = @CONDICION_PAGO OR  @CONDICION_PAGO = ''0'')
		AND   (EC.ESTADO = @ESTADO_VISTA OR  @ESTADO_VISTA = ''0'') 
		AND ([DIS86].[FUN_VALIDAR_DIAS_SEMANA](REPLACE(REPLACE(EC.SEMANA,''  '','',''),'' '',''''),@SEMANA)=1 OR @SEMANA LIKE ''%0%'' )
		AND ([DIS86].[FUN_VALIDAR_DIAS_SEMANA](REPLACE(REPLACE(EC.DIAS_RUTA,''  '','',''),'' '',''''),@DIA_SEMANA)=1 OR @DIA_SEMANA LIKE ''%0%'' )
		AND   (EC.COD_VENDEDOR = @VENDEDOR OR  @VENDEDOR = ''0'')
		AND   (EC.CLIENTE = @CLIENTE OR  @CLIENTE = ''0'')'
		+ @SALDO + 
		' ORDER BY CAST(EC.U_ORDEN_VISITA AS INT) ASC'

SET @PARAM = '@SEMANA VARCHAR(100),@DIA_SEMANA VARCHAR(8),@SALDO VARCHAR(100),@CONDICION_PAGO VARCHAR(4),@ESTADO_VISTA VARCHAR(10),@VENDEDOR VARCHAR(4),
              @CLIENTE VARCHAR(20),@FECHAVISTIAFILTROSEMANA1 VARCHAR(MAX),@FFECHAINICIO AS VARCHAR(100), @FFECHAFIN AS VARCHAR(100)'

INSERT INTO @TABLE EXEC SP_EXECUTESQL @SQL,@PARAM,@SEMANA,@DIA_SEMANA,@SALDO,@CONDICION_PAGO,@ESTADO_VISTA,@VENDEDOR,@CLIENTE,@FECHAVISTIAFILTROSEMANA1,@FFECHAINICIO,@FFECHAFIN

SELECT * FROM @TABLE
--print @SQL



END 


GO
