CREATE PROC [DIS86].[PROC_OBT_DCTO_ART_CLIENTE_INDEX]
(
@CLIENTE VARCHAR(20),
@CATEGORIA_CLIENTE VARCHAR(10),
@ARTICULO VARCHAR(20),
@CASA VARCHAR(MAX),
@SUBCASA VARCHAR(MAX),
@CIA VARCHAR(20)
)
AS 
BEGIN
DECLARE @SQL NVARCHAR(MAX),@PARAM NVARCHAR(MAX)

DECLARE @TABLE AS TABLE( [CLIENTE] VARCHAR(20)
                        ,[NOMBRE] VARCHAR(4000)
			            ,[CATEGORIA] VARCHAR(10)
			            ,[COD_ARTICULO] VARCHAR(20)
			            ,[ARTICULO_NOMBRE] VARCHAR(8000)
			            ,[ID_CASA] VARCHAR(12)
			            ,[CASA] VARCHAR(4000)
			            ,[ID_SUBCASA] VARCHAR(12)
			            ,[SUBCASA] VARCHAR(4000)
						,[ID_CATEGORIA_ART] VARCHAR(12)
			            ,[CATEGORIA_ART] VARCHAR(4000)
			            ,[ESCALA_DCTO] INT 
		                ,[CANT_MINIMA] INT
		                ,[CANT_MAXIMA] INT
		                ,[FECHA_INICIAL] VARCHAR(20) 
		                ,[FECHA_FINAL] VARCHAR(20) 
		                ,[PORC_DESCUENTO] INT
		               

				        )

SET @SQL ='SELECT 
				 [CLIENTE] 
                ,[NOMBRE] 
			    ,[CATEGORIA] 
				,[COD_ARTICULO]
				,[ARTICULO_NOMBRE]
				,[ID_CASA]
				,[CASA]
				,[ID_SUBCASA]
				,[SUBCASA]
				,[ID_CATEGORIA_ART]
				,[CATEGORIA_ART]
				,[ESCALA_DCTO]
				,[CANT_MINIMA]
				,[CANT_MAXIMA]
				,[FECHA_INICIAL]
				,[FECHA_FINAL]
				,[PORC_DESCUENTO]
		
  FROM [DIS86].[VIEW_OBT_LISTA_DCTO_ART_X_CLIENTE]
        WHERE (CLIENTE = @CLIENTE OR CLIENTE IS NULL)

          AND (CATEGORIA     = @CATEGORIA_CLIENTE OR @CATEGORIA_CLIENTE = ''0'')
          AND (COD_ARTICULO  = @ARTICULO          OR @ARTICULO          = ''0'')
          AND (
                ID_CASA IN (SELECT VAL FROM [DIS86].[TF_SPLIT](@CASA,   '',''))
             OR ''0''    IN (SELECT VAL FROM [DIS86].[TF_SPLIT](@CASA,   '',''))
              )
          AND (
                ID_SUBCASA IN (SELECT VAL FROM [DIS86].[TF_SPLIT](@SUBCASA,'',''))
             OR ''0''       IN (SELECT VAL FROM [DIS86].[TF_SPLIT](@SUBCASA,'',''))
              );
    ';


SET @PARAM = '@CLIENTE VARCHAR(20),
              @CATEGORIA_CLIENTE VARCHAR(10),
			  @ARTICULO VARCHAR(20),
              @CASA VARCHAR(MAX),
              @SUBCASA VARCHAR(MAX)
			  '


INSERT INTO @TABLE EXEC SP_EXECUTESQL @SQL,@PARAM,
										   @CLIENTE,
										   @CATEGORIA_CLIENTE,
										   @ARTICULO,
										   @CASA,
										   @SUBCASA 
	 
SELECT * FROM @TABLE NOLOCK

END 
GO
/****** Object:  StoredProcedure [DIS86].[PROC_OBT_DCTO_ART_CLIENTE_INDEX_V2]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [DIS86].[PROC_OBT_DCTO_ART_CLIENTE_INDEX_V2]
(
  @CLIENTE            VARCHAR(20),
  @CATEGORIA_CLIENTE  VARCHAR(10),
  @ARTICULO           VARCHAR(20),
  @CASA               VARCHAR(MAX),
  @SUBCASA            VARCHAR(MAX),
  @CIA                VARCHAR(20)
)
AS 
BEGIN
  DECLARE @SQL   NVARCHAR(MAX),
          @PARAM NVARCHAR(MAX);

  DECLARE @TABLE TABLE(
      CLIENTE           VARCHAR(20),
      NOMBRE            VARCHAR(4000),
      CATEGORIA         VARCHAR(10),
      COD_ARTICULO      VARCHAR(20),
      ARTICULO_NOMBRE   VARCHAR(8000),
      ID_CASA           VARCHAR(12),
      CASA              VARCHAR(4000),
      ID_SUBCASA        VARCHAR(12),
      SUBCASA           VARCHAR(4000),
      ID_CATEGORIA_ART  VARCHAR(12),
      CATEGORIA_ART     VARCHAR(4000),
      ESCALA_DCTO       INT,
      CANT_MINIMA       INT,
      CANT_MAXIMA       INT,
      FECHA_INICIAL     VARCHAR(20),
      FECHA_FINAL       VARCHAR(20),
      PORC_DESCUENTO    INT
  );

  SET @SQL = N'
    SELECT
        @CLIENTE                                AS CLIENTE,
        CLI.NOMBRE                              AS NOMBRE,
        CLI.CATEGORIA_CLIENTE                   AS CATEGORIA,
        V.COD_ARTICULO                          AS COD_ARTICULO,
        V.ARTICULO_NOMBRE                       AS ARTICULO_NOMBRE,
        V.ID_CASA                               AS ID_CASA,
        V.DESC_CASA                             AS CASA,
        V.ID_SUBCASA                            AS ID_SUBCASA,
        V.DESC_SUBCASA                          AS SUBCASA,
        V.ID_CATEGORIA_ART                      AS ID_CATEGORIA_ART,
        V.DESC_CATEGORIA_ART                    AS CATEGORIA_ART,
        
        -- de CBN ya sólo vendrá 1 fila: la válida (FECHA_INICIAL <= hoy y la más reciente)
        ISNULL(CBN.ESCALA_DCTO,0)               AS ESCALA_DCTO,
        ISNULL(CBN.CANTIDAD_INICIAL,0)          AS CANT_MINIMA,
        ISNULL(CBN.CANTIDAD_FINAL,0)            AS CANT_MAXIMA,
        ISNULL(CBN.FECHA_INICIAL,'''')          AS FECHA_INICIAL,
        ISNULL(CBN.FECHA_FINAL,'''')            AS FECHA_FINAL,
        ISNULL(CBN.PORC_DESCUENTO,0)            AS PORC_DESCUENTO

    FROM ['+@CIA+'].[VIEW_OBT_LISTA_DCTO_ART_X_CLIENTE_V2] AS V

    JOIN ExactusERP.['+@CIA+'].CLIENTE AS CLI
      ON CLI.CLIENTE = @CLIENTE
     AND CLI.ACTIVO  = ''S''

    OUTER APPLY
    (
      SELECT TOP 1
        ESCALA_DCTO,
        CANTIDAD_INICIAL,
        CANTIDAD_FINAL,
        CONVERT(VARCHAR(23), FECHA_INICIAL, 23) AS FECHA_INICIAL,
        CONVERT(VARCHAR(23), FECHA_FINAL,   23) AS FECHA_FINAL,
        PORC_DESCUENTO
      FROM ExactusERP.['+@CIA+'].DCTO_ART_X_CLI
      WHERE ARTICULO       = V.COD_ARTICULO
        AND CLIENTE        = @CLIENTE
        AND FECHA_INICIAL <= GETDATE()
      ORDER BY FECHA_INICIAL DESC
    ) AS CBN

    WHERE (@ARTICULO           = ''0'' OR V.COD_ARTICULO        = @ARTICULO)
      AND (@CATEGORIA_CLIENTE = ''0'' OR CLI.CATEGORIA_CLIENTE = @CATEGORIA_CLIENTE)
      AND (@CASA               = ''0'' OR V.ID_CASA              IN (SELECT VAL FROM ['+@CIA+'].TF_SPLIT(@CASA, '','')))
      AND (@SUBCASA            = ''0'' OR V.ID_SUBCASA           IN (SELECT VAL FROM ['+@CIA+'].TF_SPLIT(@SUBCASA,'','')))
  ';

  SET @PARAM = N'
    @CLIENTE           VARCHAR(20),
    @CATEGORIA_CLIENTE VARCHAR(10),
    @ARTICULO          VARCHAR(20),
    @CASA              VARCHAR(MAX),
    @SUBCASA           VARCHAR(MAX)
  ';

  INSERT INTO @TABLE
  EXEC sp_executesql @SQL, @PARAM,
       @CLIENTE           = @CLIENTE,
       @CATEGORIA_CLIENTE = @CATEGORIA_CLIENTE,
       @ARTICULO          = @ARTICULO,
       @CASA              = @CASA,
       @SUBCASA           = @SUBCASA;

  SELECT * 
  FROM @TABLE
  OPTION (RECOMPILE);
END;
GO
/****** Object:  StoredProcedure [DIS86].[PROC_OBT_DOCUMENTO_CLIENTE]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE PROC  [DIS86].[PROC_OBT_DOCUMENTO_CLIENTE]
(
@FECHAINI VARCHAR(20),
@FECHAFIN VARCHAR(20),
@SALDO VARCHAR(100),
@TIPO_DOC VARCHAR(100),
@VENDEDOR VARCHAR(4),
@CLIENTE VARCHAR(20)

)
AS
BEGIN 
DECLARE @SQL NVARCHAR(MAX),@PARAM NVARCHAR(MAX)
DECLARE @TABLE AS TABLE(ID INT,CLIENTE VARCHAR(20),CLIENTE_NOMBRE VARCHAR(150), DOCUMENTO VARCHAR(50),TIPO VARCHAR(3),SUBTIPO VARCHAR(25),COD_SUBTIPO_DEBITO INT ,FECHA_DOCUMENTO VARCHAR(100),FECHA_VENCE VARCHAR(100), 
						DIAS_NETO INT,MONTO DECIMAL(28,8),SALDO DECIMAL(28,8),MONTO_PAGO DECIMAL(28,8))

						
SET @SALDO		= CASE  WHEN @SALDO = '1' THEN	'AND (DOC.SALDO_DEBITO >=1)' -- SIN SALDO O EN NEGATIVO
                        WHEN @SALDO = '2' THEN  'AND (DOC.SALDO_DEBITO <=0)' -- SALDO MAYOR A CERO 
  						WHEN @SALDO = '0' THEN	' '		                     -- MUESTRA TODOS			                         
						END 


SET @SQL ='SELECT distinct 
				  ROW_NUMBER() OVER (Order by cliente) AS ID,
				  cliente,
				  cliente_nombre,
				  documento_debito,
				  TIPO_DEBITO AS TIPO,
				  SUBTIPO_debito AS SUBTIPO,
				  COD_SUBTIPO_DEBITO,
				  FECHA_DOCUMENTO_DEBITO AS FECHA_DOCUMENTO,
				  FECHA_VENCE_DEBITO AS FECHA_VENCE, 
				  DIAS_NETO, 
				  MONTO_DEBITO AS MONTO,
				  SALDO_DEBITO AS SALDO,
				  MONTO_PAGO
				  
			FROM 
				  [DIS86].[Reporte_Cuadre_Auxiliar] DOC WITH(NOLOCK)

			WHERE DATEDIFF(DD,DOC.FECHA_DOCUMENTO_DEBITO,@FECHAFIN)>=0 AND DATEDIFF(DD,DOC.FECHA_DOCUMENTO_DEBITO,@FECHAINI)<=0
			AND (DOC.TIPO_DEBITO IN(SELECT VAL FROM [DIS86].[TF_SPLIT](@TIPO_DOC,'','')) OR ''0'' IN(SELECT VAL FROM [DIS86].[TF_SPLIT](@TIPO_DOC,'','')))
			AND   (DOC.COD_VENDEDOR_CLI = @VENDEDOR OR  @VENDEDOR = ''0'')
			AND   (DOC.cliente = @CLIENTE OR  @CLIENTE = ''0'')'
			+ @SALDO +
		    'ORDER BY FECHA_DOCUMENTO_DEBITO DESC'
		   
			
	  

SET @PARAM = '@FECHAINI VARCHAR(20),@FECHAFIN VARCHAR(20),@SALDO VARCHAR(20),@TIPO_DOC VARCHAR(10),@VENDEDOR VARCHAR(4),@CLIENTE VARCHAR(20)'

INSERT INTO @TABLE EXEC SP_EXECUTESQL @SQL,@PARAM,@FECHAINI,@FECHAFIN,@SALDO,@TIPO_DOC,@VENDEDOR,@CLIENTE

SELECT * FROM @TABLE
END


GO
/****** Object:  StoredProcedure [DIS86].[PROC_OBT_EMAIL_CLIENTE_POR_COBRADOR]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE PROC [DIS86].[PROC_OBT_EMAIL_CLIENTE_POR_COBRADOR]
(
      @COBRADOR VARCHAR(20),   
      @CIA      VARCHAR(20)    
)
AS
BEGIN
    SET NOCOUNT ON;

    IF ISNULL(@COBRADOR,'') = ''
    BEGIN
        SELECT '' AS CLIENTE, '' AS COBRADOR, '' AS E_MAIL;
        RETURN;
    END

                                    
    DECLARE @SQL NVARCHAR(MAX);

    SET @SQL = N'
        SELECT
               CLI.CLIENTE                        AS CLIENTE,
               CLI.COBRADOR                       AS COBRADOR,
               ISNULL(CLI.E_MAIL, '''')           AS E_MAIL
        FROM   EXACTUSERP.[' + ISNULL(@CIA, '') + N'].CLIENTE CLI WITH (NOLOCK)
        WHERE  CLI.COBRADOR = @COBRADOR';

    EXEC sp_executesql
         @SQL,
         N'@COBRADOR VARCHAR(20)',
         @COBRADOR = @COBRADOR;
END
GO
/****** Object:  StoredProcedure [DIS86].[PROC_OBT_EMAIL_COBRADOR]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROC [DIS86].[PROC_OBT_EMAIL_COBRADOR]
(
      @COBRADOR VARCHAR(20),  
      @CIA      VARCHAR(20) 
)
AS
BEGIN
    SET NOCOUNT ON;

 
    IF ISNULL(@COBRADOR,'') = ''
    BEGIN
        SELECT '' AS COBRADOR, '' AS E_MAIL;
        RETURN;
    END

    DECLARE @SQL NVARCHAR(MAX);

    SET @SQL = N'
        SELECT TOP 1
               COB.COBRADOR        AS COBRADOR,
               ISNULL(COB.E_MAIL,'''') AS E_MAIL
        FROM   EXACTUSERP.[' + ISNULL(@CIA, '') + N'].COBRADOR  COB WITH (NOLOCK)
        WHERE  COB.COBRADOR = @COBRADOR';

    EXEC sp_executesql
         @SQL,
         N'@COBRADOR VARCHAR(20)',
         @COBRADOR = @COBRADOR;
END
GO
