CREATE PROC  [DIS86].[PROC_OBT_ID_VISITA]
AS
BEGIN 
DECLARE @ProximoID INT, @CONTADOR INT 
SET @CONTADOR  = (SELECT COUNT(ID_VISITA) FROM [PS_TRACKING].[DIS86].[VISITAS])

IF @CONTADOR = 0 
	BEGIN 
	SET @ProximoID = IDENT_CURRENT('[PS_TRACKING].[DIS86].[VISITAS]')
	END 
ELSE 
	BEGIN 
	SET @ProximoID = IDENT_CURRENT('[PS_TRACKING].[DIS86].[VISITAS]') + 1
	END 

SELECT  @ProximoID 

END 



