/****** Object:  StoredProcedure [DIS86].[PROC_OBT_INFORMACION_ARTICULO]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

 --- EXEC [DIS86].[PROC_OBT_INFORMACION_ARTICULO]  '24001','2763',2,'DIS86'


 --EXEC [DIS86].[PROC_OBT_INFORMACION_ARTICULO] ''
CREATE PROC  [DIS86].[PROC_OBT_INFORMACION_ARTICULO] 
(
@ARTICULO VARCHAR(20),
@CLIENTE VARCHAR(50),
--@CANTIDAD_MIN INT,
@CIA VARCHAR(20)
)

AS 
BEGIN 

DECLARE @NIVEL_PRECIO VARCHAR(20)
DECLARE @PRECIO DECIMAL(28,8)

SELECT @PRECIO = AP.PRECIO
       
FROM  EXACTUSERP.DIS86.CLIENTE AS CLI
JOIN  EXACTUSERP.DIS86.ARTICULO_PRECIO AS AP ON CLI.NIVEL_PRECIO = AP.NIVEL_PRECIO   
LEFT JOIN EXACTUSERP.DIS86.VERSION_NIVEL     AS  VN        ON  AP.NIVEL_PRECIO =  VN.NIVEL_PRECIO        AND 
                                                             AP.MONEDA = VN.MONEDA        AND 
															 AP.VERSION = VN.VERSION        AND 
															 VN.ESTADO   ='A'
WHERE CLIENTE = @CLIENTE


SELECT	  
		  ISNULL(BOD.CANT_DISPONIBLE,0) AS CANT_DISPONIBLE,
		  ISNULL(@PRECIO,0) PRECIO,
		  0 PORC_DCTO
FROM 
	      EXACTUSERP.DIS86.ARTICULO          AS  ART
LEFT JOIN EXACTUSERP.DIS86.EXISTENCIA_BODEGA AS  BOD       ON  ART.ARTICULO    =  BOD.ARTICULO		   AND BODEGA = '01'
--LEFT JOIN EXACTUSERP.DIS86.ARTICULO_PRECIO   AS  AP        ON  ART.ARTICULO    =  AP.ARTICULO           -- AND NIVEL_PRECIO ='DETALLE'

--LEFT JOIN EXACTUSERP.DIS86.ESCALA_DCTO       AS  DCTO_ECA  ON  AP.NIVEL_PRECIO =  DCTO_ECA.NIVEL_PRECIO  AND AP.MONEDA = DCTO_ECA.MONEDA  AND AP.VERSION = DCTO_ECA.VERSION  AND AP.ARTICULO = DCTO_ECA.ARTICULO
--LEFT JOIN EXACTUSERP.DIS86.VERSION_NIVEL     AS  VN        ON  AP.NIVEL_PRECIO =  VN.NIVEL_PRECIO        AND AP.MONEDA = VN.MONEDA        AND AP.VERSION = VN.VERSION        AND VN.ESTADO   ='A'
WHERE ART.ARTICULO = @ARTICULO



--SELECT CANT_DISPONIBLE,
--       PRECIO,
--	   0 PORC_DCTO
  
--FROM  [DIS86].[VIEW_OBT_LISTA_ARTICULOS_DCTO_ART_CLIENTE] 
 
--WHERE ARTICULO     = @ARTICULO  
--AND   NIVEL_PRECIO = @NIVEL_PRECIO 
END 




GO
/****** Object:  StoredProcedure [DIS86].[PROC_OBT_INFORMACION_ARTICULO_DCTO]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC  [DIS86].[PROC_OBT_INFORMACION_ARTICULO_DCTO] 
(
@ARTICULO VARCHAR(20),
@CLIENTE VARCHAR(50),
@CANTIDAD_MIN INT,
@CIA VARCHAR(20)
)

AS 
BEGIN 

DECLARE @NIVEL_PRECIO VARCHAR(20)

SELECT 
      @NIVEL_PRECIO = NIVEL_PRECIO
FROM  EXACTUSERP.DIS86.CLIENTE 
WHERE CLIENTE = @CLIENTE

SELECT CANT_DISPONIBLE,
       PRECIO,
	   CASE  WHEN [DIS86].[FUN_OBT_DESCUENTO_ART_CLIE_EXISTE](@CLIENTE,@ARTICULO) = 1 
	         THEN ISNULL(DIS86.FUN_OBT_DESCUENTO_ART_CLIE(@CLIENTE,@ARTICULO,@CANTIDAD_MIN),0)
	   ELSE  ISNULL(PORC_DCTO,0) END PORC_DCTO

FROM  [DIS86].[VIEW_OBT_LISTA_ARTICULOS_DCTO_ART_CLIENTE] 
 
WHERE ARTICULO     = @ARTICULO  
AND   NIVEL_PRECIO = @NIVEL_PRECIO 
END 


GO
