/****** Object:  StoredProcedure [DIS86].[PROC_OBT_NIVEL_ARTICULO_DESCUENTO_INDEX]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROC [DIS86].[PROC_OBT_NIVEL_ARTICULO_DESCUENTO_INDEX]
(
     @ARTICULO      VARCHAR(20), 
     @NIVEL_PRECIO  VARCHAR(12),   
     @CASA          VARCHAR(MAX),  
     @SUBCASA       VARCHAR(MAX),  
     @CIA           VARCHAR(20)   
)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @TABLE TABLE
    (
          NIVEL_PRECIO        VARCHAR(12)
        , COD_ARTICULO        VARCHAR(20)
        , ARTICULO            VARCHAR(8000)
        , ID_CASA             VARCHAR(12)
        , CASA                VARCHAR(4000)
        , ID_SUBCASA          VARCHAR(12)
        , SUBCASA             VARCHAR(4000)
        , ID_CATEGORIA_ART    VARCHAR(12)
        , CATEGORIA_ART       VARCHAR(4000)
        , PRECIO              DECIMAL(28,8)
        , PORC_DESCUENTO      DECIMAL(28,2)
        , PRECIO_FINAL        DECIMAL(28,8)
        , ESCALA_DCTO         INT
        , CANT_MINIMA         INT
        , CANT_MAXIMA         INT
        , FECHA_INICIAL       VARCHAR(20)
        , FECHA_FINAL         VARCHAR(20)
    );

    DECLARE @SQL NVARCHAR(MAX) = N'
    SELECT 
          NIVEL_PRECIO
        , COD_ARTICULO
        , ARTICULO
        , ID_CASA
        , CASA
        , ID_SUBCASA
        , SUBCASA
        , ID_CATEGORIA_ART
        , CATEGORIA_ART
        , PRECIO
        , PORC_DESCUENTO
        , PRECIO_FINAL
        , ESCALA_DCTO
        , CANT_MINIMA
        , CANT_MAXIMA
        , FECHA_INICIAL
        , FECHA_FINAL
    FROM  [PS_TRACKING].' + QUOTENAME(@CIA) + N'.[VIEW_OBT_LISTA_DESCUENTO_ARTICULOS_INDEX] WITH (NOLOCK)
    WHERE (@ARTICULO = ''0'' OR COD_ARTICULO = @ARTICULO)
      AND  NIVEL_PRECIO = @NIVEL_PRECIO
      AND ( ID_CASA IN (SELECT VAL FROM ' + QUOTENAME(@CIA) + N'.TF_SPLIT(@CASA,'',''))
             OR ''0'' IN (SELECT VAL FROM ' + QUOTENAME(@CIA) + N'.TF_SPLIT(@CASA,'','')) )
      AND ( ID_SUBCASA IN (SELECT VAL FROM ' + QUOTENAME(@CIA) + N'.TF_SPLIT(@SUBCASA,'',''))
             OR ''0'' IN (SELECT VAL FROM ' + QUOTENAME(@CIA) + N'.TF_SPLIT(@SUBCASA,'','')) );';

    DECLARE @PARAM NVARCHAR(MAX) = N'
        @ARTICULO     VARCHAR(20),
        @NIVEL_PRECIO VARCHAR(12),
        @CASA         VARCHAR(MAX),
        @SUBCASA      VARCHAR(MAX)';

    INSERT INTO @TABLE
    EXEC sp_executesql
         @SQL,
         @PARAM,
         @ARTICULO     = @ARTICULO,
         @NIVEL_PRECIO = @NIVEL_PRECIO,
         @CASA         = @CASA,
         @SUBCASA      = @SUBCASA;

 

SELECT * FROM @TABLE NOLOCK
 ORDER  BY
           CASE
                WHEN (ISNULL(FECHA_INICIAL,'') = '' OR ISNULL(FECHA_FINAL,'') = '')
                     THEN 1 ELSE 0
           END,
           COD_ARTICULO; 

END 
GO
/****** Object:  StoredProcedure [DIS86].[PROC_OBT_NIVEL_ARTICULO_DESCUENTO_INDEX_V2]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*********************************************************************
 *  PROC_OBT_NIVEL_ARTICULO_DESCUENTO_INDEX_V2
 *********************************************************************/
CREATE   PROC [DIS86].[PROC_OBT_NIVEL_ARTICULO_DESCUENTO_INDEX_V2]
(
     @ARTICULO      VARCHAR(20)  = '0',
     @NIVEL_PRECIO  VARCHAR(12),
     @CASA          VARCHAR(MAX) = '0',
     @SUBCASA       VARCHAR(MAX) = '0',
     @CIA           VARCHAR(20)
)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @SQL NVARCHAR(MAX) = N'
    SELECT  NIVEL_PRECIO ,
            COD_ARTICULO ,
            ARTICULO ,
            ID_CASA ,
            CASA ,
            ID_SUBCASA ,
            SUBCASA ,
            ID_CATEGORIA_ART ,
            CATEGORIA_ART ,
            PRECIO ,
            PORC_DESCUENTO ,
            PRECIO_FINAL ,
            ESCALA_DCTO ,
            CANT_MINIMA ,
            CANT_MAXIMA ,
            FECHA_INICIAL ,
            FECHA_FINAL
    FROM  ' + QUOTENAME(@CIA) + N'.VIEW_OBT_LISTA_DESCUENTO_ARTICULOS_INDEX  WITH (NOLOCK)
    WHERE NIVEL_PRECIO = @nivel
      AND (@articulo = ''0'' OR COD_ARTICULO = @articulo)
      AND (@casa     = ''0'' OR ID_CASA     IN (SELECT value FROM STRING_SPLIT(@casa,'','')))
      AND (@subcasa  = ''0'' OR ID_SUBCASA  IN (SELECT value FROM STRING_SPLIT(@subcasa,'','')))
    ORDER BY 
         CASE WHEN (FECHA_INICIAL IS NULL OR FECHA_FINAL IS NULL OR
                    FECHA_INICIAL = '''' OR FECHA_FINAL = '''') THEN 1 ELSE 0 END,
         COD_ARTICULO;
    ';

    EXEC sys.sp_executesql
        @SQL,
        N'@articulo varchar(20), @nivel varchar(12), @casa varchar(max), @subcasa varchar(max)',
        @articulo = @ARTICULO,
        @nivel    = @NIVEL_PRECIO,
        @casa     = @CASA,
        @subcasa  = @SUBCASA;
END
GO
