CREATE  PROC [DIS86].[PROC_OBT_PEDIDO_PTC]
(
@FECHAINI varchar(15),
@FECHAFIN varchar(15),
@PEDIDO VARCHAR(30),
@ESTADO_PEDIDO INT,
@ESTADO_FACTURA INT,
@VENDEDOR VARCHAR(10),
@CLIENTE VARCHAR(20)
)
AS 
BEGIN

DECLARE @SQL NVARCHAR(MAX),@PARAM NVARCHAR(MAX), @CONTADOR VARCHAR(100) 

DECLARE @TABLE AS TABLE(ID INT, PEDIDO VARCHAR(50), ESTADO_PEDIDO INT, ESTADO_PEDIDO_DESCRIPCION VARCHAR(200), AUTORIZADO VARCHAR(50), FECHA_PEDIDO VARCHAR(30), 
                        FACTURA VARCHAR(100),CLIENTE VARCHAR(173), COD_CLIENTE VARCHAR(20), CLIENTE_NOMBRE VARCHAR(150),SEGUIR_FAC INT, SEGUIR_FAC_DESCRIPCION VARCHAR(200),
						DIAS VARCHAR(20), SUBTOTAL DECIMAL(28,8), TOTAL DECIMAL(28,8), CreateDate DATETIME, COLOR_HEXA_PED VARCHAR(100), COLOR_HEXA_FAC VARCHAR(100))




SET @SQL ='SELECT
        ID
	   ,PEDIDO
	   ,ESTADO_PEDIDO 
	   ,ESTADO_PEDIDO_DESCRIPCION
	   ,AUTORIZADO
	   ,FECHA_PEDIDO
	   ,FACTURA 
	   ,CLIENTE 
	   ,COD_CLIENTE
	   ,CLIENTE_NOMBRE 
	   ,SEGUIR_FAC
	   ,SEGUIR_FAC_DESCRIPCION
	   ,DIAS
	   ,SUBTOTAL
	   ,TOTAL
	   ,CreateDate
	   ,COLOR_HEXA_PED
	   ,COLOR_HEXA_FAC
		
FROM  [DIS86].[VIEW_OBT_PEDIDO_PTC] PD
WHERE DATEDIFF(DD,PD.FECHA_PEDIDO,@FECHAFIN)>=0 AND DATEDIFF(DD,PD.FECHA_PEDIDO,@FECHAINI)<=0
AND (PD.PEDIDO= @PEDIDO OR  @PEDIDO = ''0'')
AND (PD.ESTADO_PEDIDO= @ESTADO_PEDIDO OR  @ESTADO_PEDIDO = ''0'') --filtra el estado pedido o cero si son todos.
AND (PD.SEGUIR_FAC = @ESTADO_FACTURA OR  @ESTADO_FACTURA = ''0'')
AND (PD.COD_VENDEDOR= @VENDEDOR OR  @VENDEDOR = ''0'')
AND (PD.COD_CLIENTE= @CLIENTE OR  @CLIENTE = ''0'')'


SET @PARAM = '@FECHAINI varchar(15),@FECHAFIN varchar(15),@PEDIDO VARCHAR(30),@ESTADO_PEDIDO INT,@ESTADO_FACTURA INT,@VENDEDOR VARCHAR(10),@CLIENTE VARCHAR(20)'

INSERT INTO @TABLE EXEC SP_EXECUTESQL @SQL,@PARAM,@FECHAINI,@FECHAFIN,@PEDIDO,@ESTADO_PEDIDO,@ESTADO_FACTURA,@VENDEDOR,@CLIENTE

SELECT 
        ID
	   ,PEDIDO
	   ,ESTADO_PEDIDO 
	   ,ESTADO_PEDIDO_DESCRIPCION
	   ,AUTORIZADO
	   ,FECHA_PEDIDO
	   ,FACTURA 
	   ,CLIENTE 
	   ,COD_CLIENTE
	   ,CLIENTE_NOMBRE 
	   ,SEGUIR_FAC
	   ,SEGUIR_FAC_DESCRIPCION
	   ,DIAS
	   ,SUBTOTAL
	   ,TOTAL
	   ,CreateDate
	   ,COLOR_HEXA_PED
	   ,COLOR_HEXA_FAC
FROM @TABLE NOLOCK
ORDER BY CreateDate DESC

END 


GO
