--        DATEADD(DAY, (NUMBER * 7) + (6 - (DATEPART(WEEKDAY, DATEFROMPARTS(AÑO, MES, 1)) - 1)), DATEFROMPARTS(AÑO, MES, 1)) AS ENDDATE,
--        (NUMBER % 5) + 1 AS MONTHWEEKNUMBER
