--- [DIS86].[PROC_OBT_SUBTABLA_DOCUMENTOS_POR_CLIENTE] 'CL01100'

CREATE PROC  [DIS86].[PROC_OBT_SUBTABLA_DOCUMENTOS_POR_CLIENTE]
(
@CLIENTE VARCHAR(50)
)
AS
BEGIN 
DECLARE @SQL NVARCHAR(MAX),@PARAM NVARCHAR(MAX)
DECLARE @TABLE AS TABLE(DOCUMENTO VARCHAR(50),
                        TIPO VARCHAR(3),
						SUBTIPO VARCHAR(25),
						FECHA_DOCUMENTO VARCHAR(100),
						FECHA_VENCE VARCHAR(100), 
						DIAS_NETO INT,
						MONTO DECIMAL(28,8),
						SALDO DECIMAL(28,8),
						MONTO_PAGO DECIMAL(28,8),
						NOMBRE_VENDEDOR VARCHAR(100),
						REFERENCIA_DEBITO VARCHAR(4000),
						USUARIO_CREACION VARCHAR(100),
						FECHA_CREACION_DEBITO VARCHAR(100)
						)


SET @SQL ='SELECT DISTINCT
				  documento_debito,
				  TIPO_DEBITO AS TIPO,
				  SUBTIPO_debito AS SUBTIPO,
				  FECHA_DOCUMENTO_DEBITO AS FECHA_DOCUMENTO,
				  FECHA_VENCE_DEBITO AS FECHA_VENCE, 
				  DIAS_NETO, 
				  MONTO_DEBITO AS MONTO,
				  SALDO_DEBITO AS SALDO,
				  MONTO_PAGO,
				  VENDEDOR_CLIENTE AS NOMBRE_VENDEDOR,
				  REFERENCIA_DEBITO,
				  USUARIO_CREACION_DEBITO,
				  FECHA_CREACION_DEBITO
				  
			FROM 
				  [DIS86].[Reporte_Cuadre_Auxiliar] DOC WITH(NOLOCK)
			WHERE 
				  CLIENTE= @CLIENTE
				  AND  SALDO_DEBITO > 1
				  ORDER BY FECHA_DOCUMENTO_DEBITO DESC '
				  

SET @PARAM = '@CLIENTE VARCHAR(50)'

INSERT INTO @TABLE EXEC SP_EXECUTESQL @SQL,@PARAM,@CLIENTE

SELECT * FROM @TABLE
END


