/****** Object:  StoredProcedure [DIS86].[PROC_OBT_TABLA_DOCUMENTOS_POR_CLIENTE]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


--- [DIS86].[PROC_OBT_SUBTABLA_DOCUMENTOS_POR_CLIENTE] 'CL01100'

CREATE PROC [DIS86].[PROC_OBT_TABLA_DOCUMENTOS_POR_CLIENTE]
(
    @CIA VARCHAR(50),
    @CLIENTE VARCHAR(50),
    @FECHA_INICIO VARCHAR(50) = NULL,
    @FECHA_FIN VARCHAR(50) = NULL,
    @TIPO_DOCUMENTO VARCHAR(500) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;

    IF @CIA IS NULL OR LTRIM(RTRIM(@CIA)) = ''
    BEGIN
        SELECT -1 AS code; RETURN;
    END

    IF @CLIENTE IS NULL OR LTRIM(RTRIM(@CLIENTE)) = ''
    BEGIN
        SELECT -2 AS code; RETURN;
    END

    DECLARE @SQL NVARCHAR(MAX);
    DECLARE @PARAM NVARCHAR(MAX);

    DECLARE @TABLE AS TABLE(
        DOCUMENTO VARCHAR(50),
        TIPO VARCHAR(3),
        SUBTIPO VARCHAR(25),
        FECHA_DOCUMENTO VARCHAR(100),
        FECHA_VENCE VARCHAR(100),
        DIAS_NETO INT,
        MONTO DECIMAL(28,8),
        SALDO DECIMAL(28,8),
        MONTO_PAGO DECIMAL(28,8),
        NOMBRE_VENDEDOR VARCHAR(100),
        REFERENCIA_DEBITO VARCHAR(4000),
        USUARIO_CREACION VARCHAR(100),
        FECHA_CREACION_DEBITO VARCHAR(100)
    );

    SET @SQL = '
    SELECT DISTINCT
        documento_debito AS DOCUMENTO,
        TIPO_DEBITO AS TIPO,
        SUBTIPO_debito AS SUBTIPO,
        FECHA_DOCUMENTO_DEBITO AS FECHA_DOCUMENTO,
        FECHA_VENCE_DEBITO AS FECHA_VENCE, 
        DIAS_NETO, 
        MONTO_DEBITO AS MONTO,
        SALDO_DEBITO AS SALDO,
        MONTO_PAGO,
        VENDEDOR_CLIENTE AS NOMBRE_VENDEDOR,
        REFERENCIA_DEBITO,
        USUARIO_CREACION_DEBITO,
        FECHA_CREACION_DEBITO
    FROM [' + @CIA + '].[Reporte_Cuadre_Auxiliar] DOC WITH(NOLOCK)
    WHERE CLIENTE = @CLIENTE
        --AND SALDO_DEBITO > 1
        AND (@TIPO_DOCUMENTO IS NULL OR @TIPO_DOCUMENTO = ''0'' OR TIPO_DEBITO IN (SELECT value FROM STRING_SPLIT(@TIPO_DOCUMENTO, '','')))
        AND (@FECHA_INICIO IS NULL OR FECHA_DOCUMENTO_DEBITO >= @FECHA_INICIO)
        AND (@FECHA_FIN IS NULL OR FECHA_DOCUMENTO_DEBITO <= @FECHA_FIN)
    ORDER BY FECHA_DOCUMENTO_DEBITO DESC
    ';

    SET @PARAM = '@CLIENTE VARCHAR(50), @TIPO_DOCUMENTO VARCHAR(500), @FECHA_INICIO VARCHAR(50), @FECHA_FIN VARCHAR(50)';

    INSERT INTO @TABLE
    EXEC sp_executesql @SQL, @PARAM, @CLIENTE, @TIPO_DOCUMENTO, @FECHA_INICIO, @FECHA_FIN;

    SELECT * FROM @TABLE;
END
GO
