-- EXEC [DIS86].[PROC_OBT_UBICACION_CLIENTE] 'V001'

CREATE  PROC [DIS86].[PROC_OBT_UBICACION_CLIENTE]
(
@VENDEDOR VARCHAR(4),
@FECHA_VISITA VARCHAR(20)
)
AS 
BEGIN

DECLARE @SQL NVARCHAR(MAX),@PARAM NVARCHAR(MAX), @CONTADOR VARCHAR(100) 

DECLARE @TABLE AS TABLE(COD_CLIENTE VARCHAR(20),NOM_CLIENTE VARCHAR(200),TOTAL_A_FACTURAR DECIMAL(28,8), LATITUD VARCHAR(50), LONGITUD VARCHAR(50), HORA VARCHAR(10))


SET @SQL ='SELECT
             COD_CLIENTE
			,NOM_CLIENTE
			,TOTAL_A_FACTURAR
			,LATITUD
			,LONGITUD
			,HORA
		
FROM  DIS86.VIEW_OBT_VISITAS VTA
WHERE COD_VENDEDOR = @VENDEDOR AND FECHA_VISITA = @FECHA_VISITA'

SET @PARAM = '@VENDEDOR VARCHAR(4), @FECHA_VISITA VARCHAR(20)'

INSERT INTO @TABLE EXEC SP_EXECUTESQL @SQL,@PARAM,@VENDEDOR, @FECHA_VISITA

SELECT 
     COD_CLIENTE
	,NOM_CLIENTE
	,TOTAL_A_FACTURAR
	,LATITUD
	,LONGITUD
	,HORA		 
FROM @TABLE NOLOCK

END 

