/****** Object:  StoredProcedure [DIS86].[PROC_OBT_VISITAS]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE  PROC [DIS86].[PROC_OBT_VISITAS]
(
@FECHAINI varchar(20),
@FECHAFIN varchar(20),
@SEMANA   VARCHAR(50),
@DIA_SEMANA VARCHAR(8),
@TIPO_VISITA VARCHAR(4),
@VENDEDOR VARCHAR(4),
@CLIENTE VARCHAR(20)
)
AS 
BEGIN

DECLARE @SQL NVARCHAR(MAX),@PARAM NVARCHAR(MAX), @CONTADOR VARCHAR(100) 

DECLARE @TABLE AS TABLE(COD_CLIENTE VARCHAR(20),
                        NOM_CLIENTE VARCHAR(200),
						ALIAS VARCHAR(200),
						COD_VENDEDOR VARCHAR(4),
						NOM_VENDEDOR VARCHAR(200),
						FECHA_VISITA VARCHAR(30),
                        RUTA VARCHAR(4), 
						DESCRIPCION VARCHAR(40),
						PROVINCIA VARCHAR(40), 
						ESTADO_VISITA VARCHAR(4),
						DOCUMENTO VARCHAR(50),
						TOTAL_A_FACTURAR DECIMAL(28,8),
						COMENTARIO VARCHAR(800), 
						COLOR_HEXA VARCHAR(50), 
						SEMANA VARCHAR(50), 
						DIA VARCHAR(10), 
						TIPO_VISITA VARCHAR(4), 
						LATITUD VARCHAR(50), 
						LONGITUD VARCHAR(50),
						DIRECCION VARCHAR(MAX),
					    ID_VISITA INT 
						)




SET @SQL ='SELECT
				  COD_CLIENTE
				 ,NOM_CLIENTE
				 ,ALIAS
				 ,COD_VENDEDOR
				 ,NOM_VENDEDOR
				 ,FECHA_VISITA
				 ,RUTA
				 ,DESCRIPCION
				 ,PROVINCIA
				 ,ESTADO_VISITA
				 ,DOCUMENTO
				 ,TOTAL_A_FACTURAR
				 ,COMENTARIO
				 ,COLOR_HEXA
				 ,SEMANA
				 ,DIA
				 ,TIPO_VISITA
				 ,LATITUD
				 ,LONGITUD
				 ,DIRECCION
				 ,ID_VISITA
		
          FROM  
                  DIS86.VIEW_OBT_VISITAS VTA
          WHERE 
		          DATEDIFF(DD,VTA.FECHA_VISITA,@FECHAFIN)>=0 AND DATEDIFF(DD,VTA.FECHA_VISITA,@FECHAINI)<=0
         AND (
  @SEMANA = ''0''
  OR EXISTS (
    SELECT 1
    FROM STRING_SPLIT(@SEMANA, '','') AS s
    WHERE CHARINDEX('',''+s.value+'','', '','' + REPLACE(VTA.SEMANA, '' '', '''') + '','') > 0
  )
)
AND (
  @DIA_SEMANA = ''0''
  OR EXISTS (
    SELECT 1
    FROM STRING_SPLIT(@DIA_SEMANA, '','') AS d
    WHERE CHARINDEX('',''+d.value+'','', '','' + REPLACE(VTA.DIA, '' '', '''') + '','') > 0
  )
)
  AND   (VTA.TIPO_VISITA= @TIPO_VISITA OR  @TIPO_VISITA = ''0'')
            AND   (VTA.COD_VENDEDOR= @VENDEDOR OR  @VENDEDOR = ''0'')
            AND   (VTA.COD_CLIENTE = @CLIENTE OR  @CLIENTE = ''0'')
            ORDER BY VTA.ID_VISITA DESC'

SET @PARAM = '@FECHAINI varchar(15),@FECHAFIN varchar(15),@SEMANA VARCHAR(50),@DIA_SEMANA VARCHAR(8),@TIPO_VISITA VARCHAR(4),@VENDEDOR VARCHAR(30),@CLIENTE VARCHAR(20)'

INSERT INTO @TABLE EXEC SP_EXECUTESQL @SQL,@PARAM,@FECHAINI,@FECHAFIN,@SEMANA,@DIA_SEMANA,@TIPO_VISITA,@VENDEDOR,@CLIENTE

SELECT 
     COD_CLIENTE
	,NOM_CLIENTE
	,ALIAS
	,COD_VENDEDOR
	,NOM_VENDEDOR
	,FECHA_VISITA
	,RUTA
	,DESCRIPCION
	,PROVINCIA
	,ESTADO_VISITA
	,DOCUMENTO
	,TOTAL_A_FACTURAR
	,COMENTARIO
	,COLOR_HEXA
	,SEMANA
	,DIA
	,TIPO_VISITA
	,LATITUD
	,LONGITUD
	,DIRECCION
			 
FROM @TABLE NOLOCK
ORDER BY ID_VISITA DESC
END 
GO
