/****** Object:  StoredProcedure [DIS86].[PROC_PEDIDO_TOTAL_ENTREGADOS_MES]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [DIS86].[PROC_PEDIDO_TOTAL_ENTREGADOS_MES]
AS 
BEGIN 
SELECT  
        CASE WHEN DATENAME (MONTH, DATEADD(MONTH, MONTH(PD.FECHA_HORA_RECIBIDO) - 1, '1900-01-01')) ='January' THEN 'ENE' 
             WHEN DATENAME (MONTH, DATEADD(MONTH, MONTH(PD.FECHA_HORA_RECIBIDO) - 1, '1900-01-01')) ='February' THEN 'FEB' 
			 WHEN DATENAME (MONTH, DATEADD(MONTH, MONTH(PD.FECHA_HORA_RECIBIDO) - 1, '1900-01-01')) ='March' THEN 'MAR' 
			 WHEN DATENAME (MONTH, DATEADD(MONTH, MONTH(PD.FECHA_HORA_RECIBIDO) - 1, '1900-01-01')) ='April' THEN 'ABR' 
			 WHEN DATENAME (MONTH, DATEADD(MONTH, MONTH(PD.FECHA_HORA_RECIBIDO) - 1, '1900-01-01')) ='May' THEN 'MAY'
			 WHEN DATENAME (MONTH, DATEADD(MONTH, MONTH(PD.FECHA_HORA_RECIBIDO) - 1, '1900-01-01')) ='June' THEN 'JUN'
			 WHEN DATENAME (MONTH, DATEADD(MONTH, MONTH(PD.FECHA_HORA_RECIBIDO) - 1, '1900-01-01')) ='July' THEN 'JUL'
			 WHEN DATENAME (MONTH, DATEADD(MONTH, MONTH(PD.FECHA_HORA_RECIBIDO) - 1, '1900-01-01')) ='August' THEN 'AGO'
			 WHEN DATENAME (MONTH, DATEADD(MONTH, MONTH(PD.FECHA_HORA_RECIBIDO) - 1, '1900-01-01')) ='September' THEN 'SET'
			 WHEN DATENAME (MONTH, DATEADD(MONTH, MONTH(PD.FECHA_HORA_RECIBIDO) - 1, '1900-01-01')) ='October' THEN 'OCT'
			 WHEN DATENAME (MONTH, DATEADD(MONTH, MONTH(PD.FECHA_HORA_RECIBIDO) - 1, '1900-01-01')) ='November' THEN 'NOV'
			 WHEN DATENAME (MONTH, DATEADD(MONTH, MONTH(PD.FECHA_HORA_RECIBIDO) - 1, '1900-01-01')) ='December' THEN 'DIC'
			 END  Mes, 
			 COUNT(PD.PEDIDO) TOTAL_PEDIDOS,
			 COUNT(P.PEDIDO) ENTREGADOS
FROM DIS86.VIEW_TRACKING PD WITH(NOLOCK)  
LEFT JOIN DIS86.VIEW_TRACKING P WITH(NOLOCK) ON PD.PEDIDO = P.PEDIDO AND P.ESTADO_PEDIDO = 3
WHERE YEAR(PD.FECHA_HORA_RECIBIDO) = YEAR(DATEADD(MONTH,-6,GETDATE()))
AND  (CASE WHEN MONTH(PD.FECHA_HORA_RECIBIDO) BETWEEN 1 AND 6 THEN 1 ELSE 2 END) = ( CASE WHEN MONTH(DATEADD(MONTH,-6,GETDATE())) BETWEEN 1 AND 6 THEN 1 ELSE 2 END)  
GROUP BY MONTH(PD.FECHA_HORA_RECIBIDO)
END 
GO
