---EXEC [DIS86].[PROC_REPORTE_CUADRE_AUXILIAR] '2284','2023-01-01','2023-05-01'

CREATE PROC [DIS86].[PROC_REPORTE_CUADRE_AUXILIAR]
(
@CLIENTE VARCHAR(MAX),
@FECHA_DOC_INI VARCHAR(50),
@FECHA_DOC_FIN VARCHAR(50) 
)
AS
BEGIN
DECLARE @SQL NVARCHAR(MAX),@PARAM NVARCHAR(MAX)
DECLARE @TABLE AS TABLE( cliente varchar(20),cliente_nombre varchar(150), documento_credito varchar(50),referencia_credito varchar(249),fecha_documento_credito varchar(20), tipo_credito varchar(3),monto_credito decimal(28,8),saldo_credito decimal(28,8),
						 documento_debito varchar(50),referencia_debito varchar(50) ,fecha_documento_debito varchar(20), tipo_debito varchar(3), monto_debito decimal(28,8), saldo_debito decimal(28,8), fecha_aplicacion varchar(20), 
						 monto_aplicado decimal(28,8), usuario_creacion varchar(30))


SET @SQL ='SELECT  	
                cliente,
				cliente_nombre,
				documento_credito,
				REFERENCIA_CREDITO,
				fecha_documento_credito,
				tipo_credito,
				monto_credito,
				saldo_credito,
				documento_debito,
				REFERENCIA_DEBITO,
				fecha_documento_debito,
				tipo_debito,
				monto_debito,
				saldo_debito,
				fecha_aplicacion,
				monto_aplicado,
				usuario_creacion
FROM [DIS86].[Reporte_Cuadre_Auxiliar] aux
WHERE 
aux.cliente =  @CLIENTE
and aux.fecha_aplicacion > = @FECHA_DOC_INI and aux.fecha_aplicacion<= @FECHA_DOC_FIN
order by  documento_debito, documento_credito'

SET @PARAM = '@CLIENTE VARCHAR(20),@FECHA_DOC_INI VARCHAR(50),@FECHA_DOC_FIN VARCHAR(50)'

INSERT INTO @TABLE EXEC SP_EXECUTESQL @SQL,@PARAM,@CLIENTE,@FECHA_DOC_INI,@FECHA_DOC_FIN

SELECT 
		cliente,
		cliente_nombre,
		documento_credito,
		referencia_credito,
		fecha_documento_credito,
		tipo_credito,
		monto_credito,
		saldo_credito,
		documento_debito,
		referencia_debito,
		fecha_documento_debito,
		tipo_debito,
		monto_debito,
		saldo_debito,
		fecha_aplicacion,
		monto_aplicado,
		usuario_creacion
FROM @TABLE
ORDER BY documento_credito
---and aux.cliente ='2284'

END


