--EXEC [DIS86].[PROC_REPORTE_EXCEL_ESTADO_CUENTA_CLIENTE_EN_BATCH] '3298,CL02037,2574,529,1199,CL01958,CL01984,4383,2104,2474' 

CREATE  PROC [DIS86].[PROC_REPORTE_EXCEL_ESTADO_CUENTA_CLIENTE_EN_BATCH]
(
@CLIENTE VARCHAR(max)
)
AS 
BEGIN 

DECLARE @SQL NVARCHAR(MAX),@PARAM NVARCHAR(MAX)

DECLARE @TABLE AS TABLE(ESTADO VARCHAR(4),CLIENTE VARCHAR(20),CLI_NOMBRE VARCHAR(171),ALIAS VARCHAR(150),COD_VENDEDOR VARCHAR(4),NOMBRE_VENDEDOR VARCHAR(40),
						VEN_NOMBRE VARCHAR(47),EMAIL VARCHAR(249),TELEFONO VARCHAR(50),CONDICION_PAGO VARCHAR(4),DIAS_NETO VARCHAR(36),SALDO DECIMAL(28,8),
						FECHA_ULTIMA_VISITA VARCHAR(100),SEMANA VARCHAR(7))


SET @SQL = 'SELECT  
			     ESTADO
				,CLIENTE
				,CLI_NOMBRE
				,ALIAS
				,COD_VENDEDOR
				,NOMBRE_VENDEDOR
				,VEN_NOMBRE
				,EMAIL
				,TELEFONO
				,CONDICION_PAGO
				,DIAS_NETO
				,SALDO
				,COALESCE(FECHA_ULTIMA_VISITA, ''NULL'') AS FECHA_ULTIMA_VISITA
				,SEMANA

		FROM [DIS86].[VIEW_OBT_DATOS_CLIENTE_ESTADO_CUENTA] AS EC 
		WHERE(EC.CLIENTE IN(SELECT VAL FROM [DIS86].[TF_SPLIT](@CLIENTE,'','')) OR ''0'' IN(SELECT VAL FROM [DIS86].[TF_SPLIT](@CLIENTE,'','')))
		ORDER BY EC.CLIENTE ASC'

SET @PARAM = '@CLIENTE VARCHAR(max)'

INSERT INTO @TABLE EXEC SP_EXECUTESQL @SQL,@PARAM,@CLIENTE

SELECT       ESTADO
			,CLIENTE
			,CLI_NOMBRE
			,ALIAS
			,COD_VENDEDOR
			,NOMBRE_VENDEDOR
			,VEN_NOMBRE
			,EMAIL
			,TELEFONO
			,CONDICION_PAGO
			,DIAS_NETO
			,SALDO
			,FECHA_ULTIMA_VISITA
			,SEMANA 

FROM @TABLE


END 

GO
