CREATE  PROC [DIS86].[PROC_REPORTE_EXCEL_PEDIDO_INDEX_BATCH]
(
@PEDIDO VARCHAR(50)
)
AS 
BEGIN 

DECLARE @SQL NVARCHAR(MAX),@PARAM NVARCHAR(MAX)

DECLARE @TABLE AS TABLE( PEDIDO VARCHAR(50), CLIENTE VARCHAR(173), ESTADO_PEDIDO_DESCRIPCION VARCHAR(200), FECHA_PEDIDO VARCHAR(30),FACTURA VARCHAR(50), 
						 SEGUIR_FAC_DESCRIPCION VARCHAR(200), DIAS VARCHAR(20),AUTORIZADO VARCHAR(42), SUBTOTAL DECIMAL(28,8), TOTAL DECIMAL(28,8), CreateDate DATETIME)


SET @SQL = 'SELECT
			PEDIDO
			,CLIENTE 
			,ESTADO_PEDIDO_DESCRIPCION
			,FECHA_PEDIDO
			,FACTURA 
			,SEGUIR_FAC_DESCRIPCION
			,DIAS
			,AUTORIZADO
			,SUBTOTAL
			,TOTAL
			,CreateDate
	  
		
FROM  [DIS86].[VIEW_OBT_PEDIDO_PTC] PD WITH(NOLOCK)
		WHERE(PD.PEDIDO IN(SELECT VAL FROM [DIS86].[TF_SPLIT](@PEDIDO,'','')) OR ''0'' IN(SELECT VAL FROM [DIS86].[TF_SPLIT](@PEDIDO,'','')))
		ORDER BY PD.PEDIDO ASC'

SET @PARAM = '@PEDIDO VARCHAR(50)'

INSERT INTO @TABLE EXEC SP_EXECUTESQL @SQL,@PARAM,@PEDIDO

SELECT       
		     PEDIDO
			,CLIENTE 
			,ESTADO_PEDIDO_DESCRIPCION
			,FECHA_PEDIDO
			,FACTURA 
			,SEGUIR_FAC_DESCRIPCION
			,DIAS
			,AUTORIZADO
			,SUBTOTAL
			,TOTAL
			,CreateDate
	  
FROM @TABLE


END 



