CREATE PROC [DIS86].[PROC_REPORTE_RUTA]
(
@FECHA_PROMETIDA VARCHAR(20)
)
AS
BEGIN
SELECT 
RUTA_NOMBRE RUTA, 
CLIENTE_NOMBRE CLIENTE,
PEDIDO, 
CONDICION_PAGO,
CASE WHEN OBSERVACIONES LIKE 'Cargado de FR%' THEN SUBSTRING(OBSERVACIONES,15,800) ELSE OBSERVACIONES END OBSERVACIONES
FROM DIS86.VIEW_TRACKING
WHERE dia_ruta = @FECHA_PROMETIDA
ORDER BY RUTA,CLIENTE,PEDIDO
END
GO
/****** Object:  StoredProcedure [DIS86].[PROC_REPORTE_RUTA_PEDIDO_MULTIPLE]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROC [DIS86].[PROC_REPORTE_RUTA_PEDIDO_MULTIPLE]
(
@PEDIDO VARCHAR(MAX)
)
AS
BEGIN
SELECT 
PEDIDO,
isnull(FACTURA,'') AS FACTURA,
CASE WHEN OBSERVACIONES LIKE 'Cargado de FR%' THEN SUBSTRING(OBSERVACIONES,15,800) ELSE OBSERVACIONES END OBSERVACIONES,
ESTADO_PEDIDO_DESCRIPCION,
isnull(DIA_RUTA,'No definida') AS FECHA_PROYECTADA,
DIAS,
SEGUIR_FAC_DESCRIPCION,
CLIENTE_NOMBRE CLIENTE,
AGENTE_NOMBRE AS AGENTE,
RUTA_NOMBRE AS RUTA,
isnull(FECHA_PEDIDO,'No definida') AS FECHA_PEDIDO,
TLA_ESTADO,
isnull(FECHA_HORA_RECIBIDO,'No definida') AS FECHA_HORA_RECIBIDO,
TIEMPO
FROM DIS86.VIEW_TRACKING
WHERE(PEDIDO IN(SELECT VAL FROM [DIS86].[TF_SPLIT](@PEDIDO,',')) OR '0' IN(SELECT VAL FROM [DIS86].[TF_SPLIT](@PEDIDO,',')))
ORDER BY RUTA,CLIENTE,PEDIDO
END
GO
/****** Object:  StoredProcedure [DIS86].[PROC_REPORTE_SEGUIMIENTO_FACTURA_PEDIDO]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE  PROC [DIS86].[PROC_REPORTE_SEGUIMIENTO_FACTURA_PEDIDO]
(
@PEDIDO VARCHAR(MAX),
@ESTADO_PEDIDO INT,
@ESTADO_FACTURA INT 
)
AS
BEGIN
SELECT 
PEDIDO,
isnull(FECHA_PEDIDO,'No definida') AS FECHA_PEDIDO,
isnull(FACTURA,'') AS FACTURA,
isnull(DIA_RUTA,'No definida') AS FECHA_PROYECTADA,
ESTADO_PEDIDO_DESCRIPCION,
CASE WHEN OBSERVACIONES LIKE 'Cargado de FR%' THEN SUBSTRING(OBSERVACIONES,15,800) ELSE OBSERVACIONES END OBSERVACIONES,
isnull(FECHA_CAMBIA_ESTADO_PED,'') FECHA_CAMBIA_ESTADO_PED,
SEGUIR_FAC_DESCRIPCION,
isnull(FECHA_CAMBIA_ESTADO_FACTURA,'') FECHA_CAMBIA_ESTADO_FACTURA,
SUCESO,
CASE WHEN SUCESO <> '' THEN SEG.FECHA_CREACION END FECHA_SUCESO,
RUTA,
CLIENTE,
AGENTE,
COBRADOR,
FECHA_FACTURA,
FECHA_VENCE,
CONDICION_PAGO,
TOTAL_FACTURA,
SALDO
FROM [DIS86].[VIEW_OBTENER_SEGUIMIENTO] SEG
WHERE(PEDIDO IN(SELECT VAL FROM [DIS86].[TF_SPLIT](@PEDIDO,',')) OR '0' IN(SELECT VAL FROM [DIS86].[TF_SPLIT](@PEDIDO,',')))
AND (SEG.ESTADO_PEDIDO = @ESTADO_PEDIDO OR @ESTADO_PEDIDO='0')
AND (SEG.ESTADO_FACTURA_SEGUIMIENTO = @ESTADO_FACTURA OR @ESTADO_FACTURA='0')
ORDER BY RUTA,CLIENTE,PEDIDO
END


