CREATE PROC [DIS86].[PROC_SEGUIMIENTO]
(
@FECHAINI varchar(15),
@FECHAFIN varchar(15),
@ESTADO_PEDIDO INT,
@FECHA_PROMETIDA VARCHAR(200),
@ESTADO_FACTURA INT,
@RUTAMULTI VARCHAR(100),
@PEDIDO VARCHAR(30),
@FACTURA VARCHAR(200),
@CLIENTE VARCHAR(20),
@AGENTE VARCHAR(4),
@USUARIO VARCHAR(20),
@SUCESO VARCHAR(500),
@COBRADOR VARCHAR(50),
@FMODESTADOPED VARCHAR(200),
@FMODESTADOFAC VARCHAR(200)
)
AS 
BEGIN

DECLARE @SQL NVARCHAR(MAX),@PARAM NVARCHAR(MAX), @CONTADOR VARCHAR(100)

DECLARE @TABLE AS TABLE(SEGUIMIENTO INT,PEDIDO VARCHAR(50),FACTURA VARCHAR(200),ESTADO_PEDIDO VARCHAR(1),ESTADO_PEDIDO_DESCRIPCION VARCHAR(200),
ESTADO_FACTURA_SEGUIMIENTO VARCHAR(1),SEGUIR_FAC_DESCRIPCION VARCHAR(200),SUCESO VARCHAR(200),USUARIO VARCHAR(30),MODIFICA VARCHAR(30),
OBSERVACIONES VARCHAR(8000),FECHA_HORA_RECIBIDO VARCHAR(100),FECHA_PEDIDO VARCHAR(30),RUTA VARCHAR(100),CLIENTE VARCHAR(173),COD_CLIENTE VARCHAR(20),AGENTE VARCHAR(100)
,COD_VENDEDOR VARCHAR(20),DIA_RUTA VARCHAR(30),FECHA_FACTURA VARCHAR(200),FECHA_CAMBIA_ESTADO_PED VARCHAR(100),FECHA_CAMBIA_ESTADO_FACTURA VARCHAR(100),COBRADOR VARCHAR(500))

--FECHA PROMETIDA ES LA FECHA DE LA RUTA
SET @FECHA_PROMETIDA = CASE WHEN @FECHA_PROMETIDA = ''	THEN	'AND  (SEG.DIA_RUTA IS NULL)'				-- TODAS LAS QUE NO ESTÁN ENRUTADAS
							WHEN @FECHA_PROMETIDA = '0'	 THEN	' '											-- NO HAY QUE FILTRAR NADA
							ELSE 'AND  (SEG.DIA_RUTA = '''+@FECHA_PROMETIDA+''')'	-- Se seleccionó un día de ruta en particular
						END 
						
SET @FACTURA		= CASE  WHEN @FACTURA = '99'	THEN	'AND (SEG.FACTURA IS NOT NULL)'				-- TODAS LAS QUE TIENEN FACTURA
							WHEN @FACTURA = '0'		THEN	' '											-- NO HAY QUE FILTRAR NADA
							ELSE							'AND  (SEG.FACTURA =  '''+ @FACTURA +''')'				-- Se seleccionó una factura en particular
						END 



SET @SQL ='SELECT  
        SEGUIMIENTO,
		PEDIDO, 
		FACTURA,  
		ESTADO_PEDIDO, 
		ESTADO_PEDIDO_DESCRIPCION, 
		ESTADO_FACTURA_SEGUIMIENTO, 
		SEGUIR_FAC_DESCRIPCION, 
		SUCESO,
		USUARIO, 
		MODIFICA, 
		OBSERVACIONES,
		FECHA_HORA_RECIBIDO,
		FECHA_PEDIDO,
		RUTA,
		CLIENTE,
		COD_CLIENTE,
		AGENTE,
		COD_VENDEDOR,
		DIA_RUTA,
		FECHA_FACTURA,
		FECHA_CAMBIA_ESTADO_PED,
		FECHA_CAMBIA_ESTADO_FACTURA,
		COBRADOR
FROM  [DIS86].[VIEW_OBTENER_SEGUIMIENTO] SEG
WHERE DATEDIFF(DD,SEG.FECHA_HORA_RECIBIDO,@FECHAFIN)>=0 AND DATEDIFF(DD,SEG.FECHA_HORA_RECIBIDO,@FECHAINI)<=0  
AND (SEG.ESTADO_PEDIDO= @ESTADO_PEDIDO OR  @ESTADO_PEDIDO = ''0'')
AND (SEG.ESTADO_FACTURA_SEGUIMIENTO = @ESTADO_FACTURA OR  @ESTADO_FACTURA = ''0'')
AND (SEG.COD_RUTA  IN '+@RUTAMULTI+' OR  (''0'') IN '+@RUTAMULTI+')
AND (SEG.PEDIDO= @PEDIDO OR  @PEDIDO = ''0'')
AND (SEG.COD_CLIENTE= @CLIENTE OR  @CLIENTE = ''0'')
AND (SEG.COD_VENDEDOR = @AGENTE OR @AGENTE=''0'')
AND (SEG.USUARIO = @USUARIO OR @USUARIO=''0'')
AND (SEG.SUCESO = @SUCESO OR @SUCESO=''0'')
AND (SEG.COD_COBRADOR = @COBRADOR OR @COBRADOR = ''0'' )
AND (CONVERT(VARCHAR(10),SEG.FECHA_CAMBIA_ESTADO_PED,23)    = @FMODESTADOPED OR  @FMODESTADOPED = ''0'')
AND (CONVERT(VARCHAR(10),SEG.FECHA_CAMBIA_ESTADO_FACTURA,23)= @FMODESTADOFAC OR  @FMODESTADOFAC = ''0'')'
+@FECHA_PROMETIDA+ @FACTURA +
'ORDER BY SEG.SEGUIMIENTO,SEG.MODIFICA DESC'
SET @PARAM = '@FECHAINI varchar(15),@FECHAFIN varchar(15),@ESTADO_PEDIDO INT,@FECHA_PROMETIDA VARCHAR(200),@ESTADO_FACTURA INT,
@RUTAMULTI VARCHAR(100),@PEDIDO VARCHAR(30),@FACTURA VARCHAR(200),@CLIENTE VARCHAR(20),@AGENTE VARCHAR(4),@USUARIO VARCHAR(20),@SUCESO VARCHAR(500),
@COBRADOR VARCHAR(50),@FMODESTADOPED VARCHAR(200),@FMODESTADOFAC VARCHAR(200)'

INSERT INTO @TABLE EXEC SP_EXECUTESQL @SQL,@PARAM,@FECHAINI,@FECHAFIN,@ESTADO_PEDIDO,@FECHA_PROMETIDA,@ESTADO_FACTURA,
@RUTAMULTI,@PEDIDO,@FACTURA,@CLIENTE,@AGENTE,@USUARIO,@SUCESO,@COBRADOR,@FMODESTADOPED,@FMODESTADOFAC

--PRINT @SQL
--PRINT @FMODESTADOPED
--PRINT @FMODESTADOFAC
SELECT * FROM @TABLE
END 
GO
