/****** Object:  StoredProcedure [DIS86].[PROC_SEGUIMIENTO_TRACKING_BORRAR]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE  PROC [DIS86].[PROC_SEGUIMIENTO_TRACKING_BORRAR]
(
@FECHAINI varchar(15),
@FECHAFIN varchar(15),
@ESTADO_PEDIDO INT,
@FECHA_PROMETIDA VARCHAR(15),
@ESTADO_FACTURA INT,
@RUTAMULTI VARCHAR(100),
@PEDIDO VARCHAR(30),
@FACTURA VARCHAR(50),
@CLIENTE VARCHAR(20),
@TLA_ESTADO VARCHAR(100),
@CORTE_TLA VARCHAR(8),
@AGENTE VARCHAR(4),
@DIA_SEMANA VARCHAR(8),
@HORA_FUERA_ENCORTE INT 
)
AS 
BEGIN

DECLARE @SQL NVARCHAR(MAX),@PARAM NVARCHAR(MAX)

DECLARE @TABLE AS TABLE(PEDIDO VARCHAR(50),OBSERVACIONES VARCHAR(800),TLA_ESTADO VARCHAR(1),USUARIO VARCHAR(25),
FECHA_HORA_RECIBIDO VARCHAR(30),FECHA_PEDIDO VARCHAR(30), DIA_RUTA VARCHAR(30),ESTADO_PEDIDO INT, ESTADO_PEDIDO_DESCRIPCION VARCHAR(200),
RUTA VARCHAR(47),FACTURA VARCHAR(50),TIEMPO VARCHAR(11),SEGUIR_FAC INT,SEGUIR_FAC_DESCRIPCION VARCHAR(200),SUCESOS VARCHAR(1),
CLIENTE VARCHAR(173),AGENTE VARCHAR(47),DIAS VARCHAR(20),HORA_FUERA_ENCORTE VARCHAR(1))


IF @FACTURA <>'99' AND @FECHA_PROMETIDA = '0' 
BEGIN 
SET @SQL ='SELECT  
		PEDIDO, 
		OBSERVACIONES, 
		TLA_ESTADO, 
		USUARIO, 
		FECHA_HORA_RECIBIDO, 
		FECHA_PEDIDO, 
		DIA_RUTA, 
		ESTADO_PEDIDO, 
		ESTADO_PEDIDO_DESCRIPCION, 
		RUTA, 
		FACTURA, 
		TIEMPO, 
		SEGUIR_FAC, 
        SEGUIR_FAC_DESCRIPCION, 
		SUCESOS, 
		CLIENTE, 
		AGENTE, 
		DIAS,
		HORA_FUERA_ENCORTE

FROM  DIS86.VIEW_TRACKING PD
WHERE DATEDIFF(DD,PD.FECHA_HORA_RECIBIDO,@FECHAFIN)>=0 AND DATEDIFF(DD,PD.FECHA_HORA_RECIBIDO,@FECHAINI)<=0 
AND (PD.ESTADO_PEDIDO= @ESTADO_PEDIDO OR  @ESTADO_PEDIDO = 0) --filtra el estado pedido o cero si son todos.
AND (PD.SEGUIR_FAC = @ESTADO_FACTURA OR  @ESTADO_FACTURA = 0)
AND (PD.RUTA IN(SELECT VAL FROM [DIS86].[TF_SPLIT](@RUTAMULTI,'','')) OR ''0'' IN(SELECT VAL FROM [DIS86].[TF_SPLIT](@RUTAMULTI,'','')))
AND (PD.PEDIDO= @PEDIDO OR  @PEDIDO = ''0'')
AND (PD.FACTURA = @FACTURA OR  @FACTURA = ''0'')
AND (PD.CLIENTE= @CLIENTE OR  @CLIENTE = ''0'')
AND (PD.TLA_ESTADO IN(SELECT VAL FROM [DIS86].[TF_SPLIT](@TLA_ESTADO,'','')) OR ''0'' IN(SELECT VAL FROM [DIS86].[TF_SPLIT](@TLA_ESTADO,'','')))
AND (PD.TIEMPO =@CORTE_TLA OR @CORTE_TLA=''0'')
AND (PD.AGENTE = @AGENTE OR @AGENTE=''0'')
AND ([DIS86].[FUN_VALIDAR_DIAS_SEMANA](REPLACE(REPLACE(PD.DIAS,''  '','',''),'' '',''''),@DIA_SEMANA)=1 OR @DIA_SEMANA LIKE ''%0%'' )
AND( PD.HORA_FUERA_ENCORTE = @HORA_FUERA_ENCORTE OR @HORA_FUERA_ENCORTE=''0'')
ORDER BY PD.FECHA_PEDIDO DESC'

SET @PARAM = '@FECHAINI varchar(15),@FECHAFIN varchar(15),@ESTADO_PEDIDO INT,@ESTADO_FACTURA INT,@RUTAMULTI VARCHAR(100),
@PEDIDO VARCHAR(30),@FACTURA VARCHAR(50),@CLIENTE VARCHAR(20),@TLA_ESTADO VARCHAR(100),@CORTE_TLA VARCHAR(8),@AGENTE VARCHAR(4),@DIA_SEMANA VARCHAR(8),
@HORA_FUERA_ENCORTE INT'

INSERT INTO @TABLE EXEC SP_EXECUTESQL @SQL,@PARAM ,@FECHAINI,@FECHAFIN,@ESTADO_PEDIDO,@ESTADO_FACTURA,@RUTAMULTI,
@PEDIDO,@FACTURA,@CLIENTE,@TLA_ESTADO,@CORTE_TLA ,@AGENTE,@DIA_SEMANA,@HORA_FUERA_ENCORTE
SELECT * FROM @TABLE
END 

END 
GO
