@FECHA_PROMETIDA VARCHAR(200),
@FECHA_PROMETIDAFIN VARCHAR(200),
@ESTADO_FACTURA INT,
@RUTAMULTI VARCHAR(100),
@PEDIDO VARCHAR(30),
@FACTURA VARCHAR(200),
@CLIENTE VARCHAR(20),
@TLA_ESTADO VARCHAR(100),
@CORTE_TLA VARCHAR(8),
@AGENTE VARCHAR(4),
@COBRADOR VARCHAR(4),
