@RUTAMULTI VARCHAR(100),
@PEDIDO VARCHAR(30),
@FACTURA VARCHAR(200),
@CLIENTE VARCHAR(20),
@TLA_ESTADO VARCHAR(100),
@CORTE_TLA VARCHAR(8),
@AGENTE VARCHAR(4),
@COBRADOR VARCHAR(4),
@DIA_SEMANA VARCHAR(8),
@HORA_FUERA_ENCORTE INT 
)
AS 
BEGIN

DECLARE @SQL NVARCHAR(MAX),@PARAM NVARCHAR(MAX), @CONTADOR VARCHAR(100) 

DECLARE @TABLE AS TABLE(ID INT,PEDIDO VARCHAR(50),OBSERVACIONES VARCHAR(800),TLA_ESTADO VARCHAR(1),USUARIO VARCHAR(25),
FECHA_HORA_RECIBIDO VARCHAR(30),FECHA_PEDIDO VARCHAR(30), DIA_RUTA VARCHAR(30),ESTADO_PEDIDO INT, ESTADO_PEDIDO_DESCRIPCION VARCHAR(200),
RUTA VARCHAR(47),FACTURA VARCHAR(200),TIEMPO VARCHAR(11),SEGUIR_FAC INT,SEGUIR_FAC_DESCRIPCION VARCHAR(200),SUCESOS VARCHAR(1),
CLIENTE VARCHAR(173),AGENTE VARCHAR(47),DIAS VARCHAR(20),HORA_FUERA_ENCORTE VARCHAR(1),TIPO_CORTE VARCHAR(20),COLOR_HEXA_PED VARCHAR(100),COLOR_HEXA_FAC VARCHAR(100))


--FECHA PROMETIDA ES LA FECHA DE LA RUTA
SET @FECHA_PROMETIDA = CASE WHEN (@FECHA_PROMETIDA = ''	or  @FECHA_PROMETIDAFIN ='')	THEN	'AND  (PD.DIA_RUTA IS NULL)'				-- TODAS LAS QUE NO ESTÁN ENRUTADAS
							WHEN (@FECHA_PROMETIDA = '0'	or  @FECHA_PROMETIDAFIN ='0') THEN	' '											-- NO HAY QUE FILTRAR NADA
							ELSE 'AND  (DATEDIFF(DD,PD.DIA_RUTA,'''+@FECHA_PROMETIDAFIN+''')>=0 AND DATEDIFF(DD,PD.DIA_RUTA,'''+@FECHA_PROMETIDA+''')<=0 )'	-- Se seleccionó un día de ruta en particular
						END 
						
SET @FACTURA		= CASE  WHEN @FACTURA = '99'	THEN	'AND (PD.FACTURA IS NOT NULL)'				-- TODAS LAS QUE TIENEN FACTURA
							WHEN @FACTURA = '0'		THEN	' '											-- NO HAY QUE FILTRAR NADA
							ELSE							'AND  (PD.FACTURA =  '''+ @FACTURA +''')'				-- Se seleccionó una factura en particular
						END 


SET @SQL ='SELECT
        ID,
		PEDIDO, 
		OBSERVACIONES, 
		TLA_ESTADO, 
		USUARIO, 
		FECHA_HORA_RECIBIDO, 
		FECHA_PEDIDO, 
		DIA_RUTA, 
		ESTADO_PEDIDO, 
		ESTADO_PEDIDO_DESCRIPCION, 
		RUTA, 
		FACTURA, 
		TIEMPO, 
		SEGUIR_FAC, 
        SEGUIR_FAC_DESCRIPCION, 
		SUCESOS, 
		CLIENTE, 
		AGENTE, 
		DIAS,
		HORA_FUERA_ENCORTE,
		TIPO_CORTE,
		COLOR_HEXA_PED,
		COLOR_HEXA_FAC
		
FROM  DIS86.VIEW_TRACKING PD
WHERE DATEDIFF(DD,PD.FECHA_HORA_RECIBIDO,@FECHAFIN)>=0 AND DATEDIFF(DD,PD.FECHA_HORA_RECIBIDO,@FECHAINI)<=0
--WHERE PD.FECHA_HORA_RECIBIDO  BETWEEN @FECHAINI AND  DATEADD(MILLISECOND,-2,DATEADD(DD,1,@FECHAFIN)) 
AND (PD.ESTADO_PEDIDO= @ESTADO_PEDIDO OR  @ESTADO_PEDIDO = ''0'') --filtra el estado pedido o cero si son todos.
AND (PD.SEGUIR_FAC = @ESTADO_FACTURA OR  @ESTADO_FACTURA = ''0'')
AND (COD_RUTA  IN '+@RUTAMULTI+' OR  (''0'') IN '+@RUTAMULTI+')  --IN(SELECT VAL FROM [DIS86].[TF_SPLIT](@RUTAMULTI,'','')) OR ''0'' IN(SELECT VAL FROM [DIS86].[TF_SPLIT](@RUTAMULTI,'','')))
AND (PD.PEDIDO= @PEDIDO OR  @PEDIDO = ''0'')
AND (PD.COD_CLIENTE= @CLIENTE OR  @CLIENTE = ''0'')
AND (PD.TLA_ESTADO IN(SELECT VAL FROM [DIS86].[TF_SPLIT](@TLA_ESTADO,'','')) OR ''0'' IN(SELECT VAL FROM [DIS86].[TF_SPLIT](@TLA_ESTADO,'','')))
AND (PD.TIEMPO =@CORTE_TLA OR @CORTE_TLA=''0'')
AND (PD.COD_VENDEDOR = @AGENTE OR @AGENTE=''0'')
AND (PD.COBRADOR = @COBRADOR OR @COBRADOR=''0'')
AND ([DIS86].[FUN_VALIDAR_DIAS_SEMANA](REPLACE(REPLACE(PD.DIAS,''  '','',''),'' '',''''),@DIA_SEMANA)=1 OR @DIA_SEMANA LIKE ''%0%'' )
AND( PD.HORA_FUERA_ENCORTE = @HORA_FUERA_ENCORTE OR @HORA_FUERA_ENCORTE=''0'')'
+@FECHA_PROMETIDA+ @FACTURA +
'ORDER BY PD.FACTURA ASC'

SET @PARAM = '@FECHAINI varchar(15),@FECHAFIN varchar(15),@ESTADO_PEDIDO INT,@FECHA_PROMETIDA VARCHAR(15),@FECHA_PROMETIDAFIN VARCHAR(15),@ESTADO_FACTURA INT,@RUTAMULTI VARCHAR(100),
@PEDIDO VARCHAR(30),@FACTURA VARCHAR(200),@CLIENTE VARCHAR(20),@TLA_ESTADO VARCHAR(100),@CORTE_TLA VARCHAR(8),@AGENTE VARCHAR(4),@COBRADOR VARCHAR(4),@DIA_SEMANA VARCHAR(8),
@HORA_FUERA_ENCORTE INT'

INSERT INTO @TABLE EXEC SP_EXECUTESQL @SQL,@PARAM,@FECHAINI,@FECHAFIN,@ESTADO_PEDIDO,@FECHA_PROMETIDA,@FECHA_PROMETIDAFIN,@ESTADO_FACTURA,@RUTAMULTI,
@PEDIDO,@FACTURA,@CLIENTE,@TLA_ESTADO,@CORTE_TLA,@AGENTE,@COBRADOR,@DIA_SEMANA,@HORA_FUERA_ENCORTE

SELECT * FROM @TABLE

END 




GO
/****** Object:  StoredProcedure [DIS86].[PROC_SUBTABLA_SEGUIMIENTO_TRACKING]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC  [DIS86].[PROC_SUBTABLA_SEGUIMIENTO_TRACKING]
(
@PEDIDO VARCHAR(50)

)
AS
BEGIN 
SELECT [SEGUIMIENTO]
      ,ISNULL([ESTADO_PEDIDO],1) [ESTADO_PEDIDO]
	  ,CASE WHEN ESTADO_PEDIDO = 1 THEN 'Sin Asignar' 
	        WHEN ESTADO_PEDIDO = 2 THEN 'En Reparto' 
			WHEN ESTADO_PEDIDO = 3 THEN 'Entregado' 
			WHEN ESTADO_PEDIDO = 4 THEN 'Rechazado' 
			WHEN ESTADO_PEDIDO = 5 THEN 'Vuelve a Salir' 
			WHEN ESTADO_PEDIDO = 6 THEN 'Cancelado'
			WHEN ESTADO_PEDIDO = 7 THEN 'Envío sin Factura(Carta)'
			WHEN ESTADO_PEDIDO = 8 THEN 'Pedido para OVAS'
			 WHEN ESTADO_PEDIDO IS NULL THEN 'Sin Asignar'
	    END ESTADO_PEDIDO_DESCRIPCION
      ,[ESTADO_FACTURA_SEGUIMIENTO]
	   , CASE WHEN ESTADO_FACTURA_SEGUIMIENTO =	1 THEN 'Sin Asignar' 
	          WHEN ESTADO_FACTURA_SEGUIMIENTO =	2 THEN 'DIS86 a TLA' 
			  WHEN ESTADO_FACTURA_SEGUIMIENTO =	3 THEN 'TLA a DIS86' 
			  WHEN ESTADO_FACTURA_SEGUIMIENTO =	4 THEN 'DIS86 a CxC' 
			  WHEN ESTADO_FACTURA_SEGUIMIENTO =	5 THEN 'CxC Recibe' 
			  WHEN ESTADO_FACTURA_SEGUIMIENTO =	6 THEN 'Cobrador Recibe'
			  WHEN ESTADO_FACTURA_SEGUIMIENTO =	7 THEN 'Refacturada'
			  WHEN ESTADO_FACTURA_SEGUIMIENTO =	8 THEN 'Trámite'
			  WHEN ESTADO_FACTURA_SEGUIMIENTO = 9 THEN 'Factura Posterior'
			  WHEN ESTADO_FACTURA_SEGUIMIENTO = 10 THEN 'Anulada con NC'
		END SEGUIR_FAC_DESCRIPCION 
		,TLA TLAESTADO
      ,[USUARIO]
	  ,CASE WHEN SEGUIMIENTO IN(SELECT SEGUIMIENTO FROM DIS86.SEGUIMIENTO AS S(NOLOCK) WHERE CONVERT(VARCHAR,S.FECHA,20)=CONVERT(VARCHAR,S.FECHA_CREACION,20) and ESTADO_FACTURA_SEGUIMIENTO<>1) THEN NULL ELSE CONVERT(VARCHAR,[FECHA],20) END [FECHA_CAMBIA_ESTADO_PED]
      --,CASE WHEN ESTADO_PEDIDO <> 1 THEN  CONVERT(VARCHAR,[FECHA],20) ELSE NULL END  [FECHA_CAMBIA_ESTADO_PED]
      ,CASE WHEN ESTADO_FACTURA_SEGUIMIENTO<> 1 THEN  CONVERT(VARCHAR,[FECHA_CREACION],20) ELSE NULL END [FECHA]
      ,[SUCESO]
      ,[OBSERVACIONES]
	  ,[PEDIDO]
  FROM [PS_TRACKING].[DIS86].[SEGUIMIENTO] WITH(NOLOCK)
  WHERE PEDIDO= @PEDIDO
  order by SEGUIMIENTO,CONVERT(VARCHAR,[FECHA_CREACION],20) desc 
  END
GO
/****** Object:  StoredProcedure [DIS86].[PROC_SUBTABLA_SEGUIMIENTO_TRACKING_COLOR_HEXA]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC  [DIS86].[PROC_SUBTABLA_SEGUIMIENTO_TRACKING_COLOR_HEXA]
(
@PEDIDO VARCHAR(50)

)
AS
BEGIN 
SELECT [SEGUIMIENTO]
      ,ISNULL([ESTADO_PEDIDO],1) [ESTADO_PEDIDO]
	  --,CASE WHEN ESTADO_PEDIDO = 1 THEN 'Sin Asignar' 
	  --      WHEN ESTADO_PEDIDO = 2 THEN 'En Reparto' 
			--WHEN ESTADO_PEDIDO = 3 THEN 'Entregado' 
			--WHEN ESTADO_PEDIDO = 4 THEN 'Rechazado' 
			--WHEN ESTADO_PEDIDO = 5 THEN 'Vuelve a Salir' 
			--WHEN ESTADO_PEDIDO = 6 THEN 'Cancelado'
			--WHEN ESTADO_PEDIDO = 7 THEN 'Envío sin Factura(Carta)'
			--WHEN ESTADO_PEDIDO = 8 THEN 'Pedido para OVAS'
			-- WHEN ESTADO_PEDIDO IS NULL THEN 'Sin Asignar'
	  --  END ESTADO_PEDIDO_DESCRIPCION_
		,(SELECT DESCRIPCION FROM DIS86.ESTADO_PEDIDO WHERE ESTADO_PEDIDO = SUC.ESTADO_PEDIDO) ESTADO_PEDIDO_DESCRIPCION


      ,[ESTADO_FACTURA_SEGUIMIENTO]
	 --  , CASE WHEN ESTADO_FACTURA_SEGUIMIENTO =	1 THEN 'Sin Asignar' 
	 --         WHEN ESTADO_FACTURA_SEGUIMIENTO =	2 THEN 'DIS86 a TLA' 
		--	  WHEN ESTADO_FACTURA_SEGUIMIENTO =	3 THEN 'TLA a DIS86' 
		--	  WHEN ESTADO_FACTURA_SEGUIMIENTO =	4 THEN 'DIS86 a CxC' 
		--	  WHEN ESTADO_FACTURA_SEGUIMIENTO =	5 THEN 'CxC Recibe' 
		--	  WHEN ESTADO_FACTURA_SEGUIMIENTO =	6 THEN 'Cobrador Recibe'
		--	  WHEN ESTADO_FACTURA_SEGUIMIENTO =	7 THEN 'Refacturada'
		--	  WHEN ESTADO_FACTURA_SEGUIMIENTO =	8 THEN 'Trámite'
		--	  WHEN ESTADO_FACTURA_SEGUIMIENTO = 9 THEN 'Factura Posterior'
		--	  WHEN ESTADO_FACTURA_SEGUIMIENTO = 10 THEN 'Anulada con NC'
		--END SEGUIR_FAC_DESCRIPCION_ 
		,(SELECT DESCRIPCION FROM DIS86.ESTADO_FACTURA_SEGUIMIENTO WHERE ESTADO_FACTURA_SEGUIMIENTO = SUC.ESTADO_FACTURA_SEGUIMIENTO) AS SEGUIR_FAC_DESCRIPCION
		,TLA TLAESTADO
      ,[USUARIO]
	  ,CASE WHEN SEGUIMIENTO IN(SELECT SEGUIMIENTO FROM DIS86.SEGUIMIENTO AS S(NOLOCK) WHERE CONVERT(VARCHAR,S.FECHA,20)=CONVERT(VARCHAR,S.FECHA_CREACION,20) and ESTADO_FACTURA_SEGUIMIENTO<>1) THEN NULL ELSE CONVERT(VARCHAR,[FECHA],20) END [FECHA_CAMBIA_ESTADO_PED]
      --,CASE WHEN ESTADO_PEDIDO <> 1 THEN  CONVERT(VARCHAR,[FECHA],20) ELSE NULL END  [FECHA_CAMBIA_ESTADO_PED]
      ,CASE WHEN ESTADO_FACTURA_SEGUIMIENTO<> 1 THEN  CONVERT(VARCHAR,[FECHA_CREACION],20) ELSE NULL END [FECHA]
      ,[SUCESO]
      ,[OBSERVACIONES]
	  ,[PEDIDO]
	  ,(SELECT COLOR_HEXA FROM DIS86.ESTADO_PEDIDO WHERE ESTADO_PEDIDO = SUC.ESTADO_PEDIDO) AS COLOR_HEXA_PED
	  ,(SELECT COLOR_HEXA FROM DIS86.ESTADO_FACTURA_SEGUIMIENTO WHERE ESTADO_FACTURA_SEGUIMIENTO = SUC.ESTADO_FACTURA_SEGUIMIENTO) AS COLOR_HEXA_FAC
  FROM [PS_TRACKING].[DIS86].[SEGUIMIENTO] SUC WITH(NOLOCK)
  WHERE PEDIDO= @PEDIDO
 -- WHERE PEDIDO= 'PEMM000546'
  order by SEGUIMIENTO,CONVERT(VARCHAR,[FECHA_CREACION],20) desc 
  
  END


GO
