/****** Object:  StoredProcedure [DIS86].[PROC_UPDATE_ESTADO_FACTURA_MULTIPLE]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [DIS86].[PROC_UPDATE_ESTADO_FACTURA_MULTIPLE]
(
@PEDIDO VARCHAR(20), 
@ESTADO_FACTURA INT,
--@FECHA_PROMETIDA DATETIME,
@OBSERVACION VARCHAR(800),
@USUARIO VARCHAR(20)
)
AS BEGIN 

UPDATE EXACTUSERP.DIS86.FACTURA
SET U_PS_TRACKING_ESTADO_FACTURA= @ESTADO_FACTURA
WHERE PEDIDO= @PEDIDO

UPDATE EXACTUSERP.DIS86.FACTURA
SET  U_TI_DIS86_ENTREGA     = CASE WHEN U_PS_TRACKING_ESTADO_FACTURA  =2  THEN GETDATE() ELSE NULL END,
     U_TI_DIS86_RECIBE      = CASE WHEN U_PS_TRACKING_ESTADO_FACTURA  =3  THEN GETDATE() ELSE NULL END,
	 U_TI_VB_CXC_ENVIA      = CASE WHEN U_PS_TRACKING_ESTADO_FACTURA  =4  THEN GETDATE() ELSE NULL END,
	 U_TI_CXC_RECIBE        = CASE WHEN U_PS_TRACKING_ESTADO_FACTURA  =5  THEN GETDATE() ELSE NULL END
WHERE PEDIDO= @PEDIDO 

UPDATE EXACTUSERP.DIS86.FACTURA
SET  U_TI_TLA_CORTE         = CASE WHEN U_PS_TRACKING_ESTADO_FACTURA  IN(2,3,4,5)  THEN 'S' ELSE 'N' END,
	 U_TI_TLA_CORTE_LISTO   = CASE WHEN U_PS_TRACKING_ESTADO_FACTURA  IN(2,3,4,5)  THEN 'S' ELSE 'N' END 
WHERE PEDIDO= @PEDIDO

INSERT INTO [DIS86].[SEGUIMIENTO]
           ([ESTADO_PEDIDO]
           ,[ESTADO_FACTURA_SEGUIMIENTO]
           ,[USUARIO]
           ,[FECHA]
           ,[SUCESO]
           ,[OBSERVACIONES]
		   ,[PEDIDO]
		   ,[TLA]
		   ,[FECHA_CREACION])
     VALUES
           ((SELECT U_PS_TRACKING_ESTADO_PEDIDO FROM EXACTUSERP.DIS86.PEDIDO WHERE PEDIDO = @PEDIDO) 
			,@ESTADO_FACTURA
			,@USUARIO
			,NULL--(SELECT CONVERT(VARCHAR,FECHA_PROYECTADA,23) FROM EXACTUSERP.DIS86.PEDIDO WHERE PEDIDO = @PEDIDO)
			,''
			,@OBSERVACION
			,@PEDIDO
			,ISNULL((SELECT U_TLA_ESTADO FROM EXACTUSERP.DIS86.PEDIDO WHERE PEDIDO = @PEDIDO),'N')
			,convert(varchar, getdate(), 20)--(SELECT CONVERT(VARCHAR,FECHA_PEDIDO,23) FROM EXACTUSERP.DIS86.PEDIDO WHERE PEDIDO = @PEDIDO)
			)

DELETE FROM [PS_TRACKING].[DIS86].[SEGUIMIENTO]
WHERE PEDIDO ='on'

END 



GO
/****** Object:  StoredProcedure [DIS86].[PROC_UPDATE_ESTADO_PEDIDO]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [DIS86].[PROC_UPDATE_ESTADO_PEDIDO]
(
@PEDIDO VARCHAR(20), 
@ESTADO_PEDIDO INT,
@FECHA_PROMETIDA DATETIME,
@OBSERVACION VARCHAR(800),
@USUARIO VARCHAR(20),
@CORREO VARCHAR(MAX)
)
AS 
BEGIN 

UPDATE EXACTUSERP.DIS86.PEDIDO
SET U_PS_TRACKING_ESTADO_PEDIDO= @ESTADO_PEDIDO,
    U_TI_TLA_FECHA_CORTE_CORTO = @FECHA_PROMETIDA,
	U_TI_TLA_FECHA_CORTE= GETDATE(),
    FECHA_PROYECTADA= CASE WHEN @ESTADO_PEDIDO IN('1','5') THEN NULL ELSE @FECHA_PROMETIDA END ---se omite para no cambiar la fecha proyectada.
WHERE PEDIDO= @PEDIDO 

UPDATE EXACTUSERP.DIS86.PEDIDO
SET U_TI_TLA_CORTE       = CASE WHEN U_TI_TLA_FECHA_CORTE_CORTO IS NOT NULL THEN 'S' ELSE 'N'END ,
    U_TI_TLA_CORTE_LISTO = CASE WHEN U_TI_TLA_FECHA_CORTE_CORTO IS NOT NULL THEN 'S' ELSE 'N' END
WHERE PEDIDO= @PEDIDO 



INSERT INTO [DIS86].[SEGUIMIENTO]
           ([ESTADO_PEDIDO]
           ,[ESTADO_FACTURA_SEGUIMIENTO]
           ,[USUARIO]
           ,[FECHA]
           ,[SUCESO]
           ,[OBSERVACIONES]
		   ,[PEDIDO]
		   ,[TLA]
		   ,[FECHA_CREACION])
     VALUES
           ( @ESTADO_PEDIDO
			,CASE WHEN (SELECT TOP 1 COUNT(*) FROM EXACTUSERP.DIS86.FACTURA WHERE PEDIDO = @PEDIDO) <1 THEN '1' --- se agrega por si un pedido no tiene factura.
			 ELSE (SELECT TOP 1 isnull(U_PS_TRACKING_ESTADO_FACTURA,1) FROM EXACTUSERP.DIS86.FACTURA WHERE PEDIDO = @PEDIDO) END -- de lo contrario se agrega el estado de factura. 
			,@USUARIO
			,@FECHA_PROMETIDA + convert(varchar, getdate(), 24)
			,''
			,@OBSERVACION
			,@PEDIDO
			,ISNULL((SELECT U_TLA_ESTADO FROM EXACTUSERP.DIS86.PEDIDO WHERE PEDIDO = @PEDIDO),'N')
			,convert(varchar, getdate(),20)--(SELECT CONVERT(VARCHAR,FECHA_PEDIDO,23) FROM EXACTUSERP.DIS86.PEDIDO WHERE PEDIDO = @PEDIDO)
			)

IF @CORREO <> ''
begin 
DECLARE @ESTADO AS VARCHAR(1) = CONVERT(VARCHAR(1),@ESTADO_PEDIDO) 
EXEC  [GLOBAL].[PROC_AVISO_CAMBIO_ESTADO_PEDIDO] @CORREO,@USUARIO,@ESTADO,@PEDIDO,@OBSERVACION
end 

END 
GO
/****** Object:  StoredProcedure [DIS86].[PROC_UPDATE_ESTADO_PEDIDO_MULTIPLE]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE  PROC [DIS86].[PROC_UPDATE_ESTADO_PEDIDO_MULTIPLE]
(
@PEDIDO VARCHAR(20), 
@ESTADO_PEDIDO INT,
@FECHA_PROMETIDA DATETIME,
@OBSERVACION VARCHAR(MAX),
@USUARIO VARCHAR(20),
@CORREO VARCHAR(MAX)
)
AS BEGIN

UPDATE EXACTUSERP.DIS86.PEDIDO
SET U_PS_TRACKING_ESTADO_PEDIDO= @ESTADO_PEDIDO,
    U_TI_TLA_FECHA_CORTE_CORTO = @FECHA_PROMETIDA,
	U_TI_TLA_FECHA_CORTE= GETDATE(),
    FECHA_PROYECTADA= CASE WHEN @ESTADO_PEDIDO IN('1','5') THEN NULL ELSE @FECHA_PROMETIDA END ---se omite para no cambiar la fecha proyectada.
WHERE PEDIDO= @PEDIDO 

UPDATE EXACTUSERP.DIS86.PEDIDO
SET U_TI_TLA_CORTE= CASE WHEN U_TI_TLA_FECHA_CORTE_CORTO IS NOT NULL THEN 'S' ELSE 'N'END ,
    U_TI_TLA_CORTE_LISTO = CASE WHEN U_TI_TLA_FECHA_CORTE_CORTO IS NOT NULL THEN 'S' ELSE 'N' END
WHERE PEDIDO= @PEDIDO 


INSERT INTO [DIS86].[SEGUIMIENTO]
           ([ESTADO_PEDIDO]
           ,[ESTADO_FACTURA_SEGUIMIENTO]
           ,[USUARIO]
           ,[FECHA] 
           ,[SUCESO]
           ,[OBSERVACIONES]
		   ,[PEDIDO]
		   ,[TLA]
		   ,[FECHA_CREACION])
     VALUES
           ( @ESTADO_PEDIDO
			,CASE WHEN (SELECT TOP 1 COUNT(*) FROM EXACTUSERP.DIS86.FACTURA WHERE PEDIDO = @PEDIDO) <1 THEN '1' --- se agrega por si un pedido no tiene factura.
			  ELSE (SELECT TOP 1 isnull(U_PS_TRACKING_ESTADO_FACTURA,1) FROM EXACTUSERP.DIS86.FACTURA WHERE PEDIDO = @PEDIDO) END -- de lo contrario se agrega el estado de factura. 
			,@USUARIO
			,@FECHA_PROMETIDA + convert(varchar, getdate(), 24)
			,''
			,@OBSERVACION
			,@PEDIDO
			,ISNULL((SELECT U_TLA_ESTADO FROM EXACTUSERP.DIS86.PEDIDO WHERE PEDIDO = @PEDIDO),'N')
			,convert(varchar, getdate(),20)--(SELECT CONVERT(VARCHAR,FECHA_PEDIDO,23) FROM EXACTUSERP.DIS86.PEDIDO WHERE PEDIDO = @PEDIDO)
			)


DELETE FROM [PS_TRACKING].[DIS86].[SEGUIMIENTO]
WHERE PEDIDO ='on'


IF @CORREO <> ''
begin 
DECLARE @ESTADO AS VARCHAR(1) = CONVERT(VARCHAR(1),@ESTADO_PEDIDO) 
EXEC  [GLOBAL].[PROC_AVISO_CAMBIO_ESTADO_PEDIDO] @CORREO,@USUARIO,@ESTADO,@PEDIDO,@OBSERVACION
end 

END 
GO
/****** Object:  StoredProcedure [DIS86].[PROC_UPDATE_FECHA_RUTA]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROC [DIS86].[PROC_UPDATE_FECHA_RUTA]
(
@PEDIDO VARCHAR(20), 
@FECHA_PROMETIDA DATETIME,
@USUARIO VARCHAR(20)
)
AS 
BEGIN 

UPDATE EXACTUSERP.DIS86.PEDIDO
SET FECHA_PROYECTADA= @FECHA_PROMETIDA,
    U_TI_TLA_CORTE = 'S',
	U_TI_TLA_CORTE_LISTO='S',
	U_TI_TLA_FECHA_CORTE= GETDATE()
	,U_TI_TLA_FECHA_CORTE_CORTO= @FECHA_PROMETIDA,
    U_PS_TRACKING_ESTADO_PEDIDO = '2' -- a 2 porque se le asigno ruta y va para reparto. 
WHERE PEDIDO= @PEDIDO




INSERT INTO [DIS86].[SEGUIMIENTO]
           ([ESTADO_PEDIDO]
           ,[ESTADO_FACTURA_SEGUIMIENTO]
           ,[USUARIO]
           ,[FECHA]
           ,[SUCESO]
           ,[OBSERVACIONES]
		   ,[PEDIDO]
		   ,[TLA]
		   ,[FECHA_CREACION])
     VALUES
           ( (SELECT U_PS_TRACKING_ESTADO_PEDIDO FROM EXACTUSERP.DIS86.PEDIDO WHERE PEDIDO = @PEDIDO)
			,(SELECT U_PS_TRACKING_ESTADO_FACTURA FROM EXACTUSERP.DIS86.PEDIDO WHERE PEDIDO = @PEDIDO)
			,@USUARIO
			,@FECHA_PROMETIDA + convert(varchar, getdate(), 24)
			,''
			,(SELECT OBSERVACIONES FROM EXACTUSERP.DIS86.PEDIDO WHERE PEDIDO = @PEDIDO)
			,@PEDIDO
			,ISNULL((SELECT U_TLA_ESTADO FROM EXACTUSERP.DIS86.PEDIDO WHERE PEDIDO = @PEDIDO),'N')
			,convert(varchar, getdate(), 20)--(SELECT CONVERT(VARCHAR,FECHA_PEDIDO,23) FROM EXACTUSERP.DIS86.PEDIDO WHERE PEDIDO = @PEDIDO)
			)

END 

