CREATE PROC [DIS86].[PROC_UPDATE_OBSERVACION]
(
@PEDIDO VARCHAR(20), 
@OBSERVACION VARCHAR(800),
@USUARIO VARCHAR(20)
)
AS 
BEGIN 

UPDATE EXACTUSERP.DIS86.PEDIDO
SET OBSERVACIONES = @OBSERVACION
WHERE PEDIDO= @PEDIDO

INSERT INTO [DIS86].[SEGUIMIENTO]
           ([ESTADO_PEDIDO]
           ,[ESTADO_FACTURA_SEGUIMIENTO]
           ,[USUARIO]
           ,[FECHA]
           ,[SUCESO]
           ,[OBSERVACIONES]
		   ,[PEDIDO]
		   ,[TLA]
		   ,[FECHA_CREACION])
     VALUES
           ( (SELECT U_PS_TRACKING_ESTADO_PEDIDO FROM EXACTUSERP.DIS86.PEDIDO WHERE PEDIDO = @PEDIDO)
			,(SELECT U_PS_TRACKING_ESTADO_FACTURA FROM EXACTUSERP.DIS86.PEDIDO WHERE PEDIDO = @PEDIDO)
			,@USUARIO
			,(SELECT FECHA_PROYECTADA FROM EXACTUSERP.DIS86.PEDIDO WHERE PEDIDO = @PEDIDO)
			,''
			,@OBSERVACION
			,@PEDIDO
			,ISNULL((SELECT U_TLA_ESTADO FROM EXACTUSERP.DIS86.PEDIDO WHERE PEDIDO = @PEDIDO),'N')
			,(SELECT CONVERT(VARCHAR,FECHA_PEDIDO,23) FROM EXACTUSERP.DIS86.PEDIDO WHERE PEDIDO = @PEDIDO)
			)



