/****** Object:  StoredProcedure [DIS86].[PROC_UPDATE_SUBTABLA_SUCESO]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE  PROC [DIS86].[PROC_UPDATE_SUBTABLA_SUCESO]
(
@PEDIDO VARCHAR(20), 
@SUCESO VARCHAR(800),
@CORREO VARCHAR(MAX),
@USUARIO VARCHAR(20),
@FECHAINGRESA_SUCESO DATETIME,
@OBSERVACION VARCHAR(MAX)
)
AS 
BEGIN 
declare @ID_SEGUIMIENTO int 

--SET @ID_SEGUIMIENTO = (select isnull(max(SEGUIMIENTO),0) + 1  from [DIS86].[SEGUIMIENTO] where PEDIDO =@PEDIDO)

INSERT INTO [DIS86].[SEGUIMIENTO]
           ([ESTADO_PEDIDO]
           ,[ESTADO_FACTURA_SEGUIMIENTO]
           ,[USUARIO]
           ,[FECHA]
           ,[SUCESO]
           ,[OBSERVACIONES]
           ,[PEDIDO]
           ,[TLA]
           ,[FECHA_CREACION])
     VALUES
           (
		    (SELECT U_PS_TRACKING_ESTADO_PEDIDO FROM EXACTUSERP.DIS86.PEDIDO WHERE PEDIDO = @PEDIDO)
			,CASE WHEN (SELECT COUNT(*) FROM EXACTUSERP.DIS86.FACTURA WHERE PEDIDO = @PEDIDO) <1 THEN '1' --- se agrega por si un pedido no tiene factura.
			  ELSE (SELECT TOP 1 isnull(U_PS_TRACKING_ESTADO_FACTURA,1) FROM EXACTUSERP.DIS86.FACTURA WHERE PEDIDO = @PEDIDO) END -- de lo contrario se agrega el estado de factura.
			,@USUARIO
			,@FECHAINGRESA_SUCESO + convert(varchar, getdate(), 24)
			,@SUCESO
			,@OBSERVACION
			,@PEDIDO
			,ISNULL((SELECT U_TLA_ESTADO FROM EXACTUSERP.DIS86.PEDIDO WHERE PEDIDO = @PEDIDO),'N')
			,getdate()
		   )
---  PROCEDIMIENTO QUE ENVIA AVISO QUE INGRESO UN SUCESO. 
IF @CORREO <> ''
BEGIN 
EXEC  [GLOBAL].[PROC_AVISO_CAMBIO_SUCUESO] @CORREO,@USUARIO,@SUCESO,@PEDIDO,@OBSERVACION
end
END 

GO
