CREATE PROC [DIS86].[PROC_UPDATE_USUARIO_MANTENIMIENTO]
(
@USUARIO VARCHAR(20),
@ROL INT,
@VENDEDOR VARCHAR(10),
@COBRADOR VARCHAR(10),
@BODEGA VARCHAR(10)
)        
AS BEGIN 

UPDATE GLOBAL.USUARIO
SET   ROL      = @ROL
WHERE USUARIO  = @USUARIO

 

UPDATE [GLOBAL].[USUARIO_ADICIONALES] 
SET    [VENDEDOR] = @VENDEDOR,
       [COBRADOR] = @COBRADOR,
       [BODEGA]   = @BODEGA
WHERE 
       USUARIO= @USUARIO

END
