CREATE PROCEDURE [GLOBAL].[LeerUsuarioActual] ( 
@UserName varchar(30)  OUTPUT 
) 
AS 
BEGIN
SELECT @UserName = ''  
SELECT @UserName = (SELECT Usuario 
FROM [GLOBAL].Usuario_Actual 
WHERE ConexionId = @@spid) 
IF LEN(@UserName) <= 0 OR @UserName = NULL 
  SELECT @UserName = SUSER_SNAME() 
RETURN 0 
END;


