/****** Object:  StoredProcedure [GLOBAL].[PCL_PROC_ENVIAR_APLICACION_NC]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/* ================================================================
   2??  SP con plantilla HTML unificada
   ================================================================ */
CREATE PROC [GLOBAL].[PCL_PROC_ENVIAR_APLICACION_NC]
(
    @DOC_APLICACION   VARCHAR(30),
    @CLIENTE          VARCHAR(20),
    @CORREOS          VARCHAR(MAX),
    @CIA              VARCHAR(10)
)
AS
BEGIN
    SET NOCOUNT ON;

    ----------------------------------------------------------------
    -- 1. Variables
    ----------------------------------------------------------------
    DECLARE @ASUNTO      VARCHAR(120),
            @CUERPO      NVARCHAR(MAX),
            @ADJUNTO     VARCHAR(260),
            @NOM_PDF     VARCHAR(120),
            @MES         VARCHAR(12),
            @ANO         CHAR(4),
            @NOMCLI      VARCHAR(100),
            @EMAIL_VEND  VARCHAR(250);

    ----------------------------------------------------------------
    -- 2. Datos del cliente / vendedor
    ----------------------------------------------------------------
    SELECT  @NOMCLI     = C.NOMBRE,
            @EMAIL_VEND = ISNULL(V.EMAIL_VENDEDOR,'')
    FROM    EXACTUSERP.[DIS86].CLIENTE  AS C
    LEFT JOIN DIS86.PRODUSOFT_VIEW_EC_CXC_BASE AS V
           ON V.CLIENTE LIKE C.CLIENTE + '%'
    WHERE   C.CLIENTE = @CLIENTE;

    ----------------------------------------------------------------
    -- 3. Mes y año en español
    ----------------------------------------------------------------
    SELECT @MES =
        CASE MONTH(GETDATE())
            WHEN 1 THEN 'ENERO' WHEN 2 THEN 'FEBRERO'
            WHEN 3 THEN 'MARZO' WHEN 4 THEN 'ABRIL'
            WHEN 5 THEN 'MAYO'  WHEN 6 THEN 'JUNIO'
            WHEN 7 THEN 'JULIO' WHEN 8 THEN 'AGOSTO'
            WHEN 9 THEN 'SEPTIEMBRE' WHEN 10 THEN 'OCTUBRE'
            WHEN 11 THEN 'NOVIEMBRE' WHEN 12 THEN 'DICIEMBRE'
        END,
        @ANO = YEAR(GETDATE());

    ----------------------------------------------------------------
    -- 4. Asunto, adjunto, PDF
    ----------------------------------------------------------------
    SET @NOM_PDF  = CONCAT('ReciboAplicacion_', @DOC_APLICACION, '.pdf');
    SET @ADJUNTO  = CONCAT('C:\inetpub\wwwroot\PortalClientes\DIS86rdp\rpdf\', @NOM_PDF);
