--EXEC [GLOBAL].[PCL_PROC_ENVIAR_FACTURA_AL_CLIENTE] 'CL02037 ','ND' ,'000000001','DIS86'

CREATE PROC [GLOBAL].[PCL_PROC_ENVIAR_FACTURA_AL_CLIENTE] 
(
  @CLIENTE VARCHAR(50),
  @CORREO VARCHAR(MAX),
  @FACTURA VARCHAR(50),
  @CIA VARCHAR(20)
)
AS
BEGIN 
     DECLARE @SQL NVARCHAR(MAX) , @CONJUNTO VARCHAR(15), @PARAM NVARCHAR(250) 
     DECLARE @VARASUNTO VARCHAR(100),@ADJUNTO VARCHAR(100),@MONTO VARCHAR(25),@MES VARCHAR(25),@ANO VARCHAR(25),@NOMBRE_CLIENTE VARCHAR(100),@CUERPO VARCHAR(MAX)
	 DECLARE @NOMBRE_DOCUMENTO VARCHAR(150)
	 
	 SET @NOMBRE_DOCUMENTO = (select top 1  NOMBRE_PDF from EXACTUSERP.[DIS86].[DOC_ELECTRONICO_PROC_DE] where NUMERO_DOC = @FACTURA)
	
	 DECLARE @UBICACION_BASICA NVARCHAR(400)
	 SET @UBICACION_BASICA ='\\DIS86rdp\\data_de\\DIS86\\'+ @NOMBRE_DOCUMENTO; 

    -- Intenta obtener el TOTAL_FACTURA y manejar NULL
SET @MONTO = FORMAT(
             ISNULL((SELECT TOP 1  TOTAL_FACTURA FROM EXACTUSERP.DIS86.FACTURA WHERE FACTURA = @FACTURA), 0), 
             'N2');

			  PRINT @MONTO
		-- Si @MONTO es '0.00', busca el SALDO en DOCUMENTOS_CC
		IF @MONTO = '0.00'
		BEGIN
			SET @MONTO = FORMAT(
				ISNULL((SELECT TOP 1 SALDO FROM EXACTUSERP.DIS86.DOCUMENTOS_CC WHERE DOCUMENTO = @FACTURA), 0), 
				'N2'
			);
		END

PRINT @MONTO;


     SELECT 
	 @MES =
		  ( CASE MONTH(GETDATE()) 
				WHEN '01' THEN 'ENERO'
				WHEN '02' THEN 'FEBRERO'
				WHEN '03' THEN 'MARZO'
				WHEN '04' THEN 'ABRIL'
				WHEN '05' THEN 'MAYO'
				WHEN '06' THEN 'JUNIO'
				WHEN '07' THEN 'JULIO'
				WHEN '08' THEN 'AGOSTO'
				WHEN '09' THEN 'SEPTIEMBRE'
				WHEN '10' THEN 'OCTUBRE'
				WHEN '11' THEN 'NOVIEMBRE'
				WHEN '12' THEN 'DICIEMBRE'
			END),
		  @ANO = YEAR(GETDATE()),
 		  @NOMBRE_CLIENTE = NOMBRE

	FROM EXACTUSERP.DIS86.CLIENTE 
	WHERE CLIENTE = @CLIENTE
	
	BEGIN
	
		SET @VARASUNTO = 'DOCUMENTO ELECTRONICO'  +' '+ CONVERT(VARCHAR,GETDATE(),103)
		SET @ADJUNTO = @UBICACION_BASICA ---'\\DIS86rdp\\rpdf\\'+@NOMBRE_REPORTE+'.pdf'
		PRINT @ADJUNTO 
		
