/****** Object:  StoredProcedure [GLOBAL].[PCL_PROC_OBT_DOCUMENTO_POR_CLIENTE]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


-- EXEC [GLOBAL].[PCL_PROC_OBT_DOCUMENTO_POR_CLIENTE]  '0','CND','CL02037'

CREATE PROC  [GLOBAL].[PCL_PROC_OBT_DOCUMENTO_POR_CLIENTE]
(
--@FECHAINI VARCHAR(20),
--@FECHAFIN VARCHAR(20),
@TIPO_DOC VARCHAR(100),
@VENDEDOR VARCHAR(4),
@CLIENTE VARCHAR(20)

)
AS
BEGIN 
DECLARE @SQL NVARCHAR(MAX),@PARAM NVARCHAR(MAX)
DECLARE @TABLE AS TABLE(
                         ID INT IDENTITY(1,1) PRIMARY KEY, CLIENTE VARCHAR(20),CLIENTE_NOMBRE VARCHAR(150), DOCUMENTO VARCHAR(50),TIPO VARCHAR(3),
                        SUBTIPO VARCHAR(25),COD_SUBTIPO_DEBITO INT ,FECHA_DOCUMENTO VARCHAR(100),FECHA_VENCE VARCHAR(100), 
						DIAS_NETO INT,MONTO DECIMAL(28,8),SALDO DECIMAL(28,8),MONTO_PAGO DECIMAL(28,8),COD_VENDEDOR VARCHAR(10),
						NOMBRE_VENDEDOR VARCHAR(4000), COD_COBRADOR VARCHAR(10),NOMBRE_COBRADOR VARCHAR(4000), MONEDA VARCHAR(10),
						COMENTARIO VARCHAR(MAX)
						)



SET @SQL ='SELECT DISTINCT
				  CLIENTE,
				  CLIENTE_NOMBRE,
				  DOCUMENTO_DEBITO,
				  TIPO_DEBITO AS TIPO,
				  SUBTIPO_debito AS SUBTIPO,
				  COD_SUBTIPO_DEBITO,
				  FECHA_DOCUMENTO_DEBITO AS FECHA_DOCUMENTO,
				  FECHA_VENCE_DEBITO AS FECHA_VENCE, 
				  DIAS_NETO, 
				  MONTO_DEBITO AS MONTO,
				  SALDO_DEBITO AS SALDO,
				  MONTO_PAGO,
				  COD_VENDEDOR_CLI,
				  VENDEDOR_DEBITO,
				  COBRADOR_DEBITO,
				  NOMBRE_COBRADOR_DEBITO,
				  MONEDA_DEBITO,
				  COMENTARIO_DEBITO

			FROM 
				  [DIS86].[VIEW_OBT_DOCUMENTOS_FACTURA_CLIENTE_DEBITOS] DOC WITH(NOLOCK)
			WHERE (DOC.TIPO_DEBITO      = @TIPO_DOC OR  @TIPO_DOC =''0'' )   ---(DOC.TIPO_DEBITO IN(SELECT VAL FROM [DIS86].[TF_SPLIT](@TIPO_DOC,'','')) OR ''0'' IN(SELECT VAL FROM [DIS86].[TF_SPLIT](@TIPO_DOC,'','')))
			AND   (DOC.COBRADOR_DEBITO  = @VENDEDOR OR  @VENDEDOR = ''0'')
			AND   (DOC.CLIENTE          = @CLIENTE  OR  @CLIENTE  = ''0'')'
			
		 --  DATEDIFF(DD,DOC.FECHA_DOCUMENTO_DEBITO,@FECHAFIN) >= 0 
	  --AND  DATEDIFF(DD,DOC.FECHA_DOCUMENTO_DEBITO,@FECHAINI) <= 0 SE ELIMINO POR PETICION DEL CLIENTE,

SET @PARAM = '@TIPO_DOC VARCHAR(10),@VENDEDOR VARCHAR(4),@CLIENTE VARCHAR(20)'

INSERT INTO @TABLE EXEC SP_EXECUTESQL @SQL,@PARAM,@TIPO_DOC,@VENDEDOR,@CLIENTE

SELECT * FROM @TABLE
END


GO
/****** Object:  StoredProcedure [GLOBAL].[PCL_PROC_OBT_DOCUMENTO_POR_CLIENTE_V2]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROC [GLOBAL].[PCL_PROC_OBT_DOCUMENTO_POR_CLIENTE_V2]
(
    @TIPO_DOC    VARCHAR(100),
    @VENDEDOR    VARCHAR(4),
    @CLIENTE     VARCHAR(20),
    @PAGINA      INT      = 1,
    @TAM_PAGINA  INT      = 20,
    @TOTAL_FILAS INT      OUTPUT
)
AS
BEGIN
    SET NOCOUNT ON;

    IF @PAGINA     < 1 SET @PAGINA     = 1;
    IF @TAM_PAGINA < 1 SET @TAM_PAGINA = 20;

    ;WITH SRC AS
    (
		select *
			, RN = ROW_NUMBER() OVER (ORDER BY FECHA_DOCUMENTO DESC, DOCUMENTO)
		from (
        SELECT distinct
              CLIENTE
            , CLIENTE_NOMBRE
            , DOCUMENTO_DEBITO       AS DOCUMENTO
            , TIPO_DEBITO            AS TIPO
            , SUBTIPO_DEBITO         AS SUBTIPO
            , COD_SUBTIPO_DEBITO
            , FECHA_DOCUMENTO_DEBITO AS FECHA_DOCUMENTO
            , FECHA_VENCE_DEBITO     AS FECHA_VENCE
            , DIAS_NETO
            , MONTO_DEBITO           AS MONTO
            , SALDO_DEBITO           AS SALDO
            , MONTO_PAGO
            , COD_VENDEDOR_CLI
            , VENDEDOR_DEBITO
            , COBRADOR_DEBITO
            , NOMBRE_COBRADOR_DEBITO
            , MONEDA_DEBITO
            , COMENTARIO_DEBITO
            , TOTAL_FILAS = COUNT_BIG(*) OVER()
            ,CONDICION_PAGO_DESC_DEB
		    ,CONDICION_PAGO_DEB
		    ,CONDICION_PAGO_DESC_CRE
		    ,CONDICION_PAGO_CRE
        FROM DIS86.VIEW_OBT_DOCUMENTOS_FACTURA_CLIENTE_DEBITOS WITH (NOLOCK)
        WHERE (@TIPO_DOC = '0' OR TIPO_DEBITO      = @TIPO_DOC)
          AND (@VENDEDOR = '0' OR COD_VENDEDOR_CLI  = @VENDEDOR)
          AND (@CLIENTE  = '0' OR CLIENTE          = @CLIENTE)) pp
    )

    SELECT
          CLIENTE ,
          CLIENTE_NOMBRE ,
          DOCUMENTO      ,
          TIPO           ,
          SUBTIPO        ,
          COD_SUBTIPO_DEBITO ,
          FECHA_DOCUMENTO ,
          FECHA_VENCE     ,
          DIAS_NETO       ,
          MONTO           ,
          SALDO           ,
          MONTO_PAGO      ,
          COD_VENDEDOR_CLI,
          VENDEDOR_DEBITO ,
          COBRADOR_DEBITO ,
          NOMBRE_COBRADOR_DEBITO ,
          MONEDA_DEBITO   ,
          COMENTARIO_DEBITO ,
          TOTAL_FILAS  
        ,CONDICION_PAGO_DESC_DEB
		,CONDICION_PAGO_DEB
		,CONDICION_PAGO_DESC_CRE
		,CONDICION_PAGO_CRE
    INTO   #PAGINA_DOCS
    FROM   SRC
    WHERE  RN BETWEEN ((@PAGINA - 1) * @TAM_PAGINA) + 1
                     AND  (@PAGINA      * @TAM_PAGINA);

    SELECT @TOTAL_FILAS = CONVERT(INT, MAX(TOTAL_FILAS)) FROM #PAGINA_DOCS;

    SELECT  CLIENTE ,
            CLIENTE_NOMBRE ,
            DOCUMENTO      ,
            TIPO           ,
            SUBTIPO        ,
            COD_SUBTIPO_DEBITO ,
            FECHA_DOCUMENTO ,
            FECHA_VENCE     ,
            DIAS_NETO       ,
            MONTO           ,
            SALDO           ,
            MONTO_PAGO      ,
            COD_VENDEDOR_CLI,
            VENDEDOR_DEBITO ,
            COBRADOR_DEBITO ,
            NOMBRE_COBRADOR_DEBITO ,
            MONEDA_DEBITO   ,
            COMENTARIO_DEBITO
             ,CONDICION_PAGO_DESC_DEB
		    ,CONDICION_PAGO_DEB
		    ,CONDICION_PAGO_DESC_CRE
		    ,CONDICION_PAGO_CRE
    FROM    #PAGINA_DOCS
    ORDER BY FECHA_DOCUMENTO DESC , DOCUMENTO;  

    DROP TABLE #PAGINA_DOCS;                    
END
GO
/****** Object:  StoredProcedure [GLOBAL].[PCL_PROC_OBT_RECIBOS_DOCUMENTOS_CC]    Script Date: 22/5/2026 17:05:06 ******/
