-- EXEC [GLOBAL].[PCL_PROC_OBT_RECIBOS_DOCUMENTOS_CC] '2024-02-01','2024-02-07','0','0','0','0','0','0','DIS86'

CREATE PROC  [GLOBAL].[PCL_PROC_OBT_RECIBOS_DOCUMENTOS_CC]
(
@FECHAINI VARCHAR(30),
@FECHAFIN VARCHAR(30),
@CLIENTE VARCHAR(50),
@COBRADOR VARCHAR(50),
@MONEDA VARCHAR(4),
@TIPO_DOC VARCHAR(5),
@SUBTIPO INT,
@ESTADO INT,
@CIA VARCHAR(20)
)
AS
BEGIN 
DECLARE @SQL NVARCHAR(MAX),@PARAM NVARCHAR(MAX)
DECLARE @TABLE AS TABLE(
					     ID INT
						,[CLIENTE] VARCHAR(100)
						,[NOMBRE_CLIENTE] VARCHAR(MAX)
						,[TIPO] VARCHAR(4)
						,[SUBTIPO] INT
						,[FORMA_PAGO] VARCHAR(500)
						,[DOCUMENTO] VARCHAR(100)
						,[MONEDA] VARCHAR(4)
						,[MONTO] DECIMAL(28,8)
						,[MONTO_DESPOSITAR] DECIMAL(28,8)
						,[COD_ESTADO] INT
						,[ESTADO_DESCRIPCION] VARCHAR(500)
						,[BANCO] VARCHAR(5)
						,[REFERENCIA] VARCHAR(MAX)
						,[FECHA_DOCUMENTO] VARCHAR(30)
						,[COMENTARIO] VARCHAR(MAX)
						,[COBRADOR] VARCHAR(5)
						,[NOMBRE_COBRADOR] VARCHAR(500)
						,[SALDO] DECIMAL(28,8)
			           )
SET @SQL ='SELECT 
                   ROW_NUMBER() OVER (Order by CLIENTE) + 10 AS ID
				  ,[CLIENTE]
				  ,[NOMBRE_CLIENTE]
				  ,[TIPO]
				  ,[SUBTIPO]
				  ,[FORMA_PAGO]
				  ,[DOCUMENTO]
				  ,[MONEDA]
				  ,[MONTO]
				  ,[MONTO_DESPOSITAR]
				  ,[COD_ESTADO]
				  ,[ESTADO_DESCRIPCION]
				  ,[BANCO]
				  ,[REFERENCIA]
				  ,[FECHA_DOCUMENTO]
				  ,[COMENTARIO]
				  ,[COBRADOR]
				  ,[NOMBRE_COBRADOR]
				  ,[SALDO]
		    FROM  
			       ['+ISNULL(@CIA,'')+'].[VIEW_OBT_RECIBOS_TRANSFERENCIA_DOCUMENTOS_CC]
			WHERE  DATEDIFF(DD,FECHA_DOCUMENTO,@FECHAFIN)>=0 AND DATEDIFF(DD,FECHA_DOCUMENTO,@FECHAINI)<=0 
			AND    (CLIENTE         = @CLIENTE  OR @CLIENTE  = ''0'')
			AND    (COBRADOR        = @COBRADOR OR @COBRADOR = ''0'')
			AND    (MONEDA           = @MONEDA    OR @MONEDA    = '''')
			AND    (TIPO            = @TIPO_DOC OR @TIPO_DOC = ''0'')
			AND    (SUBTIPO         = @SUBTIPO  OR @SUBTIPO  = ''0'')
			AND    (COD_ESTADO      = @ESTADO   OR @ESTADO   = ''0'') 
			'
			
SET @PARAM = '@FECHAINI VARCHAR(30),
			@FECHAFIN VARCHAR(30),
			@CLIENTE VARCHAR(50),
			@COBRADOR VARCHAR(50),
			@MONEDA VARCHAR(4),
			@TIPO_DOC VARCHAR(5),
			@SUBTIPO INT,
			@ESTADO INT'

INSERT INTO @TABLE EXEC SP_EXECUTESQL @SQL,@PARAM,@FECHAINI,
												  @FECHAFIN,
												  @CLIENTE,
												  @COBRADOR,
												  @MONEDA,
												  @TIPO_DOC,
												  @SUBTIPO,
												  @ESTADO

SELECT * FROM @TABLE

END
GO
/****** Object:  StoredProcedure [GLOBAL].[PCL_PROC_OBT_RECIBOS_DOCUMENTOS_CC_FILTRO_CHEQUE]    Script Date: 22/5/2026 17:05:06 ******/
