-- EXEC [GLOBAL].[PCL_PROC_OBT_RECIBOS_DOCUMENTOS_CC] '2024-02-01','2024-02-07','0','0','0','0','0','0','DIS86'

CREATE PROC  [GLOBAL].[PCL_PROC_OBT_RECIBOS_DOCUMENTOS_CC_FILTRO_CHEQUE]
(
@FECHAINI VARCHAR(30),
@FECHAFIN VARCHAR(30),
@CLIENTE VARCHAR(50),
@COBRADOR VARCHAR(50),
@MONEDA VARCHAR(4),
@TIPO_DOC VARCHAR(5),
@SUBTIPO INT,
@ESTADO INT,
@CIA VARCHAR(20)
)
AS
BEGIN 
DECLARE @SQL NVARCHAR(MAX),@PARAM NVARCHAR(MAX)
DECLARE @TABLE AS TABLE(
						[MONTO] DECIMAL(28,8)
			           )
SET @SQL ='SELECT 
                   SUM(MONTO)
		    FROM  
			       ['+ISNULL(@CIA,'')+'].[VIEW_OBT_RECIBOS_TRANSFERENCIA_DOCUMENTOS_CC]
			WHERE  DATEDIFF(DD,FECHA_DOCUMENTO,@FECHAFIN)>=0 AND DATEDIFF(DD,FECHA_DOCUMENTO,@FECHAINI)<=0 
			AND    (CLIENTE         = @CLIENTE  OR @CLIENTE  = ''0'')
			AND    (COBRADOR        = @COBRADOR OR @COBRADOR = ''0'')
			AND    (MONEDA           = @MONEDA    OR @MONEDA    = '''')
			AND	   (TIPO = @TIPO_DOC OR (@TIPO_DOC = ''0'' AND TIPO = ''REC''))
			--AND	   (SUBTIPO = @SUBTIPO OR (@SUBTIPO = ''0'' AND SUBTIPO = ''33''))
			AND    (COD_ESTADO      = @ESTADO   OR @ESTADO   = ''0'') 
			AND		BANCO IS NULL
			AND SUBTIPO = ''33''

			'
			
SET @PARAM = '@FECHAINI VARCHAR(30),
			  @FECHAFIN VARCHAR(30),
			  @CLIENTE VARCHAR(50),
			  @COBRADOR VARCHAR(50),
			  @MONEDA VARCHAR(4),
			  @TIPO_DOC VARCHAR(5),
			  @SUBTIPO INT,
			  @ESTADO INT'

INSERT INTO @TABLE EXEC SP_EXECUTESQL @SQL,@PARAM,@FECHAINI,
												  @FECHAFIN,
												  @CLIENTE,
												  @COBRADOR,
												  @MONEDA,
