/****** Object:  StoredProcedure [GLOBAL].[PCL_PROC_OBT_SALDO_DOC_CLIENTE]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROC [GLOBAL].[PCL_PROC_OBT_SALDO_DOC_CLIENTE]
(
    @TIPO_DOC  varchar(100),
    @VENDEDOR  varchar(5),
    @COBRADOR  varchar(5),
    @CLIENTE   varchar(20),
    @CIA       varchar(30)
)
AS
BEGIN
    DECLARE @SQL   nvarchar(max),
            @PARAM nvarchar(max);

    DECLARE @TABLE table
    (
        MONTO                decimal(28,2),
        SALDO                decimal(28,2),
        MONTO_PAGO           decimal(28,2),
        CONTADOR             int,
        SALDO_VENCIDO        decimal(28,2),
        CONTADOR_DOC_VENCIDO int
    );

    SET @SQL = N'
 
    WITH f AS
    (
        SELECT  DOC.DOCUMENTO_DEBITO,
                MAX(DOC.MONTO_DEBITO)      AS MONTO,
                MAX(DOC.SALDO_DEBITO)      AS SALDO,
                MAX(DOC.MONTO_PAGO)        AS MONTO_PAGO,
                MAX(DOC.FECHA_VENCE_DEBITO) AS FECHA_VENCE
        FROM  [DIS86].[VIEW_OBT_DOCUMENTOS_FACTURA_CLIENTE] DOC  WITH (NOLOCK)
        WHERE (DOC.TIPO_DEBITO      = @TIPO_DOC OR @TIPO_DOC = ''0'')
          AND (DOC.COD_VENDEDOR_CLI = @VENDEDOR  OR @VENDEDOR = ''0'')
          AND (DOC.COD_COBRADOR_CLI = @COBRADOR  OR @COBRADOR = ''0'')
          AND (DOC.CLIENTE          = @CLIENTE   OR @CLIENTE  = ''0'')
        GROUP BY DOC.DOCUMENTO_DEBITO
    )
    SELECT  SUM(MONTO)                       AS MONTO,
            SUM(SALDO)                       AS SALDO,
            SUM(MONTO_PAGO)                  AS MONTO_PAGO,
            COUNT(*)                         AS CONTADOR,
            SUM(CASE WHEN FECHA_VENCE < CONVERT(date, GETDATE())
                     THEN SALDO END)         AS SALDO_VENCIDO,
            SUM(CASE WHEN FECHA_VENCE < CONVERT(date, GETDATE())
                     THEN 1 END)             AS CONTADOR_DOC_VENCIDO
    FROM   f;';

    SET @PARAM = N'
        @TIPO_DOC   varchar(100),
        @VENDEDOR   varchar(5),
        @COBRADOR   varchar(5),
        @CLIENTE    varchar(20)';

    INSERT INTO @TABLE
    EXEC sp_executesql
         @SQL,
         @PARAM,
         @TIPO_DOC = @TIPO_DOC,
         @VENDEDOR = @VENDEDOR,
         @COBRADOR = @COBRADOR,
         @CLIENTE  = @CLIENTE;

    SELECT * FROM @TABLE;
END
GO
/****** Object:  StoredProcedure [GLOBAL].[PLC_PROC_OBT_DATOS_CLIENTE_ESTADO_CUENTA]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
