GO


---EXEC  [GLOBAL].[PLC_PROC_OBT_DATOS_CLIENTE_ESTADO_CUENTA] '0,','0,','0','0','0','VND','CND','2574',''''
CREATE  PROC [GLOBAL].[PLC_PROC_OBT_DATOS_CLIENTE_ESTADO_CUENTA]
(
@SEMANA VARCHAR(100),
--@RUTA VARCHAR(4),
@DIA_SEMANA VARCHAR(8),
@SALDO VARCHAR(100),
@CONDICION_PAGO VARCHAR(4),
@ESTADO_VISTA VARCHAR(10),
@VENDEDOR VARCHAR(4),
@COBRADOR VARCHAR(4),
@CLIENTE VARCHAR(20),
@FECHASEMANA VARCHAR(MAX)
)
AS 
BEGIN 

DECLARE @SQL NVARCHAR(MAX),@PARAM NVARCHAR(MAX)

DECLARE @TABLE AS TABLE(ESTADO VARCHAR(10),CLIENTE VARCHAR(21),CLI_NOMBRE VARCHAR(171),ALIAS VARCHAR(150),COD_VENDEDOR VARCHAR(4),NOMBRE_VENDEDOR VARCHAR(40),
						VEN_NOMBRE VARCHAR(47),EMAIL VARCHAR(249),TELEFONO VARCHAR(50),CONDICION_PAGO VARCHAR(4),DIAS_NETO VARCHAR(36),SALDO DECIMAL(28,8),
						FECHA_ULTIMA_VISITA VARCHAR(100),SEMANA VARCHAR(100), COLOR_HEXA VARCHAR(50), U_ORDEN_VISITA VARCHAR(2),
						ID_VISITA INT,COD_COBRADOR VARCHAR(5),COD_NOMBRE_COBRADOR VARCHAR(800),DOC_VENC INT)

DECLARE @FSEMANA AS VARCHAR(2), @FFECHAINICIO AS VARCHAR(100), @FFECHAFIN AS VARCHAR(100)


SET @SALDO		= CASE  WHEN @SALDO = '1' THEN	'AND (EC.SALDO <=0)' -- SIN SALDO O EN NEGATIVO
                        WHEN @SALDO = '2' THEN  'AND (EC.SALDO >=1)' -- SALDO MAYOR A CERO 
  						WHEN @SALDO = '0' THEN	' '		             -- MUESTRA TODOS			                         
						END 



--- SACAMOS FILTRO DE FECHAS POR SEMANA 

		-- Crear una tabla temporal para almacenar las semanas
		DECLARE @SemanaTabla TABLE (
			Semana VARCHAR(100),
			FechaInicio DATE,
			FechaFin DATE
		);
		IF @FECHASEMANA <> '0' AND ISNULL(@FECHASEMANA, '') <> ''
		BEGIN
		-- Insertar las semanas en la tabla temporal
		INSERT INTO @SemanaTabla (Semana, FechaInicio, FechaFin)
		SELECT
			VAL,
			CONVERT(DATE, SUBSTRING(VAL, CHARINDEX('|', VAL) + 1, 10), 105) AS FechaInicio,
			CONVERT(DATE, SUBSTRING(VAL, CHARINDEX('|', VAL, CHARINDEX('|', VAL) + 1) + 1, 10), 105) AS FechaFin
		FROM [DIS86].[TF_SPLIT](@FECHASEMANA, ',');

		-- Consulta para extraer la fecha de inicio de la primera semana y la fecha de fin de la última semana
		SELECT
		   @FFECHAINICIO = MIN(FechaInicio) ,
		   @FFECHAFIN =  MAX(FechaFin) 
		FROM @SemanaTabla;
		END
		ELSE
		BEGIN
		SET @FFECHAINICIO = NULL;
		SET @FFECHAFIN = NULL;
END
		PRINT @FFECHAINICIO
		PRINT @FFECHAFIN
DECLARE @OMITIR_FECHA BIT = 0;

IF @FECHASEMANA = '0'
BEGIN
    SET @OMITIR_FECHA = 1;
END
print 'lego'
SET @SQL = 'SELECT  DISTINCT
			         ISNULL(VTT.ESTADO_VISITA,''PEN'') ESTADO
			        ,EC.CLIENTE
			        ,EC.CLI_NOMBRE
			        ,EC.ALIAS
			        ,EC.COD_VENDEDOR
			        ,EC.NOMBRE_VENDEDOR
			        ,EC.VEN_NOMBRE
			        ,EC.EMAIL
			        ,EC.TELEFONO
			        ,EC.CONDICION_PAGO
			        ,EC.DIAS_NETO
			        ,EC.SALDO
			        ,CONVERT(VARCHAR,VTT.FECHA_VISITA,105) FECHA_ULTIMA_VISITA
			        ,EC.SEMANA
			        ,ISNULL(VTT.COLOR_HEXA,''label-light-danger'') COLOR_HEXA
			        ,EC.U_ORDEN_VISITA
					,VTT.ID_VISITA
					,EC.COBRADOR
					,EC.COD_NOMBRE_COBRADOR
					,EC.DOC_VENC
					
		FROM        [DIS86].[VIEW_OBT_DATOS_CLIENTE_ESTADO_CUENTA_DEBITOS_CLIENTE] EC
		LEFT JOIN  (SELECT TOP (1) VT.*
				FROM [DIS86].[VIEW_OBT_DATOS_VISITA] VT
				WHERE VT.FECHA_VISITA BETWEEN CAST( @FFECHAINICIO  AS DATE) AND CAST( @FFECHAFIN AS DATE) OR @OMITIR_FECHA = 1				
				ORDER BY VT.ID_VISITA DESC
				) VTT ON  VTT.CLIENTE= EC.CLIENTE
				
		WHERE      
		           (EC.CONDICION_PAGO = @CONDICION_PAGO OR  @CONDICION_PAGO = ''0'')
		  AND      (EC.ESTADO         = @ESTADO_VISTA   OR  @ESTADO_VISTA   = ''0'') 
		  AND      (EC.COD_VENDEDOR   = @VENDEDOR       OR  @VENDEDOR       = ''0'' OR @VENDEDOR =''ND'')
		  AND      (EC.COBRADOR       = @COBRADOR       OR  @COBRADOR       = ''0'')
		  AND      (EC.CLIENTE        = @CLIENTE        OR  @CLIENTE        = ''0'')
		  AND (
    EXISTS (
        SELECT 1
        FROM DIS86.TF_SPLIT(EC.SEMANA, '','') AS S
        WHERE S.VAL IN (SELECT VAL FROM DIS86.TF_SPLIT(@SEMANA, '',''))
    )
    OR @SEMANA LIKE ''%0%''
)
AND (
    EXISTS (
        SELECT 1
        FROM DIS86.TF_SPLIT(EC.DIAS_RUTA, '','') AS D
        WHERE D.VAL IN (SELECT VAL FROM DIS86.TF_SPLIT(@DIA_SEMANA, '',''))
    )
    OR @DIA_SEMANA LIKE ''%0%''
)

		  '
		+ @SALDO + ''
		
SET @PARAM = '@SEMANA VARCHAR(100),
               @DIA_SEMANA VARCHAR(8),
               @SALDO VARCHAR(100),
               @CONDICION_PAGO VARCHAR(4),
               @ESTADO_VISTA VARCHAR(10),
               @VENDEDOR VARCHAR(4),
               @COBRADOR VARCHAR(4),
               @CLIENTE VARCHAR(20),
               @FFECHAINICIO VARCHAR(100),
               @FFECHAFIN VARCHAR(100),
               @FECHASEMANA VARCHAR(MAX),
               @OMITIR_FECHA BIT'
			   PRINT @SQL
INSERT INTO @TABLE EXEC sp_executesql 
    @SQL,
    @PARAM,
    @SEMANA = @SEMANA,
    @DIA_SEMANA = @DIA_SEMANA,
    @SALDO = @SALDO,
    @CONDICION_PAGO = @CONDICION_PAGO,
    @ESTADO_VISTA = @ESTADO_VISTA,
    @VENDEDOR = @VENDEDOR,
    @COBRADOR = @COBRADOR,
    @CLIENTE = @CLIENTE,
    @FFECHAINICIO = @FFECHAINICIO,
    @FFECHAFIN = @FFECHAFIN,
    @FECHASEMANA = @FECHASEMANA,
    @OMITIR_FECHA = @OMITIR_FECHA


SELECT * FROM @TABLE
ORDER BY U_ORDEN_VISITA

END 
GO
