GO
CREATE  PROCEDURE [GLOBAL].[PROC_AVISO_APLICACION_DOCUMENTO]
( 
@DOCUMENTO VARCHAR(50),
@CLIENTE VARCHAR(4),
@COBRADOR VARCHAR(4),
@TIPO_CREDITO VARCHAR(4),
@TIPO_DEBITO VARCHAR(4)
)
AS
BEGIN
    
	DECLARE @VALIDO INT,
	
	@varAsunto varchar(100),
	@cuerpo varchar(Max),
	@NOMBRE VARCHAR(max),
	@DESCRIPCION_ESTADO VARCHAR(100),
	@NOMBRE_COBRADOR VARCHAR(250), @CORREO_CLIENTE VARCHAR(250), @NOMBRE_CLIENTE VARCHAR(250),@CONCEPTO VARCHAR(8000),@CORREO_COBRADOR VARCHAR(800)


	   SET @VALIDO=1
	   SELECT 
	          @NOMBRE_COBRADOR = CONCAT(COBRADOR, ' | ' , NOMBRE),
			  @CORREO_COBRADOR = E_MAIL
	   FROM   EXACTUSERP.DIS86.COBRADOR 
	   WHERE  COBRADOR = @COBRADOR
	   
	    SET @CONCEPTO = (
		                 (SELECT STUFF(
                         (SELECT DISTINCT ', ' + DEBITO 
                          FROM EXACTUSERP.DIS86.AUXILIAR_CC 
                          WHERE CREDITO      = @DOCUMENTO 
                          AND   TIPO_CREDITO = @TIPO_CREDITO 
                          AND   TIPO_DEBITO  = @TIPO_DEBITO FOR XML PATH('')),1, 2, '') AS Factura)
						  )
	   
	   SELECT  @CORREO_CLIENTE = 'rbarrientos@produsoft-businessintelligence.com', --E_MAIL,
	           @NOMBRE_CLIENTE = NOMBRE  
	   FROM EXACTUSERP.DIS86.CLIENTE WHERE CLIENTE =@CLIENTE

	   SET @TIPO_CREDITO = CASE WHEN @TIPO_CREDITO ='REC' THEN 'Recibo'
	                            WHEN @TIPO_CREDITO ='TEF' THEN 'Transferencia'
						   ELSE      @TIPO_CREDITO END 

    
	
	   
	   

SET @varAsunto = 'Aplicación de Documento'  

SET @cuerpo =  
