	@NOMBRE_COBRADOR VARCHAR(250), @CORREO_CLIENTE VARCHAR(250), @NOMBRE_CLIENTE VARCHAR(250),@CONCEPTO VARCHAR(8000),@CORREO_COBRADOR VARCHAR(800)


	   SET @VALIDO=1
	   SELECT 
	         @NOMBRE_COBRADOR = CONCAT(COBRADOR,'|', NOMBRE),
			 @CORREO_COBRADOR = E_MAIL
	   FROM   EXACTUSERP.DIS86.COBRADOR 
	   WHERE  COBRADOR= @COBRADOR
	   
	   SET @CONCEPTO = (SELECT CONCEPTO FROM DIS86.DOCUMENTOS WHERE DOCUMENTO= @DOCUMENTO)
	   
	   SELECT  @CORREO_CLIENTE = 'rbarrientos@produsoft-businessintelligence.com', --E_MAIL,
	           @NOMBRE_CLIENTE = NOMBRE  
	   FROM EXACTUSERP.DIS86.CLIENTE WHERE CLIENTE =@CLIENTE

	   SET @TIPO = CASE WHEN @TIPO ='REC' THEN 'Recibo'
	                    WHEN @TIPO ='TEF' THEN 'Transferencia'
						ELSE @TIPO END 

SET @varAsunto = 'Creación de Documento'  

SET @cuerpo =  
 ' 
