CREATE PROCEDURE [GLOBAL].[PROC_CREA_MENSAJERIA] (@VAR_PEDIDO INT,@CIA VARCHAR(20))
AS  -- POR REVISAR. FALTA DE PARAMETROS Y EL CLIENTE CUSTOMIZA

 BEGIN

DECLARE @TABLEHTML NVARCHAR(MAX),@CONSULTA NVARCHAR(MAX),@CONSECUTIVO AS VARCHAR(50), --,@TOTAL AS DECIMAL(28,8),@SUBTOTALPEDIDO AS DECIMAL(28,8),@IMPUESTO AS DECIMAL(28,8),@DESCUENTO AS DECIMAL(28,8),@TRANSPORTE AS DECIMAL(28,8),
		@TRANSPORTE AS VARCHAR(36),@CLIENTE AS VARCHAR(200),  @TOTAL AS VARCHAR(36),@SUBTOTALPEDIDO AS VARCHAR(36),@IMPUESTO AS VARCHAR(36),@DESCUENTO AS VARCHAR(36),
		@USUARIO_CREACION AS VARCHAR(200),@DESCRIPCION AS VARCHAR(600),@DIR_ENTREGA VARCHAR(1500),@FECHA_CREACION AS VARCHAR(15), @CORREO_CLIENTE VARCHAR(250), 
		@CORREO_VENDEDOR VARCHAR(250),@VARASUNTO VARCHAR(100),@COMENTARIO VARCHAR(500)
 
	SELECT 
		 @CONSECUTIVO		=	I.[CONSECUTIVO] 
		,@DESCRIPCION		=	REPLACE(I.OBSERVACIONES,'REF:EN DESARROLLO','')+CASE WHEN I.CODIGO_AUTORIZACION IS NULL THEN  '' ELSE 'REF:'+CONVERT(VARCHAR(50), I.CODIGO_AUTORIZACION)END --I.[OBSERVACIONES]
		,@DIR_ENTREGA		=	ISNULL(I.[ENTREGA_EN],'SIN ENTREGA') 
		,@CLIENTE			=	I.RUBRO2--(CASE WHEN I.CLIENTE = '02892' THEN  (SELECT NOMBRE FROM  EC.USUARIO_ADICIONALES  UA WHERE UA.USUARIO = I.USUARIO_CREACION) ELSE (SELECT NOMBRE FROM  EC.USUARIO_ADICIONALES  UA WHERE I.CLIENTE = UA.CLIENTE_EXACTUSERP) END) 
		,@FECHA_CREACION	=   CONVERT(VARCHAR(15),I.[FECHA],103)
		,@USUARIO_CREACION  =   I.[USUARIO_CREACION] 
		,@CORREO_VENDEDOR	=	'notificaciones@babariacostarica.com'--ISNULL(V.E_MAIL ,'notificaciones@babariacostarica.com')
		,@CORREO_CLIENTE	=  CASE WHEN I.CLIENTE = 'CL99999' THEN -- CLIENTE DE CONTADO.
									(SELECT TOP 1 CORREO FROM [GLOBAL].[USUARIO_ADICIONALES] WHERE USUARIO = I.USUARIO_CREACION )
									ELSE
									(SELECT TOP 1 CORREO FROM [GLOBAL].[USUARIO_ADICIONALES] WHERE CLIENTE_EXACTUSERP =  I.CLIENTE )
									--CASE WHEN UA.CORREO = ' ' THEN 'notificaciones@babariacostarica.com'
									--WHEN UA.CORREO IS NULL THEN 'notificaciones@babariacostarica.com'
									--ELSE UA.CORREO END 
									END
		,@DESCUENTO = CONVERT(VARCHAR(50), CAST(I.DESCUENTO AS MONEY), -1) 
		,@IMPUESTO = CONVERT(VARCHAR(50), CAST(I.IMPUESTO AS MONEY), -1)
		,@SUBTOTALPEDIDO =CONVERT(VARCHAR(50), CAST(I.[TOTAL] AS MONEY), -1) --((I.TOTAL -I.IMPUESTO)+I.DESCUENTO)
		,@TOTAL				=	CONVERT(VARCHAR(50), CAST(((I.[TOTAL]+I.IMPUESTO)-I.DESCUENTO) AS MONEY), -1) 
		,@COMENTARIO = ISNULL(I.COMENTARIO,'') 
		--SELECT *
		FROM	DIS86.PEDIDO I
				--LEFT JOIN EXACTUSERP.NARGA.CLIENTE CLI ON CLI.CLIENTE = I.CLIENTE
				--LEFT JOIN EC.USUARIO_ADICIONALES  UA ON CASE WHEN I.CLIENTE = '02892' THEN UA.USUARIO = I.USUARIO_CREACION ELSE I.CLIENTE = UA.IDENTIFICACION END
				LEFT JOIN EXACTUSERP.DIS86.VENDEDOR V ON I.VENDEDOR = V.VENDEDOR
			WHERE I.PEDIDO = @VAR_PEDIDO--17 -- SELECT PEDIDO FROM EC.PEDIDO WHERE CONSECUTIVO = 'DIS86-00000006'
  --SELECT @CONSECUTIVO CONSE, @DESCRIPCION DESCR, @DIR_ENTREGA DIRENT, @TOTAL TOTAL, @CLIENTE CLIEN, @FECHA_CREACION FEC, @USUARIO_CREACION UCREAC, @CORREO_VENDEDOR CODVENDE, @CORREO_CLIENTE CORRCLI, @DESCUENTO DESCU,@IMPUESTO IMPU, @SUBTOTALPEDIDO SUBTOTAL

	-- OBTENEMOS EL TRANSPORTE.
	SET @TRANSPORTE = (SELECT CONVERT(VARCHAR(36), CAST(ISNULL(MIN([PRECIO_UNITARIO]),0) AS MONEY), -1)  FROM [DIS86].[PEDIDO_LINEA] WHERE PEDIDO= @VAR_PEDIDO AND ARTICULO_EXACTUSERP = 'SER00190')
	SET @VARASUNTO = 'PEDIDO PORTAL DE CLIENTE: '+ @CONSECUTIVO
	  
	IF(LEN(@DESCRIPCION) < 1)
	BEGIN
		SET @DESCRIPCION  = 'DESDE PORTAL DE CLIENTE' 
	END  

  DECLARE @CODIGOA VARCHAR(50) ,@DESCRIPCION_ARTI VARCHAR(500),@CANTIDAD VARCHAR(50),@PRECIO VARCHAR(50),@SUBTOTAL VARCHAR(50),@DATOS VARCHAR(MAX); 
  SET @DATOS = '';
  DECLARE GRUPO CURSOR FOR   
	SELECT	--PL.ARTICULO_EXACTUSERP , 
			A.DESCRIPCION , CONVERT(VARCHAR(50), PL.CANTIDAD, 1) CANTIDAD, CONVERT(VARCHAR(50), CAST(PL.PRECIO_UNITARIO  AS MONEY), -1)PRECIO, CONVERT(VARCHAR(50), 
				CAST((PL.PRECIO_UNITARIO * PL.CANTIDAD)  AS MONEY), -1) SUBTOTAL FROM 
									DIS86.PEDIDO_LINEA PL (nolock) 
									JOIN EXACTUSERP.DIS86.ARTICULO A (nolock) ON PL.ARTICULO_EXACTUSERP = A.ARTICULO
								WHERE
									PEDIDO = @VAR_PEDIDO 

SET @DATOS='';
OPEN GRUPO
FETCH NEXT FROM GRUPO INTO @DESCRIPCION_ARTI, @CANTIDAD, @PRECIO, @SUBTOTAL-- @CODIGOA, 
WHILE @@FETCH_STATUS = 0
BEGIN 
	PRINT  @CODIGOA PRINT @DESCRIPCION_ARTI PRINT @CANTIDAD PRINT @CANTIDAD
	SET @DATOS = @DATOS+'<TR STYLE=''MSO-YFTI-IROW:1;MSO-YFTI-LASTROW:YES;HEIGHT:1.0PT;BORDER: 1PX SOLID #DDDFE1;''>'
	--SET @DATOS = @DATOS+'<TD STYLE="BORDER: 1PX SOLID #DDDFE1;">'+@CODIGOA +'</TD>'
	SET @DATOS = @DATOS+'<TD STYLE="BORDER: 1PX SOLID #DDDFE1;">'+@DESCRIPCION_ARTI+'</TD>'
	SET @DATOS = @DATOS+'<TD STYLE="BORDER: 1PX SOLID #DDDFE1; TEXT-ALIGN:CENTER">'+@CANTIDAD +'</TD>'
	SET @DATOS = @DATOS+'<TD STYLE="BORDER: 1PX SOLID #DDDFE1; TEXT-ALIGN:RIGHT">'+@PRECIO +'</TD>'
	SET @DATOS = @DATOS+'<TD STYLE="BORDER: 1PX SOLID #DDDFE1; TEXT-ALIGN:RIGHT">'+@SUBTOTAL+'</TD>'
	SET @DATOS = @DATOS+'</TR>'
	FETCH NEXT FROM GRUPO INTO @DESCRIPCION_ARTI, @CANTIDAD, @PRECIO, @SUBTOTAL  --  @CODIGOA,
END
CLOSE GRUPO
DEALLOCATE GRUPO 

DECLARE @TEM NVARCHAR(MAX),@TBINFO NVARCHAR(MAX)
SET @TEM =  '<TABLE WIDTH=790 CLASS="MSONORMALTABLE BORDER=0 CELLSPACING=0 CELLPADDING=0" STYLE="BORDER-COLLAPSE:COLLAPSE">
                <THEAD>
