                        <TD STYLE="TEXT-ALIGN:CENTER">SUBTOTAL</TD> 
                    </TR>
                </THEAD>
                <TBODY>' + @DATOS +'
                </TBODY>
            </TABLE>'

SET @TBINFO = '<TABLE>
