GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [GLOBAL].[PROC_DEL_EXPEDIENTE_DIGITAL_PP] 
(
@DOCUMENTO INT,
@CIA VARCHAR(20)
)
AS
BEGIN
	DECLARE @SQL NVARCHAR(MAX), @PARAM NVARCHAR(MAX)
	DECLARE @RESULT INT = 0

	SET @SQL = 'DELETE FROM ['+ISNULL(@CIA, '')+'].[EXPEDIENTE_DIGITAL_PP]
				WHERE EXPEDIENTE_DIGITAL_PP = @DOCUMENTO
				'
	
	SET @PARAM =N'@DOCUMENTO INT'

	EXEC SP_EXECUTESQL	@SQL,@PARAM,@DOCUMENTO

	IF @@ROWCOUNT <> 0
	BEGIN
		SET @RESULT = 1
	END
	ELSE 
	BEGIN
		SET @RESULT = 0
	END

	RETURN @RESULT

END
GO
