/****** Object:  StoredProcedure [GLOBAL].[PROC_EDI_CAMBIAR_CONTRASENA_TOKEN]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE   PROC [GLOBAL].[PROC_EDI_CAMBIAR_CONTRASENA_TOKEN]
    @TOKEN NVARCHAR(500),
    @NUEVA_CONTRASENA NVARCHAR(4000),
    @USUARIO_EJECUCION VARCHAR(100)
AS
BEGIN
    SET NOCOUNT ON;
    BEGIN TRY
        BEGIN TRAN;
        DECLARE @HASH_TOKEN VARBINARY(64);
        DECLARE @USUARIO VARCHAR(50);
        DECLARE @ID_TOKEN_RECUPERACION BIGINT;
        DECLARE @SAL_NUEVA VARBINARY(32);
        DECLARE @HASH_NUEVA VARBINARY(64);

        SET @HASH_TOKEN = GLOBAL.FUNC_HASH_TOKEN(@TOKEN);

        SELECT TOP 1 @ID_TOKEN_RECUPERACION = TR.ID_TOKEN_RECUPERACION, @USUARIO = TR.USUARIO
        FROM GLOBAL.TOKEN_RECUPERACION TR WITH (UPDLOCK, ROWLOCK)
        WHERE TR.HASH_TOKEN = @HASH_TOKEN
          AND TR.USADO = 'N'
          AND TR.FECHA_EXPIRACION_UTC >= SYSUTCDATETIME();

        IF @USUARIO IS NULL
        BEGIN
            ROLLBACK;
            SELECT -1 CODIGO, 'Token invalido o expirado.' MENSAJE;
            RETURN;
        END

        SET @SAL_NUEVA = CRYPT_GEN_RANDOM(32);
        SET @HASH_NUEVA = GLOBAL.FUNC_HASH_CONTRASENA(@NUEVA_CONTRASENA, @SAL_NUEVA);

        MERGE GLOBAL.USUARIO_CREDENCIAL AS DESTINO
        USING (SELECT @USUARIO AS USUARIO) AS ORIGEN
           ON DESTINO.USUARIO = ORIGEN.USUARIO
        WHEN MATCHED THEN
            UPDATE SET HASH_CONTRASENA = @HASH_NUEVA, SAL_CONTRASENA = @SAL_NUEVA, INTENTOS_FALLIDOS = 0, BLOQUEADO_HASTA_UTC = NULL,
                       FECHA_MODIFICACION_UTC = SYSUTCDATETIME(), USUARIO_MODIFICACION = @USUARIO_EJECUCION
        WHEN NOT MATCHED THEN
            INSERT (USUARIO, HASH_CONTRASENA, SAL_CONTRASENA, USUARIO_CREACION)
            VALUES (@USUARIO, @HASH_NUEVA, @SAL_NUEVA, @USUARIO_EJECUCION);

        INSERT INTO GLOBAL.HISTORIAL_CONTRASENA (USUARIO, HASH_CONTRASENA, SAL_CONTRASENA)
        VALUES (@USUARIO, @HASH_NUEVA, @SAL_NUEVA);

        UPDATE GLOBAL.TOKEN_RECUPERACION
           SET USADO = 'S', FECHA_USO_UTC = SYSUTCDATETIME()
         WHERE ID_TOKEN_RECUPERACION = @ID_TOKEN_RECUPERACION;

        COMMIT;
        SELECT 1 CODIGO, 'Contrasena actualizada correctamente.' MENSAJE;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK;
        SELECT -500 CODIGO, ERROR_MESSAGE() MENSAJE;
    END CATCH
END

GO
