CREATE   PROC [GLOBAL].[PROC_EDI_COMPANIA]
    @ID_COMPANIA INT,
    @NOMBRE_COMPANIA VARCHAR(200),
    @ACTIVO VARCHAR(1),
    @USUARIO_EJECUCION VARCHAR(100)
AS
BEGIN
    UPDATE GLOBAL.COMPANIA
       SET NOMBRE_COMPANIA = @NOMBRE_COMPANIA,
           ACTIVO = @ACTIVO,
           FECHA_MODIFICACION_UTC = SYSUTCDATETIME(),
           USUARIO_MODIFICACION = @USUARIO_EJECUCION
     WHERE ID_COMPANIA = @ID_COMPANIA;
    SELECT 1 CODIGO, 'Compania actualizada.' MENSAJE;
END

