/****** Object:  StoredProcedure [GLOBAL].[PROC_EDI_CONCILIACION_BANCARIA]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [GLOBAL].[PROC_EDI_CONCILIACION_BANCARIA]( 
    @CUENTA_BANCARIA VARCHAR(22),
    @CONCILIACION VARCHAR(20),
    @USUARIO VARCHAR(50),
    @DOCUMENTO VARCHAR(50),
    @FECHA VARCHAR(10),
    @CONCEPTO VARCHAR(240),
    @MONTO DECIMAL(28,8),
    @TIPO VARCHAR(3),
    @ID_LINEA VARCHAR(20),
    @CIA VARCHAR(30)
) 
AS
BEGIN
    DECLARE @SQL NVARCHAR(MAX);
    DECLARE @RESULT INT = 0;
    DECLARE @DOC_REPORTADO INT, @MONTO_REPORTADO DECIMAL(28,8);

    -- Obtener el documento reportado y monto
    SET @SQL = '
        SELECT 
            @DOC_REPORTADO = DOC_REPORTADO, 
            @MONTO_REPORTADO = MONTO 
        FROM 
            EXACTUSERP.[' + ISNULL(@CIA, '') + '].MOV_REPORTADOS 
        WHERE 
            NUMERO = @DOCUMENTO
            AND CUENTA_BANCO = @CUENTA_BANCARIA
            AND TIPO_DOCUMENTO = @TIPO';

    EXECUTE SP_EXECUTESQL @SQL, 
        N'@DOC_REPORTADO INT OUTPUT, 
          @MONTO_REPORTADO DECIMAL(28,8) OUTPUT,
          @DOCUMENTO VARCHAR(50),
          @CUENTA_BANCARIA VARCHAR(22),
          @TIPO VARCHAR(3)',
        @DOC_REPORTADO OUTPUT, 
        @MONTO_REPORTADO OUTPUT,
        @DOCUMENTO,
        @CUENTA_BANCARIA,
        @TIPO;

    SET @SQL = '
    BEGIN TRANSACTION
    BEGIN TRY

        -- Actualizar MOV_BANCOS y verificar el número de filas afectadas
        UPDATE EXACTUSERP.[' + ISNULL(@CIA, '') + '].MOV_BANCOS
        SET DOC_REPORTADO = @DOC_REPORTADO,
            MONTO_REPORTADO = @MONTO_REPORTADO,
            CONCILIACION = @CONCILIACION
        WHERE NUMERO = @DOCUMENTO
        AND TIPO_DOCUMENTO = @TIPO
        AND CUENTA_BANCO = @CUENTA_BANCARIA;

        IF @@ROWCOUNT = 0
        BEGIN
            SET @RESULT = 2;
            ROLLBACK;
            RETURN;  -- Salir del procedimiento sin hacer nada más
        END

        -- Si se actualiza MOV_BANCOS, continuar con las demás actualizaciones
        UPDATE EXACTUSERP.[' + ISNULL(@CIA, '') + '].MOV_REPORTADOS
        SET CONCILIACION = @CONCILIACION,
            ESTADO = ''T''
        WHERE DOC_REPORTADO = @DOC_REPORTADO;

        UPDATE [' + ISNULL(@CIA, '') + '].[ESTADO_H2H_LINEAS]
        SET CARGADO_CB = ''SI''
        WHERE ID_LINEA = @ID_LINEA;

        SET @RESULT = 1;
        COMMIT;

    END TRY
    BEGIN CATCH
        ROLLBACK;
        DECLARE @ERR_MSG NVARCHAR(MAX), @ERR_STATE INT, @ERR_SEVERITY INT;
        SELECT @ERR_MSG = ERROR_MESSAGE(), @ERR_STATE = ERROR_STATE(), @ERR_SEVERITY = ERROR_SEVERITY();
        PRINT(@ERR_MSG);
        RAISERROR (@ERR_MSG, @ERR_SEVERITY, @ERR_STATE) WITH NOWAIT;
    END CATCH';

    EXEC SP_EXECUTESQL @SQL,
        N'@CUENTA_BANCARIA VARCHAR(22),
          @USUARIO VARCHAR(50),
          @DOCUMENTO VARCHAR(50),
          @CONCILIACION VARCHAR(20),
          @FECHA VARCHAR(10),
          @CONCEPTO VARCHAR(240),
          @MONTO DECIMAL(28,8),
          @TIPO VARCHAR(3),
          @ID_LINEA VARCHAR(20),
          @RESULT INT OUTPUT,
          @DOC_REPORTADO VARCHAR(20) OUTPUT,
          @MONTO_REPORTADO DECIMAL(28,8) OUTPUT',
        @CUENTA_BANCARIA,
        @USUARIO,
        @DOCUMENTO,
        @CONCILIACION,
        @FECHA,
        @CONCEPTO,
        @MONTO,
        @TIPO,
        @ID_LINEA,
        @RESULT OUTPUT,
        @DOC_REPORTADO OUTPUT,
        @MONTO_REPORTADO OUTPUT;

    RETURN @RESULT;  -- Retornar el resultado final
END


