/****** Object:  StoredProcedure [GLOBAL].[PROC_EDI_NIVEL_PRECIO_DESTINO]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [GLOBAL].[PROC_EDI_NIVEL_PRECIO_DESTINO]
(
    --Parametros a recibir
    @NIVEL_PRECIO_ORIGEN  VARCHAR(50),
    @NIVEL_PRECIO_DESTINO VARCHAR(50),
    @PORCENTAJE INT,
    @CIA VARCHAR(100)
)
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY
        --BEGIN TRAN;

        DECLARE @SQL NVARCHAR(2000),
                @Filas INT;

        SET @SQL = '
                    DECLARE @Filas INT = 0;

                    UPDATE DST
                    SET DST.PRECIO = SRC.PRECIO + (SRC.PRECIO * @PORCENTAJE / 100)
                    FROM ExactusERP.' + @CIA + '.ARTICULO_PRECIO AS DST
                    INNER JOIN ExactusERP.' + @CIA +'.ARTICULO_PRECIO AS SRC
                        ON  SRC.ARTICULO  = DST.ARTICULO
                        AND SRC.NIVEL_PRECIO = @NIVEL_PRECIO_ORIGEN
                    WHERE DST.NIVEL_PRECIO =  @NIVEL_PRECIO_DESTINO;

                    SET @Filas += @@ROWCOUNT;
                    
                    INSERT INTO [ExactusERP].[' + @CIA + '].[ARTICULO_PRECIO]
                               ([NIVEL_PRECIO],[MONEDA],[VERSION],[ARTICULO],[VERSION_ARTICULO],[PRECIO]
                               ,[ESQUEMA_TRABAJO],[MARGEN_MULR],[MARGEN_UTILIDAD],[FECHA_INICIO],[FECHA_FIN]
                               ,[FECHA_ULT_MODIF],[USUARIO_ULT_MODIF],[MARGEN_UTILIDAD_MIN])
                    SELECT @NIVEL_PRECIO_DESTINO, AP.MONEDA, AP.VERSION, AP.ARTICULO, AP.VERSION_ARTICULO, AP.PRECIO + (AP.PRECIO * @PORCENTAJE / 100), 
                        AP.ESQUEMA_TRABAJO, AP.MARGEN_MULR, AP.MARGEN_UTILIDAD, AP.FECHA_INICIO, AP.FECHA_FIN,
                        AP.FECHA_ULT_MODIF, AP.USUARIO_ULT_MODIF, AP.MARGEN_UTILIDAD_MIN
                    FROM [ExactusERP].[' + @CIA + '].[ARTICULO_PRECIO] AP
                    WHERE AP.NIVEL_PRECIO = @NIVEL_PRECIO_ORIGEN
                        AND AP.ARTICULO NOT IN (SELECT AP2.ARTICULO
                                                FROM ExactusERP.' + @CIA + '.ARTICULO_PRECIO AP2
                                                WHERE AP2.NIVEL_PRECIO = @NIVEL_PRECIO_DESTINO);

                    SET @Filas += @@ROWCOUNT;
                    SET @FilasOut = @Filas;'

        EXEC SP_EXECUTESQL @SQL, N'@NIVEL_PRECIO_ORIGEN  VARCHAR(50),
                                    @NIVEL_PRECIO_DESTINO VARCHAR(50),
                                    @PORCENTAJE INT,
                                    @FilasOut INT OUTPUT',
                                    @NIVEL_PRECIO_ORIGEN,
                                    @NIVEL_PRECIO_DESTINO,
                                    @PORCENTAJE,
                                    @FilasOut=@Filas OUTPUT;

        --DECLARE @Filas INT = @@ROWCOUNT;

        --COMMIT TRAN;

        RETURN @Filas
    END TRY
    BEGIN CATCH
        --IF @@TRANCOUNT > 0
        --    ROLLBACK TRAN;

        RETURN 0
    END CATCH
END

GO
