CREATE PROCEDURE [GLOBAL].[PROC_EDI_PEDIDO_LINEA](
@PEDIDO INT,
@PEDIDO_LINEA INT,
@CANTIDAD INT,
@CIA VARCHAR(20)
 )
AS
BEGIN  
DECLARE @SQL NVARCHAR(MAX),@PARAM NVARCHAR(MAX),@CANT_MAX INT  
DECLARE @CLIENTE VARCHAR(20),@ARTICULO VARCHAR(20), @EXISTENCIA INT
    
	SELECT
	      @CLIENTE    =  CLIENTE, 
		  @ARTICULO   =  ARTICULO_EXACTUSERP,
		  @EXISTENCIA =  EXISTENCIA
	FROM  DIS86.PEDIDO AS PED
	JOIN DIS86.PEDIDO_LINEA AS PL ON PED.PEDIDO = PL.PEDIDO
	WHERE PED.PEDIDO =  @PEDIDO 
	--AND ES_BONIFICADO = 'S'

	SET @SQL = 'SELECT @CANT_MAX=COUNT(ARTICULO_EXACTUSERP) 
	             FROM  ['+@CIA+'].PEDIDO_LINEA 
	             WHERE 
				       PEDIDO=@PEDIDO 
				 AND   PEDIDO_LINEA=@PEDIDO_LINEA' 

	SET @PARAM = '@PEDIDO INT,@PEDIDO_LINEA INT ,@CANT_MAX INT OUTPUT' 
	EXEC SP_EXECUTESQL @SQL, @PARAM,@PEDIDO,@PEDIDO_LINEA,@CANT_MAX OUTPUT
 
 
--VERIFICAMOS SI EL ARTICULO EXISTE EN EL CARRITO
IF(@CANT_MAX >= 1) 
     BEGIN 
		 SET @SQL = 'UPDATE ['+@CIA+'].PEDIDO_LINEA  
						SET  CANTIDAD = @CANTIDAD
							WHERE PEDIDO=@PEDIDO AND PEDIDO_LINEA=@PEDIDO_LINEA' 
		SET @PARAM = '@PEDIDO INT,@PEDIDO_LINEA INT,@CANTIDAD INT' 
		EXEC SP_EXECUTESQL @SQL, @PARAM,@PEDIDO,@PEDIDO_LINEA, @CANTIDAD   
		

		-- ACTUALIZAMOS LA LINEA BONIFICADA PARA LUEGO VOLVER A CALCULARLA 

		SET @SQL ='UPDATE ['+@CIA+'].PEDIDO_LINEA
		           SET    CANTIDAD = 0 
		           WHERE 
		                  PEDIDO            = @PEDIDO 
		           AND    ARTICULO_EXACTUSERP = @ARTICULO
		           AND    ES_BONIFICADO     = ''S'''

		 SET @PARAM = '@PEDIDO INT,@ARTICULO VARCHAR(20)' 
		EXEC SP_EXECUTESQL @SQL, @PARAM,@PEDIDO,@ARTICULO 

		-- INSERTAMOS LINEA BONIFICADA SI ES UN REGISTRO NUEVO 

	    EXEC DIS86.PROC_INSERTAR_LINEA_BONIFICADA_PEDIDO @PEDIDO,@CLIENTE,@ARTICULO,@CANTIDAD,@EXISTENCIA

IF(@CANTIDAD < 1)

		BEGIN 
			SET @SQL = 'DELETE FROM ['+@CIA+'].PEDIDO_LINEA 
			            WHERE PEDIDO=@PEDIDO 
						AND   ARTICULO_EXACTUSERP  = @ARTICULO'
						---AND CANTIDAD=0
			SET @PARAM = '@PEDIDO INT,@ARTICULO VARCHAR(20)' 
			EXEC SP_EXECUTESQL @SQL, @PARAM,@PEDIDO,@ARTICULO   
		END
	 END
	 --ELSE 
		--BEGIN
		--DECLARE @AC VARCHAR(7) 
		----(SELECT U_ACTIVDIDAD_ECONOMICA FROM EXACTUSERP.NARGA.ARTICULO WHERE ARTICULO = @ARTICULO_EXACTUSERP) 
		--SET @AC = '519003'

		--	SET @SQL = 'INSERT INTO ['+@CIA+'].[PEDIDO_LINEA]
		--				   ([PEDIDO]
		--				   ,[ARTICULO_EXACTUSERP]
		--				   ,[CANTIDAD]
		--				   ,[ACTIVIDAD_ECONOMICA]
		--				   ,[EXISTENCIA]
		--				   ,[PORC_DESCUENTO]

		--				    )
		--			 VALUES
		--				   (@PEDIDO
		--				   ,@ARTICULO_EXACTUSERP
		--				   ,@CANTIDAD 
		--				   ,@AC
		--				   ,@EXISTENCIA
		--				   ,@PORC_DESCUENTO)'
						   
		--	SET @PARAM = '@PEDIDO INT,@ARTICULO_EXACTUSERP VARCHAR(20),@CANTIDAD INT,@AC VARCHAR(7),@EXISTENCIA INT,@PORC_DESCUENTO  DECIMAL(28,2)' 
		--	EXEC SP_EXECUTESQL @SQL, @PARAM,@PEDIDO ,@ARTICULO_EXACTUSERP ,@CANTIDAD ,@AC,@EXISTENCIA,@PORC_DESCUENTO 
			 
	  --END  
	SELECT 1 RESULTADO  



END 


