CREATE PROCEDURE [GLOBAL].[PROC_EDI_PERMISOS](
	@ROL INT,
    @SEGUIMIENTO_FACTURA_PEDIDO INT, 
    @TRACKING_IN INT,
	@ESTADISTICA INT, 
	@USUARIO INT, 
	@CONFIGURACION INT,
	@CIA VARCHAR(10)
)
AS 
BEGIN
	DECLARE @SQL NVARCHAR(MAX)
	DECLARE @COUNT INT  = 0
	-- MODULO 1 FLETE 
	SET	@SQL = 'UPDATE GLOBAL.[MODULO_X_PERMISO]
				SET    PERMISO   = @SEGUIMIENTO_FACTURA_PEDIDO,
				       SUBMODULO = @SEGUIMIENTO_FACTURA_PEDIDO
				WHERE  ROL       = @ROL AND MODULO = 1
				
				
				UPDATE GLOBAL.[MODULO_X_PERMISO]
				SET    PERMISO   = @TRACKING_IN,
				       SUBMODULO = @TRACKING_IN
				WHERE  ROL       = @ROL AND MODULO = 2
	          
			    UPDATE GLOBAL.[MODULO_X_PERMISO]
				SET   PERMISO   = @ESTADISTICA,
				      SUBMODULO = @ESTADISTICA
				WHERE ROL       = @ROL AND MODULO = 3
				
				UPDATE GLOBAL.[MODULO_X_PERMISO]
				SET    PERMISO   = @USUARIO,
				       SUBMODULO = @USUARIO
				WHERE  ROL       = @ROL AND MODULO = 4


				UPDATE GLOBAL.[MODULO_X_PERMISO]
				SET    PERMISO   = @CONFIGURACION,
				       SUBMODULO = @CONFIGURACION
				WHERE  ROL       = @ROL AND MODULO = 5
				'
	
	EXEC SP_EXECUTESQL	@SQL,
						N'@ROL INT,
						 @SEGUIMIENTO_FACTURA_PEDIDO INT,
						 @TRACKING_IN INT,
						 @ESTADISTICA INT, 
						 @USUARIO INT, 
						 @CONFIGURACION INT',
						 @ROL,
						 @SEGUIMIENTO_FACTURA_PEDIDO,
						 @TRACKING_IN,
						 @ESTADISTICA,
						 @USUARIO,
	                     @CONFIGURACION
	IF @@ROWCOUNT = 0
	BEGIN
		RETURN 0
	END
	ELSE
	BEGIN
		RETURN 1
	END

END


