CREATE PROCEDURE [GLOBAL].[PROC_EDI_PERMISOS_VERSION_NUEVA]
(
	@ROL INT,
	@MODULO INT,
	@SUBMODULO INT,
	@PERMISOS VARCHAR(200),
	@CIA VARCHAR(10)
)
AS 
BEGIN
	DECLARE @SQL NVARCHAR(MAX)
	DECLARE @COUNT INT  = 0
	SET	@SQL = 'UPDATE [GLOBAL].[MODULO_X_PERMISO]
				SET    ACTIVO    = ''S''
				WHERE  ROL       = @ROL 
				AND    MODULO    = @MODULO 
				AND    SUBMODULO = @SUBMODULO 
				AND    PERMISO   IN (SELECT Value FROM dbo.SplitString(@PERMISOS,'',''))
				
				
				SELECT @COUNT = @@ROWCOUNT

				UPDATE [GLOBAL].[MODULO_X_PERMISO]
				SET    ACTIVO    = ''N''
				WHERE  ROL       = @ROL 
				AND    MODULO    = @MODULO 
				AND    SUBMODULO = @SUBMODULO
				AND    PERMISO NOT IN (SELECT Value FROM dbo.SplitString(@PERMISOS,'',''))
				
				
				SELECT @COUNT += @@ROWCOUNT'
	
	EXEC SP_EXECUTESQL	@SQL,
						N'@ROL     INT,
						@MODULO    INT,
						@SUBMODULO INT,
						@PERMISOS VARCHAR(200),
						@COUNT INT OUTPUT',
						@ROL,
						@MODULO,
						@SUBMODULO,
						@PERMISOS,
						@COUNT OUTPUT


	IF @COUNT = 0
	BEGIN
		RETURN 0
	END
	ELSE
	BEGIN
		RETURN 1
	END

END
