CREATE   PROC [GLOBAL].[PROC_EDI_ROL]
    @ROL INT,
    @DESCRIPCION VARCHAR(255),
    @USUARIO_EJECUCION VARCHAR(100)
AS
BEGIN
    UPDATE GLOBAL.ROL
       SET DESCRIPCION = @DESCRIPCION,
           UpdatedBy = @USUARIO_EJECUCION,
           RecordDate = GETDATE()
     WHERE ROL = @ROL;
    SELECT 1 CODIGO, 'Rol actualizado.' MENSAJE;
END

GO
/****** Object:  StoredProcedure [GLOBAL].[PROC_EDI_USUARIO]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE   PROC [GLOBAL].[PROC_EDI_USUARIO]
    @USUARIO VARCHAR(50),
    @CORREO VARCHAR(255),
    @ACTIVO VARCHAR(1),
    @USUARIO_EJECUCION VARCHAR(100)
AS
BEGIN
    UPDATE GLOBAL.USUARIO
       SET ACTIVO = @ACTIVO,
           UpdatedBy = @USUARIO_EJECUCION,
           RecordDate = GETDATE()
     WHERE USUARIO = @USUARIO;

    IF OBJECT_ID('GLOBAL.USUARIO_CORREO', 'U') IS NOT NULL
    BEGIN
        MERGE GLOBAL.USUARIO_CORREO AS DESTINO
        USING (SELECT @USUARIO AS USUARIO, @CORREO AS CORREO) AS ORIGEN
           ON DESTINO.USUARIO = ORIGEN.USUARIO
        WHEN MATCHED THEN
            UPDATE SET CORREO = ORIGEN.CORREO, ACTIVO = CASE WHEN @ACTIVO = 'S' THEN 'S' ELSE DESTINO.ACTIVO END
        WHEN NOT MATCHED THEN
            INSERT (USUARIO, CORREO, ACTIVO)
            VALUES (ORIGEN.USUARIO, ORIGEN.CORREO, 'S');
    END

    SELECT 1 CODIGO, 'Usuario actualizado.' MENSAJE;
END

GO
/****** Object:  StoredProcedure [GLOBAL].[PROC_INS_ARCHIVO_SFTP_H2H]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [GLOBAL].[PROC_INS_ARCHIVO_SFTP_H2H]( 
	@NOMBRE_ARCHIVO VARCHAR(200),
	@ARCHIVO VARCHAR(MAX),
	@CIA VARCHAR(30)
) 
AS
BEGIN
DECLARE @SQL NVARCHAR(MAX)
DECLARE @RESULT INT = 0
SET @SQL = '
				INSERT INTO ['+ISNULL(@CIA,'')+'].[ESTADO_H2H_ARCHIVO]
				(
					NOMBRE_ARCHIVO,
					ARCHIVO
				)
				VALUES (
					@NOMBRE_ARCHIVO,
					@ARCHIVO
				)

				IF(@@ROWCOUNT > 0)
				BEGIN
					SET @RESULT = 1
				END
				ELSE
				BEGIN
					SET @RESULT = 0
				END
				'


	EXEC SP_EXECUTESQL @SQL,N'	@NOMBRE_ARCHIVO VARCHAR(200),
								@ARCHIVO VARCHAR(MAX),
								@RESULT INT OUTPUT',
								@NOMBRE_ARCHIVO,
								@ARCHIVO,
								@RESULT OUTPUT
	RETURN @RESULT
END

