CREATE   PROC [GLOBAL].[PROC_INS_COMPANIA]
    @CODIGO_COMPANIA VARCHAR(20),
    @NOMBRE_COMPANIA VARCHAR(200),
    @USUARIO_EJECUCION VARCHAR(100)
AS
BEGIN
    INSERT INTO GLOBAL.COMPANIA (CODIGO_COMPANIA, NOMBRE_COMPANIA, USUARIO_CREACION)
    VALUES (@CODIGO_COMPANIA, @NOMBRE_COMPANIA, @USUARIO_EJECUCION);
    SELECT 1 CODIGO, 'Compania creada.' MENSAJE;
END

