	,@FECHA VARCHAR(10)
	,@CONCEPTO VARCHAR(240)
	,@MONTO DECIMAL(28,8)
	,@MONEDA VARCHAR(4)
	,@ID_LINEA VARCHAR(20)
	,@CLIENTE VARCHAR(20)
	,@CIA VARCHAR(30)
