AS
BEGIN
DECLARE @SQL NVARCHAR(MAX)
DECLARE @RESULT INT = 0
DECLARE @TIPO_CAMBIO DECIMAL(28,8)

SET @SQL = 'SELECT @TIPO_CAMBIO = EXACTUSERP.['+ISNULL(@CIA,'')+'].SOFTLANDBI_FN_TipoCambioLocal(''USD'', CONVERT(VARCHAR(10), CONVERT(DATE, @FECHA, 103), 23) + '' 23:59:59'')'

