							  @MONEDA
							 ,@FECHA
							 ,@TIPO_CAMBIO OUTPUT

SET @SQL = '
BEGIN TRANSACTION
BEGIN TRY
				INSERT INTO EXACTUSERP.['+ISNULL(@CIA,'')+'].[DOCUMENTOS_CC]
				(
					[DOCUMENTO]
					,[TIPO]
					,[APLICACION]
