					,[FECHA]
					,[MONTO]
					,[SALDO]
					,[MONTO_LOCAL]
					,[SALDO_LOCAL]
					,[MONTO_DOLAR]
					,[SALDO_DOLAR]
					,[MONTO_CLIENTE]
					,[SALDO_CLIENTE]
					,[TIPO_CAMBIO_MONEDA]
					,[TIPO_CAMBIO_DOLAR]
					,[TIPO_CAMBIO_CLIENT]
					,[TIPO_CAMB_ACT_LOC]
					,[TIPO_CAMB_ACT_DOL]
					,[TIPO_CAMB_ACT_CLI]
					,[SUBTOTAL]
					,[DESCUENTO]
					,[IMPUESTO1]
					,[IMPUESTO2]
					,[RUBRO1]
					,[RUBRO2]
					,[MONTO_RETENCION]
					,[SALDO_RETENCION]
					,[DEPENDIENTE]
					,[FECHA_ULT_CREDITO]
					,[CARGADO_DE_FACT]
					,[APROBADO] -- VA N
					,[ASIENTO] -- VA NULL
					,[ASIENTO_PENDIENTE] --DEBE IR EN S
					,[FECHA_ULT_MOD]
					,[NOTAS]
					,[CLASE_DOCUMENTO]
					,[FECHA_VENCE]
					,[NUM_PARCIALIDADES]
					,[USUARIO_ULT_MOD]
					,[CONDICION_PAGO]
					,[MONEDA]
					,[CTA_BANCARIA]
					,[VENDEDOR]
					,[CLIENTE_REPORTE]
					,[CLIENTE_ORIGEN]
					,[CLIENTE]
					,[SUBTIPO]
					,[PORC_INTCTE]
					,[NUM_DOC_CB]
					,[USUARIO_APROBACION]
					,[FECHA_APROBACION]
					,[ANULADO]
					,[PAIS]
					,[DIVISION_GEOGRAFICA1]
					,[DIVISION_GEOGRAFICA2]
					,[BASE_IMPUESTO1]
					,[BASE_IMPUESTO2]
					,[DEPENDIENTE_GP]
					,[SALDO_TRANS]
					,[SALDO_TRANS_LOCAL]
					,[SALDO_TRANS_DOLAR]
					,[TIPO_ASIENTO]
					,[PAQUETE]
					,[SALDO_TRANS_CLI]
					,[FACTURADO]
					,[ENTIDAD_FINANCIERA]
					,[ACTIVIDAD_COMERCIAL]
					,[TIENE_RELACIONADOS]
					,[ES_FACTURA_REEMPLAZO]
					,[PORC_DETRAC]
					,[TIENE_COMPLEMENTO]
					,[IMPUESTO_BOLSA]
					,FORMA_PAGO
				)
				
				
				  SELECT
					 @DOCUMENTO
					  ,@TIPO
					  ,@CONCEPTO
					  ,CONVERT(VARCHAR(10), CONVERT(DATE, @FECHA, 103), 23) 
					  ,CONVERT(VARCHAR(10), CONVERT(DATE, @FECHA, 103), 23) 
					  ,@MONTO
					  ,@MONTO
					  ,CASE WHEN @MONEDA = ''CRC'' THEN @MONTO ELSE @MONTO * @TIPO_CAMBIO END
					  ,CASE WHEN @MONEDA = ''CRC'' THEN @MONTO ELSE @MONTO * @TIPO_CAMBIO END
					  ,CASE WHEN @MONEDA = ''USD'' THEN @MONTO ELSE @MONTO / @TIPO_CAMBIO END
					  ,CASE WHEN @MONEDA = ''USD'' THEN @MONTO ELSE @MONTO / @TIPO_CAMBIO END
					  ,CASE WHEN C.MONEDA = ''USD'' AND @MONEDA = ''USD'' 
								THEN @MONTO 
							 WHEN C.MONEDA = ''USD'' AND @MONEDA = ''CRC'' 
								THEN @MONTO / @TIPO_CAMBIO
							 WHEN C.MONEDA = ''CRC'' AND @MONEDA = ''CRC'' 
								THEN @MONTO
							 WHEN C.MONEDA = ''CRC'' AND @MONEDA = ''USD'' 
								THEN @MONTO * @TIPO_CAMBIO
						ELSE @MONTO
						END
					  ,CASE WHEN C.MONEDA = ''USD'' AND @MONEDA = ''USD'' 
								THEN @MONTO 
							 WHEN C.MONEDA = ''USD'' AND @MONEDA = ''CRC'' 
								THEN @MONTO / @TIPO_CAMBIO
							 WHEN C.MONEDA = ''CRC'' AND @MONEDA = ''CRC'' 
								THEN @MONTO
							 WHEN C.MONEDA = ''CRC'' AND @MONEDA = ''USD'' 
								THEN @MONTO * @TIPO_CAMBIO
						ELSE @MONTO
						END
					  ,CASE WHEN @MONEDA = ''USD'' THEN @TIPO_CAMBIO ELSE 1.00000000 END	
					  ,@TIPO_CAMBIO
					  ,CASE WHEN C.MONEDA = ''USD'' THEN @TIPO_CAMBIO ELSE 1.00000000 END
					  ,CASE WHEN @MONEDA = ''USD'' THEN @TIPO_CAMBIO ELSE 1.00000000 END	
					  ,@TIPO_CAMBIO
					  ,CASE WHEN C.MONEDA = ''USD'' THEN @TIPO_CAMBIO ELSE 1.00000000 END
					  ,@MONTO
					  ,0.00000000
					  ,0.00000000
					  ,0.00000000
					  ,0.00000000
					  ,0.00000000
					  ,0.00000000
					  ,0.00000000
					  ,''N''
					  ,''1980-01-01''
					  ,''N''
					  ,''N''
					  ,NULL 
					  ,''S''
					  ,GETDATE()
					  ,''''[NOTAS]
					  ,''N''
					  ,CONVERT(VARCHAR(10), CONVERT(DATE, @FECHA, 103), 23) 
					  ,0
					  ,@USUARIO
					  ,0
					  ,@MONEDA
					  ,@CUENTA_BANCARIA
					  ,VENDEDOR
					  ,@CLIENTE
					  ,@CLIENTE
					  ,@CLIENTE
					  ,@SUBTIPO
					  ,0.00000000
					  ,@DOCUMENTO
					  ,NULL
					  ,NULL 
					  ,''N''
					  ,''CRI''
					  ,DIVISION_GEOGRAFICA1
					  ,DIVISION_GEOGRAFICA2
					  ,0.00000000
					  ,0.00000000
					  ,''N'' 
					  ,0.00000000 
					  ,0.00000000 
					  ,0.00000000 
					  ,''CC''
					  ,''CC''
					  ,0.00000000
					  ,''N''
					  ,NULL
					  ,''523917''
					  ,''N''
					  ,''N''
					  ,0.00000000
					  ,''N''
					  ,0.00000000
					  ,ISNULL((
							SELECT U_PS_FORMA_PAGO
							FROM ExactusERP.' + @CIA + '.SUBTIPO_DOC_CC
							WHERE TIPO = @TIPO 
								AND SUBTIPO = @SUBTIPO
						), ''04'')
					FROM EXACTUSERP.['+ISNULL(@CIA,'')+'].CLIENTE C
					WHERE C.CLIENTE = @CLIENTE





					  INSERT INTO EXACTUSERP.['+ISNULL(@CIA,'')+'].[MOV_BANCOS]
				(
					 [CUENTA_BANCO]
					,[TIPO_DOCUMENTO]
					,[NUMERO]
					,[SUBTIPO]
					,[FECHA]
					,[PAGADERO_A]
					,[REFERENCIA]
					,[MONTO]
					,[DETALLE]
					,[CONFIRMADO]
					,[ORIGEN]
					,[ASIENTO]
					,[ANULADO]
					,[FCH_HORA_CREACION]
					,[USUARIO_CREACION]
					,[MONTO_ANULADO]
					,[ESTADO]
					,[IMPRESO]
					,[MONTO_REPORTADO]
					,[CLASE_DIF]
					,[ACLARADA_DIF]
					,[CLASE_DOCUMENTO]
					,[MODO_REGISTRO]
					,[LIQUIDADO]
					,[FCH_HORA_MODIFIC]
					,[USUARIO_MODIFIC]
					,[TIPO_CAMBIO_LOCAL]
					,[TIPO_CAMBIO_DOLAR]
					,[APROBADO]
					,[TIPO_ASIENTO]
					,[PAQUETE]
					,[DEPENDIENTE_GP]
					,[FECHA_CONTABLE]
					,[IMPUESTO1]
					,[IMP1_NODES]
					,[CONTRIBUYENTE]
				)
				
				
				  SELECT
					  @CUENTA_BANCARIA
					  ,CASE 
							WHEN @TIPO = ''TEF'' THEN ''T/C''
							ELSE @TIPO
						END
					  ,@DOCUMENTO
					  ,0
					  ,CONVERT(VARCHAR(10), CONVERT(DATE, @FECHA, 103), 23) 
					  ,C.NOMBRE
					  ,@CONCEPTO
					  ,@MONTO
					  ,''T.E.F. generado desde Cuentas por Cobrar''
					  ,''S''
					  ,''CC''
					  ,NULL
					  ,''N''
					  ,GETDATE()
					  ,@USUARIO
					  ,0.00000000
					  ,''N''
					  ,''N''
					  ,0.00000000
					  ,''X''
					  ,''X''
					  ,''N''
					  ,''M''
					  ,''N''
					  ,NULL
					  ,NULL
					  ,CASE WHEN @MONEDA = ''USD'' THEN @TIPO_CAMBIO ELSE 1.00000000 END
					  ,@TIPO_CAMBIO
					  ,''N''
					  ,''CB''
					  ,''CB''
					  ,''N''
					  ,NULL
					  ,0.00000000
					  ,0.00000000
					  ,C.CONTRIBUYENTE

					  FROM EXACTUSERP.['+ISNULL(@CIA,'')+'].CLIENTE C
					  WHERE C.CLIENTE = @CLIENTE


					  UPDATE ['+ISNULL(@CIA,'')+'].[ESTADO_H2H_LINEAS]
					  SET CLIENTE = @CLIENTE,
					  TIPO = @TIPO,
					  SUBTIPO = @SUBTIPO
					  WHERE ID_LINEA = @ID_LINEA

	IF @@ROWCOUNT <> 0
	BEGIN
		SET @RESULT = 1
	END
	ELSE
	BEGIN
		SET @RESULT = 0
	END


COMMIT
	
END TRY
BEGIN CATCH
		ROLLBACK;
		DECLARE @ERR_MSG NVARCHAR(MAX),@ERR_STATE INT, @ERR_SEVERITY INT;
		SELECT @ERR_MSG=ERROR_MESSAGE(),@ERR_STATE=ERROR_STATE(), @ERR_SEVERITY=ERROR_SEVERITY();
		PRINT(@ERR_MSG)
		RAISERROR (@ERR_MSG, @ERR_SEVERITY, @ERR_STATE) WITH NOWAIT
END CATCH'


	EXEC SP_EXECUTESQL @SQL,N'@CUENTA_BANCARIA VARCHAR(22)
							,@USUARIO VARCHAR(50)
							,@DOCUMENTO VARCHAR(50)
							,@TIPO VARCHAR(3)
							,@SUBTIPO INT
							,@FECHA VARCHAR(10)
							,@CONCEPTO VARCHAR(240)
							,@MONTO DECIMAL(28,8)
							,@MONEDA VARCHAR(4)
							,@ID_LINEA VARCHAR(20)
							,@CLIENTE VARCHAR(20)
							,@RESULT INT OUTPUT
							,@TIPO_CAMBIO DECIMAL(28,8) OUTPUT',
							 @CUENTA_BANCARIA
							,@USUARIO
							,@DOCUMENTO
							,@TIPO
							,@SUBTIPO
							,@FECHA
							,@CONCEPTO
							,@MONTO
							,@MONEDA
							,@ID_LINEA
							,@CLIENTE
							,@RESULT OUTPUT
							,@TIPO_CAMBIO OUTPUT
	RETURN @RESULT
END

