					  FROM EXACTUSERP.['+ISNULL(@CIA,'')+'].PROVEEDOR P
					  WHERE P.PROVEEDOR = @PROVEEDOR








					    INSERT INTO EXACTUSERP.['+ISNULL(@CIA,'')+'].[MOV_BANCOS]
				(
					 [CUENTA_BANCO]
					,[TIPO_DOCUMENTO]
					,[NUMERO]
					,[SUBTIPO]
					,[FECHA]
					,[PAGADERO_A]
					,[REFERENCIA]
					,[MONTO]
					,[DETALLE]
					,[CONFIRMADO]
					,[ORIGEN]
					,[ASIENTO]
					,[ANULADO]
					,[FCH_HORA_CREACION]
					,[USUARIO_CREACION]
					,[MONTO_ANULADO]
					,[ESTADO]
					,[IMPRESO]
					,[MONTO_REPORTADO]
					,[CLASE_DIF]
					,[ACLARADA_DIF]
					,[CLASE_DOCUMENTO]
					,[MODO_REGISTRO]
					,[LIQUIDADO]
					,[FCH_HORA_MODIFIC]
					,[USUARIO_MODIFIC]
					,[TIPO_CAMBIO_LOCAL]
					,[TIPO_CAMBIO_DOLAR]
					,[APROBADO]
					,[TIPO_ASIENTO]
					,[PAQUETE]
					,[DEPENDIENTE_GP]
					,[FECHA_CONTABLE]
					,[IMPUESTO1]
					,[IMP1_NODES]
					,[CONTRIBUYENTE]
				)
				
				
				  SELECT
					  @CUENTA_BANCARIA
					  ,''T/D''
					  ,@DOCUMENTO
					  ,0
					  ,CONVERT(VARCHAR(10), CONVERT(DATE, @FECHA, 103), 23) 
					  ,P.NOMBRE
					  ,@CONCEPTO
					  ,@MONTO
					  ,''T.E.F. generado desde Cuentas por Pagar''
					  ,''S''
					  ,''CP''
					  ,NULL
					  ,''N''
					  ,GETDATE()
					  ,@USUARIO
					  ,0.00000000
					  ,''N''
					  ,''N''
					  ,0.00000000
					  ,''X''
					  ,''X''
					  ,''N''
					  ,''M''
					  ,''N''
					  ,NULL
					  ,NULL
					  ,CASE WHEN @MONEDA = ''USD'' THEN @TIPO_CAMBIO ELSE 1.00000000 END
					  ,@TIPO_CAMBIO
					  ,''N''
					  ,''CB''
					  ,''CB''
					  ,''N''
					  ,NULL
					  ,0.00000000
					  ,0.00000000
					  ,P.CONTRIBUYENTE

					  FROM EXACTUSERP.['+ISNULL(@CIA,'')+'].PROVEEDOR P
					  WHERE P.PROVEEDOR = @PROVEEDOR


					  UPDATE ['+ISNULL(@CIA,'')+'].[ESTADO_H2H_LINEAS]
					  SET PROVEEDOR = @PROVEEDOR,
					  TIPO = @TIPO,
					  SUBTIPO = @SUBTIPO
					  WHERE ID_LINEA = @ID_LINEA

	IF @@ROWCOUNT <> 0
	BEGIN
		SET @RESULT = 1
	END
	ELSE
	BEGIN
		SET @RESULT = 0
	END


COMMIT
	
END TRY
BEGIN CATCH
		ROLLBACK;
		DECLARE @ERR_MSG NVARCHAR(MAX),@ERR_STATE INT, @ERR_SEVERITY INT;
		SELECT @ERR_MSG=ERROR_MESSAGE(),@ERR_STATE=ERROR_STATE(), @ERR_SEVERITY=ERROR_SEVERITY();
		PRINT(@ERR_MSG)
		RAISERROR (@ERR_MSG, @ERR_SEVERITY, @ERR_STATE) WITH NOWAIT
END CATCH'


	EXEC SP_EXECUTESQL @SQL,N'@CUENTA_BANCARIA VARCHAR(22)
							,@USUARIO VARCHAR(50)
							,@DOCUMENTO VARCHAR(50)
							,@TIPO VARCHAR(3)
							,@SUBTIPO INT
							,@FECHA VARCHAR(10)
							,@CONCEPTO VARCHAR(240)
							,@MONTO DECIMAL(28,8)
							,@MONEDA VARCHAR(4)
							,@ID_LINEA VARCHAR(20)
							,@PROVEEDOR VARCHAR(20)
							,@RESULT INT OUTPUT
							,@TIPO_CAMBIO DECIMAL(28,8) OUTPUT',
							 @CUENTA_BANCARIA
							,@USUARIO
							,@DOCUMENTO
							,@TIPO
							,@SUBTIPO
							,@FECHA
							,@CONCEPTO
							,@MONTO
							,@MONEDA
							,@ID_LINEA
							,@PROVEEDOR
							,@RESULT OUTPUT
							,@TIPO_CAMBIO OUTPUT
	RETURN @RESULT
END

