/****** Object:  StoredProcedure [GLOBAL].[PROC_INS_DOCUMENTO_FUSION]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [GLOBAL].[PROC_INS_DOCUMENTO_FUSION]( 
	 @DOCUMENTO_FUSION VARCHAR(50),
	 @CIA VARCHAR(30)
) 
AS
BEGIN
DECLARE @SQL NVARCHAR(MAX)
DECLARE @RESULT INT = 0

SET @SQL = '
BEGIN TRANSACTION
BEGIN TRY
				INSERT INTO ['+ISNULL(@CIA,'')+'].[ESTADO_H2H_LINEAS]
				(
					 [CUENTA_BANCO]
					,[DOCUMENTO_BANCO]
					,[TIPO]
					,[SUBTIPO]
					,[FECHA_BANCO]
					,[FECHA_CARGA]
					,[PS_86_REFERENCIA]
					,[CREDITO_DEBITO]
					,[MONEDA]
					,[MONTO]	
				)
				SELECT  [CUENTA_BANCO]
					,@DOCUMENTO_FUSION
					,[TIPO]
					,[SUBTIPO]
					,[FECHA_BANCO]
					,GETDATE()
					,''DOCUMENTOS FUSIONADOS '' + @DOCUMENTO_FUSION
					,[CREDITO_DEBITO]
					,[MONEDA]
					,SUM([MONTO])	
				FROM DIS86.[ESTADO_H2H_LINEAS]
				WHERE DOCUMENTO_FUSION = @DOCUMENTO_FUSION
				GROUP BY CUENTA_BANCO, DOCUMENTO_BANCO, TIPO, SUBTIPO, FECHA_BANCO, CREDITO_DEBITO, MONEDA

	IF @@ROWCOUNT <> 0
	BEGIN
		SET @RESULT = 1
	END
	ELSE
	BEGIN
		SET @RESULT = 0
	END


COMMIT
	
END TRY
BEGIN CATCH
		ROLLBACK;
		DECLARE @ERR_MSG NVARCHAR(MAX),@ERR_STATE INT, @ERR_SEVERITY INT;
		SELECT @ERR_MSG=ERROR_MESSAGE(),@ERR_STATE=ERROR_STATE(), @ERR_SEVERITY=ERROR_SEVERITY();
		PRINT(@ERR_MSG)
		RAISERROR (@ERR_MSG, @ERR_SEVERITY, @ERR_STATE) WITH NOWAIT
END CATCH'


	EXEC SP_EXECUTESQL @SQL,N' @DOCUMENTO_FUSION VARCHAR(50),
							   @RESULT INT OUTPUT',
							   @DOCUMENTO_FUSION,
							   @RESULT OUTPUT
	RETURN @RESULT
END

