CREATE   PROCEDURE [GLOBAL].[PROC_INS_DOCUMENTO_MOV_BANCOS]( 
	 @CUENTA_BANCARIA VARCHAR(22)
	,@USUARIO VARCHAR(50)
	,@DOCUMENTO VARCHAR(50)
	,@MONTO DECIMAL(28,8)
	,@MONEDA VARCHAR(4)
	,@TIPO VARCHAR(3)
	,@SUBTIPO INT
	,@FECHA VARCHAR(10)
	,@CONCEPTO VARCHAR(240)
	,@ID_LINEA VARCHAR(20)
	,@CIA VARCHAR(30)
) 
AS
BEGIN
DECLARE @SQL NVARCHAR(MAX)
DECLARE @RESULT INT = 0

SET @SQL = '
BEGIN TRANSACTION
BEGIN TRY
				INSERT INTO EXACTUSERP.['+ISNULL(@CIA,'')+'].[MOV_BANCOS]
				(
					 [CUENTA_BANCO]
					,[TIPO_DOCUMENTO]
					,[NUMERO]
					,[SUBTIPO]
					,[FECHA]
					,[PAGADERO_A]
					,[REFERENCIA]
					,[MONTO]
					,[DETALLE]
					,[CONFIRMADO]
					,[ORIGEN]
					,[ASIENTO]
					,[ANULADO]
					,[FCH_HORA_CREACION]
					,[USUARIO_CREACION]
					,[MONTO_ANULADO]
					,[ESTADO]
					,[IMPRESO]
					,[MONTO_REPORTADO]
					,[CLASE_DIF]
					,[ACLARADA_DIF]
					,[CLASE_DOCUMENTO]
					,[MODO_REGISTRO]
					,[LIQUIDADO]
					,[FCH_HORA_MODIFIC]
					,[USUARIO_MODIFIC]
					,[TIPO_CAMBIO_LOCAL]
					,[TIPO_CAMBIO_DOLAR]
					,[APROBADO]
					,[TIPO_ASIENTO]
					,[PAQUETE]
					,[DEPENDIENTE_GP]
					,[FECHA_CONTABLE]
					,[IMPUESTO1]
					,[IMP1_NODES]
				)
				
				
				  SELECT
					  REPLACE(@CUENTA_BANCARIA,''CR'','''')
					  ,@TIPO
					  ,@DOCUMENTO
					  ,@SUBTIPO
					  ,CONVERT(VARCHAR(10), CONVERT(DATE, @FECHA, 103), 23) 
					  ,CASE WHEN @TIPO = ''T/D'' THEN @CONCEPTO ELSE NULL END
					  ,@CONCEPTO
					  ,@MONTO
					  ,''CARGADO POR MT940 '' + CONVERT(VARCHAR,FORMAT(GETDATE(),''dd/MM/yyyy''))
					  ,''S''
					  ,''CB''
					  ,NULL
					  ,''N''
					  ,GETDATE()
					  ,@USUARIO
					  ,0.00000000
					  ,''N''
					  ,''N''
					  ,0.00000000
					  ,''X''
					  ,''X''
					  ,''N''
					  ,''M''
					  ,''N''
					  ,GETDATE()
					  ,@USUARIO
					  ,CASE WHEN @MONEDA = ''CRC'' THEN 1.00000000 ELSE (SELECT EXACTUSERP.['+ISNULL(@CIA,'')+'].SOFTLANDBI_FN_TipoCambioLocal(''USD'', CONVERT(VARCHAR(10), CONVERT(DATE, @FECHA, 103), 23) + '' 23:59:59'')) END
					  ,(SELECT EXACTUSERP.['+ISNULL(@CIA,'')+'].SOFTLANDBI_FN_TipoCambioLocal(''USD'', CONVERT(VARCHAR(10), CONVERT(DATE, @FECHA, 103), 23) + '' 23:59:59''))
					  ,''N''
					  ,''CB''
					  ,''CB''
					  ,''N''
					  ,CONVERT(VARCHAR(10), CONVERT(DATE, @FECHA, 103), 23) 
					  ,0.00000000
					  ,0.00000000


					  UPDATE ['+ISNULL(@CIA,'')+'].[ESTADO_H2H_LINEAS]
					  SET CARGADO_ERP = ''SI'',
					  TIPO = @TIPO,
					  SUBTIPO = @SUBTIPO,
					  DOCUMENTO = @DOCUMENTO
					  WHERE ID_LINEA = @ID_LINEA

	IF @@ROWCOUNT <> 0
	BEGIN
		SET @RESULT = 1
	END
	ELSE
	BEGIN
		SET @RESULT = 0
	END


COMMIT
	
END TRY
BEGIN CATCH
		ROLLBACK;
		DECLARE @ERR_MSG NVARCHAR(MAX),@ERR_STATE INT, @ERR_SEVERITY INT;
		SELECT @ERR_MSG=ERROR_MESSAGE(),@ERR_STATE=ERROR_STATE(), @ERR_SEVERITY=ERROR_SEVERITY();
		PRINT(@ERR_MSG)
		RAISERROR (@ERR_MSG, @ERR_SEVERITY, @ERR_STATE) WITH NOWAIT
END CATCH'


	EXEC SP_EXECUTESQL @SQL,N'@CUENTA_BANCARIA VARCHAR(22)
							,@USUARIO VARCHAR(50)
							,@DOCUMENTO VARCHAR(50)
							,@MONTO DECIMAL(28,8)
							,@MONEDA VARCHAR(4)
							,@TIPO VARCHAR(3)
							,@SUBTIPO INT
							,@FECHA VARCHAR(10)
							,@CONCEPTO VARCHAR(240)
							,@ID_LINEA VARCHAR(20)
							,@RESULT INT OUTPUT',
							 @CUENTA_BANCARIA
							,@USUARIO
							,@DOCUMENTO
							,@MONTO
							,@MONEDA
							,@TIPO
							,@SUBTIPO
							,@FECHA
							,@CONCEPTO
							,@ID_LINEA
							,@RESULT OUTPUT
	RETURN @RESULT
END

