GO
CREATE PROCEDURE [GLOBAL].[PROC_INS_DOCUMENTO_MOV_BANCOS_NUEVO_DOC]( 
	 @CUENTA_BANCARIA VARCHAR(22)
	,@USUARIO VARCHAR(50)
	,@DOCUMENTO VARCHAR(50)
	,@MONTO DECIMAL(28,8)
	,@TIPO VARCHAR(3)
	,@SUBTIPO INT
	,@FECHA DATE
	,@CONCEPTO VARCHAR(240)
	,@BENEFICIARIO VARCHAR(150)
	,@MONEDA VARCHAR(4)
	,@TIPO_CAMBIO_ORIG DECIMAL(28,8)
	,@MONTO_ORIGINAL DECIMAL(28,8)
	,@CIA VARCHAR(30)
) 
AS
BEGIN
DECLARE @SQL NVARCHAR(MAX)
DECLARE @RESULT INT = 0

SET @TIPO = 'DEP'

SET @SQL = '
BEGIN TRANSACTION
BEGIN TRY

				INSERT INTO ExactusERP.['+ISNULL(@CIA,'')+'].[MONEDA_HIST]
					(
							MONEDA
							,FECHA
							,USUARIO
							,MONTO
					)

					SELECT 
						@MONEDA
						,GETDATE()
						,@USUARIO
						,@TIPO_CAMBIO_ORIG



				INSERT INTO ExactusERP.['+ISNULL(@CIA,'')+'].[MOV_BANCOS]
				(
					 [CUENTA_BANCO]
					,[CONTRIBUYENTE]
					,[TIPO_DOCUMENTO]
					,[NUMERO]
					,[SUBTIPO]
					,[FECHA]
					,[PAGADERO_A]
					,[REFERENCIA]
					,[MONTO]
					,[DETALLE]
					,[CONFIRMADO]
					,[ORIGEN]
					,[ASIENTO]
					,[ANULADO]
					,[FCH_HORA_CREACION]
					,[USUARIO_CREACION]
					,[MONTO_ANULADO]
					,[ESTADO]
					,[IMPRESO]
					,[MONTO_REPORTADO]
					,[CLASE_DIF]
					,[ACLARADA_DIF]
					,[CLASE_DOCUMENTO]
					,[MODO_REGISTRO]
					,[LIQUIDADO]
					,[FCH_HORA_MODIFIC]
					,[USUARIO_MODIFIC]
					,[TIPO_CAMBIO_LOCAL]
					,[TIPO_CAMBIO_DOLAR]
					,[APROBADO]
					,[TIPO_ASIENTO]
					,[PAQUETE]
					,[DEPENDIENTE_GP]
					,[FECHA_CONTABLE]
					,[IMPUESTO1]
					,[IMP1_NODES]
					,[DOCUMENTO_FISCAL]
					--,[U_PS_MONEDA_ORIG]
					--,[U_PS_MONTO_ORIG]
					--,[U_PS_TIPOCAMBIO_ORIG] 
				)
				
				
				  SELECT
					   @CUENTA_BANCARIA
					  ,NULL
					  ,@TIPO
					  ,@DOCUMENTO
					  ,@SUBTIPO
			          ,CONVERT(VARCHAR(10), @FECHA, 23) 
					  ,@BENEFICIARIO
					  ,@CONCEPTO
					  ,@MONTO
					  ,''''
					  ,''S''
					  ,''CB''
					  ,NULL
					  ,''N''
					  ,GETDATE()
					  ,@USUARIO
					  ,0.00000000
					  ,''N''
					  ,''N''
					  ,0.00000000
					  ,''X''
					  ,''X''
					  ,''N''
					  ,''M''
					  ,''N''
					  ,GETDATE()
					  ,@USUARIO,
			(SELECT ExactusERP.['+ISNULL(@CIA,'')+'].SoftlandBI_FN_TipoCambioDolar(''USD'', CONVERT(VARCHAR(10), @FECHA, 23) + '' 23:59:59''))
					  ,1.00000000 --REU CON DANIEL, SOFTLAND MANDA UN 1 (SELECT ExactusERP.['+ISNULL(@CIA,'')+'].SoftlandBI_FN_TipoCambioDolar(@MONEDA, CONVERT(VARCHAR(10), CONVERT(DATE, @FECHA, 103), 23) + '' 23:59:59''))
					  ,''N''
					  ,''CB''
					  ,''CB''
					  ,''N''
					  ,CONVERT(VARCHAR(10), CONVERT(DATE, @FECHA, 103), 23) 
					  ,0.00000000
					  ,0.00000000
					  ,@MONTO
					  --,@MONEDA
					  --,@MONTO_ORIGINAL
					  --,@TIPO_CAMBIO_ORIG

					UPDATE ExactusERP.['+ISNULL(@CIA,'')+'].CUENTA_BANCARIA
					SET SALDO = 
						CASE 
							WHEN @TIPO IN (''T/C'', ''N/C'') THEN SALDO + @MONTO
							WHEN @TIPO IN (''T/D'', ''N/D'') THEN SALDO - @MONTO
							ELSE SALDO -- Si el tipo no coincide con ninguna condición, no cambia el saldo
						END,
						POSICION_DE_CAJA = 
						CASE 
							WHEN @TIPO IN (''T/C'', ''N/C'') THEN POSICION_DE_CAJA + @MONTO
							WHEN @TIPO IN (''T/D'', ''N/D'') THEN POSICION_DE_CAJA - @MONTO
							ELSE SALDO -- Si el tipo no coincide con ninguna condición, no cambia el saldo
						END
					WHERE CUENTA_BANCO = @CUENTA_BANCARIA


	IF @@ROWCOUNT <> 0
	BEGIN
		SET @RESULT = 1
	END
	ELSE
	BEGIN
		SET @RESULT = 0
	END


COMMIT
	
END TRY
BEGIN CATCH
		ROLLBACK;
		DECLARE @ERR_MSG NVARCHAR(MAX),@ERR_STATE INT, @ERR_SEVERITY INT;
		SELECT @ERR_MSG=ERROR_MESSAGE(),@ERR_STATE=ERROR_STATE(), @ERR_SEVERITY=ERROR_SEVERITY();
		PRINT(@ERR_MSG)
		RAISERROR (@ERR_MSG, @ERR_SEVERITY, @ERR_STATE) WITH NOWAIT
END CATCH'


	EXEC SP_EXECUTESQL @SQL,N' @CUENTA_BANCARIA VARCHAR(22)
							,@USUARIO VARCHAR(50)
							,@DOCUMENTO VARCHAR(50)
							,@MONTO DECIMAL(28,8)
							,@TIPO VARCHAR(3)
							,@SUBTIPO INT
							,@FECHA DATE
							,@CONCEPTO VARCHAR(240)
							,@BENEFICIARIO VARCHAR(150)
							,@MONEDA VARCHAR(4)
							,@TIPO_CAMBIO_ORIG DECIMAL(28,8)
							,@MONTO_ORIGINAL DECIMAL(28,8)
							,@RESULT INT OUTPUT',
							 @CUENTA_BANCARIA
							,@USUARIO
							,@DOCUMENTO
							,@MONTO
							,@TIPO
							,@SUBTIPO
							,@FECHA
							,@CONCEPTO
							,@BENEFICIARIO
							,@MONEDA
							,@TIPO_CAMBIO_ORIG
							,@MONTO_ORIGINAL
							,@RESULT OUTPUT
	RETURN @RESULT
END

GO
/****** Object:  StoredProcedure [GLOBAL].[PROC_INS_DOCUMENTO_MOV_REPORTADOS]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [GLOBAL].[PROC_INS_DOCUMENTO_MOV_REPORTADOS]( 
	 @CUENTA_BANCARIA VARCHAR(22)
	,@DOCUMENTO VARCHAR(50)
	,@TIPO VARCHAR(3)
	,@FECHA VARCHAR(10)
	,@CONCEPTO VARCHAR(240)
	,@MONTO DECIMAL(28,8)
	,@USUARIO VARCHAR(50)
	,@ID_LINEA VARCHAR(20)
	,@CIA VARCHAR(30)
) 
AS
BEGIN
DECLARE @SQL NVARCHAR(MAX)
DECLARE @RESULT INT = 0
DECLARE @MONEDA VARCHAR(4)
DECLARE @CONSECUTIVO VARCHAR(20)

SET @SQL = 'SELECT TOP 1 @CONSECUTIVO = ISNULL(MAX(DOC_REPORTADO),0) + 1 FROM EXACTUSERP.['+ISNULL(@CIA, '')+'].[MOV_REPORTADOS]'

EXECUTE SP_EXECUTESQL @SQL, N'@CONSECUTIVO VARCHAR(20) OUTPUT',
							  @CONSECUTIVO OUTPUT

SET @SQL = 'SELECT TOP 1 @MONEDA = MONEDA FROM EXACTUSERP.['+ISNULL(@CIA, '')+'].[CUENTA_BANCARIA] WHERE CUENTA_BANCO = @CUENTA_BANCARIA ORDER BY CREATEDATE DESC'

EXECUTE SP_EXECUTESQL @SQL, N'@CUENTA_BANCARIA VARCHAR(22)
							 ,@MONEDA VARCHAR(4) OUTPUT',
							 @CUENTA_BANCARIA,
							 @MONEDA OUTPUT

SET @SQL = '
BEGIN TRANSACTION
BEGIN TRY
				
				INSERT INTO EXACTUSERP.['+ISNULL(@CIA,'')+'].[MOV_REPORTADOS]
				(
					 [DOC_REPORTADO]
					,[CUENTA_BANCO]
					,[TIPO_DOCUMENTO]
					,[NUMERO]
					,[MONTO]
					,[FECHA]
					,[ESTADO]
					,[MODO_REGISTRO]
					,[COMPENSADO]
					,[CONCILIACION]
					,[NOTAS]
					,[FCH_HORA_CREACION]
					,[USUARIO_CREACION]
				)
				
				
				  SELECT
					  @CONSECUTIVO
					  ,@CUENTA_BANCARIA
					  ,@TIPO
					  ,@DOCUMENTO
					  ,@MONTO
					  ,@FECHA 
					  ,''N''
					  ,''M''
					  ,''N''
					  ,NULL
					  ,@CONCEPTO
					  ,GETDATE()
					  ,@USUARIO



				UPDATE ['+ISNULL(@CIA,'')+'].[ESTADO_H2H_LINEAS]
				SET SE_INSERTO_EN_MOV_REPORTADOS = ''S''
				WHERE ID_LINEA = @ID_LINEA



	IF @@ROWCOUNT <> 0
	BEGIN
		SET @RESULT = 1
	END
	ELSE
	BEGIN
		SET @RESULT = 0
	END


COMMIT
	
END TRY
BEGIN CATCH
		ROLLBACK;
		DECLARE @ERR_MSG NVARCHAR(MAX),@ERR_STATE INT, @ERR_SEVERITY INT;
		SELECT @ERR_MSG=ERROR_MESSAGE(),@ERR_STATE=ERROR_STATE(), @ERR_SEVERITY=ERROR_SEVERITY();
		PRINT(@ERR_MSG)
		RAISERROR (@ERR_MSG, @ERR_SEVERITY, @ERR_STATE) WITH NOWAIT
END CATCH'


	EXEC SP_EXECUTESQL @SQL,N' @CUENTA_BANCARIA VARCHAR(22)
							,@DOCUMENTO VARCHAR(50)
							,@TIPO VARCHAR(3)
							,@FECHA VARCHAR(10)
							,@CONCEPTO VARCHAR(240)
							,@MONTO DECIMAL(28,8)
							,@USUARIO VARCHAR(50)
							,@ID_LINEA VARCHAR(20)
							,@RESULT INT OUTPUT
							,@CONSECUTIVO VARCHAR(20) OUTPUT
							,@MONEDA VARCHAR(4) OUTPUT',
							 @CUENTA_BANCARIA
							,@DOCUMENTO
							,@TIPO
							,@FECHA
							,@CONCEPTO
							,@MONTO
							,@USUARIO
							,@ID_LINEA
							,@RESULT OUTPUT
							,@CONSECUTIVO OUTPUT
							,@MONEDA OUTPUT
	RETURN @RESULT
END

GO
/****** Object:  StoredProcedure [GLOBAL].[PROC_INS_DOCUMENTOS]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
