CREATE PROCEDURE [GLOBAL].[PROC_INS_DOCUMENTOS]
(
	@CLIENTE VARCHAR(20),
	@DOCUMENTO VARCHAR(100), 
	@TIPO VARCHAR(3),
	@SUBTIPO INT,
	@CUENTA_BANCARIA VARCHAR(50),
	@FECHA VARCHAR(20),
	@REFERENCIA VARCHAR(50),
	@MONEDA VARCHAR(3),
	@TOTAL_ABONADO DECIMAL(28,8),
	@CONCEPTO VARCHAR(MAX),
	@IMG_COMPROBANTE1 VARCHAR(MAX), -- se debe usar expediente digital 1 y 2 
	@IMG_COMPROBANTE2 VARCHAR(MAX),
	@ID_VISITA INT,
	@VENDEDOR VARCHAR(4),
	@COBRADOR VARCHAR(4), --EN TODO LUGAR DONDE SE MANDA EL VENDEDOR SE MANDA EL COBRADOR.
	@USUARIO VARCHAR(100),
	@COMENTARIOCOB VARCHAR(250),
	@CIA VARCHAR(20)
)
AS 
BEGIN
DECLARE @SQL NVARCHAR(MAX),@PARAM NVARCHAR(MAX),@LAST VARCHAR (15)
DECLARE @USUARIOEXISTE INT,@NUM_DOC_CB DECIMAL(28,0), @TIPO_CAMBIO DECIMAL(28,8)
SET XACT_ABORT ON;

BEGIN TRY
BEGIN TRAN;

-- Recalcula el consecutivo real con la misma formula de PROC_OBT_CONSECUTIVO_DOCUMENTOS_CC.
-- El lock evita que dos guardados del mismo cobrador calculen el mismo siguiente numero.
SET @LAST = (
    SELECT @COBRADOR + RIGHT('000000000' + CAST(CAST(RIGHT(CO.ULTIMO_VALOR, 9) AS BIGINT) + 1 AS VARCHAR), 9)
    FROM EXACTUSERP.DIS86.CONSECUTIVO AS CO WITH (UPDLOCK, HOLDLOCK)
    WHERE CO.CONSECUTIVO = @COBRADOR
);

IF @LAST IS NULL
    THROW 51002, 'El cobrador no tiene un consecutivo asignado.', 1;

SET @DOCUMENTO = @LAST;

IF @TIPO = 'REC'
    SET @REFERENCIA = @DOCUMENTO;

/*
Procesamiento del campo FORMA_PAGO, se hace con base en el tipo y subtipo, si no cumple con las condiciones se asigna el valor 99 que es equivalente a otros	
TABLA DE REFERENCIA: EXACTUSERP.DIS86.FORMAS_PAGO
*/

SET @USUARIOEXISTE =(
						SELECT COUNT(USUARIO) 
						 FROM EXACTUSERP.ERPADMIN.USUARIO  
						 WHERE USUARIO = @USUARIO
					 )

IF @USUARIOEXISTE <> 1 
	BEGIN 
		SET @USUARIO = 'sa'
	END 

SET @SQL = '
	IF EXISTS (SELECT 1 
			   FROM  [' + @CIA + '].[DOCUMENTOS]
			   WHERE TIPO_DOC IN (''TEF'', ''DEP'') 
			   AND   NUM_DOC_CB = @REFERENCIA)

		BEGIN 
			SET @REFERENCIA = CONCAT(@REFERENCIA, FORMAT(GETDATE(), ''ddMMyyyy''));
		END

SELECT @TIPO_CAMBIO =[GLOBAL].[GETTIPOCAMBIOFECHA](''USD'', CONVERT(DATETIME, @FECHA + '' 23:59:59'', 120))'

EXECUTE SP_EXECUTESQL @SQL, N'@MONEDA VARCHAR(4)
						     ,@FECHA VARCHAR(10)
							 ,@REFERENCIA VARCHAR(50) OUTPUT
							 ,@TIPO_CAMBIO DECIMAL(28,8) OUTPUT',
							  @MONEDA
							 ,@FECHA
							 ,@REFERENCIA OUTPUT
							 ,@TIPO_CAMBIO OUTPUT
							 
SET @SQL = N'INSERT INTO EXACTUSERP.['+@CIA+'].[DOCUMENTOS_CC]
           (
		    [DOCUMENTO]
           ,[TIPO]
           ,[APLICACION]
           ,[FECHA_DOCUMENTO]
           ,[FECHA]
           ,[MONTO]
           ,[SALDO]
           ,[MONTO_LOCAL]
           ,[SALDO_LOCAL]
           ,[MONTO_DOLAR]
           ,[SALDO_DOLAR]
           ,[MONTO_CLIENTE]
           ,[SALDO_CLIENTE]
           ,[TIPO_CAMBIO_MONEDA]
           ,[TIPO_CAMBIO_DOLAR]
           ,[TIPO_CAMBIO_CLIENT]
           ,[TIPO_CAMB_ACT_LOC]
           ,[TIPO_CAMB_ACT_DOL]
           ,[TIPO_CAMB_ACT_CLI]
           ,[SUBTOTAL]
           ,[DESCUENTO]
           ,[IMPUESTO1]
           ,[IMPUESTO2]
           ,[RUBRO1]
           ,[RUBRO2]
           ,[MONTO_RETENCION]
           ,[SALDO_RETENCION]
           ,[DEPENDIENTE]
           ,[FECHA_ULT_CREDITO]
           ,[CARGADO_DE_FACT]
           ,[APROBADO]
           ,[ASIENTO_PENDIENTE]
           ,[FECHA_ULT_MOD]
           ,[NOTAS]
           ,[CLASE_DOCUMENTO]
           ,[FECHA_VENCE]
           ,[NUM_PARCIALIDADES]
           ,[COBRADOR]
           ,[USUARIO_ULT_MOD]
           ,[CONDICION_PAGO]
           ,[MONEDA]
           ,[CTA_BANCARIA]
           ,[VENDEDOR]
           ,[CLIENTE_REPORTE]
           ,[CLIENTE_ORIGEN]
           ,[CLIENTE]
           ,[SUBTIPO]
           ,[PORC_INTCTE]
           ,[NUM_DOC_CB]
           ,[USUARIO_APROBACION]
           ,[FECHA_APROBACION]
           ,[ANULADO]
           ,[CODIGO_IMPUESTO]
           ,[PAIS]
           ,[DIVISION_GEOGRAFICA1]
           ,[DIVISION_GEOGRAFICA2]
           ,[BASE_IMPUESTO1]
           ,[BASE_IMPUESTO2]
           ,[DEPENDIENTE_GP]
           ,[SALDO_TRANS]
           ,[SALDO_TRANS_LOCAL]
           ,[SALDO_TRANS_DOLAR]
           ,[TIPO_ASIENTO]
           ,[PAQUETE]
           ,[SALDO_TRANS_CLI]
           ,[FACTURADO]
           ,[GENERA_DOC_FE]
           ,[ENTIDAD_FINANCIERA]
           ,[CLAVE_DE]
           ,[TIPO_IMPUESTO1]
           ,[TIPO_TARIFA1]
           ,[TIPO_IMPUESTO2]
           ,[TIPO_TARIFA2]
           ,[ACTIVIDAD_COMERCIAL]
           ,[ES_FACTURA_REEMPLAZO]
           ,[TIENE_RELACIONADOS]
           ,[PORC_DETRAC]
		   ,[TIENE_COMPLEMENTO]
           ,[IMPUESTO_BOLSA]
		   --,[U_PS_PCW_ID_VISITA] 
		   ,[FORMA_PAGO]
		   )

SELECT TOP(1)				 
		 @DOCUMENTO					                                                                    AS DOCUMENTO
		,@TIPO						                                                                    AS TIPO
		,ISNULL(@CONCEPTO,''ADELANTO'')						                                            AS APLICACION
		,CONVERT(DATE, GETDATE())		                                                                AS FECHA_DOCUMENTO
		,@FECHA 												                                       
		,@TOTAL_ABONADO					                                                                AS MONTO
		,@TOTAL_ABONADO					                                                                AS SALDO
	    ,CASE WHEN @MONEDA  = ''CRC'' THEN @TOTAL_ABONADO ELSE @TOTAL_ABONADO * @TIPO_CAMBIO END        AS MONTO_LOCAL          
		,CASE WHEN @MONEDA  = ''CRC'' THEN @TOTAL_ABONADO ELSE @TOTAL_ABONADO * @TIPO_CAMBIO END        AS SALDO_LOCAL         
		,CASE WHEN @MONEDA  = ''USD'' THEN @TOTAL_ABONADO ELSE @TOTAL_ABONADO / @TIPO_CAMBIO END        AS MONTO_DOLAR
		,CASE WHEN @MONEDA  = ''USD'' THEN @TOTAL_ABONADO ELSE @TOTAL_ABONADO / @TIPO_CAMBIO END        AS SALDO_DOLAR
		,CASE WHEN C.MONEDA = @MONEDA THEN @TOTAL_ABONADO
              WHEN C.MONEDA = ''CRC'' THEN @TOTAL_ABONADO * @TIPO_CAMBIO
              ELSE @TOTAL_ABONADO / @TIPO_CAMBIO END                                                    AS MONTO_CLIENTE        
		,CASE WHEN C.MONEDA = @MONEDA THEN @TOTAL_ABONADO
              WHEN C.MONEDA = ''CRC'' THEN @TOTAL_ABONADO * @TIPO_CAMBIO
         ELSE @TOTAL_ABONADO / @TIPO_CAMBIO END                                                         AS SALDO_CLIENTE        
		,CASE WHEN @MONEDA  = ''CRC'' THEN 1 ELSE  @TIPO_CAMBIO END                                     AS TIPO_CAMBIO_MONEDA
		,@TIPO_CAMBIO					                                                                AS TIPO_CAMBIO_DOLAR	   
		,CASE WHEN C.MONEDA = ''CRC'' THEN 1 ELSE @TIPO_CAMBIO END                                      AS TIPO_CAMBIO_CLIENT
		,CASE WHEN @MONEDA  = ''CRC'' THEN 1 ELSE @TIPO_CAMBIO END                                      AS TIPO_CAMB_ACT_LOC	   
		,@TIPO_CAMBIO					                                                                AS TIPO_CAMB_ACT_DOL
		,CASE WHEN C.MONEDA = ''CRC'' THEN 1 ELSE @TIPO_CAMBIO END                                      AS TIPO_CAMB_ACT_CLI
		,@TOTAL_ABONADO					                                                                AS SUBTOTAL
	    ,0                                                                                              AS DESCUENTO
		,0                                                                                              AS IMPUESTO1
		,0                                                                                              AS IMPUESTO2
		,0                                                                                              AS RUBRO1
		,0                                                                                              AS RUBRO2
		,0                                                                                              AS MONTO_RETENCION 
		,0                                                                                              AS SALDO_RETENCION 
		,''N''	                                                                                        AS DEPENDIENTE           
		,''1980-01-01''																				    AS FECHA_ULT_CREDITO     
		,''N''                                                                                          AS CARGADO_DE_FACT
		,''N''                                                                                          AS APROBADO
		,''S''                                                                                          AS ASIENTO_PENDIENTE
		,GETDATE()                                                                                      AS FECHA_ULT_MOD
		,CASE WHEN @COMENTARIOCOB ='''' THEN ''ADELANTO'' ELSE @COMENTARIOCOB END                       AS NOTAS
		,''N''                                                                                          AS CLASE_DOCUMENTO
		,CONVERT(DATE, GETDATE() + CP.DIAS_NETO)		                                                AS FECHA_VENCE
	    ,0                                                                                              AS NUM_PARCIALIDADES
		,@COBRADOR							                                                            AS COBRADOR              
		,@USUARIO			                                                                            AS USUARIO_ULT_MOD
		,C.CONDICION_PAGO
		,@MONEDA                                                                                        AS MONEDA 
		,CB.CUENTA_BANCO 
		,@VENDEDOR    					                                                                AS VENDEDOR
		,C.CLIENTE							                                                            AS CLIENTE_REPORTE
		,C.CLIENTE							                                                            AS CLIENTE_ORIGEN
		,C.CLIENTE							                                                            AS CLIENTE
		,@SUBTIPO
	    ,0                                                                                              AS PORC_INTCTE	
		,@NUM_DOC_CB																					AS NUM_DOC_CB
		,@USUARIO					                                                                    AS USUARIO_APROBACION
		,CONVERT(DATE, GETDATE())			                                                            AS FECHA_APROBACION
		,''N''                                                                                          AS ANULADO
		,CODIGO_IMPUESTO 								       
		,C.PAIS								                                                            AS PAIS
		,C.DIVISION_GEOGRAFICA1			                                                                AS DIVISION_GEOGRAFICA1
		,C.DIVISION_GEOGRAFICA2			                                                                AS DIVISION_GEOGRAFICA2
		,@TOTAL_ABONADO						                                                            AS BASE_IMPUESTO1
		,@TOTAL_ABONADO						                                                            AS BASE_IMPUESTO2
		,''N''                                                                                          AS DEPENDIENTE_GP
		,0                                                                                              AS SALDO_TRANS
		,0                                                                                              AS SALDO_TRANS_LOCAL 
		,0                                                                                              AS SALDO_TRANS_DOLAR 
		,''CC''                                                                                         AS TIPO_ASIENTO
		,''CC''                                                                                         AS PAQUETE
		,0                                                                                              AS SALDO_TRANS_CLI
		,''N''                                                                                          AS FACTURADO 
		,''S''                                                                                          AS GENERA_DOC_FE 
		,CB.ENTIDAD_FINANCIERA				                                                            AS ENTIDAD_FINANCIERA
		,''''                                                                                           AS CLAVE_DE
	    ,NULL                                                                                           AS TIPO_IMPUESTO1
		,NULL                                                                                           AS TIPO_IMPUESTO2
		,NULL                                                                                           AS TIPO_TARIFA1
		,NULL                                                                                           AS TIPO_TARIFA2
		,''523917''                                                                                     AS ACTIVIDAD_COMERCIAL
		,''N''                                                                                          AS ES_FACTURA_REEMPLAZO
		,''N''                                                                                          AS TIENE_RELACIONADOS
	    ,0                                                                                              AS PORC_DETRAC
		,''N''                                                                                          AS TIENE_COMPLEMENTO
		--,0                                                                                              AS IMPUESTO_BOLSA
		,@ID_VISITA
		,ISNULL((
					SELECT U_PS_FORMA_PAGO
					FROM ExactusERP.' + @CIA + '.SUBTIPO_DOC_CC
					WHERE TIPO = @TIPO 
						AND SUBTIPO = @SUBTIPO
				), ''04'')
FROM 
          
          [EXACTUSERP].['+@CIA+'].[CLIENTE]              C   (NOLOCK) 
     JOIN [EXACTUSERP].['+@CIA+'].[CONDICION_PAGO]       CP  (NOLOCK) ON CP.CONDICION_PAGO = C.CONDICION_PAGO
     JOIN [EXACTUSERP].['+@CIA+'].[MONEDA]               M   (NOLOCK) ON M.MONEDA          = @MONEDA        
     JOIN [EXACTUSERP].['+@CIA+'].[COBRADOR]             CBR (NOLOCK) ON CBR.COBRADOR      = C.COBRADOR
LEFT JOIN [EXACTUSERP].['+@CIA+'].[CUENTA_BANCARIA]      CB  (NOLOCK) ON M.MONEDA          = CB.MONEDA          AND 
                                                                    CB.CUENTA_BANCO   = @CUENTA_BANCARIA 
LEFT JOIN [EXACTUSERP].['+@CIA+'].[SUBTIPO_DOC_CC]       DCC (NOLOCK) ON DCC.SUBTIPO       = @SUBTIPO          

WHERE C.CLIENTE      = @CLIENTE
'


SET @PARAM = '@CLIENTE VARCHAR(20),	
              @DOCUMENTO VARCHAR(100),
			  @TIPO VARCHAR(3),
			  @SUBTIPO INT,
			  @CUENTA_BANCARIA VARCHAR(50),
              @FECHA VARCHAR(20),
			  @REFERENCIA VARCHAR(50),
			  @MONEDA VARCHAR(3),
			  @TOTAL_ABONADO DECIMAL(28,8),
			  @CONCEPTO VARCHAR(MAX),
			  @IMG_COMPROBANTE1 VARCHAR(MAX),
			  @IMG_COMPROBANTE2 VARCHAR(MAX),
			  @VENDEDOR VARCHAR(4),
			  @COBRADOR VARCHAR(4),
			  @USUARIO VARCHAR(100),
			  @COMENTARIOCOB VARCHAR(250),
			  @TIPO_CAMBIO DECIMAL(28,8),
			  @NUM_DOC_CB DECIMAL(28,0),
			  @ID_VISITA INT'


EXEC SP_EXECUTESQL @SQL,@PARAM,
                        @CLIENTE,
						@DOCUMENTO,
						@TIPO,
						@SUBTIPO,
						@CUENTA_BANCARIA,
						@FECHA,
						@REFERENCIA,
						@MONEDA,
                        @TOTAL_ABONADO,
						@CONCEPTO,
						@IMG_COMPROBANTE1,
						@IMG_COMPROBANTE2,
						@VENDEDOR,
						@COBRADOR,
						@USUARIO,
						@COMENTARIOCOB,
						@TIPO_CAMBIO,
						@NUM_DOC_CB,
						@ID_VISITA

------ ACTUALIZAMOS LOS DOCUMENTOS EN TABAL VISITA ---RECIBO, DEPOSITO - NC Y OTROS

SET @SQL =' UPDATE ['+@CIA+'].[VISITAS]
			SET    DOCUMENTO = @DOCUMENTO  
			WHERE  ID_VISITA = @ID_VISITA'
		SET @PARAM = '@DOCUMENTO VARCHAR(50),@ID_VISITA INT'
		EXECUTE SP_EXECUTESQL @SQL,@PARAM,@DOCUMENTO,@ID_VISITA


 -- ---- ACTUALIZAMOS SALDOS EN TABLA CLIENTE 
 
	UPDATE   C 
	SET      C.SALDO =       ISNULL((SELECT (ISNULL(SUM(CC.SALDO),0) - ISNULL((SELECT SUM(SALDO)  FROM EXACTUSERP.DIS86.DOCUMENTOS_CC (NOLOCK) WHERE CC.CLIENTE = CLIENTE AND TIPO IN ('REC','O/C','DEP','TEF','N/C')), 0)) SALDO  FROM EXACTUSERP.DIS86.DOCUMENTOS_CC CC (NOLOCK)
	                                 WHERE    CC.CLIENTE = C.CLIENTE AND CC.TIPO NOT IN ('REC','O/C','DEP','TEF','N/C')
	                                 GROUP BY CC.CLIENTE),0),
			 C.SALDO_DOLAR = ISNULL((SELECT (ISNULL(SUM(CC.SALDO_DOLAR),0) - ISNULL((SELECT SUM(SALDO_DOLAR)  FROM EXACTUSERP.DIS86.DOCUMENTOS_CC (NOLOCK) WHERE CC.CLIENTE = CLIENTE AND TIPO IN ('REC','O/C','DEP','TEF','N/C')), 0)) SALDO_DOLAR  FROM EXACTUSERP.DIS86.DOCUMENTOS_CC CC (NOLOCK)
	                                 WHERE CC.CLIENTE = C.CLIENTE AND CC.TIPO NOT IN ('REC','O/C','DEP','TEF','N/C')
	                                 GROUP BY CC.CLIENTE),0),
			C.SALDO_LOCAL =  ISNULL((SELECT (ISNULL(SUM(CC.SALDO_LOCAL),0) - ISNULL((SELECT SUM(SALDO_LOCAL)  FROM EXACTUSERP.DIS86.DOCUMENTOS_CC (NOLOCK) WHERE CC.CLIENTE = CLIENTE AND TIPO IN ('REC','O/C','DEP','TEF','N/C')), 0)) SALDO_LOCAL  FROM EXACTUSERP.DIS86.DOCUMENTOS_CC CC (NOLOCK)
	                         WHERE   CC.CLIENTE = C.CLIENTE AND CC.TIPO NOT IN ('REC','O/C','DEP','TEF','N/C')
	                         GROUP BY CC.CLIENTE),0)
	FROM  EXACTUSERP.DIS86.CLIENTE AS  C (NOLOCK)
	WHERE C.CLIENTE = @CLIENTE 
	  
	
     

	--UPDATE CLI 
 --    SET SALDO =		CASE
	--					WHEN CC.TIPO NOT IN('REC','O/C','DEP','TEF','N/C') AND CLI.MONEDA <> 'USD' THEN CC.SALDO  - @TOTAL_ABONADO
	--					WHEN CC.TIPO NOT IN('REC','O/C','DEP','TEF','N/C') AND CLI.MONEDA  = 'USD' THEN CC.SALDO  - (@TOTAL_ABONADO/@TIPO_CAMBIO)  --15000 / 513.5
	--					WHEN CC.TIPO IN('REC','O/C','DEP','TEF','N/C')     AND CLI.MONEDA  <> 'USD' THEN CC.SALDO + ABS(@TOTAL_ABONADO)
	--					WHEN CC.TIPO IN('REC','O/C','DEP','TEF','N/C')     AND CLI.MONEDA  = 'USD'  THEN CC.SALDO + ABS(@TOTAL_ABONADO/@TIPO_CAMBIO) END,

	--     SALDO_DOLAR =  CASE
	--				    WHEN CC.TIPO NOT IN('REC','O/C','DEP','TEF','N/C') THEN CC.SALDO_DOLAR - (CASE WHEN @MONEDA     = 'USD' AND 
	--	                                                                                                    CLI.MONEDA  = 'USD' 
	--					  						                                                            THEN ROUND(@TOTAL_ABONADO / @TIPO_CAMBIO,4)  
	--		                                                                                                ELSE ROUND(@TOTAL_ABONADO / @TIPO_CAMBIO,4) END) 
                         
	--					 ELSE CC.SALDO_DOLAR + ABS(CASE WHEN @MONEDA   = 'USD' AND CLI.MONEDA  = 'USD'  
	--					                                THEN ROUND(@TOTAL_ABONADO / @TIPO_CAMBIO,4)  
	--		                                       ELSE ROUND(@TOTAL_ABONADO / @TIPO_CAMBIO,4) END) END,

	--     SALDO_LOCAL =  CASE WHEN CC.TIPO NOT IN('REC','O/C','DEP','TEF','N/C') 
	--	                     THEN CC.SALDO_LOCAL - @TOTAL_ABONADO
	--   				         ELSE CC.SALDO_LOCAL + ABS(@TOTAL_ABONADO) END


	--FROM 
	--     EXACTUSERP.DIS86.CLIENTE  AS CLI
	--JOIN EXACTUSERP.[DIS86].[DOCUMENTOS_CC]    AS CC ON CLI.CLIENTE = CC.CLIENTE
	
	--WHERE CC.DOCUMENTO = @DOCUMENTO
	--AND   CC.CLIENTE   = @CLIENTE
	--AND   CC.TIPO      = @TIPO 
	--AND   CC.SUBTIPO   = @SUBTIPO

	


	---- ACTUALIZAMOS EL SALDO EN TABLA SALDO_CLIENTE 

	UPDATE SC
    SET    SALDO = CASE WHEN CC.TIPO NOT IN('REC','O/C','DEP','TEF','N/C') AND @MONEDA  <> 'USD' THEN SC.SALDO + @TOTAL_ABONADO 
	                    WHEN CC.TIPO NOT IN('REC','O/C','DEP','TEF','N/C') AND @MONEDA  =  'USD' THEN SC.SALDO + (@TOTAL_ABONADO/@TIPO_CAMBIO)
						WHEN CC.TIPO  IN('REC','O/C','DEP','TEF','N/C')    AND @MONEDA  <> 'USD' THEN SC.SALDO - ABS(@TOTAL_ABONADO)
						WHEN CC.TIPO  IN('REC','O/C','DEP','TEF','N/C')    AND @MONEDA  =  'USD' THEN SC.SALDO - (@TOTAL_ABONADO/@TIPO_CAMBIO)
						END   

                        
	FROM 
	       EXACTUSERP.DIS86.SALDO_CLIENTE AS SC
	JOIN   EXACTUSERP.DIS86.DOCUMENTOS_CC AS CC ON SC.CLIENTE = CC.CLIENTE
	WHERE  CC.DOCUMENTO = @DOCUMENTO
	AND    CC.CLIENTE   = @CLIENTE
	AND    CC.TIPO      = @TIPO
	AND    CC.SUBTIPO   = @SUBTIPO
	AND    SC.MONEDA    = @MONEDA


-----ENVIAMOS CORREO 
--IF(@VENDEDOR IS NOT NULL OR @VENDEDOR <>'')
--BEGIN
--EXEC [GLOBAL].[PROC_AVISO_CREO_DOCUMENTO] @DOCUMENTO,@CLIENTE,@VENDEDOR,@TIPO
--END 

------- CONFIRMAMOS EL CONSECUTIVO SOLO SI TODO EL GUARDADO FUE EXITOSO

UPDATE EXACTUSERP.DIS86.CONSECUTIVO
SET    ULTIMO_VALOR = @DOCUMENTO
WHERE  CONSECUTIVO  = @COBRADOR;

COMMIT;
END TRY
BEGIN CATCH
    IF @@TRANCOUNT > 0
        ROLLBACK;
    THROW;
END CATCH

END 
GO
/****** Object:  StoredProcedure [GLOBAL].[PROC_INS_DOCUMENTOS_DET]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

--- [GLOBAL].[PROC_INS_DOCUMENTOS_DET]  'CND000000031','000000002','REC','FAC',0,0,'2024-10-22',100,'DIS86'   

CREATE PROCEDURE [GLOBAL].[PROC_INS_DOCUMENTOS_DET]
(
	@DOCUMENTO_CREDITO VARCHAR(50), 
	@DOCUMENTO_DEBITO VARCHAR(50),
	@TIPO_CREDITO VARCHAR(4),
	@TIPO_DEBITO VARCHAR(4),
	@SUBTIPO_CREDITO INT,
	@SUBTIPO_DEBITO INT,
	@FECHA_CREDITO VARCHAR(20),
	@MONTO_CREDITO DECIMAL(28,8),
	@CIA VARCHAR(20)
)
AS 
BEGIN

DECLARE @SQL NVARCHAR(MAX),@PARAM NVARCHAR(MAX),@LAST VARCHAR (15)
DECLARE @CODIGO_DOC INT, @CLIENTE VARCHAR(10), @COBRADOR VARCHAR(4)
 DECLARE 
        @TIPO_CAMBIO    DECIMAL(28, 8),
        @MONTO_LOCAL    DECIMAL(28, 8),
        @MONTO_DOLAR    DECIMAL(28, 8),
		@MONEDA         VARCHAR(4),
		@FACTOR_CAMBIO  DECIMAL(28,8),
		@TIPO_CAMBIO_MONEDA_CLI DECIMAL(28,8)

-- OBTENEMOS EL CLIENTE DEL DOCUMENTO
SET @CLIENTE =(SELECT TOP 1 CLIENTE 
              FROM   EXACTUSERP.DIS86.DOCUMENTOS_CC 
              WHERE  DOCUMENTO = @DOCUMENTO_CREDITO
			  )


SET @MONEDA =(
              SELECT TOP 1 MONEDA 
              FROM   EXACTUSERP.DIS86.CLIENTE 
              WHERE  CLIENTE = @CLIENTE
)


---- NO TOCAR SP POR FAVOR--------------

-- TIPO DE CAMBIO DOLAR 
SET @SQL = 'SELECT @TIPO_CAMBIO =[GLOBAL].[GETTIPOCAMBIOFECHA](''USD'', CONVERT(DATETIME, @FECHA_CREDITO + '' 23:59:59'', 120))'

EXECUTE SP_EXECUTESQL @SQL, N'@MONEDA VARCHAR(4)
						     ,@FECHA_CREDITO VARCHAR(10)
							 ,@TIPO_CAMBIO DECIMAL(28,8) OUTPUT',
							  @MONEDA
							 ,@FECHA_CREDITO
							 ,@TIPO_CAMBIO OUTPUT

-- FACTOR  DE CAMBIO

SET @SQL = 'SELECT @FACTOR_CAMBIO =EXACTUSERP.['+ISNULL(@CIA,'')+'].SOFTLANDBI_FN_TipoCambioDolar(@MONEDA, CONVERT(DATETIME, @FECHA_CREDITO + '' 23:59:59'', 120))'

EXECUTE SP_EXECUTESQL @SQL, N'@MONEDA VARCHAR(4)
						     ,@FECHA_CREDITO VARCHAR(10)
							 ,@FACTOR_CAMBIO DECIMAL(28,8) OUTPUT',
							  @MONEDA
							 ,@FECHA_CREDITO
							 ,@FACTOR_CAMBIO OUTPUT





-- TIPO DE CAMBIO MONEDA CLIENTE.

SET @SQL = 'SELECT @TIPO_CAMBIO_MONEDA_CLI =[GLOBAL].[GETTIPOCAMBIOFECHA](@MONEDA, CONVERT(DATETIME, @FECHA_CREDITO + '' 23:59:59'', 120))'

EXECUTE SP_EXECUTESQL @SQL, N'@MONEDA VARCHAR(4)
						     ,@FECHA_CREDITO VARCHAR(10)
							 ,@TIPO_CAMBIO_MONEDA_CLI DECIMAL(28,8) OUTPUT',
							  @MONEDA
							 ,@FECHA_CREDITO
							 ,@TIPO_CAMBIO_MONEDA_CLI OUTPUT


 -- Calcular montos locales y en dólares
    SET @MONTO_LOCAL = CASE 
        WHEN @MONEDA = 'CRC' THEN @MONTO_CREDITO  --25
        ELSE @MONTO_CREDITO * @TIPO_CAMBIO  --25 * 513.4 =  12,832 LOCAL
    END

    SET @MONTO_DOLAR = CASE 
        WHEN @MONEDA = 'USD' THEN @MONTO_CREDITO 
        ELSE @MONTO_CREDITO / @TIPO_CAMBIO --0.05
    END


	---- AJUSTES QUE NO CUADRAN DEL ORIGINAL DE JHONNY 

 ----,CASE WHEN DEB.MONEDA  = ''USD'' AND @MONEDA = ''USD''  THEN @MONTO_DOLAR
   ----         WHEN DEB.MONEDA  = ''USD'' AND @MONEDA = ''CRC''  THEN @MONTO_LOCAL * @TIPO_CAMBIO 
   ----         WHEN DEB.MONEDA  = ''CRC'' AND @MONEDA = ''USD''  THEN @MONTO_DOLAR / @TIPO_CAMBIO
   ----         WHEN DEB.MONEDA  = ''CRC'' AND @MONEDA = ''CRC''  THEN @MONTO_LOCAL END              AS MONTO_DEBITO
   	  --,CASE WHEN @MONEDA    = ''USD'' THEN @MONTO_DOLAR ELSE @MONTO_LOCAL END                      AS MONTO_CREDITO



SET @SQL =N'INSERT INTO EXACTUSERP.['+ISNULL(@CIA,'')+'].[AUXILIAR_CC]
			   (
				[TIPO_CREDITO]
			   ,[TIPO_DEBITO]
			   ,[FECHA]
			   ,[CREDITO]
			   ,[DEBITO]
			   ,[MONTO_DEBITO]
			   ,[MONTO_CREDITO]
			   ,[MONTO_LOCAL]
			   ,[MONTO_DOLAR]
			   ,[MONTO_CLI_CREDITO]
			   ,[ASIENTO]
			   ,[MONTO_CLI_DEBITO]
			   ,[MONEDA_CREDITO]
			   ,[MONEDA_DEBITO]
			   ,[CLI_REPORTE_CREDIT]
			   ,[CLI_REPORTE_DEBITO]
			   ,[CLI_DOC_CREDIT]
			   ,[CLI_DOC_DEBITO]
			   ,[FOLIOSAT_DEBITO]
			   ,[FOLIOSAT_CREDITO]
			   ,[TIPO_CAMBIO_APLICA]
			   ,[ES_INT_CORRIENTE]
			   )

	 SELECT 
	   @TIPO_CREDITO			                                                                 AS  [TIPO_CREDITO]
      ,@TIPO_DEBITO				                                                                 AS [TIPO_DEBITO]
      ,GETDATE()                                                                                 AS [FECHA]
	  ,@DOCUMENTO_CREDITO					                                                     AS [CREDITO] 
      ,@DOCUMENTO_DEBITO					                                                     AS [DEBITO]
	  
	  ,CASE WHEN DEB.MONEDA  =  ''USD'' THEN @MONTO_DOLAR 
	        WHEN DEB.MONEDA  <> ''USD'' THEN @MONTO_LOCAL END                                    AS MONTO_DEBITO

	  ,CASE WHEN R.MONEDA  = ''USD''  THEN @MONTO_DOLAR
	        WHEN R.MONEDA <> ''USD''  THEN @MONTO_LOCAL END                                      AS MONTO_CREDITO
	 
	  ,CASE WHEN @MONEDA    = ''USD'' THEN @MONTO_DOLAR * @TIPO_CAMBIO ELSE @MONTO_LOCAL END     AS MONTO_LOCAL
	  ,CASE WHEN DEB.MONEDA = ''USD'' THEN @MONTO_DOLAR ELSE @MONTO_LOCAL / @TIPO_CAMBIO END     AS MONTO_DOLAR
	  ,CASE WHEN @MONEDA    = ''USD'' THEN @MONTO_DOLAR ELSE @MONTO_LOCAL END                    AS MONTO_CLI_CREDITO  --- SE CORRIGE POR QUE SI LA MONEDA DEL CLIENTE ES DIFERENTE A USD SE DEJA EL MONTO LOCAL
	  ,''''													                                     AS [ASIENTO]
	  ,CASE WHEN @MONEDA = ''USD'' THEN @MONTO_DOLAR ELSE @MONTO_LOCAL END                       AS MONTO_CLI_DEBITO   --  SE CORRIGE POR QUE SI LA MONEDA DEL CLIENTE ES DIFERENTE A USD SE DEJA EL MONTO LOCAL
	  ,@MONEDA											                                         AS [MONEDA_CREDITO]
      ,DEB.MONEDA											                                     AS [MONEDA_DEBITO]		 
      ,C.[CLIENTE]                                                                               AS [CLI_REPORTE_CREDIT]
      ,C.[CLIENTE]                                                                               AS [CLI_REPORTE_DEBITO]
      ,C.[CLIENTE]                                                                               AS [CLI_DOC_CREDIT]
      ,C.[CLIENTE]                                                                               AS [CLI_DOC_DEBITO]
	  ,''''[FOLIOSAT_DEBITO]
      ,''''[FOLIOSAT_CREDITO]
	  ,CASE WHEN @MONEDA = ''CRC'' THEN @TIPO_CAMBIO_MONEDA_CLI ELSE @FACTOR_CAMBIO END          AS [TIPO_CAMBIO_APLICA]  -- MONEDA DEL CLIENTE DIFERENTE DE USD APLICA EL TIPO DE CAMBIO EN BASE A LA MONEDA DEL CLIENTE, DE LO CONTRARIO APLICA EL FACTOR.
	  ,''N'' [ES_INT_CORRIENTE]
FROM  EXACTUSERP.['+ISNULL(@CIA,'')+'].[DOCUMENTOS_CC]   R   (NOLOCK) 
JOIN  [EXACTUSERP].['+ISNULL(@CIA,'')+'].[MONEDA]        M   (NOLOCK) ON R.MONEDA      = M.MONEDA
JOIN  [EXACTUSERP].['+ISNULL(@CIA,'')+'].[CLIENTE]       C   (NOLOCK) ON C.CLIENTE     = R.CLIENTE
JOIN  [EXACTUSERP].['+ISNULL(@CIA,'')+'].[DOCUMENTOS_CC] DEB (NOLOCK) ON DEB.DOCUMENTO = @DOCUMENTO_DEBITO AND 
                                                         DEB.TIPO      = @TIPO_DEBITO
WHERE R.DOCUMENTO = @DOCUMENTO_CREDITO
AND   R.TIPO      = @TIPO_CREDITO
AND   NOT EXISTS (SELECT 1 FROM EXACTUSERP.'+ISNULL(@CIA,'')+'.AUXILIAR_CC AS AUX WHERE AUX.CREDITO = @DOCUMENTO_CREDITO AND AUX.TIPO_CREDITO = @TIPO_CREDITO AND AUX.FECHA = GETDATE())

'

      SET @PARAM ='@CODIGO_DOC INT,
                   @DOCUMENTO_CREDITO VARCHAR(50), 
			       @DOCUMENTO_DEBITO VARCHAR(50),
			       @TIPO_CREDITO VARCHAR(4),
			       @TIPO_DEBITO VARCHAR(4),
	               @SUBTIPO_CREDITO INT,
	               @SUBTIPO_DEBITO INT,
	               @FECHA_CREDITO VARCHAR(20),
	               @MONTO_CREDITO DECIMAL(28,8),
				   @TIPO_CAMBIO   DECIMAL(28, 8),
                   @MONTO_LOCAL   DECIMAL(28, 8),
                   @MONTO_DOLAR   DECIMAL(28, 8),
		           @MONEDA        VARCHAR(4),
				   @FACTOR_CAMBIO DECIMAL(28, 8),
				   @TIPO_CAMBIO_MONEDA_CLI DECIMAL(28,8)
				   '
print @sql
EXEC SP_EXECUTESQL @SQL,@PARAM,
                   @CODIGO_DOC,
				   @DOCUMENTO_CREDITO, 
				   @DOCUMENTO_DEBITO,
				   @TIPO_CREDITO,
				   @TIPO_DEBITO,
				   @SUBTIPO_CREDITO,
				   @SUBTIPO_DEBITO,
				   @FECHA_CREDITO,
				   @MONTO_CREDITO,
				   @TIPO_CAMBIO,
                   @MONTO_LOCAL,
                   @MONTO_DOLAR,    
	               @MONEDA,
				   @FACTOR_CAMBIO,
				   @TIPO_CAMBIO_MONEDA_CLI

SET @SQL = 'IF @@ROWCOUNT > 0
				BEGIN
					UPDATE   CC  
					SET      SALDO         = CASE WHEN CC.MONEDA  <> ''USD'' AND @MONEDA <> ''USD'' THEN SALDO - @MONTO_CREDITO             ELSE SALDO - (@MONTO_CREDITO/CC.TIPO_CAMBIO_DOLAR) END,
								SALDO_DOLAR   = CASE WHEN CC.MONEDA  <> ''USD'' THEN SALDO_DOLAR   - (@MONTO_CREDITO / CC.TIPO_CAMBIO_DOLAR) ELSE SALDO_DOLAR  - @MONTO_CREDITO END,
								SALDO_LOCAL   = CASE WHEN CC.MONEDA  <> ''USD'' THEN SALDO_LOCAL   - @MONTO_CREDITO                          ELSE SALDO_LOCAL  - (@MONTO_CREDITO  * TIPO_CAMBIO_MONEDA)  END,
								SALDO_CLIENTE = CASE WHEN CC.MONEDA  <> ''USD'' AND @MONEDA <> ''USD'' THEN SALDO_CLIENTE - @MONTO_CREDITO     ELSE SALDO_CLIENTE - (@MONTO_CREDITO * TIPO_CAMBIO_MONEDA)  END
					FROM EXACTUSERP.'+ISNULL(@CIA,'')+'.DOCUMENTOS_CC AS CC
					WHERE   
								CC.DOCUMENTO = @DOCUMENTO_CREDITO
						AND  CC.TIPO      = @TIPO_CREDITO
						---AND  CC.SUBTIPO   = @SUBTIPO_CREDITO
			
					UPDATE   CC
					SET      SALDO         = CASE WHEN CC.MONEDA  <> ''USD'' AND @MONEDA <> ''USD'' THEN SALDO - @MONTO_CREDITO             ELSE SALDO - (@MONTO_CREDITO/CC.TIPO_CAMBIO_DOLAR) END,
								SALDO_DOLAR   = CASE WHEN CC.MONEDA  <> ''USD'' THEN SALDO_DOLAR   - (@MONTO_CREDITO / CC.TIPO_CAMBIO_DOLAR) ELSE SALDO_DOLAR  - @MONTO_CREDITO END,
								SALDO_LOCAL   = CASE WHEN CC.MONEDA  <> ''USD'' THEN SALDO_LOCAL   - @MONTO_CREDITO                          ELSE SALDO_LOCAL  - (@MONTO_CREDITO  * TIPO_CAMBIO_MONEDA)  END,
								SALDO_CLIENTE = CASE WHEN CC.MONEDA  <> ''USD'' AND @MONEDA <> ''USD'' THEN SALDO_CLIENTE - @MONTO_CREDITO     ELSE SALDO_CLIENTE - (@MONTO_CREDITO * TIPO_CAMBIO_MONEDA)  END 
					FROM  EXACTUSERP.'+ISNULL(@CIA,'')+'.DOCUMENTOS_CC AS CC
					WHERE   
								CC.DOCUMENTO =  @DOCUMENTO_DEBITO
						AND   CC.TIPO      =  @TIPO_DEBITO
						--AND   CC.SUBTIPO   =  @SUBTIPO_DEBITO
				END'

EXEC SP_EXECUTESQL @SQL, 
					N' @DOCUMENTO_CREDITO VARCHAR(50), 
			       @DOCUMENTO_DEBITO VARCHAR(50),
			       @TIPO_CREDITO VARCHAR(4),
			       @TIPO_DEBITO VARCHAR(4),
	               @MONTO_CREDITO DECIMAL(28,8),
		           @MONEDA        VARCHAR(4)',
				   @DOCUMENTO_CREDITO, 
				   @DOCUMENTO_DEBITO,
				   @TIPO_CREDITO,
				   @TIPO_DEBITO,
				   @MONTO_CREDITO,
				   @MONEDA

--IF(@DOCUMENTO_CREDITO IS NOT NULL OR @DOCUMENTO_CREDITO <> '')
--SELECT 
--       @CLIENTE  =  CLIENTE, 
--       @COBRADOR =  COBRADOR
	   
	   
--FROM EXACTUSERP.[DIS86].[DOCUMENTOS_CC]
--WHERE DOCUMENTO = @DOCUMENTO_CREDITO

--EXEC [GLOBAL].[PROC_AVISO_APLICACION_DOCUMENTO] @DOCUMENTO_CREDITO, @CLIENTE,@COBRADOR,@TIPO_CREDITO,@TIPO_DEBITO

END 
GO
/****** Object:  StoredProcedure [GLOBAL].[PROC_INS_DOCUMENTOS_V2]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [GLOBAL].[PROC_INS_DOCUMENTOS_V2]
(
	@CLIENTE          VARCHAR(20),
	@DOCUMENTO        VARCHAR(100), 
	@TIPO             VARCHAR(3),
	@SUBTIPO          INT,
	@CUENTA_BANCARIA  VARCHAR(50),
	@FECHA            VARCHAR(20),   -- dd/MM/yyyy
	@REFERENCIA       VARCHAR(50),
	@MONEDA           VARCHAR(3),    -- 'CRC' | 'USD'
	@TOTAL_ABONADO    DECIMAL(28,8),
	@CONCEPTO         VARCHAR(MAX),
	@IMG_COMPROBANTE1 VARCHAR(MAX),
	@IMG_COMPROBANTE2 VARCHAR(MAX),
	@ID_VISITA        INT,
	@VENDEDOR         VARCHAR(4),
	@COBRADOR         VARCHAR(4),
	@USUARIO          VARCHAR(100),
	@COMENTARIOCOB    VARCHAR(250),
	@CIA              VARCHAR(20),

    -- Detalle de aplicación (opcional)
    -- Ej.: [{"TIPO_DOC":"FAC","DOCUMENTO":"202034507","MONTO_APLICADO":10.00}]
    @DETALLE_APLICACION_JSON NVARCHAR(MAX) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE
        @SQL NVARCHAR(MAX),
        @PARAM NVARCHAR(MAX),
        @LAST VARCHAR(15),
        @USUARIOEXISTE INT,
        @NUM_DOC_CB DECIMAL(28,0),
        @TIPO_CAMBIO DECIMAL(28,8),
        @MONEDA_CLIENTE VARCHAR(4) = NULL,
        @U_PS_ESTADO_LIQUIDACION INT;

    /* 1) Validar usuario */
    SET @USUARIOEXISTE = (SELECT COUNT(USUARIO) FROM EXACTUSERP.ERPADMIN.USUARIO WHERE USUARIO = @USUARIO);
    IF @USUARIOEXISTE <> 1 SET @USUARIO = 'sa';

    /* 2) NUM_DOC_CB desde referencia (si es numérica) */
    SET @NUM_DOC_CB = TRY_CONVERT(DECIMAL(28,0), @REFERENCIA);

    /*2.1 U_PS_ESTADO_LIQUIDACION desde referencia*/
    SET @U_PS_ESTADO_LIQUIDACION = TRY_CONVERT(INT, LTRIM(RTRIM(@REFERENCIA)));

    /* 3) Evitar referencia duplicada en TEF/DEP */
    IF EXISTS (SELECT 1 FROM DIS86.DOCUMENTOS WHERE TIPO_DOC IN ('TEF','DEP') AND NUM_DOC_CB = @REFERENCIA)
        SET @REFERENCIA = CONCAT(@REFERENCIA, FORMAT(GETDATE(), 'ddMMyyyy'));

    /* 4) Tipo de cambio del día (USD) */
    SET @SQL = N'SELECT @TC = [GLOBAL].[GETTIPOCAMBIOFECHA](''USD'', CONVERT(DATETIME, @F + '' 23:59:59'', 120))';
    EXEC sp_executesql
        @SQL,
        N'@F VARCHAR(10), @TC DECIMAL OUTPUT',
        @F=@FECHA, @TC=@TIPO_CAMBIO OUTPUT;

    /* ============================================================
       5) INSERTAR REC/DEP EN DOCUMENTOS_CC
       ============================================================ */
    --SET @SQL = N'
    --INSERT INTO EXACTUSERP.'+QUOTENAME(@CIA)+'.DOCUMENTOS_CC
    --(
    --    [DOCUMENTO],[TIPO],[APLICACION],[FECHA_DOCUMENTO],[FECHA],
    --    [MONTO],[SALDO],
    --    [MONTO_LOCAL],[SALDO_LOCAL],
    --    [MONTO_DOLAR],[SALDO_DOLAR],
    --    [MONTO_CLIENTE],[SALDO_CLIENTE],
    --    [TIPO_CAMBIO_MONEDA],[TIPO_CAMBIO_DOLAR],[TIPO_CAMBIO_CLIENT],
    --    [TIPO_CAMB_ACT_LOC],[TIPO_CAMB_ACT_DOL],[TIPO_CAMB_ACT_CLI],
    --    [SUBTOTAL],[DESCUENTO],[IMPUESTO1],[IMPUESTO2],[RUBRO1],[RUBRO2],
    --    [MONTO_RETENCION],[SALDO_RETENCION],[DEPENDIENTE],[FECHA_ULT_CREDITO],
    --    [CARGADO_DE_FACT],[APROBADO],[ASIENTO_PENDIENTE],[FECHA_ULT_MOD],[NOTAS],
    --    [CLASE_DOCUMENTO],[FECHA_VENCE],[NUM_PARCIALIDADES],[COBRADOR],[USUARIO_ULT_MOD],
    --    [CONDICION_PAGO],[MONEDA],[CTA_BANCARIA],[VENDEDOR],
    --    [CLIENTE_REPORTE],[CLIENTE_ORIGEN],[CLIENTE],
    --    [SUBTIPO],[PORC_INTCTE],[NUM_DOC_CB],[USUARIO_APROBACION],[FECHA_APROBACION],
    --    [ANULADO],[CODIGO_IMPUESTO],[PAIS],[DIVISION_GEOGRAFICA1],[DIVISION_GEOGRAFICA2],
    --    [BASE_IMPUESTO1],[BASE_IMPUESTO2],[DEPENDIENTE_GP],[SALDO_TRANS],
    --    [SALDO_TRANS_LOCAL],[SALDO_TRANS_DOLAR],[TIPO_ASIENTO],[PAQUETE],[SALDO_TRANS_CLI],
    --    [FACTURADO],[GENERA_DOC_FE],[ENTIDAD_FINANCIERA],[CLAVE_DE],[TIPO_IMPUESTO1],
    --    [TIPO_TARIFA1],[TIPO_IMPUESTO2],[TIPO_TARIFA2],[ACTIVIDAD_COMERCIAL],
    --    [ES_FACTURA_REEMPLAZO],[TIENE_RELACIONADOS],[PORC_DETRAC],[TIENE_COMPLEMENTO],
    --    [IMPUESTO_BOLSA]
    --)
    --SELECT TOP(1)
    --    @DOCUMENTO,
    --    @TIPO,
    --    ISNULL(@CONCEPTO,''ADELANTO''),
    --    CONVERT(DATE, GETDATE()),
    --    @FECHA,
    --    @TOTAL_ABONADO,
    --    @TOTAL_ABONADO,
    --    CASE WHEN @MONEDA=''CRC'' THEN @TOTAL_ABONADO ELSE @TOTAL_ABONADO*@TIPO_CAMBIO END,
    --    CASE WHEN @MONEDA=''CRC'' THEN @TOTAL_ABONADO ELSE @TOTAL_ABONADO*@TIPO_CAMBIO END,
    --    CASE WHEN @MONEDA=''USD'' THEN @TOTAL_ABONADO ELSE @TOTAL_ABONADO/@TIPO_CAMBIO END,
    --    CASE WHEN @MONEDA=''USD'' THEN @TOTAL_ABONADO ELSE @TOTAL_ABONADO/@TIPO_CAMBIO END,
    --    CASE WHEN C.MONEDA=@MONEDA THEN @TOTAL_ABONADO
    --         WHEN C.MONEDA=''CRC'' THEN @TOTAL_ABONADO*@TIPO_CAMBIO
    --         ELSE @TOTAL_ABONADO/@TIPO_CAMBIO END,
    --    CASE WHEN C.MONEDA=@MONEDA THEN @TOTAL_ABONADO
    --         WHEN C.MONEDA=''CRC'' THEN @TOTAL_ABONADO*@TIPO_CAMBIO
    --         ELSE @TOTAL_ABONADO/@TIPO_CAMBIO END,
    --    CASE WHEN @MONEDA=''CRC'' THEN 1 ELSE @TIPO_CAMBIO END,
    --    @TIPO_CAMBIO,
    --    CASE WHEN C.MONEDA=''CRC'' THEN 1 ELSE @TIPO_CAMBIO END,
    --    CASE WHEN @MONEDA=''CRC'' THEN 1 ELSE @TIPO_CAMBIO END,
    --    @TIPO_CAMBIO,
    --    CASE WHEN C.MONEDA=''CRC'' THEN 1 ELSE @TIPO_CAMBIO END,
    --    @TOTAL_ABONADO,
    --    0,0,0,0,0,0,0,
    --    ''N'',''1980-01-01'',''N'',''N'',''S'',GETDATE(),
    --    CASE WHEN @COMENTARIOCOB='''' THEN ''ADELANTO'' ELSE @COMENTARIOCOB END,
    --    ''N'', CONVERT(DATE, GETDATE()+CP.DIAS_NETO), 0,
    --    @COBRADOR, @USUARIO, C.CONDICION_PAGO, @MONEDA, CB.CUENTA_BANCO,
    --    @VENDEDOR, C.CLIENTE, C.CLIENTE, C.CLIENTE, @SUBTIPO, 0, @NUM_DOC_CB,
    --    @USUARIO, CONVERT(DATE, GETDATE()), ''N'', CODIGO_IMPUESTO, C.PAIS,
    --    C.DIVISION_GEOGRAFICA1, C.DIVISION_GEOGRAFICA2, @TOTAL_ABONADO, @TOTAL_ABONADO,
    --    ''N'', 0, 0, 0, ''CC'',''CC'', 0, ''N'',''S'', CB.ENTIDAD_FINANCIERA, '''',
    --    NULL, NULL, NULL, NULL, ''523917'', ''N'',''N'', 0, ''N'', 0
    --FROM EXACTUSERP.'+QUOTENAME(@CIA)+'.CLIENTE C (NOLOCK)
    --JOIN EXACTUSERP.'+QUOTENAME(@CIA)+'.CONDICION_PAGO CP (NOLOCK) ON CP.CONDICION_PAGO = C.CONDICION_PAGO
    --JOIN EXACTUSERP.'+QUOTENAME(@CIA)+'.MONEDA M (NOLOCK) ON M.MONEDA = @MONEDA
    --JOIN EXACTUSERP.'+QUOTENAME(@CIA)+'.COBRADOR CBR (NOLOCK) ON CBR.COBRADOR = C.COBRADOR
    --LEFT JOIN EXACTUSERP.'+QUOTENAME(@CIA)+'.CUENTA_BANCARIA CB (NOLOCK)
    --       ON M.MONEDA = CB.MONEDA AND CB.CUENTA_BANCO = @CUENTA_BANCARIA
    --WHERE C.CLIENTE = @CLIENTE;
    --';

    --SET @PARAM = N'
    --    @DOCUMENTO VARCHAR(100), @TIPO VARCHAR(3), @CONCEPTO VARCHAR(MAX),
    --    @FECHA VARCHAR(20), @TOTAL_ABONADO DECIMAL,
    --    @MONEDA VARCHAR(3), @TIPO_CAMBIO DECIMAL,
    --    @COBRADOR VARCHAR(4), @USUARIO VARCHAR(100), @VENDEDOR VARCHAR(4),
    --    @COMENTARIOCOB VARCHAR(250),
    --    @NUM_DOC_CB DECIMAL, @CUENTA_BANCARIA VARCHAR(50),
    --    @CLIENTE VARCHAR(20), @ID_VISITA INT, @SUBTIPO INT';

    --EXEC sp_executesql
    --    @SQL, @PARAM,
    --    @DOCUMENTO=@DOCUMENTO, @TIPO=@TIPO, @CONCEPTO=@CONCEPTO,
    --    @FECHA=@FECHA, @TOTAL_ABONADO=@TOTAL_ABONADO,
    --    @MONEDA=@MONEDA, @TIPO_CAMBIO=@TIPO_CAMBIO,
    --    @COBRADOR=@COBRADOR, @USUARIO=@USUARIO, @VENDEDOR=@VENDEDOR,
    --    @COMENTARIOCOB=@COMENTARIOCOB,
    --    @NUM_DOC_CB=@NUM_DOC_CB, @CUENTA_BANCARIA=@CUENTA_BANCARIA,
    --    @CLIENTE=@CLIENTE, @ID_VISITA=@ID_VISITA, @SUBTIPO=@SUBTIPO;

    /* 6) VISITA */
    SET @SQL = N'UPDATE PS_TRACKING.'+QUOTENAME(@CIA)+N'.VISITAS SET DOCUMENTO=@D WHERE ID_VISITA=@V';
    EXEC sp_executesql @SQL, N'@D VARCHAR(50), @V INT', @D=@DOCUMENTO, @V=@ID_VISITA;

    /* 7) CONSECUTIVO */
    --SET @SQL=N'SET @LAST_O = (
    --    SELECT @COBRADOR + RIGHT(''000000000'' + CAST(CAST(RIGHT(CO.ULTIMO_VALOR,9) AS INT)+1 AS VARCHAR(9)),9)
    --    FROM EXACTUSERP.'+QUOTENAME(@CIA)+N'.CONSECUTIVO CO
    --    WHERE CO.CONSECUTIVO = @COBRADOR_O
    --);
    --  UPDATE EXACTUSERP.'+QUOTENAME(@CIA)+N'.CONSECUTIVO
    --  SET ULTIMO_VALOR = @LAST_O
    --WHERE CONSECUTIVO = @COBRADOR_O;
    --';


    SET @LAST = (
        SELECT @COBRADOR + RIGHT('000000000' + CAST(CAST(RIGHT(CO.ULTIMO_VALOR,9) AS INT)+1 AS VARCHAR(9)),9)
        FROM EXACTUSERP.DIS86.CONSECUTIVO CO
        WHERE CO.CONSECUTIVO = @COBRADOR
    );
    UPDATE EXACTUSERP.DIS86.CONSECUTIVO
      SET ULTIMO_VALOR = @LAST
    WHERE CONSECUTIVO = @COBRADOR;

    /* ============================================================
       8) APLICAR A DOCUMENTOS (bajar SALDO de cada línea del JSON)
       ============================================================ */
    IF (@DETALLE_APLICACION_JSON IS NOT NULL AND LTRIM(RTRIM(@DETALLE_APLICACION_JSON)) <> '')
    BEGIN
        -- 8.1 Parseo
        IF OBJECT_ID('tempdb..#DET') IS NOT NULL DROP TABLE #DET;
        SELECT
            TIPO_DOC,
            DOCUMENTO,
            MONTO_APLICADO = CAST(MONTO_APLICADO AS DECIMAL(28,8))
        INTO #DET
        FROM OPENJSON(@DETALLE_APLICACION_JSON)
        WITH (
            TIPO_DOC       VARCHAR(3)    '$.TIPO_DOC',
            DOCUMENTO      VARCHAR(50)   '$.DOCUMENTO',
            MONTO_APLICADO DECIMAL(28,8) '$.MONTO_APLICADO'
        );

        -- 8.2 Total validar
        DECLARE @APLICA_TOTAL DECIMAL(28,8) = (SELECT ISNULL(SUM(MONTO_APLICADO),0) FROM #DET);
        IF (@APLICA_TOTAL > @TOTAL_ABONADO)
        BEGIN
            DECLARE @msg NVARCHAR(400);
            SET @msg = N'Suma de aplicaciones (' 
                     + CONVERT(NVARCHAR(50), CAST(@APLICA_TOTAL  AS DECIMAL(38,2))) 
                     + N') no puede exceder el total abonado (' 
                     + CONVERT(NVARCHAR(50), CAST(@TOTAL_ABONADO AS DECIMAL(38,2))) 
                     + N').';
            THROW 51001, @msg, 1;
        END

        -- 8.3 Moneda del cliente
        SET @SQL = N'SELECT @OUT = MONEDA FROM EXACTUSERP.'+QUOTENAME(@CIA)+N'.CLIENTE WHERE CLIENTE=@C;';
        EXEC sp_executesql @SQL, N'@C VARCHAR(20), @OUT VARCHAR(4) OUTPUT', @C=@CLIENTE, @OUT=@MONEDA_CLIENTE OUTPUT;

        -- 8.4 Aplicar a CUALQUIER documento listado en el JSON (FAC/ND/REC/DEP/etc.)
        SET @SQL = N'
;WITH J AS (
    SELECT
        CC.DOCUMENTO, CC.TIPO, CC.MONEDA,
        CC.SALDO, CC.SALDO_LOCAL, CC.SALDO_DOLAR, CC.SALDO_CLIENTE,
        DET.MONTO_APLICADO,
        CLI.MONEDA AS MONEDA_CLIENTE,

        -- Equivalente en moneda del documento
        CASE WHEN CC.MONEDA = ''CRC''
             THEN CASE WHEN @MONEDA_MOV = ''CRC'' THEN DET.MONTO_APLICADO ELSE DET.MONTO_APLICADO * @TC END
             ELSE CASE WHEN @MONEDA_MOV = ''USD'' THEN DET.MONTO_APLICADO ELSE DET.MONTO_APLICADO / @TC END
        END AS AP_DOC,

        -- Equivalentes
        CASE WHEN @MONEDA_MOV = ''CRC'' THEN DET.MONTO_APLICADO ELSE DET.MONTO_APLICADO * @TC END AS AP_LOCAL,
        CASE WHEN @MONEDA_MOV = ''USD'' THEN DET.MONTO_APLICADO ELSE DET.MONTO_APLICADO / @TC END AS AP_DOLAR,
        CASE WHEN CLI.MONEDA = @MONEDA_MOV THEN DET.MONTO_APLICADO
             WHEN CLI.MONEDA = ''CRC''      THEN DET.MONTO_APLICADO * @TC
             ELSE                                DET.MONTO_APLICADO / @TC END AS AP_CLIENTE
    FROM EXACTUSERP.'+QUOTENAME(@CIA)+'.DOCUMENTOS_CC CC
    JOIN #DET DET
      ON DET.DOCUMENTO = CC.DOCUMENTO
     AND DET.TIPO_DOC  = CC.TIPO
    JOIN EXACTUSERP.'+QUOTENAME(@CIA)+'.CLIENTE CLI
      ON CLI.CLIENTE = CC.CLIENTE
    WHERE CC.CLIENTE = @CLIENTE
)
UPDATE CC
   SET
       CC.SALDO          = CASE WHEN J.AP_DOC     >= CC.SALDO         THEN 0 ELSE CC.SALDO         - J.AP_DOC     END,
       CC.SALDO_LOCAL    = CASE WHEN J.AP_LOCAL   >= CC.SALDO_LOCAL   THEN 0 ELSE CC.SALDO_LOCAL   - J.AP_LOCAL   END,
       CC.SALDO_DOLAR    = CASE WHEN J.AP_DOLAR   >= CC.SALDO_DOLAR   THEN 0 ELSE CC.SALDO_DOLAR   - J.AP_DOLAR   END,
       CC.SALDO_CLIENTE  = CASE WHEN J.AP_CLIENTE >= CC.SALDO_CLIENTE THEN 0 ELSE CC.SALDO_CLIENTE - J.AP_CLIENTE END,
       CC.FECHA_ULT_MOD  = GETDATE(),
       CC.USUARIO_ULT_MOD= @USUARIO
       ,CC.U_PS_ESTADO_LIQUIDACION=@U_PS_ESTADO_LIQUIDACION
FROM EXACTUSERP.'+QUOTENAME(@CIA)+'.DOCUMENTOS_CC CC
JOIN J ON J.DOCUMENTO = CC.DOCUMENTO AND J.TIPO = CC.TIPO;';

        EXEC sp_executesql
            @SQL,
            N'@CLIENTE VARCHAR(20), @MONEDA_MOV VARCHAR(4), @TC DECIMAL, @USUARIO VARCHAR(100),  @U_PS_ESTADO_LIQUIDACION INT',
            @CLIENTE=@CLIENTE, @MONEDA_MOV=@MONEDA, @TC=@TIPO_CAMBIO, @USUARIO=@USUARIO, @U_PS_ESTADO_LIQUIDACION=@U_PS_ESTADO_LIQUIDACION;

        -- 8.5 Bajar SALDO del propio REC/DEP insertado por el total aplicado
        DECLARE
            @AP_LOCAL_TOTAL  DECIMAL(28,8) = CASE WHEN @MONEDA='CRC' THEN @APLICA_TOTAL ELSE @APLICA_TOTAL * @TIPO_CAMBIO END,
            @AP_DOLAR_TOTAL  DECIMAL(28,8) = CASE WHEN @MONEDA='USD' THEN @APLICA_TOTAL ELSE @APLICA_TOTAL / @TIPO_CAMBIO END,
            @AP_CLIENTE_TOT  DECIMAL(28,8) = CASE
                                                WHEN @MONEDA_CLIENTE = @MONEDA THEN @APLICA_TOTAL
                                                WHEN @MONEDA_CLIENTE = 'CRC'    THEN @APLICA_TOTAL * @TIPO_CAMBIO
                                                ELSE                                  @APLICA_TOTAL / @TIPO_CAMBIO END;

        SET @SQL = N'
UPDATE CC
   SET CC.SALDO          = CASE WHEN @APLICA_TOTAL  >= CC.SALDO         THEN 0 ELSE CC.SALDO         - @APLICA_TOTAL  END,
       CC.SALDO_LOCAL    = CASE WHEN @AP_LOCAL_TOTAL>= CC.SALDO_LOCAL   THEN 0 ELSE CC.SALDO_LOCAL   - @AP_LOCAL_TOTAL END,
       CC.SALDO_DOLAR    = CASE WHEN @AP_DOLAR_TOTAL>= CC.SALDO_DOLAR   THEN 0 ELSE CC.SALDO_DOLAR   - @AP_DOLAR_TOTAL END,
       CC.SALDO_CLIENTE  = CASE WHEN @AP_CLIENTE_TOT>= CC.SALDO_CLIENTE THEN 0 ELSE CC.SALDO_CLIENTE - @AP_CLIENTE_TOT END,
       CC.FECHA_ULT_MOD  = GETDATE(),
       CC.USUARIO_ULT_MOD= @USUARIO
FROM EXACTUSERP.'+QUOTENAME(@CIA)+'.DOCUMENTOS_CC CC
WHERE CC.CLIENTE  = @CLIENTE
  AND CC.TIPO     = @TIPO
  AND CC.DOCUMENTO= @DOCUMENTO;';
        EXEC sp_executesql
            @SQL,
            N'@CLIENTE VARCHAR(20), @TIPO VARCHAR(3), @DOCUMENTO VARCHAR(100),
              @APLICA_TOTAL DECIMAL, @AP_LOCAL_TOTAL DECIMAL,
              @AP_DOLAR_TOTAL DECIMAL, @AP_CLIENTE_TOT DECIMAL,
              @USUARIO VARCHAR(100)',
            @CLIENTE=@CLIENTE, @TIPO=@TIPO, @DOCUMENTO=@DOCUMENTO,
            @APLICA_TOTAL=@APLICA_TOTAL, @AP_LOCAL_TOTAL=@AP_LOCAL_TOTAL,
            @AP_DOLAR_TOTAL=@AP_DOLAR_TOTAL, @AP_CLIENTE_TOT=@AP_CLIENTE_TOT,
            @USUARIO=@USUARIO;
    END

    /* ============================================================
       9) ACTUALIZAR SALDO EN CLIENTE (cálculo existente)
       ============================================================ */
	UPDATE   C 
	SET      C.SALDO = ISNULL((
                    SELECT (ISNULL(SUM(CC.SALDO),0) - ISNULL((SELECT SUM(SALDO)
                            FROM EXACTUSERP.DIS86.DOCUMENTOS_CC (NOLOCK)
                            WHERE CC.CLIENTE = CLIENTE AND TIPO IN ('REC','O/C','DEP','TEF','N/C')), 0))
                    FROM EXACTUSERP.DIS86.DOCUMENTOS_CC CC (NOLOCK)
                    WHERE CC.CLIENTE = C.CLIENTE AND CC.TIPO NOT IN ('REC','O/C','DEP','TEF','N/C')
                    GROUP BY CC.CLIENTE),0),
			 C.SALDO_DOLAR = ISNULL((
                    SELECT (ISNULL(SUM(CC.SALDO_DOLAR),0) - ISNULL((SELECT SUM(SALDO_DOLAR)
                            FROM EXACTUSERP.DIS86.DOCUMENTOS_CC (NOLOCK)
                            WHERE CC.CLIENTE = CLIENTE AND TIPO IN ('REC','O/C','DEP','TEF','N/C')), 0))
                    FROM EXACTUSERP.DIS86.DOCUMENTOS_CC CC (NOLOCK)
                    WHERE CC.CLIENTE = C.CLIENTE AND CC.TIPO NOT IN ('REC','O/C','DEP','TEF','N/C')
                    GROUP BY CC.CLIENTE),0),
			C.SALDO_LOCAL =  ISNULL((
                    SELECT (ISNULL(SUM(CC.SALDO_LOCAL),0) - ISNULL((SELECT SUM(SALDO_LOCAL)
                            FROM EXACTUSERP.DIS86.DOCUMENTOS_CC (NOLOCK)
                            WHERE CC.CLIENTE = CLIENTE AND TIPO IN ('REC','O/C','DEP','TEF','N/C')), 0))
                    FROM EXACTUSERP.DIS86.DOCUMENTOS_CC CC (NOLOCK)
                    WHERE CC.CLIENTE = C.CLIENTE AND CC.TIPO NOT IN ('REC','O/C','DEP','TEF','N/C')
                    GROUP BY CC.CLIENTE),0)
	FROM  EXACTUSERP.DIS86.CLIENTE AS  C (NOLOCK)
	WHERE C.CLIENTE = @CLIENTE;

    /* ============================================================
       10) SALDO_CLIENTE (por moneda del movimiento)
       ============================================================ */
	UPDATE SC
    SET    SC.SALDO = CASE 
                         WHEN @TIPO NOT IN('REC','O/C','DEP','TEF','N/C') AND @MONEDA <> 'USD' THEN SC.SALDO + @TOTAL_ABONADO
                         WHEN @TIPO NOT IN('REC','O/C','DEP','TEF','N/C') AND @MONEDA =  'USD' THEN SC.SALDO + (@TOTAL_ABONADO/@TIPO_CAMBIO)
                         WHEN @TIPO IN('REC','O/C','DEP','TEF','N/C')     AND @MONEDA <> 'USD' THEN SC.SALDO - ABS(@TOTAL_ABONADO)
                         WHEN @TIPO IN('REC','O/C','DEP','TEF','N/C')     AND @MONEDA =  'USD' THEN SC.SALDO - (@TOTAL_ABONADO/@TIPO_CAMBIO)
                      END
    FROM EXACTUSERP.DIS86.SALDO_CLIENTE AS SC
    WHERE SC.CLIENTE = @CLIENTE
      AND SC.MONEDA  = @MONEDA;
END
GO
