CREATE   PROCEDURE [GLOBAL].[PROC_INS_ESTADO_CUENTA_EXCEL]( 
	 @CUENTA_BANCARIA VARCHAR(22)
	,@DOCUMENTO VARCHAR(50)
	,@TIPO VARCHAR(3)
	,@SUBTIPO INT
	,@FECHA VARCHAR(10)
	,@CONCEPTO VARCHAR(240)
	,@MONTO DECIMAL(28,8)
	,@CREDITO_DEBITO VARCHAR(1)
	,@USUARIO VARCHAR(50)
	,@INS_MOV_REPORTADOS VARCHAR(1)
	,@CIA VARCHAR(30)
) 
AS
BEGIN

DECLARE @SQL NVARCHAR(MAX)
DECLARE @RESULT INT = 0
DECLARE @MONEDA VARCHAR(4)
DECLARE @CONSECUTIVO VARCHAR(20)

SET @SQL = 'SELECT TOP 1 @CONSECUTIVO = ISNULL(MAX(DOC_REPORTADO),0) + 1 FROM EXACTUSERP.['+ISNULL(@CIA,'')+'].[MOV_REPORTADOS]'

EXECUTE SP_EXECUTESQL @SQL, N'@CONSECUTIVO VARCHAR(20) OUTPUT',
