SET @SQL = 'SELECT TOP 1 @MONEDA = MONEDA FROM EXACTUSERP.['+ISNULL(@CIA, '')+'].[CUENTA_BANCARIA] WHERE CUENTA_BANCO = @CUENTA_BANCARIA ORDER BY CREATEDATE DESC'

EXECUTE SP_EXECUTESQL @SQL, N'@CUENTA_BANCARIA VARCHAR(22)
							 ,@MONEDA VARCHAR(4) OUTPUT',
							 @CUENTA_BANCARIA,
							 @MONEDA OUTPUT

SET @SQL = '
BEGIN TRANSACTION
BEGIN TRY
				INSERT INTO ['+ISNULL(@CIA,'')+'].[ESTADO_H2H_LINEAS]
				(
					 [CUENTA_BANCO]
					,[DOCUMENTO_BANCO]
					,[TIPO]
					,[SUBTIPO]
