				  SELECT
					 @CUENTA_BANCARIA
					 ,@DOCUMENTO
					 ,@TIPO
					 ,@SUBTIPO
					 ,@FECHA
					 ,GETDATE()
					 ,@CONCEPTO
					 ,@CREDITO_DEBITO
					 ,@MONEDA
					 ,@MONTO
					 ,@INS_MOV_REPORTADOS 
					 ,CASE
							WHEN @INS_MOV_REPORTADOS = ''S'' THEN ''N''
							WHEN @INS_MOV_REPORTADOS = ''N'' THEN ''D''
							ELSE NULL
					  END

	IF @@ROWCOUNT <> 0
	BEGIN
		SET @RESULT = 1
	END
	ELSE
	BEGIN
		SET @RESULT = 0
	END

COMMIT
	
END TRY
BEGIN CATCH
		ROLLBACK;
		DECLARE @ERR_MSG NVARCHAR(MAX),@ERR_STATE INT, @ERR_SEVERITY INT;
		SELECT @ERR_MSG=ERROR_MESSAGE(),@ERR_STATE=ERROR_STATE(), @ERR_SEVERITY=ERROR_SEVERITY();
		PRINT(@ERR_MSG)
		RAISERROR (@ERR_MSG, @ERR_SEVERITY, @ERR_STATE) WITH NOWAIT
END CATCH'

				-- IF @INS_MOV_REPORTADOS = ''S''
				-- BEGIN
				--INSERT INTO EXACTUSERP.['+ISNULL(@CIA,'')+'].[MOV_REPORTADOS]
				--(
				--	 [DOC_REPORTADO]
				--	,[CUENTA_BANCO]
				--	,[TIPO_DOCUMENTO]
				--	,[NUMERO]
				--	,[MONTO]
				--	,[FECHA]
				--	,[ESTADO]
				--	,[MODO_REGISTRO]
				--	,[COMPENSADO]
				--	,[CONCILIACION]
				--	,[NOTAS]
				--	,[FCH_HORA_CREACION]
				--	,[USUARIO_CREACION]
				--)
				--  SELECT
				--	  @CONSECUTIVO
				--	  ,@CUENTA_BANCARIA
				--	  ,@TIPO
				--	  ,@DOCUMENTO
				--	  ,@MONTO
				--	  ,@FECHA 
				--	  ,''N''
				--	  ,''M''
				--	  ,''N''
				--	  ,NULL
				--	  ,@CONCEPTO
				--	  ,GETDATE()
				--	  ,@USUARIO

				--	  END
print @sql
	EXEC SP_EXECUTESQL @SQL,N' @CUENTA_BANCARIA VARCHAR(22)
							,@DOCUMENTO VARCHAR(50)
							,@TIPO VARCHAR(3)
							,@SUBTIPO INT
							,@FECHA VARCHAR(10)
							,@CONCEPTO VARCHAR(240)
							,@MONTO DECIMAL(28,8)
							,@CREDITO_DEBITO VARCHAR(1)
							,@USUARIO VARCHAR(50)
							,@INS_MOV_REPORTADOS VARCHAR(1)
							,@RESULT INT OUTPUT
							,@CONSECUTIVO VARCHAR(20) OUTPUT
							,@MONEDA VARCHAR(4) OUTPUT',
							 @CUENTA_BANCARIA
							,@DOCUMENTO
							,@TIPO
							,@SUBTIPO
							,@FECHA
							,@CONCEPTO
							,@MONTO
							,@CREDITO_DEBITO
							,@USUARIO
							,@INS_MOV_REPORTADOS
							,@RESULT OUTPUT
							,@CONSECUTIVO OUTPUT
							,@MONEDA OUTPUT
	RETURN @RESULT
END
