CREATE PROC [GLOBAL].[PROC_INS_ESTADO_CUENTA_EXCEL_BULK]
(
    @LISTA   GLOBAL.TP_ESTADO_CUENTA_EXCEL READONLY,
    @USUARIO VARCHAR(50),
    @CIA     VARCHAR(30)
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON; -- mata la transacción en error

    BEGIN TRY

        INSERT INTO [DIS86].[ESTADO_H2H_LINEAS]
        (
            CUENTA_BANCO,
            DOCUMENTO_BANCO,
            TIPO,
            SUBTIPO,
            FECHA_BANCO,
            FECHA_CARGA,
            PS_86_REFERENCIA,
            CREDITO_DEBITO,
            MONEDA,
            MONTO,
            SE_INSERTO_EN_MOV_REPORTADOS,
            ESTADO
        )
        SELECT
            L.CUENTA_BANCARIA,
            L.DOCUMENTO,
            L.TIPO,
            L.SUBTIPO,
            L.FECHA,
            SYSDATETIME(),
            L.CONCEPTO,
            L.CREDITO_DEBITO,
            CB.MONEDA,
            L.MONTO,
            L.INS_MOV_REPORTADOS,
            CASE
                WHEN L.INS_MOV_REPORTADOS = 'S' THEN 'N'
                WHEN L.INS_MOV_REPORTADOS = 'N' THEN 'D'
                ELSE NULL
            END
        FROM @LISTA L
        INNER JOIN EXACTUSERP.[DIS86].[CUENTA_BANCARIA] CB
            ON CB.CUENTA_BANCO = L.CUENTA_BANCARIA;

		--exec [DIS86].[PROC_ACTUALIZAR_NUMEROS_BANCO]

        RETURN 1;

    END TRY
    BEGIN CATCH
        THROW;
    END CATCH
END;
