CREATE PROC [GLOBAL].[PROC_INS_EXPEDIENTE_DIGITAL_PP](
	@DOCUMENTO VARCHAR(4), 
	@TIPO VARCHAR(4), 
	@REFERENCIA VARCHAR(40), 
	@REFERENCIA_LINEA INT,
	@PROVEEDOR VARCHAR(20), 
	@NOMBRE VARCHAR(200), 
	@ADJUNTO VARCHAR(MAX), 
	@EXTENSION VARCHAR(10), 
	@USUARIO  VARCHAR(30),
	@SUBTIPO INT,
	@DECRIPCION VARCHAR(500),
	@CIA  VARCHAR(30)
)
AS 
BEGIN

	DECLARE @RESULT INT = 0
	DECLARE @SQL NVARCHAR(MAX), @PARAM NVARCHAR(MAX)

	SET @SQL = 'INSERT INTO ['+ISNULL(@CIA, '')+'].[EXPEDIENTE_DIGITAL_PP](
					[TIPO],
					[MODULO], 
					[REFERENCIA],
					[REFERENCIA_LINEA],
					[PROVEEDOR_CLIENTE],
					[NOMBRE],
					[ADJUNTO],
					[EXTENSION],
					[FECHA],
					[USUARIO],
					[SUBTIPO],
                    [COMENTARIO]
				)
				VALUES	(
					@TIPO,
					@DOCUMENTO, 
					@REFERENCIA, 
					@REFERENCIA_LINEA,
					@PROVEEDOR, 
					@NOMBRE, 
					@ADJUNTO, 
					@EXTENSION,
					GETDATE(),
					@USUARIO,
					@SUBTIPO,
					@DECRIPCION
				)'

    SET @PARAM = N'@DOCUMENTO VARCHAR(4),@TIPO VARCHAR(4),@REFERENCIA VARCHAR(40),@REFERENCIA_LINEA INT,@PROVEEDOR VARCHAR(20),@NOMBRE VARCHAR(200), 
				   @ADJUNTO VARCHAR(MAX),@EXTENSION VARCHAR(10),@USUARIO  VARCHAR(30),@SUBTIPO INT,@DECRIPCION VARCHAR(500)'
	
	EXEC SP_EXECUTESQL	@SQL,@PARAM,@DOCUMENTO,@TIPO,@REFERENCIA,@REFERENCIA_LINEA,@PROVEEDOR,@NOMBRE,@ADJUNTO,@EXTENSION,@USUARIO,@SUBTIPO,@DECRIPCION
	
	IF @@ROWCOUNT <> 0
	BEGIN
		SET @RESULT = 1
	END
	ELSE 
	BEGIN
		SET @RESULT = 0
	END
	RETURN @RESULT
END

