CREATE   PROC [GLOBAL].[PROC_INS_MENU_PERMISO]
    @ID_MENU INT,
    @PERMISO INT,
    @USUARIO_EJECUCION VARCHAR(100)
AS
BEGIN
    IF NOT EXISTS (SELECT 1 FROM GLOBAL.MENU_PERMISO WITH (NOLOCK) WHERE ID_MENU = @ID_MENU AND PERMISO = @PERMISO)
    BEGIN
        INSERT INTO GLOBAL.MENU_PERMISO (ID_MENU, PERMISO, USUARIO_CREACION)
        VALUES (@ID_MENU, @PERMISO, @USUARIO_EJECUCION);
    END
    SELECT 1 CODIGO, 'Asignacion menu-permiso aplicada.' MENSAJE;
END

