/****** Object:  StoredProcedure [GLOBAL].[PROC_INS_PEDIDO_LINEA]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [GLOBAL].[PROC_INS_PEDIDO_LINEA](
@PEDIDO INT,
@ARTICULO_EXACTUSERP VARCHAR(20),
@CANTIDAD INT,
@EXISTENCIA INT,
@PORC_DESCUENTO  DECIMAL(28,2),
@CIA VARCHAR(20)
 )
AS
BEGIN  
DECLARE @SQL NVARCHAR(MAX),@PARAM NVARCHAR(MAX),@CANT_MAX INT, @ARTICULO_BONIFICADO VARCHAR(20)
DECLARE @CLIENTE VARCHAR(20), @CANTIDAD_TOTAL_PED INT, @EXISTENCIA_TOTAL_PED INT 
    -- SACAMOS EL CLIENTE DEL PEDIDO PARA MANDARLO Y VALIDAR SI HAY BONIFICACION

	SELECT
	      @CLIENTE = CLIENTE 
	FROM  DIS86.PEDIDO 
	WHERE PEDIDO =  @PEDIDO  

	SET @SQL =   'SELECT 
	                     @CANT_MAX= COUNT(ARTICULO_EXACTUSERP) 
	              FROM   
				         ['+@CIA+'].PEDIDO_LINEA 
				  WHERE 
				         PEDIDO=@PEDIDO 
				  AND    ARTICULO_EXACTUSERP = @ARTICULO_EXACTUSERP
				  AND    ES_BONIFICADO     IS NULL 
				  ' 
	
	SET @PARAM = '@PEDIDO INT,@ARTICULO_EXACTUSERP VARCHAR(20),@CANT_MAX INT OUTPUT' 
	EXEC SP_EXECUTESQL @SQL, @PARAM,@PEDIDO , @ARTICULO_EXACTUSERP ,@CANT_MAX OUTPUT

	
--VERIFICAMOS SI EL ARTICULO EXISTE EN EL CARRITO
IF(@CANT_MAX >= 1) 
     BEGIN 
		 SET @SQL = 'UPDATE ['+@CIA+'].PEDIDO_LINEA  
					 SET    CANTIDAD = CANTIDAD + @CANTIDAD, 
					        EXISTENCIA = EXISTENCIA - @CANTIDAD,
							PORC_DESCUENTO = @PORC_DESCUENTO/100
					 WHERE  PEDIDO            = @PEDIDO 
					 AND    ARTICULO_EXACTUSERP = @ARTICULO_EXACTUSERP
					 AND    ES_BONIFICADO     IS NULL 
					' 
		SET @PARAM = '@PEDIDO INT,@ARTICULO_EXACTUSERP VARCHAR(20),@CANTIDAD INT,@PORC_DESCUENTO  DECIMAL(28,2)' 
		
		EXEC SP_EXECUTESQL @SQL, @PARAM,@PEDIDO ,@ARTICULO_EXACTUSERP,@CANTIDAD,@PORC_DESCUENTO  
		

		
		---- INSERTAMOS 
		SELECT
			  @CANTIDAD_TOTAL_PED   = CANTIDAD,
			  @EXISTENCIA_TOTAL_PED = EXISTENCIA
		FROM  DIS86.PEDIDO_LINEA  
		WHERE PEDIDO            =  @PEDIDO  
		AND   ARTICULO_EXACTUSERP =  @ARTICULO_EXACTUSERP
		AND   ES_BONIFICADO IS NULL
	
		-- INSERTAMOS LINEA BONIFICADA SI CUMPLE CON LAS CANTIDADES 
	    
		EXEC DIS86.PROC_INSERTAR_LINEA_BONIFICADA_PEDIDO @PEDIDO,@CLIENTE,@ARTICULO_EXACTUSERP,@CANTIDAD_TOTAL_PED,@EXISTENCIA_TOTAL_PED

		IF(@CANTIDAD < 1)

		BEGIN 
			SET @SQL = 'DELETE FROM ['+@CIA+'].PEDIDO_LINEA 
			            WHERE PEDIDO             = @PEDIDO 
			            AND   ARTICULO_EXACTUSERP  = @ARTICULO_EXACTUSERP
						--AND CANTIDAD = 0
						' 
			SET @PARAM = '@PEDIDO INT,@ARTICULO_EXACTUSERP VARCHAR(20)' 
			EXEC SP_EXECUTESQL @SQL, @PARAM,@PEDIDO,@ARTICULO_EXACTUSERP  

		END
	 END
	 ELSE 
		BEGIN
		DECLARE @AC VARCHAR(7) 
		--(SELECT U_ACTIVDIDAD_ECONOMICA FROM EXACTUSERP.NARGA.ARTICULO WHERE ARTICULO = @ARTICULO_EXACTUSERP) 
		SET @AC = '519003'

			SET @SQL = 'INSERT INTO ['+@CIA+'].[PEDIDO_LINEA]
						   ([PEDIDO]
						   ,[ARTICULO_EXACTUSERP]
						   ,[CANTIDAD]
						   ,[ACTIVIDAD_ECONOMICA]
						   ,[EXISTENCIA]
						   ,[PORC_DESCUENTO]
						   ,[BODEGA]
						    )
					 VALUES
						   (@PEDIDO
						   ,@ARTICULO_EXACTUSERP
						   ,@CANTIDAD 
						   ,@AC
						   ,@EXISTENCIA
						   ,@PORC_DESCUENTO/100
						   ,''01'')'
						   
			SET @PARAM = '@PEDIDO INT,@ARTICULO_EXACTUSERP VARCHAR(20),@CANTIDAD INT,@AC VARCHAR(7),@EXISTENCIA INT,@PORC_DESCUENTO  DECIMAL(28,2)' 
			EXEC SP_EXECUTESQL @SQL, @PARAM,@PEDIDO ,@ARTICULO_EXACTUSERP ,@CANTIDAD ,@AC,@EXISTENCIA,@PORC_DESCUENTO 
			

			-- INSERTAMOS LINEA BONIFICADA SI ES UN REGISTRO NUEVO 
			EXEC DIS86.PROC_INSERTAR_LINEA_BONIFICADA_PEDIDO @PEDIDO,@CLIENTE,@ARTICULO_EXACTUSERP,@CANTIDAD,@EXISTENCIA

	  END  
	SELECT 1 RESULTADO  

END 



GO
