/****** Object:  StoredProcedure [GLOBAL].[PROC_INS_TOKEN_RECUPERACION]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE   PROC [GLOBAL].[PROC_INS_TOKEN_RECUPERACION]
    @CORREO VARCHAR(255),
    @IP_SOLICITUD VARCHAR(45) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    BEGIN TRY
        DECLARE @USUARIO VARCHAR(50);
        DECLARE @TOKEN NVARCHAR(500);
        DECLARE @HASH_TOKEN VARBINARY(64);

        SELECT TOP 1 @USUARIO = UC.USUARIO
        FROM GLOBAL.USUARIO_CORREO UC WITH (NOLOCK)
        INNER JOIN GLOBAL.USUARIO U WITH (NOLOCK) ON U.USUARIO = UC.USUARIO
        WHERE UC.CORREO = @CORREO
          AND UC.ACTIVO = 'S'
          AND U.ACTIVO = 'S';

        IF @USUARIO IS NULL
        BEGIN
            SELECT 1 CODIGO, 'Si el correo existe, se envio un token.' MENSAJE, CAST(NULL AS NVARCHAR(500)) TOKEN;
            RETURN;
        END

        SET @TOKEN = CONVERT(NVARCHAR(100), NEWID()) + CONVERT(NVARCHAR(100), NEWID());
        SET @HASH_TOKEN = GLOBAL.FUNC_HASH_TOKEN(@TOKEN);

        INSERT INTO GLOBAL.TOKEN_RECUPERACION (USUARIO, HASH_TOKEN, FECHA_EXPIRACION_UTC, USADO, IP_SOLICITUD)
        VALUES (@USUARIO, @HASH_TOKEN, DATEADD(MINUTE, 30, SYSUTCDATETIME()), 'N', @IP_SOLICITUD);

        SELECT 1 CODIGO, 'Token generado.' MENSAJE, @TOKEN TOKEN, @USUARIO USUARIO;
    END TRY
    BEGIN CATCH
        SELECT -500 CODIGO, ERROR_MESSAGE() MENSAJE, CAST(NULL AS NVARCHAR(500)) TOKEN;
    END CATCH
END

GO
/****** Object:  StoredProcedure [GLOBAL].[PROC_INS_USUARIO]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE   PROC [GLOBAL].[PROC_INS_USUARIO]
    @USUARIO VARCHAR(50),
    @CORREO VARCHAR(255),
    @USUARIO_EXACTUSERP VARCHAR(20) = NULL,
    @ROL INT = 1,
    @USUARIO_EJECUCION VARCHAR(100)
AS
BEGIN
    INSERT INTO GLOBAL.USUARIO
    (
        USUARIO,
        CLAVE,
        ROL,
        ACTIVO,
        USUARIO_EXACTUSERP,
        NoteExistsFlag,
        RecordDate,
        CreatedBy,
        UpdatedBy,
        CreateDate
    )
    VALUES
    (
        @USUARIO,
        '',
        @ROL,
        'S',
        @USUARIO_EXACTUSERP,
        0,
        GETDATE(),
        @USUARIO_EJECUCION,
        @USUARIO_EJECUCION,
        GETDATE()
    );

    IF OBJECT_ID('GLOBAL.USUARIO_CORREO', 'U') IS NOT NULL
    BEGIN
        MERGE GLOBAL.USUARIO_CORREO AS DESTINO
        USING (SELECT @USUARIO AS USUARIO, @CORREO AS CORREO) AS ORIGEN
           ON DESTINO.USUARIO = ORIGEN.USUARIO
        WHEN MATCHED THEN
            UPDATE SET CORREO = ORIGEN.CORREO, ACTIVO = 'S'
        WHEN NOT MATCHED THEN
            INSERT (USUARIO, CORREO, ACTIVO)
            VALUES (ORIGEN.USUARIO, ORIGEN.CORREO, 'S');
    END

    SELECT 1 CODIGO, 'Usuario creado.' MENSAJE;
END

GO
/****** Object:  StoredProcedure [GLOBAL].[PROC_INS_USUARIO_PERMISO_COMPANIA]    Script Date: 22/5/2026 17:05:06 ******/
