CREATE   PROC [GLOBAL].[PROC_INS_USUARIO_PERMISO_COMPANIA]
    @USUARIO VARCHAR(50),
    @PERMISO INT,
    @ID_COMPANIA INT,
    @ES_PERMITIDO VARCHAR(1),
    @USUARIO_EJECUCION VARCHAR(100)
AS
BEGIN
    MERGE GLOBAL.USUARIO_PERMISO_COMPANIA AS DESTINO
    USING (SELECT @USUARIO USUARIO, @PERMISO PERMISO, @ID_COMPANIA ID_COMPANIA) AS ORIGEN
       ON DESTINO.USUARIO = ORIGEN.USUARIO
      AND DESTINO.PERMISO = ORIGEN.PERMISO
      AND DESTINO.ID_COMPANIA = ORIGEN.ID_COMPANIA
    WHEN MATCHED THEN
        UPDATE SET ES_PERMITIDO = @ES_PERMITIDO, ACTIVO = 'S', FECHA_MODIFICACION_UTC = SYSUTCDATETIME(), USUARIO_MODIFICACION = @USUARIO_EJECUCION
    WHEN NOT MATCHED THEN
        INSERT (USUARIO, PERMISO, ID_COMPANIA, ES_PERMITIDO, ACTIVO, USUARIO_CREACION)
        VALUES (@USUARIO, @PERMISO, @ID_COMPANIA, @ES_PERMITIDO, 'S', @USUARIO_EJECUCION);

    SELECT 1 CODIGO, 'Override usuario-permiso-compania aplicado.' MENSAJE;
END

