/****** Object:  StoredProcedure [GLOBAL].[PROC_INS_VISITA]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [GLOBAL].[PROC_INS_VISITA]( 
 @CLIENTE VARCHAR(20)
,@TIPO_VISITA VARCHAR(4)
,@FECHA_VISITA DATETIME
,@LATITUD VARCHAR(50)
,@LONGITUD VARCHAR(50)
,@ESTADO_VISITA VARCHAR(4)
,@COMENTARIO VARCHAR(800)
,@DOCUMENTO VARCHAR(50)
,@VENDEDOR VARCHAR(4)
,@USUARIO VARCHAR(50)
,@DOC_VENC_DESCRIPCION VARCHAR(800)
,@DIRECCION VARCHAR(MAX)
,@CIA VARCHAR(20)
,@ID_VISITA VARCHAR(20) OUT 
)
AS
BEGIN

	DECLARE @SQL NVARCHAR(MAX),@PARAM NVARCHAR(MAX),@LAST INT
	DECLARE @RUTA VARCHAR(4),@SEMANA VARCHAR(50),@DIA VARCHAR(10)

	 SET @RUTA   = (SELECT RUTA             FROM EXACTUSERP.DIS86.CLIENTE WHERE CLIENTE =@CLIENTE )
     SET @SEMANA = (SELECT U_SEMANA_VISITA  FROM EXACTUSERP.DIS86.CLIENTE WHERE CLIENTE =@CLIENTE )
	 SET @DIA    = (SELECT U_DIA_VISITA     FROM EXACTUSERP.DIS86.CLIENTE WHERE CLIENTE =@CLIENTE )
	
	
	---- SI EL CLIENTE NO TIENE DIA ASINGADO
	IF (@DIA = 'ND' OR @DIA IS NULL OR @DIA = '')
	BEGIN
		-- Obtener el día de la semana (1 = Domingo, 2 = Lunes, ..., 7 = Sábado)
		DECLARE @DiaDeLaSemana INT = DATEPART(WEEKDAY, @FECHA_VISITA);
    
		-- Asignar la letra del día correspondiente
		SET @DIA = CASE 
					WHEN @DiaDeLaSemana = 1 THEN 'D'  -- Domingo
					WHEN @DiaDeLaSemana = 2 THEN 'L'  -- Lunes
					WHEN @DiaDeLaSemana = 3 THEN 'K'  -- Martes
					WHEN @DiaDeLaSemana = 4 THEN 'M'  -- Miércoles
					WHEN @DiaDeLaSemana = 5 THEN 'J'  -- Jueves
					WHEN @DiaDeLaSemana = 6 THEN 'V'  -- Viernes
					WHEN @DiaDeLaSemana = 7 THEN 'S'  -- Sábado
				   END
	    END

		
		IF (@SEMANA IS NULL OR @SEMANA ='' OR @SEMANA = 'ND')
		BEGIN
		 SET @SEMANA = (SELECT semana 
		                FROM   DIS86.VIW_OBT_SEMANA_POR_FECHA_VISITA
                        WHERE  CONVERT(VARCHAR(10), (@FECHA_VISITA), 105) BETWEEN inicio_semana AND fin_semana)

		END 

	 --SET @FECHA_VISITA = CONVERT(date, @FECHA_VISITA, 103)
      
	  
	   INSERT INTO DIS86.[VISITAS]
					   (
						CLIENTE
					   ,TIPO_VISITA
					   ,FECHA_VISITA
					   ,LATITUD
					   ,LONGITUD
					   ,RUTA
					   ,SEMANA
					   ,DIA
					   ,ESTADO_VISITA
					   ,COMENTARIO
					   ,DOCUMENTO
					   ,VENDEDOR
					   ,USUARIO
                       ,DOC_VENC_DESCRIPCION
					   ,DIRECCION
						)
				 VALUES
					   (
					   	@CLIENTE
					   ,@TIPO_VISITA
					   ,@FECHA_VISITA --CONVERT(varchar,@FECHA_VISITA, 120)  
					   ,@LATITUD
					   ,@LONGITUD
					   ,@RUTA
					   ,@SEMANA
					   ,@DIA
					   ,@ESTADO_VISITA
					   ,@COMENTARIO
					   ,@DOCUMENTO
					   ,@VENDEDOR
					   ,@USUARIO	
					   ,@DOC_VENC_DESCRIPCION
					   ,@DIRECCION
					   )


	
	
	SET @LAST  = (SELECT MAX(ID_VISITA) FROM [DIS86].[VISITAS] WHERE USUARIO = @USUARIO) 

	SET @SQL   = 'SELECT @ID_VISITA = ID_VISITA  FROM ['+@CIA+'].[VISITAS] WHERE ID_VISITA =  @LAST'
	SET @PARAM = '@ID_VISITA INT OUTPUT, @LAST INT'
	
	EXEC SP_EXECUTESQL @SQL,@PARAM,@ID_VISITA OUTPUT, @LAST 
END
GO
/****** Object:  StoredProcedure [GLOBAL].[PROC_INSERTAR_PEDIDO]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [GLOBAL].[PROC_INSERTAR_PEDIDO]( 
	@CONSECUTIVO VARCHAR(50), 
	@CLIENTE VARCHAR(20),
	@TIPO INT,
	@VENDEDOR VARCHAR(20),
	@OBSERVACIONES VARCHAR(200),
	@USUARIO_CREACION VARCHAR(50),
	@BODEGA VARCHAR(10),
	@CIA VARCHAR(20),
	@PEDIDO VARCHAR(20) OUT 
)
AS
BEGIN

	DECLARE @SQL NVARCHAR(MAX),@PARAM NVARCHAR(MAX),@LAST VARCHAR (15)
	SET @LAST  = (SELECT  TIPO+'-'+ RIGHT('00000000' +  CAST(RIGHT(CO.[SIGUIENTE_CONSEC], 8) + 1 AS VARCHAR),8 ) AS CONSECUTIVO
						FROM    [GLOBAL].[CONSECUTIVO]  CO
							WHERE   CO.TIPO = 'TEMP') --AND CIA = @CIA) --- VAMOS A PASARLO PARA CUANDO INSERTA LAS LINEAS 

 
	SET @SQL = 'INSERT INTO ['+@CIA+'].[PEDIDO]
					   ([CONSECUTIVO]
					   ,[FECHA]
					   ,[OBSERVACIONES]
					   ,[ESTADO]
					   ,[ESTADO_A_EXACTUSERP]
					   ,[USUARIO_CREACION]
					   ,[CLIENTE]
					   ,[VENDEDOR] 
					   ,[TIPO]
					   ,[BODEGA]
					   )
				 VALUES
					   (
					    @LAST
					   ,GETDATE()
					   ,@OBSERVACIONES
					   ,1
					   ,''P''
					   ,@USUARIO_CREACION  
					   ,@CLIENTE	 
					   ,@VENDEDOR 
					   ,@TIPO
					   ,@BODEGA
					   )' 

	SET @PARAM = '@LAST VARCHAR (15),
	              @OBSERVACIONES VARCHAR(200), 
				  @USUARIO_CREACION VARCHAR(50),
				  @CLIENTE VARCHAR(20),
				  @VENDEDOR VARCHAR(20),
				  @TIPO INT,
				  @BODEGA VARCHAR(10)
				  ' 
	EXEC SP_EXECUTESQL @SQL, 
	                   @PARAM, 
	                   @LAST,
					   @OBSERVACIONES,
					   @USUARIO_CREACION,
					   @CLIENTE,@VENDEDOR,
					   @TIPO,
					   @BODEGA


	
	SET @SQL  = 'SELECT @PEDIDO = PEDIDO  FROM ['+@CIA+'].[PEDIDO] WHERE CONSECUTIVO =  @LAST'

	SET @PARAM = ' @PEDIDO INT OUTPUT, @LAST VARCHAR (15)'
	
	EXEC SP_EXECUTESQL @SQL,@PARAM,@PEDIDO  OUTPUT, @LAST 

	UPDATE [GLOBAL].[CONSECUTIVO]
	SET    SIGUIENTE_CONSEC = @LAST
	WHERE  TIPO = 'TEMP' AND CIA = @CIA 

END

GO
/****** Object:  StoredProcedure [GLOBAL].[PROC_INSERTAR_USUARIO]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [GLOBAL].[PROC_INSERTAR_USUARIO]( 
	@USUARIO VARCHAR(200),
	@CLAVE VARCHAR(68),
	@CORREO VARCHAR (200),
	@IDENTIFICACION VARCHAR(20),
	@NOMBRE VARCHAR(80),
	@VENDEDOR VARCHAR(10),
	@COBRADOR VARCHAR(10),
	@BODEGA VARCHAR(10),
	@ROL INT,
	@CIA VARCHAR(50)
) 
		-- ADD THE PARAMETERS FOR THE STORED PROCEDURE HERE
	AS
	BEGIN

	INSERT INTO [GLOBAL].[USUARIO]
           ([USUARIO]
           ,[ROL]
           ,[ACTIVO]
           ,[CLAVE] 
		   ,USUARIO_EXACTUSERP)
     VALUES
           ( 
		    @USUARIO
		   ,@ROL		
		   ,'A'		-- A DE ACTIVO, I DE INACTIVO.
		   ,ENCRYPTBYPASSPHRASE('CONTRASE;AECOMMERCE',@CLAVE ) 
		   ,@IDENTIFICACION
		   )   

		INSERT INTO [GLOBAL].[USUARIO_ADICIONALES]
           ([USUARIO]
           ,[CORREO]
           ,[IDENTIFICACION]
           ,[TIPO_IDENTIFICACION]
           ,[NOMBRE]
           ,[APELLIDO_1]
           ,[APELLIDO_2]
           ,[TELEFONO_CODIGO_PAIS]
           ,[TELEFONO]
           ,[PAIS]
           ,[PROVINCIA]
           ,[CANTON]
           ,[DISTRITO]
           ,[BARRIO]
           ,[OTRAS_SENAS]
           ,[CODIGO_VERIFICACION] 
		   ,CLIENTE_EXACTUSERP
		   ,FA_DE
		   ,[VENDEDOR]
		   ,[COBRADOR]
           ,[BODEGA]
		   ,[CIA_DEFECTO]
		   )
      SELECT  
			 @USUARIO
			,@CORREO
			,@IDENTIFICACION
			,''                   --@TIPO_IDENTIFICACION 
			,@NOMBRE			
			,'CLIENTE PLANTILLA'
			,'CLIENTE PLANTILLA'
			,'506'                -- CODIGO DEL PAIS
			,''                   --@TELEFONO1 
			,'CRI'                --PAIS
			,'1'                  --DIVISION_GEOGRAFICA1--PROVINCIA
			,'01'                 --DIVISION_GEOGRAFICA2--CANTON
			,'02'                 --DIVISION_GEOGRAFICA3--DISTRITO
			,'06'                 --DIVISION_GEOGRAFICA4-- BARRIO
			,'SIN OTRAS SEÑAS'    --OTRAS_SENAS--OTRAS_SENAS
			,0                    --CODIGO_VERIFICACION 
			,'CL09999'
			,'N' 
		    ,@VENDEDOR
			,@COBRADOR
			,@BODEGA
			,@CIA


			---- ACTUALIZAMOS EL CORREO EN ERPADMIN
			UPDATE  US
			SET     US.CORREO_ELECTRONICO = @CORREO
			FROM    EXACTUSERP.ERPADMIN.USUARIO AS US
			WHERE   USUARIO = @USUARIO

	END


	
GO
