CREATE PROCEDURE [GLOBAL].[PROC_OBT_ARTICULOS_TODOS](
@CIA VARCHAR(30))
AS 
BEGIN
    DECLARE @SQL NVARCHAR(MAX)
    DECLARE @TABLE TABLE(
        ARTICULO VARCHAR(50),
        DESCRIPCION VARCHAR(500),
        UNIDAD_ALMACEN VARCHAR(10),
        COMPLETO VARCHAR(2000)
    )

    SET @SQL = '
                SELECT ARTICULO, DESCRIPCION, UNIDAD_ALMACEN, CONCAT(ARTICULO, '' - '', DESCRIPCION) AS COMPLETO
                FROM EXACTUSERP.['+ISNULL(@CIA, '')+'].ARTICULO
				where ACTIVO=''S''
                '

    INSERT INTO @TABLE EXECUTE    SP_EXECUTESQL @SQL

    SELECT *
    FROM @TABLE
END

