	      WHERE MAR.AGRUPACION = 2'

SET @PARAM = '@FECHAINI varchar(15)'


INSERT INTO @TABLE EXEC SP_EXECUTESQL @SQL
	 
SELECT * FROM @TABLE NOLOCK

END 
