CREATE   PROCEDURE [GLOBAL].[PROC_OBT_CLIENTE_X_ID] (
	@CLIENTE VARCHAR(20),
	@CIA VARCHAR(20)
)
AS
BEGIN
	DECLARE @SQL NVARCHAR(MAX)
	DECLARE @TABLE TABLE(
		CLIENTE VARCHAR(50),
		NOMBRE VARCHAR(250),
		VENDEDOR VARCHAR(50),
		NOMBRE_VENDEDOR VARCHAR(250),
		COBRADOR VARCHAR(50),
		NOMBRE_COBRADOR VARCHAR(250)
	)

	SET @SQL = 'SELECT CC.CLIENTE, 
					CC.NOMBRE, 
					CC.VENDEDOR, 
					VV.NOMBRE NOMBRE_VENDEDOR,
					CC.COBRADOR,
					CB.NOMBRE NOMBRE_COBRADOR
				FROM ExactusERP.' + @CIA + '.CLIENTE CC
				JOIN ExactusERP.' + @CIA + '.VENDEDOR VV ON VV.VENDEDOR = CC.VENDEDOR
				JOIN ExactusERP.' + @CIA + '.COBRADOR CB ON CB.COBRADOR = CC.COBRADOR
				WHERE CC.CLIENTE = @CLIENTE
				'
				
	INSERT INTO @TABLE 
	EXECUTE	SP_EXECUTESQL @SQL,
						N'@CLIENTE VARCHAR(50)',
						@CLIENTE

	SELECT 
		CLIENTE,
		NOMBRE,
		VENDEDOR,
		NOMBRE_VENDEDOR,
		COBRADOR,
		NOMBRE_COBRADOR
	FROM @TABLE
END
