/****** Object:  StoredProcedure [GLOBAL].[PROC_OBT_COMPROBANTE_APLICACION]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [GLOBAL].[PROC_OBT_COMPROBANTE_APLICACION]
(
	@DOCUMENTO VARCHAR(20),
	@CIA VARCHAR(50)
)
AS
BEGIN
	SET NOCOUNT ON;
    SET CONCAT_NULL_YIELDS_NULL OFF;

	DECLARE @ANCHO INT = 42,
			@SALTO VARCHAR(2) = CHAR(13) + CHAR(10),
			@SEPARADOR VARCHAR(50),
			@TEXTO NVARCHAR(MAX) = '',
			@COL_ANCHO INT,
			@SQL NVARCHAR(MAX);

	set @SEPARADOR = REPLICATE('-', @ANCHO);
	SET @COL_ANCHO = @ANCHO / 5;

	SET @SQL = '
						SELECT @TEXTO = @SALTO +
										REPLICATE('' '', (@ANCHO - LEN(LTRIM(RTRIM(CC.NOMBRE_CIA)))) / 2) + CC.NOMBRE_CIA + @SALTO +
										REPLICATE('' '', (@ANCHO - LEN(LTRIM(RTRIM(''Cédula Jurídica No.'' + CC.NIT)))) / 2) + ''Cédula Jurídica No.'' + CC.NIT + @SALTO +
										REPLICATE('' '', (@ANCHO - LEN(LTRIM(RTRIM(DIREC1)))) / 2) + DIREC1 + @SALTO +
										REPLICATE('' '', (@ANCHO - LEN(LTRIM(RTRIM(TELEFONO)))) / 2) + TELEFONO + @SALTO +
										@SEPARADOR + @SALTO + @SALTO +
										REPLICATE('' '', (@ANCHO - LEN(LTRIM(RTRIM(''Recibo por Dinero'')))) / 2) + ''Recibo por Dinero'' + @SALTO +
										REPLICATE('' '', (@ANCHO - LEN(LTRIM(RTRIM(''Original'')))) / 2) + ''Original'' + @SALTO +
										@SEPARADOR + @SALTO + @SALTO +
										''Referencia: '' + REPLICATE('' '', (@ANCHO - LEN(''Referencia: '' + ISNULL(DCC.REFERENCIA, '''')))) + ISNULL(DCC.REFERENCIA, '''') + @SALTO +
										''Fecha: '' + REPLICATE('' '', (@ANCHO - LEN(''Fecha: '' + ISNULL(DCC.FECHA_MOV, '''')))) + ISNULL(DCC.FECHA_MOV, '''') + @SALTO +
										''Hora: '' + REPLICATE('' '', (@ANCHO - LEN(''Hora: '' + ISNULL(DCC.HORA, '''')))) + ISNULL(DCC.HORA, '''') + @SALTO +
										''Moneda: '' + REPLICATE('' '', (@ANCHO - LEN(''Moneda: '' + ISNULL(DCC.MONEDA, '''')))) + ISNULL(DCC.MONEDA, '''') + @SALTO +
										''Metodo Pago: '' + REPLICATE('' '', (@ANCHO - LEN(''Metodo Pago: '' + ISNULL(DCC.METODO_PAGO_DESC, '''')))) + ISNULL(DCC.METODO_PAGO_DESC, '''') + @SALTO +
										[GLOBAL].[FUNC_WRAP_TEXT](''Cliente: '' + DCC.CLIENTE + '' - '' + DCC.NOM_CLIENTE, @ANCHO) + @SALTO +
										@SEPARADOR + @SALTO + @SALTO +
										CASE
											WHEN DETALLE = ''ADELANTO'' THEN ''''
											ELSE ''Numero Documento'' + ''       '' + ''Abonado'' + ''    '' + ''Saldo'' + @SALTO +
													ISNULL((
															SELECT STRING_AGG(
																   LEFT(x.DEBITO + REPLICATE('' '', 23), 23)
																 + LEFT(LTRIM(RTRIM(CONVERT(VARCHAR(20), 
																		CAST(x.MONTO_DEBITO AS DECIMAL(18,2))
																   ))) + REPLICATE('' '', 10), 10)
																 + LTRIM(RTRIM(CONVERT(VARCHAR(20), 
																		CAST(x.SALDO AS DECIMAL(18,2))
																   )))
																 , @SALTO
															)
															FROM (
																SELECT DISTINCT 
																	   AC.DEBITO,
																	   AC.MONTO_DEBITO,
																	   DC.SALDO
																FROM EXACTUSERP.' + @CIA + '.AUXILIAR_CC AC
																JOIN EXACTUSERP.' + @CIA + '.DOCUMENTOS_CC DC 
																	 ON DC.DOCUMENTO = AC.DEBITO 
																	AND DC.TIPO = AC.TIPO_DEBITO
																WHERE AC.CREDITO      = DCC.REFERENCIA 
																AND   AC.TIPO_CREDITO = DCC.REFERENCIA_TIPO
															) X
														), '''') + @SALTO 
										END + @SALTO +
										''Total Documentos: '' + REPLICATE('' '', (@ANCHO - LEN(''Total Documentos: '' + ISNULL(FORMAT(DCC.MONTO_DEBITO, ''N2''), ''0.00'')))) + ISNULL(FORMAT(DCC.MONTO_DEBITO, ''N2''), ''0.00'') + @SALTO +
										@SEPARADOR + @SALTO + 
										[GLOBAL].[FUNC_WRAP_TEXT](DCC.NOTAS, @ANCHO) + @SALTO +
										@SALTO + @SALTO +
										REPLICATE('' '', (@ANCHO - LEN(LTRIM(RTRIM(''RESUMEN DE MONTOS TOTALES'')))) / 2) + ''RESUMEN DE MONTOS TOTALES'' + @SALTO +
										''Monto: '' + REPLICATE('' '', (@ANCHO - LEN(''Monto: '' + ISNULL(FORMAT(DCC.MONTO_CREDITO, ''N2''), ''0.00'')))) + ISNULL(FORMAT(DCC.MONTO_CREDITO, ''N2''), ''0.00'') + @SALTO +
										''Recibo: '' + REPLICATE('' '', (@ANCHO - LEN(''Recibo: '' + ISNULL(FORMAT(DCC.MONTO_CREDITO, ''N2''), ''0.00'')))) + ISNULL(FORMAT(DCC.MONTO_CREDITO, ''N2''), ''0.00'') + @SALTO +
										@SEPARADOR + @SALTO + @SALTO + @SALTO + @SALTO +
										REPLICATE('' '', (@ANCHO - LEN(LTRIM(RTRIM(''Firma ____________________'')))) / 2) + ''Firma ____________________'' + @SALTO +
										@SALTO + @SALTO 
						FROM [' + @CIA + '].[VIEW_REPORTE_COMPROBANTE_APLICACION_V2] DCC
						CROSS APPLY ( 
											SELECT NIT, 
												NOMBRE NOMBRE_CIA,
												DIREC1,
												TELEFONO
											FROM EXACTUSERP.ERPADMIN.CONJUNTO 
											WHERE CONJUNTO = ''' + @CIA + '''
									) CC
						WHERE DCC.REFERENCIA = @DOCUMENTO
	'
	PRINT @SQL
	EXEC SP_EXECUTESQL @SQL, 
						N'@DOCUMENTO VARCHAR(20),
						@ANCHO INT = 42,
						@SALTO VARCHAR(2),
						@SEPARADOR VARCHAR(50),
						@TEXTO NVARCHAR(MAX) OUTPUT',
						@DOCUMENTO,
						@ANCHO,
						@SALTO,
						@SEPARADOR,
						@TEXTO OUTPUT


	SELECT 
    TRANSLATE(
        @TEXTO COLLATE Latin1_General_CS_AS,
        'ÁÉÍÓÚáéíóúÄËÏÖÜäëïöüÑñ',
        'AEIOUaeiouAEIOUaeiouNn'
    ) AS TEXTO_IMPRESION;
END 
GO
/****** Object:  StoredProcedure [GLOBAL].[PROC_OBT_CONCILIACIONES_FILTRO]    Script Date: 22/5/2026 17:05:06 ******/
