CREATE   PROCEDURE [GLOBAL].[PROC_OBT_CONCILIACIONES_FILTRO](
@CUENTA_BANCO VARCHAR(22),
@FECHA VARCHAR(10),
@CIA VARCHAR(30))
AS 
BEGIN  
DECLARE @SQL NVARCHAR(MAX)
DECLARE @TABLE TABLE (CONCILIACION VARCHAR(200))

SET @SQL = 'SELECT 
				CONCAT(CONCILIACION, ''//'', CUENTA_BANCO)
			FROM EXACTUSERP.['+ISNULL(@CIA,'')+'].CONCILIACION
			WHERE CONVERT(DATE, @FECHA, 103) BETWEEN FECHA_INICIAL AND FECHA_FINAL
			AND CUENTA_BANCO = REPLACE(@CUENTA_BANCO,''CR'','''')
			'

INSERT INTO @TABLE
EXEC SP_EXECUTESQL @SQL, N'@CUENTA_BANCO VARCHAR(22),
						 @FECHA VARCHAR(10)',
						 @CUENTA_BANCO,
						 @FECHA

SELECT CONCILIACION FROM @TABLE

END
GO
/****** Object:  StoredProcedure [GLOBAL].[PROC_OBT_CONCILIACIONES_TODAS_FILTRO]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE   PROCEDURE [GLOBAL].[PROC_OBT_CONCILIACIONES_TODAS_FILTRO](
@CUENTA_BANCO VARCHAR(22),
@CIA VARCHAR(30))
AS 
BEGIN  
DECLARE @SQL NVARCHAR(MAX)
DECLARE @TABLE TABLE (CONCILIACION VARCHAR(50),
					  COMPLETO VARCHAR (200),
					  CREATEDATE DATETIME)

SET @SQL = '-- Usa una Expresión de Tabla Común (CTE) para manejar el ordenamiento
			WITH ResultadosCombinados AS (
				SELECT 
					''N'' AS ESTADO, 
					''Sin conciliación'' AS DESCRIPCION,
					''3030-01-01'' AS CreateDate  -- Incluye NULL o un valor ficticio para la columna CreateDate
				UNION
				SELECT 
					CONCAT(CONCILIACION, ''//'', CUENTA_BANCO) AS ESTADO,
					CONCAT(
						CONCILIACION, 
						'' || '', 
						CUENTA_BANCO, 
						'' || '', 
						CASE DATEPART(MONTH, CONVERT(DATE, FECHA_INICIAL, 103))
							WHEN 1 THEN ''Enero''
							WHEN 2 THEN ''Febrero''
							WHEN 3 THEN ''Marzo''
							WHEN 4 THEN ''Abril''
							WHEN 5 THEN ''Mayo''
							WHEN 6 THEN ''Junio''
							WHEN 7 THEN ''Julio''
							WHEN 8 THEN ''Agosto''
							WHEN 9 THEN ''Septiembre''
							WHEN 10 THEN ''Octubre''
							WHEN 11 THEN ''Noviembre''
							WHEN 12 THEN ''Diciembre''
						END,
						'' '',
						YEAR(CONVERT(DATE, FECHA_INICIAL, 103))  -- Agrega el año
					) AS DESCRIPCION,
					CreateDate
				FROM EXACTUSERP.['+ISNULL(@CIA,'')+'].CONCILIACION
				WHERE YEAR(CONVERT(DATE, FECHA_INICIAL, 103)) = YEAR(GETDATE())  -- Filtra por el año actual
				AND (CUENTA_BANCO = REPLACE(@CUENTA_BANCO,''CR'','''') OR @CUENTA_BANCO IS NULL)
			)
			-- Selecciona desde la CTE o tabla derivada con ordenamiento
			SELECT * 
			FROM ResultadosCombinados
			ORDER BY CreateDate DESC;  -- Ordena por la columna CreateDate
			'

INSERT INTO @TABLE
EXEC SP_EXECUTESQL @SQL,N'@CUENTA_BANCO VARCHAR(22)',
						  @CUENTA_BANCO

SELECT CONCILIACION, 
	   COMPLETO,
	   CREATEDATE
	   FROM @TABLE

END
GO
