/****** Object:  StoredProcedure [GLOBAL].[PROC_OBT_CUENTAS_X_COBRAR]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [GLOBAL].[PROC_OBT_CUENTAS_X_COBRAR]
    @FECHA_INICIO VARCHAR(25),
    @FECHA_FINAL  VARCHAR(25),
    @DOCUMENTO    VARCHAR(40)  = NULL,
    @TIPO         VARCHAR(40)  = NULL,
    @SUBTIPO      VARCHAR(30)  = NULL,
    @VENDEDOR     VARCHAR(50)  = NULL,
    @CIA          VARCHAR(20)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @SQL   NVARCHAR(MAX);
    DECLARE @TABLE TABLE
    (
        DOCUMENTO_DEBITO   VARCHAR(40),
        TIPO               VARCHAR(40),
        SUBTIPO            VARCHAR(30),
        FECHA_DOCUMENTO    DATETIME,
        FECHA_DOCUMENTO_STR VARCHAR(10),
        FECHA_VENCE        DATETIME,
        FECHA_VENCE_STR    VARCHAR(10),
        DIAS_NETO          INT,
        MONTO              DECIMAL(28,8),
        MONTO_STR          VARCHAR(50),
        SALDO              DECIMAL(28,8),
        SALDO_STR          VARCHAR(50),
        MONTO_PAGO         DECIMAL(28,8),
        MONTO_PAGO_STR     VARCHAR(50),
        NOMBRE_VENDEDOR    VARCHAR(50)
    );

    SET @SQL = N'
    SELECT DISTINCT
           DOC.DOCUMENTO_DEBITO,
           DOC.TIPO_DEBITO        AS TIPO,
           DOC.SUBTIPO_DEBITO     AS SUBTIPO,
           DOC.FECHA_DOCUMENTO_DEBITO       AS FECHA_DOCUMENTO,
           CONVERT(VARCHAR, DOC.FECHA_DOCUMENTO_DEBITO, 103) AS FECHA_DOCUMENTO_STR,
           DOC.FECHA_VENCE_DEBITO           AS FECHA_VENCE,
           CONVERT(VARCHAR, DOC.FECHA_VENCE_DEBITO,    103) AS FECHA_VENCE_STR,
           DOC.DIAS_NETO,
           DOC.MONTO_DEBITO       AS MONTO,
           CONVERT(VARCHAR, CAST(DOC.MONTO_DEBITO AS MONEY), 1) AS MONTO_STR,
           DOC.SALDO_DEBITO       AS SALDO,
           CONVERT(VARCHAR, CAST(DOC.SALDO_DEBITO AS MONEY), 1) AS SALDO_STR,
           DOC.MONTO_PAGO,
           CONVERT(VARCHAR, CAST(DOC.MONTO_PAGO AS MONEY),    1) AS MONTO_PAGO_STR,
           V.NOMBRE               AS NOMBRE_VENDEDOR
    FROM  ' + QUOTENAME(@CIA) + N'.REPORTE_CUADRE_AUXILIAR DOC WITH (NOLOCK)
 LEFT JOIN EXACTUSERP.' + QUOTENAME(@CIA) + N'.VENDEDOR V WITH(NOLOCK)
    ON V.VENDEDOR = DOC.COD_VENDEDOR_CLI  
    WHERE  DOC.FECHA_DOCUMENTO_DEBITO BETWEEN @FECHA_INICIO AND @FECHA_FINAL
      AND  (@DOCUMENTO IS NULL OR DOC.DOCUMENTO_DEBITO = @DOCUMENTO)
      AND  (
               @TIPO IS NULL
            OR DOC.TIPO_DEBITO IN (
                   SELECT VAL
                   FROM  ' + QUOTENAME(@CIA) + N'.TF_SPLIT(@TIPO, '','')
               )
           )
      AND  (
               @SUBTIPO IS NULL
            OR DOC.SUBTIPO_DEBITO IN (
                   SELECT VAL
                   FROM  ' + QUOTENAME(@CIA) + N'.TF_SPLIT(@SUBTIPO, '','')
               )
           )
      AND  (@VENDEDOR   IS NULL OR DOC.COD_VENDEDOR_CLI = @VENDEDOR) 

      AND  DOC.SALDO_DEBITO > 1
    ORDER BY DOC.FECHA_DOCUMENTO_DEBITO DESC;';

    INSERT INTO @TABLE
    EXEC sp_executesql
         @SQL,
         N'@FECHA_INICIO VARCHAR(25),
           @FECHA_FINAL  VARCHAR(25),
           @DOCUMENTO    VARCHAR(40),
           @TIPO         VARCHAR(40),
           @SUBTIPO      VARCHAR(30),
           @VENDEDOR     VARCHAR(50)',
         @FECHA_INICIO,
         @FECHA_FINAL,
         @DOCUMENTO,
         @TIPO,
         @SUBTIPO,
         @VENDEDOR;

    SELECT *
    FROM   @TABLE;
END
GO
