CREATE PROCEDURE [GLOBAL].[PROC_OBT_DOC_CXC_EXPEDIENTE_DIGITAL](
    @PROV_CLIENTE VARCHAR(20),
	@FECHA_INICIO VARCHAR(10),
	@FECHA_FIN VARCHAR(10),
	@CIA VARCHAR(20)
)
AS
BEGIN
	DECLARE @SQL NVARCHAR(MAX), @PARAM NVARCHAR(MAX)
	DECLARE @TABLE TABLE(DOCUMENTO VARCHAR(50))

	SET @SQL = 'SELECT 
				      DOCUMENTO
                FROM 
                EXACTUSERP.['+ISNULL(@CIA, '')+'].[DOCUMENTOS_CC] WITH(NOLOCK)
				WHERE (CLIENTE = @PROV_CLIENTE)
				AND   CREATEDATE BETWEEN @FECHA_INICIO AND @FECHA_FIN 

				UNION ALL

				SELECT 
				      DOCUMENTO
                FROM 
                EXACTUSERP.['+ISNULL(@CIA, '')+'].[DOCUMENTOS_CP] WITH(NOLOCK)
				WHERE (PROVEEDOR = @PROV_CLIENTE)
				AND  CONVERT(DATE,CREATEDATE) BETWEEN @FECHA_INICIO AND @FECHA_FIN 
				' 
				
	SET @PARAM =N'@PROV_CLIENTE VARCHAR(20),@FECHA_INICIO VARCHAR(10),@FECHA_FIN VARCHAR(10)'
	
	INSERT INTO @TABLE	EXEC SP_EXECUTESQL @SQL,@PARAM,@PROV_CLIENTE,@FECHA_INICIO,@FECHA_FIN

	SELECT * FROM @TABLE
	ORDER BY DOCUMENTO

END






