/****** Object:  StoredProcedure [GLOBAL].[PROC_OBT_DOCUMENTO_ESTADO_CUENTA_BANCARIO]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [GLOBAL].[PROC_OBT_DOCUMENTO_ESTADO_CUENTA_BANCARIO]  (
@CUENTA_BANCARIA VARCHAR(22),
@DOCUMENTO VARCHAR(50),
@CIA VARCHAR(20)
)
AS
-- =============================================
-- Empresa: PRODUSOFT
-- Autor: Dario Rodriguez Obando
-- Información: drodriguez@produsoftcr.com
-- Parametros: @CIA-schema y compañia
-- Objetivo: Obtener los Proveedores de la base de datos para mostrar al usuario
-- =============================================
BEGIN
DECLARE @SQL NVARCHAR(MAX)
DECLARE @TABLE TABLE(
	   [TIPO] VARCHAR(10)
	  ,[SUBTIPO] VARCHAR(10)
	  ,[FECHA_TEF_STR] VARCHAR(10)
	  ,[PS_86_REFERENCIA] VARCHAR(200)
	  ,[MONTO] DECIMAL(28,8)
	  ,[MONEDA] VARCHAR(4)
	  ,[ID_LINEA] INT
	)

SET @SQL='SELECT TOP 1
			[TIPO]
			,[SUBTIPO]
			,[FECHA_TEF_STR]
			,[PS_86_REFERENCIA]
			,[MONTO_TRIGGER]
			,[MONEDA]
			,[ID_LINEA]
			FROM ['+ISNULL(@CIA, '')+'].[PS_VIEW_OBT_LISTADO_MT940]
			WHERE (CUENTA_BANCO = @CUENTA_BANCARIA
					OR CUENTA_BANCO = (
						SELECT CTA_ELECTRONICA 
						FROM EXACTUSERP.DIS86.CUENTA_BANCARIA 
						WHERE CUENTA_BANCO = @CUENTA_BANCARIA
					)
					)
			AND REFERENCIA = @DOCUMENTO'

INSERT INTO @TABLE EXECUTE SP_EXECUTESQL @SQL, N'@CUENTA_BANCARIA VARCHAR(22),
												@DOCUMENTO VARCHAR(50)',
												@CUENTA_BANCARIA,
												@DOCUMENTO

SELECT   
	 [TIPO]
	,[SUBTIPO]
	,[FECHA_TEF_STR]
	,[PS_86_REFERENCIA]
	,[MONTO]
	,[MONEDA]
	,[ID_LINEA]

FROM @TABLE
END
GO
