/****** Object:  StoredProcedure [GLOBAL].[PROC_OBT_DOCUMENTOS_INDEX_CC]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [GLOBAL].[PROC_OBT_DOCUMENTOS_INDEX_CC](
    @FECHA_INICIO VARCHAR(25),
    @FECHA_FINAL  VARCHAR(25),
    @CLIENTE      VARCHAR(20),
    @MONEDA       VARCHAR(4),
    @CIA          VARCHAR(20)
)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @SQL NVARCHAR(MAX);

    DECLARE @TABLE TABLE(
        TIPO                   VARCHAR(3),
        DOCUMENTO              VARCHAR(50),
        TIPO_CAMBIO            DECIMAL(28,8),
        FECHA                  VARCHAR(25),
        CONDICION_PAGO         VARCHAR(4),
        U_ORDEN_COMPRA         VARCHAR(30),
        MONEDA                 VARCHAR(4),
        MONTO                  DECIMAL(28,8),
        MONTO_MILES            VARCHAR(50),
        SALDO                  DECIMAL(28,8),
        SALDO_MILES            VARCHAR(50),
        IMPUESTO1              DECIMAL(28,8),
        IMPUESTO_MILES         VARCHAR(50),
        CODIGO_IMPUESTO        DECIMAL(28,8),
        USUARIO_APROBACION     VARCHAR(25),
        CLIENTE_CONTRIBUYENTE  VARCHAR(200),
        TIPO_CAMBIO_MH         DECIMAL(28,8),
        USUARIO                VARCHAR(50),
        COD_PROVEEDOR          VARCHAR(20),
        SUBTIPO                INT,
        FECHA_REAL             DATETIME
    );

    SET @SQL = N'
        SELECT
            CC.TIPO,
            CC.DOCUMENTO,
            CC.TIPO_CAMBIO_DOLAR                         AS TIPO_CAMBIO,
            CONVERT(VARCHAR(15), CC.FECHA, 103)          AS FECHA,
            CC.CONDICION_PAGO,
            ''N''                                        AS U_ORDEN_COMPRA,
            CC.MONEDA,
            CC.MONTO,
            CONVERT(VARCHAR, CAST(CC.MONTO AS MONEY), 1) AS MONTO_MILES,
            CC.SALDO,
            CONVERT(VARCHAR, CAST(CC.SALDO AS MONEY), 1) AS SALDO_MILES,
            CC.IMPUESTO1,
            CONVERT(VARCHAR, CAST(CC.IMPUESTO1 AS MONEY), 1) AS IMPUESTO_MILES,
            0                                            AS CODIGO_IMPUESTO,
            CC.USUARIO_APROBACION,
            C.CLIENTE + '' - '' + C.NOMBRE              AS CLIENTE_CONTRIBUYENTE,
            CC.TIPO_CAMBIO_MONEDA                        AS TIPO_CAMBIO_MH,
            ISNULL(CC.USUARIO_ULT_MOD, ''N/D'')          AS USUARIO,
            CC.CLIENTE                                   AS COD_PROVEEDOR,
            CC.SUBTIPO,
            CC.FECHA                                     AS FECHA_REAL
        FROM ExactusERP.' + ISNULL(@CIA, '''') + '.DOCUMENTOS_CC CC
        JOIN ExactusERP.' + ISNULL(@CIA, '''') + '.CLIENTE C ON C.CLIENTE = CC.CLIENTE
        WHERE CC.SALDO > 0 AND CC.TIPO = ''REC''
          AND CC.FECHA BETWEEN @FECHA_INICIO AND @FECHA_FINAL
          AND (@CLIENTE IS NULL OR CC.CLIENTE = @CLIENTE)
          AND (@MONEDA  IS NULL OR CC.MONEDA  = @MONEDA)
        ORDER BY CC.FECHA DESC;
    ';

    INSERT INTO @TABLE
    EXEC SP_EXECUTESQL
        @SQL,
        N'@FECHA_INICIO VARCHAR(25),
          @FECHA_FINAL  VARCHAR(25),
          @CLIENTE      VARCHAR(20),
          @MONEDA       VARCHAR(4)',
        @FECHA_INICIO,
        @FECHA_FINAL,
        @CLIENTE,
        @MONEDA;

    -- ?? Aquí exponemos “MONTO_A_LIQUIDAR = SALDO”
    SELECT
        TIPO,
        DOCUMENTO,
        TIPO_CAMBIO,
        FECHA,
        CONDICION_PAGO,
        U_ORDEN_COMPRA,
        MONEDA,
        MONTO,
        MONTO_MILES,
        SALDO           AS MONTO_A_LIQUIDAR,  -- << alias que verá el frontend
        SALDO,
        SALDO_MILES,
        IMPUESTO1,
        IMPUESTO_MILES,
        CODIGO_IMPUESTO,
        USUARIO_APROBACION,
        CLIENTE_CONTRIBUYENTE,
        TIPO_CAMBIO_MH,
        USUARIO,
        COD_PROVEEDOR,
        SUBTIPO,
        FECHA_REAL
    FROM @TABLE;
END
GO
/****** Object:  StoredProcedure [GLOBAL].[PROC_OBT_DOCUMENTOS_INDEX_CC_V2]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [GLOBAL].[PROC_OBT_DOCUMENTOS_INDEX_CC_V2](
    @FECHA_INICIO VARCHAR(25),
    @FECHA_FINAL  VARCHAR(25),
    @CLIENTE      VARCHAR(20),
    @MONEDA       VARCHAR(4),
    @CIA          VARCHAR(20)
)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @SQL NVARCHAR(MAX);

    DECLARE @TABLE TABLE(
        TIPO                   VARCHAR(3),
        DOCUMENTO              VARCHAR(50),
        TIPO_CAMBIO            DECIMAL(28,8),
        FECHA                  VARCHAR(25),
        CONDICION_PAGO         VARCHAR(4),
        U_ORDEN_COMPRA         VARCHAR(30),
        MONEDA                 VARCHAR(4),
        MONTO_ORIGINAL         DECIMAL(28,8),
        MONTO_LIQUIDADO        DECIMAL(28,8),   -- ? NUEVO
        MONTO_A_LIQUIDAR       DECIMAL(28,8),
        SALDO                  DECIMAL(28,8),
        MONTO_MILES            VARCHAR(50),
        SALDO_MILES            VARCHAR(50),
        IMPUESTO1              DECIMAL(28,8),
        IMPUESTO_MILES         VARCHAR(50),
        CODIGO_IMPUESTO        DECIMAL(28,8),
        USUARIO_APROBACION     VARCHAR(25),
        CLIENTE_CONTRIBUYENTE  VARCHAR(200),
        TIPO_CAMBIO_MH         DECIMAL(28,8),
        USUARIO                VARCHAR(50),
        COD_PROVEEDOR          VARCHAR(20),
        SUBTIPO                INT,
        FECHA_REAL             DATETIME
    );

    SET @SQL = N'
        SELECT
            CC.TIPO,
            CC.DOCUMENTO,
            CC.TIPO_CAMBIO_DOLAR                         AS TIPO_CAMBIO,
            CONVERT(VARCHAR(15), CC.FECHA, 103)          AS FECHA,
            CC.CONDICION_PAGO,
            ''N''                                        AS U_ORDEN_COMPRA,
            CC.MONEDA,
            CC.MONTO                                     AS MONTO_ORIGINAL,
            (CC.MONTO - CC.SALDO_CLIENTE)                AS MONTO_LIQUIDADO,
            CC.SALDO_CLIENTE                             AS MONTO_A_LIQUIDAR,
            CC.SALDO_CLIENTE                             AS SALDO,
            CONVERT(VARCHAR, CAST(CC.MONTO AS MONEY), 1) AS MONTO_MILES,
            CONVERT(VARCHAR, CAST(CC.SALDO_CLIENTE AS MONEY), 1) AS SALDO_MILES,
            CC.IMPUESTO1,
            CONVERT(VARCHAR, CAST(CC.IMPUESTO1 AS MONEY), 1) AS IMPUESTO_MILES,
            0                                            AS CODIGO_IMPUESTO,
            CC.USUARIO_APROBACION,
            C.CLIENTE + '' - '' + C.NOMBRE              AS CLIENTE_CONTRIBUYENTE,
            CC.TIPO_CAMBIO_MONEDA                        AS TIPO_CAMBIO_MH,
            ISNULL(CC.USUARIO_ULT_MOD, ''N/D'')          AS USUARIO,
            CC.CLIENTE                                   AS COD_PROVEEDOR,
            CC.SUBTIPO,
            CC.FECHA                                     AS FECHA_REAL
        FROM ExactusERP.' + ISNULL(@CIA, '''') + '.DOCUMENTOS_CC CC
        JOIN ExactusERP.' + ISNULL(@CIA, '''') + '.CLIENTE C ON C.CLIENTE = CC.CLIENTE
        WHERE CC.FECHA BETWEEN @FECHA_INICIO AND @FECHA_FINAL
          AND (@CLIENTE IS NULL OR CC.CLIENTE = @CLIENTE)
          AND (@MONEDA  IS NULL OR CC.MONEDA  = @MONEDA)
        ORDER BY CC.FECHA DESC;
    ';

    INSERT INTO @TABLE
    EXEC SP_EXECUTESQL
        @SQL,
        N'@FECHA_INICIO VARCHAR(25),
          @FECHA_FINAL  VARCHAR(25),
          @CLIENTE      VARCHAR(20),
          @MONEDA       VARCHAR(4)',
        @FECHA_INICIO, @FECHA_FINAL, @CLIENTE, @MONEDA;

    SELECT
        TIPO,
        DOCUMENTO,
        TIPO_CAMBIO,
        FECHA,
        CONDICION_PAGO,
        U_ORDEN_COMPRA,
        MONEDA,
        MONTO_ORIGINAL,
        MONTO_LIQUIDADO,   -- ? asegúrate que salga
        SALDO,
        MONTO_A_LIQUIDAR,
        MONTO_MILES,
        SALDO_MILES,
        IMPUESTO1,
        IMPUESTO_MILES,
        CODIGO_IMPUESTO,
        USUARIO_APROBACION,
        CLIENTE_CONTRIBUYENTE,
        TIPO_CAMBIO_MH,
        USUARIO,
        COD_PROVEEDOR,
        SUBTIPO,
        FECHA_REAL
    FROM @TABLE;
END
GO
/****** Object:  StoredProcedure [GLOBAL].[PROC_OBT_DOCUMENTOS_INDEX_CC_V3]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [GLOBAL].[PROC_OBT_DOCUMENTOS_INDEX_CC_V3](
    @FECHA_INICIO VARCHAR(25),
    @FECHA_FINAL  VARCHAR(25),
	@COBRADOR	  VARCHAR(20),
	@VENDEDOR	  VARCHAR(50),
    @CLIENTE      VARCHAR(20),
    @SUBTIPO      VARCHAR(20),
	@DEPOSITO	  VARCHAR(50),
	@DEPOSITADO	  VARCHAR(1),
    @CIA          VARCHAR(20)
)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @SQL NVARCHAR(MAX);
	DECLARE @WHERE NVARCHAR(MAX)

    DECLARE @TABLE TABLE(
        TIPO                   VARCHAR(3),
        DOCUMENTO              VARCHAR(50),
        TIPO_CAMBIO            DECIMAL(28,8),
        FECHA                  VARCHAR(25),
        CONDICION_PAGO         VARCHAR(4),
        U_ORDEN_COMPRA         VARCHAR(30),
        MONEDA                 VARCHAR(4),
        MONTO                  DECIMAL(28,8),
        MONTO_MILES            VARCHAR(50),
        SALDO                  DECIMAL(28,8),
        SALDO_MILES            VARCHAR(50),
        IMPUESTO1              DECIMAL(28,8),
        IMPUESTO_MILES         VARCHAR(50),
        CODIGO_IMPUESTO        DECIMAL(28,8),
        USUARIO_APROBACION     VARCHAR(25),
        CLIENTE_CONTRIBUYENTE  VARCHAR(200),
        TIPO_CAMBIO_MH         DECIMAL(28,8),
        USUARIO                VARCHAR(50),
        COD_PROVEEDOR          VARCHAR(20),
        SUBTIPO                INT,
        FECHA_REAL             DATETIME,
		SUBTIPO_DESC		   VARCHAR(250),
		VENDEDOR			   VARCHAR(20),
		COBRADOR			   VARCHAR(20),
		VENDEDOR_NOMBRE		   VARCHAR(250),
		COBRADOR_NOMBRE		   VARCHAR(250),
		DEPOSITADO			   VARCHAR(30)
    );

	SET @WHERE = '';

	IF(@COBRADOR <> '0')
		BEGIN
			SET @WHERE = @WHERE + ' AND CC.COBRADOR = ''' + @COBRADOR + ''''
		END

	IF(@VENDEDOR <> '0')
		BEGIN
			SET @WHERE = @WHERE + ' AND CC.VENDEDOR = ''' + @VENDEDOR + ''''
		END

	IF(@CLIENTE <> '0')
		BEGIN
			SET @WHERE = @WHERE + ' AND CC.CLIENTE = ''' + @CLIENTE + ''''
		END

	IF(@SUBTIPO <> '0')
		BEGIN
			SET @WHERE = @WHERE + ' AND CC.SUBTIPO = ''' + @SUBTIPO + ''''
		END

	IF(@DEPOSITO <> '0')
		BEGIN
			SET @WHERE = @WHERE + ' AND CC.DOCUMENTO = ''' + @DEPOSITO + ''''
		END

	IF(@DEPOSITADO <> '0')
		BEGIN
			IF(@DEPOSITADO = 'S')
				BEGIN
					SET @WHERE = @WHERE + ' AND CC.U_PS_ESTADO_LIQUIDACION IS NOT NULL'
				END
			ELSE
				BEGIN
					SET @WHERE = @WHERE + ' AND CC.U_PS_ESTADO_LIQUIDACION IS NULL'
				END
		END
	
    SET @SQL = N'
        SELECT
            CC.TIPO,
            CC.DOCUMENTO,
            CC.TIPO_CAMBIO_DOLAR                         AS TIPO_CAMBIO,
            CONVERT(VARCHAR(15), CC.FECHA, 103)          AS FECHA,
            CC.CONDICION_PAGO,
            ''N''                                        AS U_ORDEN_COMPRA,
            CC.MONEDA,
            CC.MONTO,
            CONVERT(VARCHAR, CAST(CC.MONTO AS MONEY), 1) AS MONTO_MILES,
            CC.SALDO,
            CONVERT(VARCHAR, CAST(CC.SALDO AS MONEY), 1) AS SALDO_MILES,
            CC.IMPUESTO1,
            CONVERT(VARCHAR, CAST(CC.IMPUESTO1 AS MONEY), 1) AS IMPUESTO_MILES,
            0                                            AS CODIGO_IMPUESTO,
            CC.USUARIO_APROBACION,
            C.CLIENTE + '' - '' + C.NOMBRE              AS CLIENTE_CONTRIBUYENTE,
            CC.TIPO_CAMBIO_MONEDA                        AS TIPO_CAMBIO_MH,
            ISNULL(CC.USUARIO_ULT_MOD, ''N/D'')          AS USUARIO,
            CC.CLIENTE                                   AS COD_PROVEEDOR,
            CC.SUBTIPO,
            CC.FECHA                                     AS FECHA_REAL,
			CAST(CC.SUBTIPO AS VARCHAR) + '' | '' + SDC.DESCRIPCION SUBTIPO_DESC,
			CC.VENDEDOR,
			CC.COBRADOR,
			V.NOMBRE VENDEDOR_NOMBRE,
			CO.NOMBRE COBRADOR_NOMBRE,
			CC.U_PS_ESTADO_LIQUIDACION DEPOSITADO
        FROM ExactusERP.' + ISNULL(@CIA, '''') + '.DOCUMENTOS_CC CC
        JOIN ExactusERP.' + ISNULL(@CIA, '''') + '.CLIENTE C ON C.CLIENTE = CC.CLIENTE
		JOIN ExactusERP.' + ISNULL(@CIA, '''') + '.VENDEDOR V ON V.VENDEDOR = CC.VENDEDOR
		JOIN ExactusERP.' + ISNULL(@CIA, '''') + '.COBRADOR CO ON CO.COBRADOR = CC.COBRADOR
		JOIN ExactusERP.' + ISNULL(@CIA, '''') + '.SUBTIPO_DOC_CC SDC ON SDC.TIPO = CC.TIPO AND SDC.SUBTIPO = CC.SUBTIPO
        WHERE CC.TIPO = ''REC''
			AND CC.FECHA BETWEEN @FECHA_INICIO AND @FECHA_FINAL
          ' + @WHERE + '
        ORDER BY CC.FECHA DESC;
    ';
	
    INSERT INTO @TABLE
    EXEC SP_EXECUTESQL
        @SQL,
        N'@FECHA_INICIO VARCHAR(25),
          @FECHA_FINAL  VARCHAR(25)',
        @FECHA_INICIO,
        @FECHA_FINAL;

    -- ?? Aquí exponemos “MONTO_A_LIQUIDAR = SALDO”
    SELECT
        TIPO,
        DOCUMENTO,
        TIPO_CAMBIO,
        FECHA,
        CONDICION_PAGO,
        U_ORDEN_COMPRA,
        MONEDA,
        MONTO,
        MONTO_MILES,
        SALDO           AS MONTO_A_LIQUIDAR,  -- << alias que verá el frontend
        SALDO,
        SALDO_MILES,
        IMPUESTO1,
        IMPUESTO_MILES,
        CODIGO_IMPUESTO,
        USUARIO_APROBACION,
        CLIENTE_CONTRIBUYENTE,
        TIPO_CAMBIO_MH,
