        COD_PROVEEDOR,
        SUBTIPO,
        FECHA_REAL,
		SUBTIPO_DESC,
		VENDEDOR,
		COBRADOR,
		VENDEDOR_NOMBRE,
		COBRADOR_NOMBRE,
