/****** Object:  StoredProcedure [GLOBAL].[PROC_OBT_DOCUMENTOS_TOTAL_CC]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [GLOBAL].[PROC_OBT_DOCUMENTOS_TOTAL_CC](
    @FECHA_INICIO VARCHAR(25),
    @FECHA_FINAL  VARCHAR(25),
	@COBRADOR	  VARCHAR(20),
	@VENDEDOR	  VARCHAR(50),
    @CLIENTE      VARCHAR(20),
    @SUBTIPO      VARCHAR(20),
	@DEPOSITO	  VARCHAR(50),
	@DEPOSITADO	  VARCHAR(1),
    @CIA          VARCHAR(20)
)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @SQL NVARCHAR(MAX);
	DECLARE @WHERE NVARCHAR(MAX)

    DECLARE @TABLE TABLE(
        TIPO                   VARCHAR(3),
		SUBTIPO                INT,
        MONTO                  DECIMAL(28,8),
		TOTAL				INT
    );

	SET @WHERE = '';

	IF(@COBRADOR <> '0')
		BEGIN
			SET @WHERE = @WHERE + ' AND CC.COBRADOR = ''' + @COBRADOR + ''''
		END

	IF(@VENDEDOR <> '0')
		BEGIN
			SET @WHERE = @WHERE + ' AND CC.VENDEDOR = ''' + @VENDEDOR + ''''
		END

	IF(@CLIENTE <> '0')
		BEGIN
			SET @WHERE = @WHERE + ' AND CC.CLIENTE = ''' + @CLIENTE + ''''
		END

	IF(@SUBTIPO <> '0')
		BEGIN
			SET @WHERE = @WHERE + ' AND CC.SUBTIPO = ''' + @SUBTIPO + ''''
		END

	IF(@DEPOSITO <> '0')
		BEGIN
			SET @WHERE = @WHERE + ' AND CC.DOCUMENTO = ''' + @DEPOSITO + ''''
		END

	IF(@DEPOSITADO <> '0')
		BEGIN
			IF(@DEPOSITADO = 'S')
				BEGIN
					SET @WHERE = @WHERE + ' AND CC.U_PS_ESTADO_LIQUIDACION IS NOT NULL'
				END
			ELSE
				BEGIN
					SET @WHERE = @WHERE + ' AND CC.U_PS_ESTADO_LIQUIDACION IS NULL'
				END
		END
	
    SET @SQL = N'
        SELECT
            CC.TIPO,
            CC.SUBTIPO,
            SUM(CC.MONTO),
			COUNT(CC.TIPO)
        FROM ExactusERP.' + ISNULL(@CIA, '''') + '.DOCUMENTOS_CC CC
        JOIN ExactusERP.' + ISNULL(@CIA, '''') + '.CLIENTE C ON C.CLIENTE = CC.CLIENTE
		JOIN ExactusERP.' + ISNULL(@CIA, '''') + '.VENDEDOR V ON V.VENDEDOR = CC.VENDEDOR
		JOIN ExactusERP.' + ISNULL(@CIA, '''') + '.COBRADOR CO ON CO.COBRADOR = CC.COBRADOR
		JOIN ExactusERP.' + ISNULL(@CIA, '''') + '.SUBTIPO_DOC_CC SDC ON SDC.TIPO = CC.TIPO AND SDC.SUBTIPO = CC.SUBTIPO
        WHERE CC.TIPO = ''REC''
			AND CC.FECHA BETWEEN @FECHA_INICIO AND @FECHA_FINAL
          ' + @WHERE + '
        GROUP BY CC.TIPO, CC.SUBTIPO;
    ';
	
    INSERT INTO @TABLE
    EXEC SP_EXECUTESQL
        @SQL,
        N'@FECHA_INICIO VARCHAR(25),
          @FECHA_FINAL  VARCHAR(25)',
        @FECHA_INICIO,
        @FECHA_FINAL;

    SELECT
        TIPO,
		SUBTIPO,
        MONTO,
		TOTAL
    FROM @TABLE;
END
GO
