      ,[REFERENCIA] VARCHAR(50)
      ,[TIPO] VARCHAR(10)
	  ,[SUBTIPO] VARCHAR(10)
      ,[DOCUMENTO] VARCHAR(50)
      ,[CARGADO_ERP] VARCHAR(2)
      ,[FECHA_TEF] DATETIME
      ,[FECHA_TEF_STR] VARCHAR(10)
      ,[PS_86_REFERENCIA] VARCHAR(200)
      ,[CREDITO] DECIMAL(28,8)
      ,[DEBITO] DECIMAL(28,8)
	  ,[CREDITO_STR] VARCHAR(50)
      ,[DEBITO_STR] VARCHAR(50)
	  ,[CREDITO_DEBITO] VARCHAR(1)
      ,[ESTADO_CB] VARCHAR(20)
	  ,[FECHA_MT] DATETIME
      ,[FECHA_MT_STR] VARCHAR(10)
      ,[PROVEEDOR] VARCHAR(50)
      ,[CLIENTE] VARCHAR(50)
