	  ,[DOCUMENTO_FUSION] VARCHAR(50)
	  ,[DOCUMENTO_BANCO_VIEJO] VARCHAR(50)
	  ,[SE_INSERTO_EN_MOV_REPORTADOS] VARCHAR(1)
	  ,DUPLICADO_EN_LIBROS VARCHAR(1)
	)
SET @SQL='
	SELECT 
	   [ID_H2H]
	  ,[ID_LINEA]
      ,[CUENTA_BANCO]
      ,[REFERENCIA]
      ,[TIPO]
	  ,[SUBTIPO]
      ,[DOCUMENTO]
      ,[CARGADO_ERP]
      ,[FECHA_TEF]
      ,[FECHA_TEF_STR]
      ,[PS_86_REFERENCIA]
      ,[CREDITO]
      ,[DEBITO]
      ,[CREDITO_STR]
      ,[DEBITO_STR]
      ,[CREDITO_DEBITO]
      ,[ESTADO_CB]
      ,[FECHA_MT]
      ,[FECHA_MT_STR]
      ,[PROVEEDOR]
      ,[CLIENTE]
	  ,[CC_CP]
	  ,[MONEDA]
	  ,[ASOCIADO_H2H]
	  ,[ASIENTO]
	  ,[ESTADO]
	  ,[DOCUMENTO_FUSION]
	  ,[DOCUMENTO_BANCO_VIEJO]
	  ,[SE_INSERTO_EN_MOV_REPORTADOS]
	  ,DUPLICADO_EN_LIBROS
  
	  FROM ['+ISNULL(@CIA, '')+'].[PS_VIEW_OBT_LISTADO_MT940]

	  WHERE FECHA_TEF BETWEEN @FECHA_INICIO AND @FECHA_FINAL 
	  AND	(CUENTA_BANCO = @CUENTA_BANCARIA OR @CUENTA_BANCARIA IS NULL)
	  AND	(TIPO = @TIPO OR @TIPO IS NULL)
	  AND	(SUBTIPO = @SUBTIPO OR @SUBTIPO IS NULL)
	  AND	(DOCUMENTO = @DOCUMENTO_SOFTLAND OR @DOCUMENTO_SOFTLAND IS NULL)
	  AND	(PROVEEDOR = @PROVEEDOR OR @PROVEEDOR IS NULL)
	  AND	(CLIENTE = @CLIENTE OR @CLIENTE IS NULL)
	  AND	(CREDITO_DEBITO = @DEBITO_O_CREDITO OR @DEBITO_O_CREDITO IS NULL)
	  AND	(CC_CP = @CXC_CXP OR @CXC_CXP IS NULL)
	  AND	(ESTADO_CB = @CARGADO_BANCOS OR @CARGADO_BANCOS IS NULL)

	  ORDER BY FECHA_TEF DESC, REFERENCIA'

INSERT INTO @TABLE EXECUTE SP_EXECUTESQL @SQL, N'@FECHA_INICIO VARCHAR(25),
												@FECHA_FINAL VARCHAR(25),
												@CUENTA_BANCARIA VARCHAR(22),
												@TIPO VARCHAR(10),
												@SUBTIPO VARCHAR(10),
												@DOCUMENTO_SOFTLAND VARCHAR(50),
												@PROVEEDOR VARCHAR(20),
												@CLIENTE VARCHAR(50),
												@DEBITO_O_CREDITO VARCHAR(1),
												@CXC_CXP VARCHAR(3),
												@CARGADO_BANCOS VARCHAR(2)',
												@FECHA_INICIO,
												@FECHA_FINAL,
												@CUENTA_BANCARIA,
												@TIPO,
												@SUBTIPO,
												@DOCUMENTO_SOFTLAND,
												@PROVEEDOR,
												@CLIENTE,
												@DEBITO_O_CREDITO,
												@CXC_CXP,
												@CARGADO_BANCOS
SELECT   
	   [ID_H2H]
	  ,[ID_LINEA]
      ,[CUENTA_BANCO]
      ,[REFERENCIA]
      ,[TIPO]
	  ,[SUBTIPO]
      ,[DOCUMENTO]
      ,[CARGADO_ERP]
      ,[FECHA_TEF]
      ,[FECHA_TEF_STR]
      ,[PS_86_REFERENCIA]
      ,[CREDITO]
      ,[DEBITO]
      ,[CREDITO_STR]
      ,[DEBITO_STR]
      ,[CREDITO_DEBITO]
      ,[ESTADO_CB]
      ,[FECHA_MT]
      ,[FECHA_MT_STR]
      ,[PROVEEDOR]
      ,[CLIENTE]
	  ,[CC_CP]
	  ,[MONEDA]
	  ,[ASOCIADO_H2H]
	  ,[ASIENTO]
	  ,[ESTADO]
	  ,[DOCUMENTO_FUSION]
	  ,[DOCUMENTO_BANCO_VIEJO]
	  ,[SE_INSERTO_EN_MOV_REPORTADOS]
	  ,DUPLICADO_EN_LIBROS

FROM @TABLE
END
GO
