/****** Object:  StoredProcedure [GLOBAL].[PROC_OBT_EXPEDIENTE_DIGITAL_PP]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

--- EXEC [GLOBAL].[PROC_OBT_EXPEDIENTE_DIGITAL_PP]  '2024-12-01','2024-12-24',NULL,NULL,NULL,NULL,NULL,1,'ALB_1'

CREATE PROC [GLOBAL].[PROC_OBT_EXPEDIENTE_DIGITAL_PP] 
(
@FECHAINICIO VARCHAR(10),
@FECHAFIN VARCHAR(10),
@TIPO VARCHAR(4),
@MODULO VARCHAR(5),
@PROVEEDOR_CLIENTE VARCHAR(20),
@REFERENCIA VARCHAR(50),
@USUARIO VARCHAR(500),
@ROL INT,
@CIA VARCHAR(20)
)
AS
BEGIN
	DECLARE @SQL NVARCHAR(MAX),@PARAM NVARCHAR(MAX),@FILTROUSUARIO VARCHAR(MAX)
	DECLARE @TABLE TABLE(
	                     [EXPEDIENTE_DIGITAL_PP] INT,
	                     [TIPO] VARCHAR(5),
	                     [DESCRIPCION] VARCHAR(800),
						 [REFERENCIA] VARCHAR(40),
						 [PROVEEDOR] VARCHAR(20),
						 [NOMBRE_PROV_CLI] VARCHAR(800),
						 [MODULO] VARCHAR(5),
						 [NOMBRE] VARCHAR(200),
						 [ADJUNTO] VARCHAR(MAX),
						 [EXTENSION] VARCHAR(10),
						 [FECHA] VARCHAR(10),
						 [USUARIO] VARCHAR(30)
						 )

SET @FILTROUSUARIO = CASE  WHEN @ROL = 3 THEN ''				
							             ELSE 'AND (USUARIO = @USUARIO OR @USUARIO IS NULL)'				
						   END 

	SET @SQL = 'SELECT 
	                   PP.[EXPEDIENTE_DIGITAL_PP],
					   PP.TIPO, 
					   TP.[DESCRIPCION],    
					   PP.[REFERENCIA],
					   PP.[PROVEEDOR_CLIENTE],
					   ISNULL(CASE WHEN PP.TIPO = ''CXC''  THEN CLI.NOMBRE 
		                           WHEN PP.TIPO = ''CXP''  THEN PROV.NOMBRE
	                               END,''ND'') NOMBRE_PROV_CLI,
					   PP.MODULO,
					   TE.[DESCRIPCION]    [NOMBRE_MODULO],
					   PP.[ADJUNTO],
					   PP.[EXTENSION],
					   CONVERT(VARCHAR, PP.[FECHA], 103) [FECHA],
					   PP.[USUARIO]
				FROM   ['+ISNULL(@CIA, '')+'].[EXPEDIENTE_DIGITAL_PP]           AS PP
				JOIN   ['+ISNULL(@CIA, '')+'].[TIPO_EXPEDIENTE_DIGITAL_PP]      AS TP   ON PP.TIPO        = TP.TIPO_EXPEDIENTE_DIGITAL
				JOIN  ['+ISNULL(@CIA, '')+'].VIEW_OBT_SUBTIPO_MODULO_EXACTUSERP   AS TE   ON TE.CODIGO    = PP.MODULO AND 
				                                                                           TE.MODULO    = PP.TIPO AND 
																	                       TE.SUBTIPO   = PP.SUBTIPO 
		        LEFT JOIN EXACTUSERP.['+ISNULL(@CIA, '')+'].PROVEEDOR             AS PROV ON PROV.PROVEEDOR = PP.PROVEEDOR_CLIENTE 
                LEFT JOIN EXACTUSERP.['+ISNULL(@CIA, '')+'].CLIENTE               AS CLI  ON CLI.CLIENTE    = PP.PROVEEDOR_CLIENTE 
				WHERE  
				CONVERT(VARCHAR, PP.[FECHA], 23) BETWEEN @FECHAINICIO AND @FECHAFIN
				AND    (PP.TIPO               = @TIPO                 OR  @TIPO               IS NULL)
				AND    (PP.PROVEEDOR_CLIENTE  = @PROVEEDOR_CLIENTE    OR  @PROVEEDOR_CLIENTE  IS NULL)
				AND    (PP.REFERENCIA         = @REFERENCIA           OR  @REFERENCIA         IS NULL)
				AND    (PP.MODULO             = @MODULO               OR  @MODULO             IS NULL)
				'+@FILTROUSUARIO+''
	
	SET @PARAM = N'@FECHAINICIO VARCHAR(10),
	               @FECHAFIN VARCHAR(10),
				   @TIPO VARCHAR(4),
				   @MODULO VARCHAR(5),
				   @PROVEEDOR_CLIENTE VARCHAR(20),
				   @REFERENCIA VARCHAR(50),
				   @USUARIO VARCHAR(500),
				   @ROL INT'

	INSERT INTO @TABLE EXEC SP_EXECUTESQL @SQL,
	                                           @PARAM,
	                                           @FECHAINICIO,
											   @FECHAFIN,
											   @TIPO,
											   @MODULO,
											   @PROVEEDOR_CLIENTE,
											   @REFERENCIA,
											   @USUARIO,
											   @ROL
	
	SELECT * FROM @TABLE


END





GO
/****** Object:  StoredProcedure [GLOBAL].[PROC_OBT_INDEX_KARDEX]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [GLOBAL].[PROC_OBT_INDEX_KARDEX]  (
@FECHA_INICIO VARCHAR(300),
@FECHA_FIN VARCHAR(300),
@CLIENTE VARCHAR(20),
@TIPO VARCHAR(10),
@BODEGA VARCHAR(4),
@ARTICULO VARCHAR(100),
@CIA VARCHAR(20),
@START INT = 0,
@LENGTH INT = 20,
@SEARCH VARCHAR(200) = NULL,
@ORDER_COLUMN VARCHAR(50) = 'FECHA',
@ORDER_DIR VARCHAR(4) = 'DESC'
)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @SQL NVARCHAR(MAX);
    DECLARE @ORDER_BY NVARCHAR(200);

    SET @START = ISNULL(@START, 0);
    SET @LENGTH = ISNULL(@LENGTH, 20);
    SET @SEARCH = NULLIF(LTRIM(RTRIM(@SEARCH)), '');
    SET @ORDER_COLUMN = UPPER(ISNULL(@ORDER_COLUMN, 'FECHA'));
    SET @ORDER_DIR = UPPER(ISNULL(@ORDER_DIR, 'DESC'));

    IF (@START < 0) SET @START = 0;
    IF (@LENGTH <= 0) SET @LENGTH = 20;

    IF (@ORDER_COLUMN NOT IN (
        'AUDIT_TRANS_INV', 'ARTICULO_COMPLETO', 'FECHA', 'APLICACION', 'TIPO',
        'NATURALEZA', 'ASIENTO', 'REFERENCIA', 'CLIENTE_NOMBRE', 'BODEGA',
        'CANTIDAD_INT', 'COSTO_TOT_FISC_LOC', 'PRECIO_UNITARIO'))
        SET @ORDER_COLUMN = 'FECHA';

    IF (@ORDER_DIR NOT IN ('ASC', 'DESC'))
        SET @ORDER_DIR = 'DESC';

    SET @ORDER_BY =
        CASE @ORDER_COLUMN
            WHEN 'AUDIT_TRANS_INV' THEN 'AUDIT_TRANS_INV'
            WHEN 'ARTICULO_COMPLETO' THEN 'ARTICULO_COMPLETO'
            WHEN 'APLICACION' THEN 'APLICACION'
            WHEN 'TIPO' THEN 'TIPO'
            WHEN 'NATURALEZA' THEN 'NATURALEZA'
            WHEN 'ASIENTO' THEN 'ASIENTO'
            WHEN 'REFERENCIA' THEN 'REFERENCIA'
            WHEN 'CLIENTE_NOMBRE' THEN 'CLIENTE_NOMBRE'
            WHEN 'BODEGA' THEN 'BODEGA'
            WHEN 'CANTIDAD_INT' THEN 'CANTIDAD_INT'
            WHEN 'COSTO_TOT_FISC_LOC' THEN 'COSTO_TOT_FISC_LOC'
            WHEN 'PRECIO_UNITARIO' THEN 'PRECIO_UNITARIO'
            ELSE 'FECHA'
        END + ' ' + @ORDER_DIR + ', AUDIT_TRANS_INV DESC';

    SET @SQL=' 
SELECT
    T.AUDIT_TRANS_INV,
    A.APLICACION,
    A.ASIENTO,
    A.REFERENCIA,
    CC.CENTRO_COSTO,
    CONCAT(CC.CENTRO_COSTO, '' - '', CC.DESCRIPCION) AS CENTRO_COSTO_COMPLETO,
    T.ARTICULO,
    CONCAT(T.ARTICULO, '' - '', AA.DESCRIPCION) AS ARTICULO_COMPLETO,
    T.COSTO_TOT_FISC_LOC,
    CONVERT(VARCHAR, CAST(T.COSTO_TOT_FISC_LOC AS MONEY), 1) AS COSTO_TOT_FISC_LOC_STR,
    X.COSTO_UNITARIO_LOCAL,
    CONVERT(VARCHAR, CAST(X.COSTO_UNITARIO_LOCAL AS MONEY), 1) AS COSTO_UNITARIO_LOCAL_STR,
    X.COSTO_UNITARIO_DOLAR,
    CONVERT(VARCHAR, CAST(X.COSTO_UNITARIO_DOLAR AS MONEY), 1) AS COSTO_UNITARIO_DOLAR_STR,
    T.COSTO_TOT_FISC_DOL,
    CONVERT(VARCHAR, CAST(T.COSTO_TOT_FISC_DOL AS MONEY), 1) AS COSTO_TOT_FISC_DOL_STR,
    T.NATURALEZA,
    T.CANTIDAD,
    CONVERT(INT, T.CANTIDAD) AS CANTIDAD_INT,
    A.FECHA_HORA AS FECHA,
    CONVERT(VARCHAR(10), A.FECHA_HORA, 103) AS FECHA_STR,
    T.TIPO,
    T.BODEGA,
    F.CLIENTE,
    C.ALIAS AS CLIENTE_NOMBRE,
    FL.PRECIO_UNITARIO,
    (FL.PRECIO_UNITARIO + FL.TOTAL_IMPUESTO1 + FL.TOTAL_IMPUESTO2) AS PRECIO_TOTAL
INTO #BASE
FROM EXACTUSERP.[' + ISNULL(@CIA, '') + '].TRANSACCION_INV T
INNER JOIN EXACTUSERP.[' + ISNULL(@CIA, '') + '].ARTICULO AA
    ON T.ARTICULO = AA.ARTICULO
INNER JOIN EXACTUSERP.[' + ISNULL(@CIA, '') + '].AUDIT_TRANS_INV A
    ON T.AUDIT_TRANS_INV = A.AUDIT_TRANS_INV
INNER JOIN EXACTUSERP.[' + ISNULL(@CIA, '') + '].FACTURA F
    ON F.AUDIT_TRANS_INV = A.AUDIT_TRANS_INV
INNER JOIN EXACTUSERP.[' + ISNULL(@CIA, '') + '].FACTURA_LINEA FL
    ON F.FACTURA = FL.FACTURA AND FL.ARTICULO = AA.ARTICULO
LEFT JOIN EXACTUSERP.[' + ISNULL(@CIA, '') + '].CENTRO_COSTO CC
    ON T.CENTRO_COSTO = CC.CENTRO_COSTO
LEFT JOIN EXACTUSERP.[' + ISNULL(@CIA, '') + '].CLIENTE C
    ON F.CLIENTE = C.CLIENTE
CROSS APPLY
(
    SELECT
        COSTO_UNITARIO_LOCAL = CASE
            WHEN T.CANTIDAD = 0 THEN 0
            ELSE T.COSTO_TOT_FISC_LOC / T.CANTIDAD
        END,
        COSTO_UNITARIO_DOLAR = CASE
            WHEN T.CANTIDAD = 0 THEN 0
            ELSE T.COSTO_TOT_FISC_DOL / T.CANTIDAD
        END
) X
WHERE
    A.FECHA_HORA >= @FECHA_INICIO
    AND A.FECHA_HORA < DATEADD(DAY, 1, @FECHA_FIN)
    AND (@TIPO IS NULL OR T.TIPO = @TIPO)
    AND (@BODEGA IS NULL OR T.BODEGA = @BODEGA)
    AND (@ARTICULO IS NULL OR T.ARTICULO = @ARTICULO)
    AND (@CLIENTE IS NULL OR F.CLIENTE = @CLIENTE);

SELECT *
INTO #FILTRADO
FROM #BASE
WHERE
    @SEARCH IS NULL
    OR AUDIT_TRANS_INV LIKE ''%'' + @SEARCH + ''%''
    OR ARTICULO_COMPLETO LIKE ''%'' + @SEARCH + ''%''
    OR APLICACION LIKE ''%'' + @SEARCH + ''%''
    OR TIPO LIKE ''%'' + @SEARCH + ''%''
    OR NATURALEZA LIKE ''%'' + @SEARCH + ''%''
    OR ASIENTO LIKE ''%'' + @SEARCH + ''%''
    OR REFERENCIA LIKE ''%'' + @SEARCH + ''%''
    OR CLIENTE LIKE ''%'' + @SEARCH + ''%''
    OR CLIENTE_NOMBRE LIKE ''%'' + @SEARCH + ''%''
    OR BODEGA LIKE ''%'' + @SEARCH + ''%'';

;WITH PAGINADO AS (
    SELECT *, ROW_NUMBER() OVER (ORDER BY ' + @ORDER_BY + ') AS RN
    FROM #FILTRADO
)
SELECT
    AUDIT_TRANS_INV,
    APLICACION,
    ASIENTO,
    REFERENCIA,
    CENTRO_COSTO,
    CENTRO_COSTO_COMPLETO,
    ARTICULO,
    ARTICULO_COMPLETO,
    COSTO_TOT_FISC_LOC,
    COSTO_TOT_FISC_LOC_STR,
    COSTO_UNITARIO_LOCAL,
    COSTO_UNITARIO_LOCAL_STR,
    COSTO_UNITARIO_DOLAR,
    COSTO_UNITARIO_DOLAR_STR,
    COSTO_TOT_FISC_DOL,
    COSTO_TOT_FISC_DOL_STR,
    NATURALEZA,
    CANTIDAD,
    CANTIDAD_INT,
    FECHA,
    FECHA_STR,
    TIPO,
    BODEGA,
    CLIENTE,
    CLIENTE_NOMBRE,
    PRECIO_UNITARIO,
    PRECIO_TOTAL
FROM PAGINADO
WHERE RN > @START
  AND RN <= (@START + @LENGTH)
ORDER BY RN;

SELECT
    (SELECT COUNT(1) FROM #BASE) AS TOTAL_REGISTROS,
    (SELECT COUNT(1) FROM #FILTRADO) AS REGISTROS_FILTRADOS;

DROP TABLE #FILTRADO;
DROP TABLE #BASE;
';

    EXECUTE SP_EXECUTESQL @SQL,
        N'@FECHA_INICIO VARCHAR(300),
          @FECHA_FIN VARCHAR(300),
          @CLIENTE VARCHAR(20),
          @TIPO VARCHAR(10),
          @BODEGA VARCHAR(4),
          @ARTICULO VARCHAR(100),
          @SEARCH VARCHAR(200),
          @START INT,
          @LENGTH INT',
        @FECHA_INICIO,
        @FECHA_FIN,
        @CLIENTE,
        @TIPO,
        @BODEGA,
        @ARTICULO,
        @SEARCH,
        @START,
        @LENGTH;
END
GO
