/****** Object:  StoredProcedure [GLOBAL].[PROC_OBT_LOGIN_USUARIO]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE   PROC [GLOBAL].[PROC_OBT_LOGIN_USUARIO]
    @USUARIO VARCHAR(50),
    @CONTRASENA_PLANA NVARCHAR(4000),
    @ID_COMPANIA INT,
    @IP_ACCESO VARCHAR(45) = NULL,
    @USER_AGENT VARCHAR(300) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    BEGIN TRY
        DECLARE @HASH_DB VARBINARY(64);
        DECLARE @SAL_DB VARBINARY(32);
        DECLARE @BLOQUEADO_HASTA_UTC DATETIME2(0);
        DECLARE @HASH_ENTRADA VARBINARY(64);

        IF NOT EXISTS (SELECT 1 FROM GLOBAL.USUARIO WITH (NOLOCK) WHERE USUARIO = @USUARIO AND ACTIVO = 'S')
        BEGIN
            INSERT INTO GLOBAL.BITACORA_ACCESO (USUARIO, ID_COMPANIA, RESULTADO_ACCESO, DETALLE_ACCESO, IP_ACCESO, USER_AGENT)
            VALUES (@USUARIO, @ID_COMPANIA, 'ERROR', 'USUARIO_NO_EXISTE', @IP_ACCESO, @USER_AGENT);
            SELECT -1 CODIGO, 'Usuario o contrasena invalida.' MENSAJE;
            RETURN;
        END

        SELECT TOP 1 @HASH_DB = UC.HASH_CONTRASENA, @SAL_DB = UC.SAL_CONTRASENA, @BLOQUEADO_HASTA_UTC = UC.BLOQUEADO_HASTA_UTC
        FROM GLOBAL.USUARIO_CREDENCIAL UC WITH (NOLOCK)
        WHERE UC.USUARIO = @USUARIO;

        IF @HASH_DB IS NULL OR @SAL_DB IS NULL
        BEGIN
            SELECT -2 CODIGO, 'El usuario no tiene credencial configurada.' MENSAJE;
            RETURN;
        END

        IF @BLOQUEADO_HASTA_UTC IS NOT NULL AND @BLOQUEADO_HASTA_UTC > SYSUTCDATETIME()
        BEGIN
            SELECT -3 CODIGO, 'Usuario bloqueado temporalmente.' MENSAJE;
            RETURN;
        END

        SET @HASH_ENTRADA = GLOBAL.FUNC_HASH_CONTRASENA(@CONTRASENA_PLANA, @SAL_DB);

        IF @HASH_ENTRADA <> @HASH_DB
        BEGIN
            UPDATE GLOBAL.USUARIO_CREDENCIAL
               SET INTENTOS_FALLIDOS = INTENTOS_FALLIDOS + 1,
                   BLOQUEADO_HASTA_UTC = CASE WHEN INTENTOS_FALLIDOS + 1 >= 5 THEN DATEADD(MINUTE, 15, SYSUTCDATETIME()) ELSE BLOQUEADO_HASTA_UTC END,
                   FECHA_MODIFICACION_UTC = SYSUTCDATETIME(),
                   USUARIO_MODIFICACION = @USUARIO
             WHERE USUARIO = @USUARIO;

            INSERT INTO GLOBAL.BITACORA_ACCESO (USUARIO, ID_COMPANIA, RESULTADO_ACCESO, DETALLE_ACCESO, IP_ACCESO, USER_AGENT)
            VALUES (@USUARIO, @ID_COMPANIA, 'ERROR', 'CONTRASENA_INVALIDA', @IP_ACCESO, @USER_AGENT);

            SELECT -1 CODIGO, 'Usuario o contrasena invalida.' MENSAJE;
            RETURN;
        END

        IF NOT EXISTS (SELECT 1 FROM GLOBAL.USUARIO_ROL_COMPANIA WITH (NOLOCK) WHERE USUARIO = @USUARIO AND ID_COMPANIA = @ID_COMPANIA AND ACTIVO = 'S')
        BEGIN
            SELECT -4 CODIGO, 'Usuario sin acceso a la compania.' MENSAJE;
            RETURN;
        END

        UPDATE GLOBAL.USUARIO_CREDENCIAL
           SET INTENTOS_FALLIDOS = 0,
               BLOQUEADO_HASTA_UTC = NULL,
               FECHA_MODIFICACION_UTC = SYSUTCDATETIME(),
               USUARIO_MODIFICACION = @USUARIO
         WHERE USUARIO = @USUARIO;

        INSERT INTO GLOBAL.BITACORA_ACCESO (USUARIO, ID_COMPANIA, RESULTADO_ACCESO, DETALLE_ACCESO, IP_ACCESO, USER_AGENT)
        VALUES (@USUARIO, @ID_COMPANIA, 'OK', 'LOGIN_EXITOSO', @IP_ACCESO, @USER_AGENT);

        SELECT 1 CODIGO, 'Login exitoso.' MENSAJE;
    END TRY
    BEGIN CATCH
        SELECT -500 CODIGO, ERROR_MESSAGE() MENSAJE;
    END CATCH
END

GO
