/****** Object:  StoredProcedure [GLOBAL].[PROC_OBT_PERMISOS]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
--[GLOBAL].[PROC_OBT_PERMISOS] 'DIS86'

CREATE PROCEDURE [GLOBAL].[PROC_OBT_PERMISOS](
@CIA VARCHAR(25)
)
AS 
BEGIN

DECLARE @SQL NVARCHAR(MAX)
DECLARE @TABLE TABLE(
ROL int,
DESCRIPCION varchar(50), 
SEGUIMIENTO_FACTURA_PEDIDO int, 
TRACKING_IN int, 
ESTADISTICA int, 
USUARIO int, 
CONFIGURACION int

)
SET @SQL = 'SELECT * FROM   
			(
				SELECT	M.[DESCRIPCION] [MODULO]
						,P.[ROL]
						,R.DESCRIPCION
						,PERMISO
				FROM	[GLOBAL].[MODULO_X_PERMISO] P
				JOIN	[GLOBAL].[ROL] R ON R.ROL = P.ROL
				JOIN	[GLOBAL].[MODULO] M ON M.MODULO = P.MODULO
			) T
			PIVOT(
				MAX(PERMISO) 
				FOR [MODULO] IN (
					[SEGUIMIENTO FACTURA Y PEDIDO] , 
					[TRACKING IN] , 
					ESTADISTICA , 
					USUARIO , 
					CONFIGURACION   
					)
			) AS PIVOT_TABLE
			ORDER BY ROL'
	
INSERT INTO @TABLE EXEC SP_EXECUTESQL	@SQL
										
SELECT	ROL,
		DESCRIPCION,
		SEGUIMIENTO_FACTURA_PEDIDO, 
		TRACKING_IN, 
		ESTADISTICA, 
		USUARIO, 
		CONFIGURACION

FROM @TABLE

END


