            FROM '+ISNULL(@CIA, '')+'.MODULO_X_PERMISO MP
            JOIN GLOBAL.PERMISO P ON P.PERMISO = MP.PERMISO
            WHERE ROL = 1
            AND   MODULO = @MODULO
            ORDER BY PERMISO'
	
INSERT INTO @TABLE EXEC SP_EXECUTESQL	@SQL, N'@MODULO INT', @MODULO
										

										
SELECT	PERMISO,
		DESCRIPCION
FROM @TABLE

END
