/****** Object:  StoredProcedure [GLOBAL].[PROC_OBT_PERMISOS_POR_ROL]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [GLOBAL].[PROC_OBT_PERMISOS_POR_ROL](@ROL INT, @CIA VARCHAR(25))
AS 
BEGIN

DECLARE @SQL NVARCHAR(MAX)
DECLARE @TABLE TABLE(
ROL int,
DESCRIPCION varchar(50), 
COMPROBANTES int, 
SOLICITUDES int, 
ORGANIGRAMA int, 
PORTAFOLIO int, 
RELOJ_MARCADOR int,
USUARIOS int
)
SET @SQL = 'SELECT * FROM   
			(
				SELECT	M.DESCRIPCION MODULO
						,P.ROL
						,R.DESCRIPCION
						,CASE WHEN (P.PERMISO =1 OR P.PERMISO = 2) AND P.ACTIVO = ''S'' THEN 1 ELSE 0 END PERMISO
				FROM	'+ISNULL(@CIA, '')+'.MODULO_X_PERMISO P
				JOIN	GLOBAL.ROL R ON R.ROL = P.ROL
				JOIN	GLOBAL.MODULO M ON M.MODULO = P.MODULO
                WHERE P.ROL = 1

                AND   M.DESCRIPCION NOT LIKE ''TAB_%''
                --AND   P.PERMISO IN (1,2)
			) T
			PIVOT(
				--MIN(COUNT(*))
                MAX(PERMISO)
				FOR MODULO IN ( 
					COMPROBANTES , 
					SOLICITUDES , 
					ORGANIGRAMA , 
					PORTAFOLIO , 
					RELOJ_MARCADOR ,
					USUARIOS 
					)
			) PIVOT_TABLE
			ORDER BY ROL'
	
INSERT INTO @TABLE EXEC SP_EXECUTESQL	@SQL, N'@ROL INT', @ROL
										
SELECT	ROL,
		DESCRIPCION,
		COMPROBANTES , 
		SOLICITUDES , 
		ORGANIGRAMA , 
		PORTAFOLIO , 
		RELOJ_MARCADOR ,
		USUARIOS 

FROM @TABLE

END
