TRACKING_IN int, 
ESTADISTICA int, 
USUARIO int, 
CONFIGURACION int

)
SET @SQL = 'SELECT * FROM   
			(
				SELECT	 M.[DESCRIPCION] [MODULO]
						,P.[ROL]
						,R.DESCRIPCION
						,[PERMISO]
				FROM	[GLOBAL].[MODULO_X_PERMISO] P
				JOIN	[GLOBAL].[ROL] R ON R.ROL = P.ROL
				JOIN	[GLOBAL].[MODULO] M ON M.MODULO = P.MODULO
				WHERE	P.ROL = @ROL
			) T
			PIVOT(
				MAX(PERMISO) 
				FOR [MODULO] IN (
					[SEGUIMIENTO FACTURA Y PEDIDO] , 
					[TRACKING IN] , 
					ESTADISTICA , 
					USUARIO , 
					CONFIGURACION 
					)
			) AS PIVOT_TABLE
			ORDER BY ROL'
	
INSERT INTO @TABLE EXEC SP_EXECUTESQL	@SQL, N'@ROL INT', @ROL
										
SELECT	ROL,
		DESCRIPCION,
		SEGUIMIENTO_FACTURA_PEDIDO, 
		TRACKING_IN, 
