/****** Object:  StoredProcedure [GLOBAL].[PROC_OBT_PERMISOS_ROL_MODULO]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

-- [GLOBAL].[PROC_OBT_PERMISOS_ROL_MODULO] 2,'DIS86'

CREATE PROCEDURE [GLOBAL].[PROC_OBT_PERMISOS_ROL_MODULO]
(
    @ROL INT,
    @CIA VARCHAR(20)
)
AS
BEGIN 
    DECLARE @SQL NVARCHAR(MAX), @PARAM NVARCHAR(MAX);
    DECLARE @RESULT TABLE (ROL INT, MODULO INT, PERMISOS_MOD VARCHAR(MAX));

    SET @SQL = '
	            SELECT
				P.ROL,
				P.MODULO,
				STUFF((
					SELECT DISTINCT '','' + CAST(M.PERMISO AS VARCHAR)
					FROM 
						   [GLOBAL].[MODULO_X_PERMISO] P2
					JOIN   [GLOBAL].[PERMISO] M ON M.PERMISO = P2.PERMISO
					WHERE  P2.ROL = P.ROL AND P2.MODULO = P.MODULO AND P2.ACTIVO = ''S''
					FOR XML PATH(''''), TYPE).value(''.'', ''NVARCHAR(MAX)''), 1, 1, '''') AS PERMISOS
			FROM 
				[GLOBAL].[MODULO_X_PERMISO] P
			JOIN 
				[GLOBAL].[ROL] R ON R.ROL = P.ROL
			WHERE 
				P.ROL = @ROL AND 
				P.ACTIVO = ''S''  
	
			GROUP BY 
				P.ROL, P.MODULO'

    SET @PARAM = N'@ROL INT';

    INSERT INTO @RESULT EXEC SP_EXECUTESQL @SQL, @PARAM, @ROL;

    SELECT * FROM @RESULT;
END;
GO
/****** Object:  StoredProcedure [GLOBAL].[PROC_OBT_PERMISOS_ROL_MODULO_SUB]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [GLOBAL].[PROC_OBT_PERMISOS_ROL_MODULO_SUB]
(
    @ROL INT ,
    @CIA VARCHAR(20)    
)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @SQL   NVARCHAR(MAX);
    DECLARE @PARAM NVARCHAR(400);


    SET @SQL = N'
        SELECT
              P.ROL
            , P.MODULO
            , P.SUBMODULO                        
            , STUFF
              ( ( SELECT DISTINCT '','' + CAST(M.PERMISO AS VARCHAR)
                  FROM [GLOBAL].[MODULO_X_PERMISO]  P2
                  JOIN [GLOBAL].[PERMISO]          M  ON  M.PERMISO = P2.PERMISO
                  WHERE P2.ROL       = P.ROL
                    AND P2.MODULO    = P.MODULO
                    AND P2.SUBMODULO = P.SUBMODULO
                    AND P2.ACTIVO    = ''S''
                  FOR XML PATH(''''), TYPE
                ).value(''.'', ''NVARCHAR(MAX)''), 1, 1, ''''
              ) AS PERMISOS
        FROM   [GLOBAL].[MODULO_X_PERMISO] P
        WHERE  P.ROL    = @ROL
          AND  P.ACTIVO = ''S''
		  AND  P.MODULO <> 23
        GROUP BY
              P.ROL
            , P.MODULO
            , P.SUBMODULO;';

 
    SET @PARAM = N'@ROL INT';
    EXEC sp_executesql @SQL, @PARAM, @ROL;
END;
GO
