---EXEC [GLOBAL].[PROC_OBT_PERMISOS_ROL_V2]  4 ,'DIS86'


CREATE PROCEDURE [GLOBAL].[PROC_OBT_PERMISOS_ROL_V2]
(
@ROL INT,
@CIA VARCHAR(25)
)
AS 
BEGIN

DECLARE @SQL NVARCHAR(MAX)
DECLARE @TABLE TABLE(
ROL int,
DESCRIPCION varchar(50), 
SEGUIMIENTO_FACTURA_PEDIDO int, 
TRACKING_IN int, 
ESTADISTICA int, 
USUARIO int, 
CONFIGURACION int,
PORTAL_DE_CLIENTES int,
GESTION_DE_PEDIDOS int,
DESCUENTOS int
)
SET @SQL = 'SELECT * FROM   
			(
				SELECT	 M.[DESCRIPCION] [MODULO]
						,P.[ROL]
						,R.DESCRIPCION
						,[PERMISO]
				FROM	[GLOBAL].[MODULO_X_PERMISO] P
				JOIN	[GLOBAL].[ROL] R ON R.ROL = P.ROL
				JOIN	[GLOBAL].[MODULO] M ON M.MODULO = P.MODULO
				WHERE	P.ROL = @ROL
			) T
			PIVOT(
				MAX(PERMISO) 
				FOR [MODULO] IN (
					[SEGUIMIENTO FACTURA Y PEDIDO] , 
					[TRACKING IN] , 
					ESTADISTICA , 
					USUARIO , 
					CONFIGURACION,
					[PORTAL DE CLIENTES],
					[GESTION DE PEDIDOS],
					[DESCUENTOS]
					)
			) AS PIVOT_TABLE
			ORDER BY ROL'
	
INSERT INTO @TABLE EXEC SP_EXECUTESQL	@SQL, N'@ROL INT', @ROL
										
SELECT	*

FROM @TABLE

END

GO
