CREATE PROCEDURE [GLOBAL].[PROC_OBT_PERMISOS_V2]
(
@CIA VARCHAR(25)
)
AS 
BEGIN

DECLARE @SQL NVARCHAR(MAX)
DECLARE @TABLE TABLE(
ROL INT ,
DESCRIPCION VARCHAR(50), 
SEGUIMIENTO_FACTURA_PEDIDO INT, 
TRACKING_IN INT, 
USUARIO INT, 
CONFIGURACION INT, 
GESTION_DE_PEDIDOS INT, 
PORTAL_DE_CLIENTES INT,
DESCUENTOS INT,
MENU INT
)
SET @SQL = 'SELECT * FROM   
			(
				SELECT	M.[DESCRIPCION] [MODULO]
						,P.[ROL]
						,R.DESCRIPCION
						,CASE WHEN P.ACTIVO = ''S'' THEN 1 ELSE 0 END PERMISO
				FROM	[GLOBAL].[MODULO_X_PERMISO] P
				JOIN	[GLOBAL].[ROL] R ON R.ROL = P.ROL
				JOIN	[GLOBAL].[MODULO] M ON M.MODULO = P.MODULO
			) T
			PIVOT(
				MAX(PERMISO) 
				FOR [MODULO] IN (
					[SEGUIMIENTO FACTURA Y PEDIDO] , 
					[TRACKING IN] , 
					[USUARIO] , 
					[CONFIGURACION],
					[GESTION DE PEDIDOS],
					[PORTAL DE CLIENTES],
					[DESCUENTOS],
					[MENU]
					)
			) AS PIVOT_TABLE
			ORDER BY ROL'
	
INSERT INTO @TABLE EXEC SP_EXECUTESQL	@SQL
										
SELECT	ROL,
		DESCRIPCION,
		SEGUIMIENTO_FACTURA_PEDIDO, 
		TRACKING_IN, 
		USUARIO, 
		CONFIGURACION,
		GESTION_DE_PEDIDOS , 
		PORTAL_DE_CLIENTES,
		DESCUENTOS,
		MENU
FROM @TABLE

END


