CREATE PROCEDURE [GLOBAL].[PROC_OBT_PERMISOS_X_SUBMODULO](
@MODULO INT, 
@ROL INT, 
@TAB INT, 
@CIA VARCHAR(25))
AS 
BEGIN

DECLARE @SQL NVARCHAR(MAX)
DECLARE @TABLE TABLE(
PERMISO int,
ACTIVO VARCHAR(1),
DESCRIPCION varchar(50)
)
SET @SQL = 'SELECT P.PERMISO,
					ACTIVO,
					P.DESCRIPCION
			FROM GLOBAL.MODULO_X_PERMISO MP
			JOIN GLOBAL.PERMISO P ON P.PERMISO = MP.PERMISO
			WHERE ROL = @ROL
			AND MODULO = @MODULO
			AND SUBMODULO = @TAB
			'
	
INSERT INTO @TABLE EXEC SP_EXECUTESQL	@SQL,
										N'@MODULO INT,
										@ROL INT,
										@TAB INT',
										@MODULO,
										@ROL,
										@TAB

										
SELECT	PERMISO,
		ACTIVO,
		DESCRIPCION
FROM @TABLE

END
