)
AS
BEGIN

DECLARE @SQL NVARCHAR(MAX),@PARAM NVARCHAR(MAX)
DECLARE @TABLE AS TABLE (USUARIO VARCHAR(100),DESCRIPCION VARCHAR(4000),E_MAIL VARCHAR(800))
SET @SQL = N'(
    SELECT  USUARIO, 
            CONCAT(USUARIO,'' - '',NOMBRE) DESCRIPCION,
			ISNULL(CORREO_ELECTRONICO,'''') E_MAIL
    FROM    EXACTUSERP.ERPADMIN.USUARIO
    WHERE   ACTIVO = ''S'' 
    AND     USUARIO NOT IN (SELECT  USUARIO 
