CREATE PROCEDURE [GLOBAL].[PROC_OBT_SUBTIPOS_DOCUMENTOS_CC]
    @CIA      VARCHAR(30),
    @Tipo     VARCHAR(200) = NULL,
    @Subtipo  VARCHAR(200) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    IF NULLIF(LTRIM(RTRIM(@Tipo)),   '') IN ('0','') SET @Tipo    = NULL;
    IF NULLIF(LTRIM(RTRIM(@Subtipo)),'') IN ('0','') SET @Subtipo = NULL;

    IF @Tipo IS NULL
    BEGIN
        SELECT CAST(NULL AS VARCHAR(30)) AS SUBTIPO,
               CAST(NULL AS VARCHAR(100)) AS DESCRIPCION,
               CAST(NULL AS VARCHAR(130)) AS LABEL
        WHERE 1 = 0;
        RETURN;
    END

    DECLARE @T TABLE
    (
        SUBTIPO     VARCHAR(30),
        DESCRIPCION VARCHAR(100),
        LABEL       VARCHAR(130)
    );

    DECLARE @sql NVARCHAR(MAX) = N'
        SELECT DISTINCT
               CONVERT(VARCHAR(30), SUBTIPO)            AS SUBTIPO,
               DESCRIPCION,
               CONVERT(VARCHAR(30), SUBTIPO) + '' | '' +
               DESCRIPCION                             AS LABEL
        FROM   EXACTUSERP.' + QUOTENAME(@CIA) + N'.SUBTIPO_DOC_CC WITH (NOLOCK)
        WHERE  TIPO IN (
                  SELECT VAL
                  FROM   ' + QUOTENAME(@CIA) + N'.TF_SPLIT(@Tipo, '','')
               )
          AND  (
                   @Subtipo IS NULL
                OR DESCRIPCION IN (
                       SELECT VAL
                       FROM   ' + QUOTENAME(@CIA) + N'.TF_SPLIT(@Subtipo, '','')
                    )
               );';

    INSERT INTO @T (SUBTIPO, DESCRIPCION, LABEL)
    EXEC sp_executesql
         @sql,
         N'@Tipo VARCHAR(200), @Subtipo VARCHAR(200)',
         @Tipo    = @Tipo,
         @Subtipo = @Subtipo;

    SELECT SUBTIPO, DESCRIPCION, LABEL
    FROM   @T
    ORDER  BY SUBTIPO;
END
GO
