/****** Object:  StoredProcedure [GLOBAL].[PROC_OBT_TIPO_CAMBIO_MONEDA_X_FECHA]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [GLOBAL].[PROC_OBT_TIPO_CAMBIO_MONEDA_X_FECHA]
(
    @MONEDA VARCHAR(4),
    @FECHA VARCHAR(10),
    @CIA VARCHAR(20)
)
AS
BEGIN
	  -- Verificar si @MONEDA es NULL o vacío
    IF @MONEDA IS NULL OR LTRIM(RTRIM(@MONEDA)) = ''
    BEGIN
        -- Retornar 0 si @MONEDA es NULL o vacío
        SELECT 0.00000000 AS TIPO_CAMBIO
        RETURN
    END
    DECLARE @SQL NVARCHAR(MAX)
    DECLARE @TABLE TABLE(
        TIPO_CAMBIO DECIMAL(28,8)
    )
    DECLARE @FECHA_DATETIME DATETIME
    DECLARE @FECHA_CON_HORA NVARCHAR(20)

    -- Convertir @FECHA a formato DATETIME
    SET @FECHA_DATETIME = CONVERT(DATETIME, @FECHA, 103) -- 103 es el estilo para DD/MM/YYYY

    -- Formatear la fecha y agregar la hora 23:59:59
    SET @FECHA_CON_HORA = FORMAT(@FECHA_DATETIME, 'yyyy-MM-dd') + ' 23:59:59'

    -- Construir la consulta dinámica
    SET @SQL = N'SELECT EXACTUSERP.[' + ISNULL(@CIA, '') + '].SOFTLANDBI_FN_TipoCambioLocal(''USD'', @FECHA_CON_HORA)'

    -- Ejecutar la consulta dinámica
    INSERT INTO @TABLE 
    EXEC SP_EXECUTESQL 
        @SQL,
        N'@MONEDA VARCHAR(4), @FECHA_CON_HORA NVARCHAR(20)',
        @MONEDA,
        @FECHA_CON_HORA

    -- Seleccionar el resultado
    SELECT TIPO_CAMBIO
    FROM @TABLE
END
GO
