/****** Object:  StoredProcedure [GLOBAL].[PROC_OBT_TIPOS_DOCUMENTOS_CC]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [GLOBAL].[PROC_OBT_TIPOS_DOCUMENTOS_CC]
    @CIA  VARCHAR(30),
    @Tipo VARCHAR(20) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @Tipos TABLE
    (
        TIPO        VARCHAR(20),
        BADGE_CLASS VARCHAR(40),
        BADGE_TITLE VARCHAR(20)
    );

    DECLARE @sql NVARCHAR(MAX) = N'
        SELECT  DISTINCT
                TIPO,
                CASE TIPO
                    WHEN ''FAC'' THEN ''badge-light-success''
                    WHEN ''REC'' THEN ''badge-light-warning''
                    WHEN ''TEF'' THEN ''badge-light-info''
                    WHEN ''N/C'' THEN ''badge-light-primary''
                    WHEN ''N/D'' THEN ''badge-light-success''
                    WHEN ''O/C'' THEN ''badge-light-danger''
                    WHEN ''O/D'' THEN ''badge-light-warning''
                    WHEN ''CNJ'' THEN ''badge-light-dark''
                    WHEN ''DEP'' THEN ''badge-light-info''
                    WHEN ''INT'' THEN ''badge-light-primary''
                    WHEN ''L/C'' THEN ''badge-light-success''
                    WHEN ''RET'' THEN ''badge-light-danger''
                    ELSE ''badge-light-secondary''
                END AS BADGE_CLASS,
                TIPO AS BADGE_TITLE            -- por si algún día difiere
        FROM  [' + REPLACE(@CIA, '''', '') + '].VW_TIPOS_DOCUMENTOS_CC
        WHERE (@Tipo IS NULL OR TIPO = @Tipo);';

    INSERT INTO @Tipos (TIPO, BADGE_CLASS, BADGE_TITLE)
    EXEC sp_executesql
         @sql,
         N'@Tipo VARCHAR(20)',
         @Tipo = @Tipo;

    SELECT  TIPO,
            BADGE_CLASS,
            BADGE_TITLE
    FROM    @Tipos
    ORDER BY TIPO;
END
GO
