/****** Object:  StoredProcedure [GLOBAL].[PROC_OBT_TIPOSINV]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [GLOBAL].[PROC_OBT_TIPOSINV]
(
    @CIA VARCHAR(20)
)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @SQL NVARCHAR(MAX);

    -- Tabla temporal para resultados
    DECLARE @TABLE TABLE (
        TIPO VARCHAR(10),
        DESCRIPCION VARCHAR(100)
    );

    -- Construir SQL dinámico para tomar los TIPO distintos
    SET @SQL = '
        SELECT DISTINCT
            TIPO,
              CASE TIPO
              
                WHEN ''O'' THEN ''Compra''
                WHEN ''P'' THEN ''Producción''
                WHEN ''R'' THEN ''Reservación''
                WHEN ''S'' THEN ''Costo''
                WHEN ''T'' THEN ''Traspaso''
                WHEN ''V'' THEN ''Venta''

             
                WHEN ''A'' THEN ''Aprobación''
                WHEN ''C'' THEN ''Consumo''
                WHEN ''E'' THEN ''Ensamble''
                WHEN ''F'' THEN ''Físico''
                WHEN ''I'' THEN ''Remisión''
                WHEN ''M'' THEN ''Misceláneo''
                WHEN ''N'' THEN ''Vencimiento''

                ELSE ''Desconocido''
            END AS Descripcion


        FROM EXACTUSERP.[' + ISNULL(@CIA, '') + '].TRANSACCION_INV
        WHERE TIPO IS NOT NULL
        ORDER BY TIPO;
    ';

    INSERT INTO @TABLE
    EXEC sp_executesql @SQL;

    SELECT * FROM @TABLE;
END;
GO
