CREATE   PROCEDURE [GLOBAL].[PROC_OBT_USUARIO]
	@USUARIO VARCHAR(25)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @SQL NVARCHAR(MAX)
	DECLARE @TABLE TABLE(
		                 CORREO VARCHAR(249),
						 NOMBRE VARCHAR(200),
						 IDENTIFICACION VARCHAR(20),
						 ROL INT,
						 ACTIVO VARCHAR(1),
						 USUARIO VARCHAR(100),
						 VENDEDOR VARCHAR(100),
						 NOM_VENDEDOR VARCHAR(200),
						 COBRADOR VARCHAR(5),
						 NOM_COBRADOR VARCHAR(800),
						 CIA VARCHAR(20)
	)

	SET @SQL = '
		SELECT	
				  ISNULL(SU.[CORREO], '''') CORREO,
				  SU.[NOMBRE]
				  ,SU.IDENTIFICACION
				  ,USU.ROL
				  ,USU.ACTIVO 
				  ,USU.USUARIO
				  ,ISNULL(VEN.VENDEDOR,''V001'') 
				  ,ISNULL(VEN.NOMBRE,''Administrativo'') NOM_VENDEDOR 
				  ,ISNULL(SU.COBRADOR,''C001'')
				  ,ISNULL(COB.NOMBRE,''Administrativo'')
				  ,ISNULL(SU.CIA_DEFECTO,''ANCLA'')
		FROM	
			      [GLOBAL].[USUARIO_ADICIONALES] AS  SU
		JOIN      [GLOBAL].USUARIO               AS USU ON USU.USUARIO  = SU.USUARIO  
		LEFT JOIN exactuserp.dis86.VENDEDOR        AS VEN ON VEN.VENDEDOR = SU.VENDEDOR  AND VEN.ACTIVO =''S''
		LEFT JOIN exactuserp.dis86.COBRADOR        AS COB ON SU.COBRADOR  = COB.COBRADOR AND COB.ACTIVO =''S''
		WHERE	
		          USU.USUARIO = @USUARIO'


	INSERT INTO @TABLE EXEC SP_EXECUTESQL	@SQL,
											N'@USUARIO VARCHAR(25)',
											@USUARIO
	SELECT	* FROM @TABLE
END
GO
