/****** Object:  StoredProcedure [GLOBAL].[PROC_OBT_VALIDAR_TOKEN_RECUPERACION]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE   PROC [GLOBAL].[PROC_OBT_VALIDAR_TOKEN_RECUPERACION]
    @TOKEN NVARCHAR(500)
AS
BEGIN
    SET NOCOUNT ON;
    BEGIN TRY
        DECLARE @HASH_TOKEN VARBINARY(64);
        SET @HASH_TOKEN = GLOBAL.FUNC_HASH_TOKEN(@TOKEN);
        IF EXISTS (SELECT 1 FROM GLOBAL.TOKEN_RECUPERACION TR WITH (NOLOCK) WHERE TR.HASH_TOKEN = @HASH_TOKEN AND TR.USADO = 'N' AND TR.FECHA_EXPIRACION_UTC >= SYSUTCDATETIME())
            SELECT 1 CODIGO, 'Token valido.' MENSAJE;
        ELSE
            SELECT -1 CODIGO, 'Token invalido o expirado.' MENSAJE;
    END TRY
    BEGIN CATCH
        SELECT -500 CODIGO, ERROR_MESSAGE() MENSAJE;
    END CATCH
END

GO
