GO

CREATE PROCEDURE [GLOBAL].[PROC_PEDIDO_MIGRAR_SOFTLAND]( 
	 @PEDIDO_TEMPORAL INT  --NUMERO PEDIDO DE LA TABLA TEMPORAL CAMPO LLAVE
	,@ROL INT --1,2,3,4
	,@OBSERVACIONES VARCHAR(500) 
	,@TFACTURACION VARCHAR(50)
	,@TIPO_PAGO VARCHAR(2)
	,@CLIENTE VARCHAR(20)
	,@ID_VISITA INT
	,@CIA VARCHAR(20)
)
AS
BEGIN


	DECLARE @SQL NVARCHAR(MAX),@PARAM NVARCHAR(MAX)
	DECLARE	@RETURN_VALUE INT,  @CONSECUTIVO VARCHAR(20),@CANT_ACT INT
	DECLARE  @RUBRO1 VARCHAR(50),@RUBRO2 VARCHAR(50),@RUBRO3 VARCHAR(50),@RUBRO4 VARCHAR(500),@RUBRO5 VARCHAR(50),@VENDEDOR VARCHAR(5)
	DECLARE @TIPO_PAGO_ANTERIOR VARCHAR(2),@PEDEXISTEEXACTUSERP INT,@CONSECUTIVOSOFT VARCHAR(500)

	SET @RUBRO1 = 'ND'
	SET @RUBRO2 = (SELECT NOMBRE    FROM EXACTUSERP.DIS86.CLIENTE WHERE CLIENTE = @CLIENTE)
	SET @RUBRO3 = (SELECT E_MAIL    FROM EXACTUSERP.DIS86.CLIENTE WHERE CLIENTE = @CLIENTE)
	SET @RUBRO4 = (SELECT SUBSTRING(DIRECCION,1,50) FROM EXACTUSERP.DIS86.CLIENTE WHERE CLIENTE = @CLIENTE)  -- AQUI PUSIMOS LA RUTA
	SET @RUBRO5 = (SELECT TELEFONO1 FROM EXACTUSERP.DIS86.CLIENTE WHERE CLIENTE = @CLIENTE)
	SET @VENDEDOR =(SELECT VENDEDOR FROM DIS86.PEDIDO WHERE PEDIDO = @PEDIDO_TEMPORAL)
			 
    
	SELECT 
	       @CONSECUTIVOSOFT = CONSECUTIVO 
	FROM   DIS86.PEDIDO WHERE PEDIDO = @PEDIDO_TEMPORAL

	SET @PEDEXISTEEXACTUSERP =(SELECT COUNT(PEDIDO) FROM EXACTUSERP.DIS86.PEDIDO WHERE PEDIDO = @CONSECUTIVOSOFT AND ESTADO = 'N')


	IF @PEDEXISTEEXACTUSERP = 0
	BEGIN 
	EXEC @RETURN_VALUE = [GLOBAL].[PROC_OBTENER_CONSECUTIVO_SEGUN_ROL] @ROL,@CIA, @CONSECUTIVO OUTPUT
	END 
	ELSE 
	BEGIN 
	SET @CONSECUTIVO = @CONSECUTIVOSOFT
	END 

	SET @SQL = 'SELECT @TIPO_PAGO_ANTERIOR = ISNULL(TIPO_PAGO,''NO'') FROM ['+@CIA+'].PEDIDO WHERE PEDIDO = @PEDIDO_TEMPORAL'
	
	SET @PARAM  = ' @PEDIDO_TEMPORAL INT,@TIPO_PAGO_ANTERIOR VARCHAR(2) OUTPUT '

	EXEC SP_EXECUTESQL @SQL,@PARAM,@PEDIDO_TEMPORAL,@TIPO_PAGO_ANTERIOR OUTPUT
	
	
	IF (@CONSECUTIVO IS NOT NULL AND @CONSECUTIVO <> '')
     BEGIN
    -- Extraer solo los números del consecutivo
    
	DECLARE @NUMEROS VARCHAR(10);
    SET @NUMEROS = REPLACE(SUBSTRING(@CONSECUTIVO, CHARINDEX('-', @CONSECUTIVO) + 1, LEN(@CONSECUTIVO)), 'PTLC-', '');
    -- Concatenar con el vendedor
    IF @PEDEXISTEEXACTUSERP = 0
	BEGIN
	SET @CONSECUTIVO = CONCAT(@NUMEROS,'|',@VENDEDOR);
    END 
	ELSE 
	BEGIN
	SET @CONSECUTIVO = @CONSECUTIVOSOFT
	END 
	END

	--SET @TIPO_PAGO_ANTERIOR = (SELECT ISNULL(TIPO_PAGO,'NO') FROM EC.PEDIDO WHERE PEDIDO = @PEDIDO_TEMPORAL)
	PRINT  @TIPO_PAGO_ANTERIOR
	IF(@TIPO_PAGO_ANTERIOR = 'NO')
	BEGIN
--************************************************************************************************************************************************** 
-- ACTUALIZAMOS PRIMERO LAS OBSERVACIONES O SI NO NO LAS CARGA A EXACTUSERP.
--**************************************************************************************************************************************************
	SET @SQL = '
		       UPDATE ['+@CIA+'].[PEDIDO]
				    SET  OBSERVACIONES        = @OBSERVACIONES
						 ,FECHA               = GETDATE()
					     ,RUBRO1              = @RUBRO1
					     ,TIPO_FACTURACION    = @TFACTURACION
					     ,ACTIVIDAD_ECONOMICA = ''519003''
					     ,RUBRO2			  = @RUBRO2
					     ,RUBRO3              = @RUBRO3
					     ,RUBRO4              = @RUBRO4
					     ,RUBRO5              = @RUBRO5
					     ,ENTREGA_EN          = @RUBRO4				 
					     ,COMENTARIO          = @OBSERVACIONES
					     ,TIPO_PAGO           = @TIPO_PAGO
				    WHERE 
						  PEDIDO =  @PEDIDO_TEMPORAL '
		
		SET @PARAM = '@PEDIDO_TEMPORAL INT,@OBSERVACIONES VARCHAR(500),@TFACTURACION VARCHAR(50),@TIPO_PAGO VARCHAR(2),@RUBRO1 VARCHAR(50),@RUBRO2 VARCHAR(50),@RUBRO3 VARCHAR(50),@RUBRO4 VARCHAR(500),@RUBRO5 VARCHAR(50)'

		EXEC SP_EXECUTESQL @SQL,@PARAM, @PEDIDO_TEMPORAL ,@OBSERVACIONES,@TFACTURACION,@TIPO_PAGO,@RUBRO1,@RUBRO2,@RUBRO3,@RUBRO4,@RUBRO5

--************************************************************************************************************************************************** 
-- ACTUALIZAMOS EL CONSECUTIVO PARA CARGAR EL PEDIDO A EXACTUSERP.		-- SIGUE EL PROCESO NORMAL
--************************************************************************************************************************************************** 
	
	--- Limpiamos las tablas de EXACTUSERP antes de cargarlo nuevamente cuando se mande a editar el pedido 
	IF @PEDEXISTEEXACTUSERP <> 0
	BEGIN
	
	DELETE FROM EXACTUSERP.DIS86.PEDIDO_LINEA WHERE PEDIDO = @CONSECUTIVOSOFT
	DELETE FROM EXACTUSERP.DIS86.PEDIDO       WHERE PEDIDO = @CONSECUTIVOSOFT
	
	END 
	
	SET @SQL =' UPDATE ['+@CIA+'].[PEDIDO]
				SET    [CONSECUTIVO] = @CONSECUTIVO  
				WHERE  PEDIDO        =  @PEDIDO_TEMPORAL'
		SET @PARAM = '@CONSECUTIVO VARCHAR(20),@PEDIDO_TEMPORAL INT'
		EXECUTE SP_EXECUTESQL @SQL,@PARAM,@CONSECUTIVO,@PEDIDO_TEMPORAL

			
--************************************************************************************************************************************************** 
-- ACTUALIZAMOS EL PEDIDO EN LA TABLA DE VISITA -- PARA LOGRAR ASOCIAR EL PEDIDO A ESA VISITA.
--************************************************************************************************************************************************** 
       SET @SQL =' UPDATE ['+@CIA+'].[VISITAS]
					SET   DOCUMENTO   = @CONSECUTIVO  
				   WHERE  ID_VISITA   = @ID_VISITA'
		SET @PARAM = '@CONSECUTIVO VARCHAR(20),@ID_VISITA INT'
		EXECUTE SP_EXECUTESQL @SQL,@PARAM,@CONSECUTIVO,@ID_VISITA


	    --  IF(@TIPO_PAGO = 'NO') -- SI EL @TIPO_PAGO ES IGUAL A TR ENTONCES NO ENVIA EL CORREO AQUI SINO EN LA CONFIRMACION. 
		--	EXEC [GLOBAL].[PROC_CREA_MENSAJERIA] @PEDIDO_TEMPORAL,@CIA


	 END

END
GO
/****** Object:  StoredProcedure [GLOBAL].[PROC_VAL_USUARIO_SOFTLAND]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [GLOBAL].[PROC_VAL_USUARIO_SOFTLAND] (@USUARIO VARCHAR(50), @PASS VARCHAR(50)) 
AS
BEGIN  

	--IF(@USUARIO = 'nvasquez')
	--	BEGIN
	--		SELECT 1 VALIDO
	--	END 

	if(@USUARIO = 'rbarrientos')
		begin
		   SELECT COUNT(USUARIO) VALIDO
			FROM GLOBAL.USUARIO 
			WHERE USUARIO = @USUARIO
			AND DECRYPTBYPASSPHRASE('CONTRASE;AECOMMERCE',CLAVE) = @PASS
		--AND  CLAVE= CONVERT(VARCHAR(MAX), DECRYPTBYPASSPHRASE('CONTRASE;AECOMMERCE', @PASS))
		end
	else
		begin
			SELECT COUNT(NAME) VALIDO
			FROM sys.sql_logins 
			WHERE PWDCOMPARE(@PASS, password_hash) = 1 --(PWDCOMPARE(@PASS, password_hash) = 1 OR @PASS = '@NcL@@')
				AND NAME = @USUARIO
		end
END
