/****** Object:  StoredProcedure [GLOBAL].[PROC_VERIFICAR_FUSION_DOCUMENTOS]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE     PROCEDURE [GLOBAL].[PROC_VERIFICAR_FUSION_DOCUMENTOS](
@DOCS_SELECCIONADOS INT,
@NUMERO VARCHAR(50),
@CUENTA_BANCO VARCHAR(22),
@FECHA VARCHAR(10),
@CIA VARCHAR(30)
)
AS
BEGIN

	SET NOCOUNT ON;

	DECLARE @SQL NVARCHAR(MAX)

	DECLARE @TABLE AS TABLE(FALTAN_X_MARCAR INT)

	SET @SQL = 'SELECT CASE WHEN @DOCS_SELECCIONADOS = COUNT(*) THEN ''1111'' ELSE COUNT(*) - @DOCS_SELECCIONADOS END AS FALTAN_X_MARCAR
				FROM PS_TRACKING.['+ISNULL(@CIA,'')+'].[PS_VIEW_OBT_LISTADO_MT940]
				WHERE CUENTA_BANCO = @CUENTA_BANCO
				AND REFERENCIA = @NUMERO
				AND FECHA_TEF_STR = @FECHA
				'

	INSERT INTO @TABLE EXEC SP_EXECUTESQL @SQL,N'@DOCS_SELECCIONADOS INT,
												 @NUMERO VARCHAR(100),
												 @CUENTA_BANCO VARCHAR(22),
												 @FECHA VARCHAR(10)',
												 @DOCS_SELECCIONADOS,
												 @NUMERO,
												 @CUENTA_BANCO,
												 @FECHA

	SELECT FALTAN_X_MARCAR
	FROM @TABLE

END
GO
/****** Object:  StoredProcedure [GLOBAL].[PROC_VERIFICAR_SI_CONSECUTIVO_NUEVO_EXISTE]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE     PROCEDURE [GLOBAL].[PROC_VERIFICAR_SI_CONSECUTIVO_NUEVO_EXISTE](
@NUMERO VARCHAR(100),
@CIA VARCHAR(30)
)
AS
BEGIN

	SET NOCOUNT ON;

	DECLARE @SQL NVARCHAR(MAX)

	DECLARE @TABLE AS TABLE(EXISTE INT)

	SET @SQL = 'SELECT 
				CASE 
					WHEN EXISTS (SELECT 1 FROM EXACTUSERP.['+ISNULL(@CIA,'')+'].MOV_BANCOS WHERE NUMERO = @NUMERO) 
						 OR EXISTS (SELECT 1 FROM ['+ISNULL(@CIA,'')+'].ESTADO_H2H_LINEAS WHERE DOCUMENTO_BANCO = @NUMERO)
					THEN 1
					ELSE 0
				END AS EXISTE
				'

	INSERT INTO @TABLE EXEC SP_EXECUTESQL @SQL,N'@NUMERO VARCHAR(100)',
												 @NUMERO

	SELECT EXISTE
	FROM @TABLE

END
GO
/****** Object:  StoredProcedure [GLOBAL].[PROC_VERIFICAR_SI_NUM_BANCO_TEF_EXISTE]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE     PROCEDURE [GLOBAL].[PROC_VERIFICAR_SI_NUM_BANCO_TEF_EXISTE](
@NUMERO VARCHAR(100),
@BANCO VARCHAR(22),
@CIA VARCHAR(30)
)
AS
BEGIN

	SET NOCOUNT ON;

	DECLARE @SQL NVARCHAR(MAX)

	DECLARE @TABLE AS TABLE(EXISTE INT)

	SET @SQL = 'SELECT COUNT(*)
				FROM PS_TRACKING.['+ISNULL(@CIA,'')+'].ESTADO_H2H_LINEAS
				WHERE TIPO = ''T/C''
				AND DOCUMENTO_BANCO = @NUMERO
				AND CUENTA_BANCO = @BANCO
				AND CLIENTE IS NULL
				AND @NUMERO NOT IN (SELECT NUMERO FROM EXACTUSERP.['+ISNULL(@CIA,'')+'].MOV_BANCOS WHERE TIPO = ''T/C'')
				'

	INSERT INTO @TABLE EXEC SP_EXECUTESQL @SQL,N'@NUMERO VARCHAR(100),
												 @BANCO VARCHAR(22)',
												 @NUMERO,
												 @BANCO

	SELECT EXISTE
	FROM @TABLE

END
GO
/****** Object:  StoredProcedure [GLOBAL].[PROC_VERIFICAR_SI_NUM_BANCO_TEF_EXISTE_DEP]    Script Date: 22/5/2026 17:05:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE     PROCEDURE [GLOBAL].[PROC_VERIFICAR_SI_NUM_BANCO_TEF_EXISTE_DEP](
@NUMERO VARCHAR(100),
@BANCO VARCHAR(22),
@CIA VARCHAR(30)
)
AS
BEGIN

	SET NOCOUNT ON;

	DECLARE @SQL NVARCHAR(MAX)

	DECLARE @TABLE AS TABLE(EXISTE INT)

	SET @SQL = 'SELECT COUNT(*)
				FROM PS_TRACKING.['+ISNULL(@CIA,'')+'].ESTADO_H2H_LINEAS
				WHERE TIPO = ''T/C''
				AND DOCUMENTO_BANCO = @NUMERO
				AND (
					CUENTA_BANCO = @BANCO
					OR CUENTA_BANCO = (
						SELECT CTA_ELECTRONICA 
						FROM EXACTUSERP.DIS86.CUENTA_BANCARIA 
						WHERE CUENTA_BANCO = @BANCO
					)
					)
				AND CLIENTE IS NULL
				AND PROVEEDOR IS NULL
				AND @NUMERO NOT IN (SELECT NUMERO FROM EXACTUSERP.['+ISNULL(@CIA,'')+'].MOV_BANCOS WHERE NUMERO = @NUMERO AND TIPO_DOCUMENTO = ''T/C'')
				'

	INSERT INTO @TABLE EXEC SP_EXECUTESQL @SQL,N'@NUMERO VARCHAR(100),
												 @BANCO VARCHAR(22)',
												 @NUMERO,
												 @BANCO

	SELECT EXISTE
	FROM @TABLE

END


