CREATE PROC [GLOBAL].[PS_EXACTUSERP_INS_AUXILIAR_CC]
(
@ID_DOCUMENTO INT,
@CIA VARCHAR(25)
)
AS 
 BEGIN
 
  DECLARE @SQL NVARCHAR(MAX),@PARAMS NVARCHAR(MAX)
  
  SET @SQL = N'INSERT INTO EXACTUSERP.['+ISNULL(@CIA,'')+'].[AUXILIAR_CC]
			   (
				[TIPO_CREDITO]
			   ,[TIPO_DEBITO]
			   ,[FECHA]
			   ,[CREDITO]
			   ,[DEBITO]
			   ,[MONTO_DEBITO]
			   ,[MONTO_CREDITO]
			   ,[MONTO_LOCAL]
			   ,[MONTO_DOLAR]
			   ,[MONTO_CLI_CREDITO]
			   ,[ASIENTO]
			   ,[MONTO_CLI_DEBITO]
			   ,[MONEDA_CREDITO]
			   ,[MONEDA_DEBITO]
			   ,[CLI_REPORTE_CREDIT]
			   ,[CLI_REPORTE_DEBITO]
			   ,[CLI_DOC_CREDIT]
			   ,[CLI_DOC_DEBITO]
			   ,[FOLIOSAT_DEBITO]
			   ,[FOLIOSAT_CREDITO]
			   ,[TIPO_CAMBIO_APLICA]
			   ,[ES_INT_CORRIENTE]
			   )
	 SELECT 
			   [TIPO_CREDITO]
			  ,[TIPO_DEBITO]
			  ,[FECHA]
			  ,[CREDITO]
			  ,[DEBITO]
			  ,[MONTO_DEBITO]
			  ,[MONTO_CREDITO]
			  ,[MONTO_LOCAL]
			  ,[MONTO_DOLAR]
			  ,[MONTO_CLI_CREDITO]
			  ,[ASIENTO]
			  ,[MONTO_CLI_DEBITO]
			  ,[MONEDA_CREDITO]
			  ,[MONEDA_DEBITO]
			  ,[CLI_REPORTE_CREDIT]
			  ,[CLI_REPORTE_DEBITO]
			  ,[CLI_DOC_CREDIT]
			  ,[CLI_DOC_DEBITO]
			  ,[FOLIOSAT_DEBITO]
			  ,[FOLIOSAT_CREDITO]
			  ,[TIPO_CAMBIO_APLICA]
			  ,[ES_INT_CORRIENTE]
	  FROM 
	          ['+ISNULL(@CIA,'')+'].[PS_EXACTUSERP_INS_AUXILIAR_CC]
	  WHERE 
	           [ID_DOC_DETALLE] = @ID_DOCUMENTO'

  SET @PARAMS =N'@ID_DOCUMENTO INT'
  EXEC SP_EXECUTESQL @SQL,@PARAMS,@ID_DOCUMENTO

END 


