		  ,[TIPO_CAMB_ACT_DOL]
		  ,[TIPO_CAMB_ACT_CLI]
		  ,[SUBTOTAL]
		  ,[DESCUENTO]
		  ,[IMPUESTO1]
		  ,[IMPUESTO2]
		  ,[RUBRO1]
		  ,[RUBRO2]
		  ,[MONTO_RETENCION]
		  ,[SALDO_RETENCION]
		  ,[DEPENDIENTE]
		  ,[FECHA_ULT_CREDITO]
		  ,[CARGADO_DE_FACT]
		  ,[APROBADO]
		  ,[ASIENTO_PENDIENTE]
		  ,[FECHA_ULT_MOD]
		  ,[NOTAS]
		  ,[CLASE_DOCUMENTO]
		  ,[FECHA_VENCE]
		  ,[NUM_PARCIALIDADES]
		  ,[COBRADOR]
		  ,[USUARIO_ULT_MOD]
		  ,[CONDICION_PAGO]
		  ,[MONEDA]
		  ,[CUENTA_BANCO]
		  ,[VENDEDOR]
		  ,[CLIENTE_REPORTE]
		  ,[CLIENTE_ORIGEN]
		  ,[CLIENTE]
		  ,[SUBTIPO]
		  ,[PORC_INTCTE]
		  ,[AUD_USUARIO_ANUL]
		  ,[NUM_DOC_CB]
		  ,[USUARIO_APROBACION]
		  ,[FECHA_APROBACION]
		  ,[ANULADO]
		  ,[CODIGO_IMPUESTO]
		  ,[PAIS]
		  ,[DIVISION_GEOGRAFICA1]
		  ,[DIVISION_GEOGRAFICA2]
		  ,[BASE_IMPUESTO1]
		  ,[BASE_IMPUESTO2]
		  ,[DEPENDIENTE_GP]
		  ,[SALDO_TRANS]
		  ,[SALDO_TRANS_LOCAL]
		  ,[SALDO_TRANS_DOLAR]
		  ,[TIPO_ASIENTO]
		  ,[PAQUETE]
		  ,[SALDO_TRANS_CLI]
		  ,[FACTURADO]
		  ,[GENERA_DOC_FE]
		  ,[ENTIDAD_FINANCIERA]
		  ,[CLAVE_DE]
		  ,[TIPO_IMPUESTO1]
		  ,[TIPO_TARIFA1]
		  ,[TIPO_IMPUESTO2]
		  ,[TIPO_TARIFA2]
		  ,[ACTIVIDAD_COMERCIAL]
		  ,[ES_FACTURA_REEMPLAZO]
		  ,[TIENE_RELACIONADOS]
		  ,[PORC_DETRAC]
		  ,[TIENE_COMPLEMENTO]
		  ,[IMPUESTO_BOLSA]   
FROM 
           ['+ISNULL(@CIA,'')+'].[PS_EXACTUSERP_INS_DOCUMENTOS_CC]
WHERE      ID_DOCUMENTO = @ID_DOCUMENTO'

SET @PARAMS ='@ID_DOCUMENTO INT'

EXEC SP_EXECUTESQL @SQL,@PARAMS,@ID_DOCUMENTO

END


